DELETE FROM `quest_offer_reward_locale` WHERE `locale` = 'itIT';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(11, 'itIT', 'Vedo che ti sei dato da fare! Hai la nostra gratitudine, $N.', 0),
(16, 'itIT', 'Grazie, $N! Torna se vuoi fare un altro scambio.', 0),
(35, 'itIT', 'Sì, i Murloc si sono insediati vicino ai corsi d''acqua nella parte orientale di Elwynn. Non sappiamo cosa ci facciano qui, ma sono aggressivi e dotati di un minimo d''intelligenza.', 0),
(37, 'itIT', '<Anche se i corpi sono stati spogliati di gran parte dei loro averi, vicino a essi trovi un medaglione con sopra inciso: "Coscritto Malakai Stone".>', 0),
(40, 'itIT', 'Sì, ho parlato con Remy. Lo rispetto come mercante, anche se tutti i rapporti sui Murloc a est sono a dir poco superficiali.$B$BCapisco la tua preoccupazione, ma finché non riceverò un rapporto militare sulla minaccia dei Murloc non posso inviare altre truppe a est.', 0),
(45, 'itIT', '<Tra i resti del cadavere trovi un medaglione di metallo con su scritto: "Coscritto Rolf Hartford".>', 0),
(46, 'itIT', 'Hai portato le pinne? Magnifico! Il Maresciallo Dughan è preoccupato per il problema dei Murloc nella parte orientale di Elwynn. Volevo rassicurarlo dicendogli che è tutto sotto controllo.$B$BGrazie a te ora posso farlo.', 0),
(47, 'itIT', 'Grazie per la polvere, $N. Ecco il tuo denaro... e un regalino da parte di alcuni miei soci. Potrebbe tornarti utile... utile.', 0),
(52, 'itIT', 'Grazie mille per il tuo aiuto, $N. C''è qualcosa nella foresta che rende questi animali così aggressivi.$B$BDi qualunque cosa si tratti, spero resti lì.', 0),
(54, 'itIT', 'Be'', dice che ti hanno conferito lo stato di Vice dei Marescialli di Roccavento. Congratulazioni.$B$BE buona fortuna. Proteggere Elwynn non è semplice... Soprattutto con gran parte dell''esercito occupato a fare chissà cosa per chissà quale nobile!$B$BIn questo periodo è dura stare dietro alla politica...', 0),
(59, 'itIT', 'Ah, grazie per il buono. Scegli pure l''armatura che preferisci.$B$BSpero ti tornerà utile. Buona fortuna, $c.', 0),
(60, 'itIT', 'Vedo che ti sei dato da fare con i Coboldi. Grazie per le candele, $N. Tieni la tua ricompensa...', 0),
(62, 'itIT', 'Questa è una pessima notizia. Cosa dobbiamo aspettarci dopo? I draghi?!? Dovremo intensificare la presenza delle nostre pattuglie vicino a quella miniera. Grazie dell''aiuto, $N. Non te ne andare... potrei avere un altro incarico da affidarti.', 0),
(71, 'itIT', 'Hai confermato i miei timori, $N. I Murloc sono una minaccia che non possiamo ignorare.', 0),
(76, 'itIT', 'La Miniera Venarossa è piena di Coboldi? Questa non ci voleva!$B$BGrazie per il tuo rapporto, $N, anche se avrei preferito delle buone notizie.', 0),
(84, 'itIT', 'Mmm, delizioso! Questo pasticcio è il migliore che abbia mai mangiato!$B$BSento già che mi sta tornando la memoria...', 0),
(85, 'itIT', 'Cos''è che hai perso? Be'', io non ho preso nessuna collana, non sono un ladro!$B$BPotrei dirti chi è stato, ma... <Billy Maclure ghigna.>... sono troppo affamato per ricordarmi il suo nome.', 0),
(87, 'itIT', 'Oh, l''hai trovata! Grazie, tesoro, grazie!$B$BPrendi questo oggetto... apparteneva a mio marito, diceva sempre che portava fortuna. Vorrei tanto che non se lo fosse dimenticato nella sua ultima missione! *sniff*', 0),
(106, 'itIT', 'Ah! Non posso sopportare l''idea di stare lontano da lei. Devo vederla assolutamente!', 0),
(107, 'itIT', 'Mi piange il cuore per quei due poveri ragazzi, Maybell e Tommy Joe. Mi ricordano me, quand''ero giovane e innamorato.$B$BDeve pur esserci qualcosa che posso fare per aiutarli. Fammi pensare...', 0),
(111, 'itIT', 'Finché la rivalità tra le nostre famiglie andrà avanti, la storia d''amore tra Tommy Joe e Maybell non ha futuro. Forse però possiamo farli stare insieme, anche solo per un po''.$B$BMmm... vediamo cosa si può fare...', 0),
(112, 'itIT', 'Vedo che ti sei procurato le alghe! Molto bene. Ora aspetta un momento mentre preparo la pozione...', 0),
(114, 'itIT', 'Santo cielo! Mi sento in colpa a ingannare la mia famiglia, ma i miei sentimenti verso Tommy Joe sono troppo forti per poterli ignorare.$B$BGrazie, $N. Berrò questo liquore alla prima occasione utile e poi andrò dal mio amore.$B$BTi prego di accettare questo.', 0),
(123, 'itIT', 'Mmm... ho sentito parlare di questo "Collezionista" ma non so per chi lavori. Grazie per avermi portato il programma. Ci aiuterà a risolvere questo mistero.', 0),
(172, 'itIT', 'Zug zug! Mi chiamo Grunth. Sei tu che devi accompagnarmi? Sei un avventuriero... proprio come lo erano mia madre e mio padre.$B$BLa Matrona mi ha detto che sono morti in battaglia con onore. Felice di conoscerti.$B$BCi sono delle cose che mi piacerebbe fare e la Matrona mi ha detto che per me sarai come un fratello maggiore per tutta la settimana. La cosa mi piace un sacco.', 0),
(193, 'itIT', 'Quindi la grande Bhag''thera è morta! Congratulazioni, $N. Sei davvero un grande $c!', 0),
(197, 'itIT', 'Mastro $n, flagello dei raptor!

Suona bene, vero?', 0),
(208, 'itIT', 'Diavolo, ben fatto! Ottimo! Congratulazioni, $N, per essere riuscito dove altri hanno fallito.$B$BSono onorato di poterti considerare membro di questo gruppo di caccia. Nessuno dubiterà mai della tua abilità nella caccia!$B$BAlla tua! Salute!', 0),
(216, 'itIT', 'Ben fatto, $c, ben fatto! Dovrò continuare a organizzare incursioni per eliminare i Mezzorsi, ma almeno avrò la certezza di poter contare su una strada libera dall''influenza dell''Alleanza. La conquista di Valtetra da parte dell''Orda è ora più vicina!$B$BTi sei guadagnato la tua paga, oggi. Grazie!', 0),
(239, 'itIT', 'Ti manda il Maresciallo Dughan? Non fai parte dell''esercito, ma se Dughan si fida di te, chi sono io per contraddirlo?$B$BLa nostra situazione è a dir poco disperata. Spero tu possa aiutarci.', 0),
(264, 'itIT', 'Metti sulla tomba il pendente senza valore, e le gemme incastonate sembrano diventare più cupe.$B$BMentre ti alzi per andartene, osservi il pendente: giace scomposto sulle mani del bassorilievo scolpito sulla bara. I tuoi pensieri vengono interrotti da una brezza fredda e pungente che invade Mausolea. Per un attimo, tutto intorno a te si ferma.', 0),
(314, 'itIT', 'Davvero un ottimo lavoro! Veron farà salti di gioia quando lo saprà. Non è da tutti uccidere Vagash. Immagino che un giorno combatterai al fianco degli uomini di Re Magni sul fronte dell''Alleanza.', 0),
(315, 'itIT', 'Magnifico! Non vedo l''ora di usare quest''erba in alcune delle mie ricette. Ce n''è una in particolare per la quale credo che sarà perfetta...', 0),
(333, 'itIT', 'Qui dice che gli affari di Harlan vanno a gonfie vele. Mi fa piacere, ma mi chiedo come mai la gente abbia bisogno di tante armature. Non mi sembra che siamo in guerra... C''è qualcosa che i nobili non ci stanno dicendo?$B$BComunque, grazie per aver consegnato la richiesta. Ecco il tuo pagamento, farò in modo che Harlan riceva la sua merce.', 0),
(334, 'itIT', 'Oh, maledizione! Pensavo che dimenticandomi gli strumenti, oggi non avrei lavorato. Ora immagino che dovrò aiutare i Larson a cucire...$B$BOh, va bene. Come si dice? Prima il dovere e poi il piacere.', 0),
(351, 'itIT', 'Piazzi l''uovo... ehm... il trasmettitore d''emergenza... all''interno della gallina... cioè, del robot teleguidato.$B$BIl robot ronza e vibra, tentando di rialzarsi. Quando finalmente torna in funzione, senti nuovamente la voce di Oglethorpe. Stavolta, però, proviene dall''interno del robot:$B$B"Finalmente OOX-17/TN si è riattivato, ma ha bisogno di ingenti riparazioni! È troppo pesante da trasportare, ma... forse ho un''idea. Puoi sorvegliarlo un altro po''?".', 0),
(353, 'itIT', 'Ahah! E così Grimand ha finalmente terminato la mia ascia! Non vedo l''ora di provarla con Trogg e Coboldi!$B$BMolte grazie, $N. Hai dovuto fare un lungo viaggio per questa consegna. Tieni, ecco delle monete per ricompensare i tuoi sforzi.', 0),
(384, 'itIT', 'La birra è pronta e i cinghiali sono arrivati!$B$BQuesto sì che ci rende contenti e sollevati!$B$BOra non ci resta che mettere tutto sul tavolo in bella mostra...$B$BE quella deliziosa Costoletta di Cinghiale alla Birra sarà nostra!', 0),
(432, 'itIT', 'Questo mi fa sentire un po'' meglio...$B$BMa non avrò pace finché non saranno tutti morti! TUTTI!', 0),
(475, 'itIT', 'Sia lode agli spiriti della foresta, sei qui! Sapevo che Athridas avrebbe percepito il pericolo e avrebbe mandato aiuto.', 0),
(483, 'itIT', 'Ce l''hai fatta, giovane $c! Bene. E appena in tempo, aggiungo.', 0),
(487, 'itIT', 'Hai reso un grande servigio alla brava gente di Dolanaar e Darnassus, prode $c. Come membro delle Sentinelle di Teldrassil, rendo onore alle tue imprese.', 0),
(488, 'itIT', 'Ahah! Ben fatto.$B$BChi avrebbe mai immaginato che io, Zenn Empiazampa, avrei affidato il mio lavoro a una semplice $R? Di sicuro non io! Ma va così... questo mondo che tanto amiamo è pieno di sorprese.$B$BViva l''ingenuità!', 0),
(489, 'itIT', 'Ah, che dolce $R! Sapevo che servivi a qualcosa!', 0),
(648, 'itIT', 'Ah! Sei la salvatrice di OOX-17/TN! Non so come ringraziarti! I miei robot teleguidati necessitano di essere sviluppati ulteriormente. Il tuo recupero mi ha risparmiato tantissime ore di lavoro per ricostruirli... e molti pezzi d''oro per i costi di produzione!$B$BPrendi quello che vuoi tra i miei oggetti. Forse almeno uno di loro ti tornerà utile. Grazie ancora per il tuo generoso aiuto... Io e miei robot ti siamo debitori!', 0),
(743, 'itIT', 'Molto bene, $N. Sembra tu sia pronto a proseguire nei tuoi viaggi. Che il vento ti spinga sempre avanti.', 0),
(744, 'itIT', 'Grazie dell''aiuto, $N.$B$BLa mia parte nella cerimonia di mio fratello è quasi terminata. I miei doveri sono di consegnargli questo copricapo e di assistere alla cerimonia.', 0),
(749, 'itIT', 'Tutte le casse portano il simbolo del Reparto Minerario della S.P.R. & Co. Le note stampigliate con cura sui lati indicano che il contenuto delle casse deve essere lavorato in uno dei loro stabilimenti principali.', 0),
(761, 'itIT', 'So che non è stato facile raccogliere queste penne, $N. Con le tue gesta hai dimostrato il tuo merito come $c. È un bene che tu faccia parte del Villaggio di Zoccolo Sanguinario.', 0),
(833, 'itIT', 'Ben fatto. Hai mandato un chiaro messaggio a quei dannati Mantotergo. Ora ci penseranno due volte prima di profanare nuovamente questo luogo sacro.', 0),
(834, 'itIT', 'Ehi, hai recuperato le nostre provviste! Magnifico. Ora posso tornare al lavoro, non appena avrò trovato qualcuno che mi aiuti a trasportare queste sacche.', 0),
(835, 'itIT', 'Finalmente posso tirare un sospiro di sollievo, sapendo che le Arpie non creeranno più problemi alle nostre carovane. Giusto in tempo... Ho saputo che mi spediranno dei giocattoli sfiziosi con il prossimo carico!$B$BTe la cavi bene, $N. Dovresti andare dal mio capo a Porto Paranco. Scommetto che ha qualcosa da farti fare.$B$BE non temere, non mi sono dimenticato di pagarti per quello che hai fatto per me.', 0),
(848, 'itIT', 'Ah, sì. Sono campioni perfetti. Potenti.$B$BSono un Reietto e onoriamo i patti che stringiamo. Ecco la tua ricompensa, $N.', 0),
(852, 'itIT', 'Hai le mie lodi, $N. I Centauri sono indisciplinati e incapaci di focalizzare la rabbia come gli Orchi, ma restano comunque possenti. Sconfiggendoli, hai dimostrato il tuo valore.', 0),
(876, 'itIT', 'Ah! Ben fatto, $N! Davvero ben fatto... Non ero certo che fossi all''altezza dell''incarico, ma hai dimostrato talento come tagliagole. Grazie ancora per averci aiutato a reprimere l''infestazione delle Arpie. Ecco la tua ricompensa. Usala bene.', 0),
(899, 'itIT', '$c, hai preso seriamente la mia missione e te ne sono grato.$B$BSebbene il mio desiderio di vendetta non si sia spento, posso quantomeno sorridere al pensiero che anche i Verrospino hanno sofferto.', 0),
(919, 'itIT', 'Sono davvero molti! Temo che si stiano diffondendo a una velocità preoccupante. Spero di riuscire a scoprire cosa li sta contaminando.$B$BGrazie per l''aiuto, $N. Questa terra è un luogo migliore grazie ai tuoi sforzi.', 0),
(922, 'itIT', 'Ah, un seme di Alberiano? Volevo farne crescere uno per aiutare Denalan nei suoi studi.$B$BMa ho scoperto che molti degli Alberiani sono corrotti, e i semi di queste creature hanno la stessa malattia del loro genitore. Curarli va oltre le mie capacità.$B$BDenalan è molto abile con le piante, potrebbe trovare una cura per i nuovi Alberiani. Forse egli rappresenta la loro unica speranza.', 0),
(927, 'itIT', '...Che cos''è? Il cuore di un Alberiano?!? È ricoperto da un muschio malefico!$B$BGrazie per avermelo portato, $N. Lo esaminerò e, con un po'' di fortuna, comprenderò la natura del muschio che lo avvolge.', 0),
(930, 'itIT', 'L''hai trovato su Teldrassil? Interessante... questo è un frutto esotico. Forse i semi sono giunti fin qui da molto lontano. Forse addirittura da Azeroth! E questo frutto ha qualcosa... sembra aver reagito in maniera molto strana al terreno di Teldrassil.$B$BGrazie, $N. Ora, se vuoi scusarmi, devo dedicarmi a un esame approfondito...', 0),
(931, 'itIT', 'Dove l''hai presa? Non vedevo una pianta del genere da quando sono stato alla Palude del Dolore... decenni fa! È incredibile che un esemplare sia arrivato fino a Teldrassil... E che abbia raggiunto una tale dimensione!$B$BGrazie, $N. Perdona la mia sinteticità, ma voglio effettuare un esperimento con questa fronda...', 0),
(932, 'itIT', 'Con la morte di Sire Melenas, posso finalmente occuparmi di altre questioni. Grazie, $N.', 0),
(1097, 'itIT', 'Sei qui per aiutarmi con la consegna? Benissimo!', 0),
(1168, 'itIT', 'Hai ucciso tanti di esercito di Draghi Neri. Tu molto coraggiosa, $r.$B$BTharg felice.', 0),
(1201, 'itIT', 'Ottimo lavoro. I loro infiltrati saranno anche abili, ma non abbastanza da sfuggire all''occhio vigile dell''Orda!', 0),
(1202, 'itIT', 'Sei stata grande, $N. Non era una missione facile. I documenti che hai recuperato contengono informazioni preziose per i nostri superiori.', 0),
(1455, 'itIT', 'Bentornata al Presidio di Nijel, $N. Allora, dimmi cos''hai trovato.$B$BNiente? Temo che non ci pagheranno per una cassa vuota.$B$BDimmi di più su questi segni che hai visto... questi tagli.', 0),
(1582, 'itIT', 'Sì, questi oggetti vanno bene. Hai una mano allenata e un occhio attento per i particolari. Il tuo futuro come conciatrice promette bene.$B$BEcco, $N, lascia che ti mostri il modello per realizzare un Giaco del Bagliore Lunare.', 0),
(2159, 'itIT', 'Ah sì, il pacchetto di erbe da Vallombra. Peccato che Porthannius non sia potuto venire di persona, io e lui abbiamo molte cose di cui parlare. Ma sono comunque contento di aver ricevuto le erbe, e di aver incontrato te.$B$BRiposati mentre sei qui. Gli eroi devono mantenersi in forze e con il morale alto... e godere di riposo e conforto quando possono. Negare a se stessi la pace del corpo e dell''anima è una strada che porta al fallimento certo.$B$BDunque... riposa.', 0),
(2438, 'itIT', 'Il mio acchiappasogni di smeraldo è molto importante per me. È un dono che solo in pochi ricevono. Grazie per avermelo riportato, $N.', 0),
(2459, 'itIT', 'Ora posso riparare il mio acchiappasogni. Grazie, $N.', 0),
(2499, 'itIT', 'Sapevo che avevi le capacità necessarie per liberare il lago da quella bestia immonda.$B$BÈ una brutta situazione... un tempo Quercipiglio era una grande guida per la sua gente... ma la corruzione non fa distinzione tra nobili e plebei.$B$BLe dimensioni di questo tumore sono inquietanti, ma devo studiarlo per scoprire di più sulla malattia che affligge la popolazione degli Alberiani.$B$BGrazie, $N.', 0),
(2541, 'itIT', 'Grazie, $N.$B$BChe monile curioso... Percepisco l''aura malefica che emana... è un incantesimo davvero potente.', 0),
(2561, 'itIT', 'Finalmente sono libero dal controllo dei Mordipigna. Grazie, $N.$B$BIl mio spirito ora può riposare per sempre in pace nel Sogno di Smeraldo.$B$BForse un giorno ci rivedremo, giovane $c. Per ora però ti prego di accettare questa ricompensa come segno della mia gratitudine.', 0),
(2947, 'itIT', 'Un anello, hai detto? Fammi vedere... perbacco, è proprio una mia creazione!$B$BAvevo una piccola bottega a Gnomeregan prima che la città cadesse. Forse l''anello è tra quelli che ho lasciato per cercare di mettermi in salvo sulle colline. Ha un aspetto semplice, ne ho realizzati parecchi come questo. Forse appartiene a qualcuno che non ce l''ha fatta.$B$BCe l''avevano i Nani Ferroscuro? Non è una buona notizia... Faresti meglio a parlarne alle autorità.$B$BOra, tornando all''anello...', 0),
(2948, 'itIT', 'Ah, proprio ciò che mi serviva! Un giorno, quando sarò fuori da questo buco in cui sono ingiustamente costretto, forgerò per te... anzi, no: per TUTTI... i monili più belli di tutta Azeroth! Nel frattempo, ti ringrazio per avermi portato i reagenti. Solitamente, un anello di questa qualità lo faccio pagare dieci volte tanto.$B$BA proposito: ecco il tuo nuovo anello!', 0),
(3861, 'itIT', '"COCCODÈ!!!"

<La gallina comincia a mangiare il cibo che le hai gettato a terra.>

<Dopo un po'' si guarda intorno, spaventata, poi comincia a fare avanti e indietro nervosamente. Che stia covando? Pensi sia meglio dare un''occhiata sotto di lei.>', 0),
(4021, 'itIT', 'Ce l''hai fatta! Hai sconfitto i Kolkar!$B$BSarà mia premura che Thrall sia informato delle tue gesta, $N.$B$BCammina a testa alta. Hai portato onore a te e all''Orda.', 0),
(5545, 'itIT', 'Eccellente! Grazie a te dovrei riuscire a completare l''ordine in tempo. Prendi queste monete per il disturbo, in segno di gratitudine.$B$BGrazie ancora e addio.', 0),
(6365, 'itIT', 'Devi consegnare questa carne a Orgrimmar? Non c''è problema. La mia Viverna dei Venti può condurti lì, in cambio di una piccola somma.', 0),
(6387, 'itIT', 'Devi consegnare questa lista a Forgiardente, eh? Posso portarti a destinazione su uno dei miei grifoni in cambio di poche monete. Che ne dici?', 0),
(6442, 'itIT', 'Da cheste parti teniamo bisogno di più persone come te. Grazie per l''aiuto tuo.', 0),
(6482, 'itIT', 'Hai trovato mio fratello! Era stato catturato dai Mantocardo? Questa è davvero una pessima notizia, perché anche se la maggior parte dei Mezzorsi è composta da nobili creature, i Mantocardo sono corrotti.$B$B$N, grazie per aver salvato mio fratello. Non voglio neanche pensare a come possano averlo trattato. Di sicuro adesso lo aspetta una lunga dormita...', 0),
(6544, 'itIT', 'E così l''assalto di Torek è stato un successo! Ben fatto, $N. Gli Elfi della Notte sono dei nemici degni. Un po'' gracilini, forse, ma forti e feroci! Sono certo che la battaglia è stata uno spettacolo...$B$BE spero che tu abbia guadagnato un paio di cicatrici!', 0),
(6622, 'itIT', 'Dottor $N, benvenuto all''Istituto di Traumatologia dell''Orda.', 0),
(6641, 'itIT', 'Da quando sono qui ho visto molti attacchi dei Naga. Sapere che Vorsha non si aggirerà più nell''area mi tranquillizza non poco.$B$BTi siamo tutti debitori, $N.', 0),
(6643, 'itIT', 'La tua offerta è stata accettata e ne hai guadagnato in benevolenza. Continua così e avrai accesso alle attività antiche.', 0),
(6644, 'itIT', 'La tua offerta è stata accettata e ne hai guadagnato in benevolenza. Continua così e avrai accesso alle attività antiche.', 0),
(6741, 'itIT', 'Grazie ancora, $N. Sappi che l''Orda è fiera di te...', 0),
(6781, 'itIT', 'Davvero dei bei pezzi, $N. Posso usarli senza alcuna difficoltà per realizzare del nuovo equipaggiamento per le nostre truppe.$B$BE se ne realizzerò a sufficienza, allora le nostre unità di veterani potranno unirsi alla battaglia!', 0),
(6801, 'itIT', 'Il sangue dei nostri nemici è stato versato. Lo miscelerò con quello già raccolto. Una volta raggiunta la quantità necessaria per l''offerta, il Signore del Ghiaccio si scaglierà su questi cani dei Piccatonante con tutta la furia del Clan Lupi Bianchi!', 0),
(6825, 'itIT', 'La squadriglia si ciba della loro carne. Consuma letteralmente il nemico.$B$BL''attacco è imminente!', 0),
(6881, 'itIT', 'Ben fatto, $N. Adesso userò il potere di questo talismano per potenziare la magia raccolta finora. Una volta accumulato potere a sufficienza, concentrerò le energie raccolte e chiamerò il Signore della Foresta in nostro aiuto.', 0),
(6942, 'itIT', 'Continua così, soldato, e i Grifoni di Picco dell''Aquila potranno attaccare presto!', 0),
(6961, 'itIT', 'Oh oh oh! Salve! Sono Babbo Inverno e, per gentile concessione dei ragazzi della Masseria Buongusto... "Dalle nostre fattorie direttamente nel tuo piatto: Masseria Buongusto, la bontà al prezzo giusto!", vorrei augurarti una splendida Vigilia di Grande Inverno.$B$BSe te lo sei meritato, forse riceverai i dolci della Masseria Buongusto come regalo per la Vigilia di Grande Inverno. Evviva!', 0),
(6962, 'itIT', '$N, sei proprio un bravo aiutante di Babbo Inverno! Divertiti alla Vigilia di Grande Inverno.$B$BEcco una piccola ricompensa per la tua gentilezza.', 0),
(6964, 'itIT', 'La Vigilia di Grande Inverno? Ah, in passato aveva un significato molto più importante per noi Tauren. Oggigiorno, sembra che altri abbiano trasformato la leggenda di questa festività in qualcosa che li aiuta a vendere candele e regali.$B$BNon mi sorprende che Furmund sia amareggiato da un simile cambiamento. Lui e i Tauren come lui si aggrappano al passato come a uno stendardo di guerra. Anche se credo che festeggiare un po'' sia sempre una cosa positiva, è importante ricordare l''origine della Vigilia.', 0),
(6984, 'itIT', 'Oh oh oh!$B$BI Goblin mi hanno detto che quest''anno ti meriti un regalo speciale ed è mio immenso piacere dartelo. Ecco. Che tu possa passare una splendida Vigilia di Grande Inverno, quest''anno e anche in tutti quelli a venire.', 0),
(7022, 'itIT', 'Oh oh oh! Salve! Sono Babbo Inverno e, per gentile concessione dei ragazzi della Masseria Buongusto... "Dalle nostre fattorie direttamente nel tuo piatto: Masseria Buongusto, la bontà al prezzo giusto!", ti auguro una splendida Vigilia di Grande Inverno.$B$BSe te lo sei meritato, forse riceverai i dolci della Masseria Buongusto come regalo per la Vigilia di Grande Inverno. Urrà!', 0),
(7023, 'itIT', 'Oh oh oh! Salve! Sono Babbo Inverno e, per gentile concessione dei ragazzi della Masseria Buongusto... "Dalle nostre fattorie direttamente nel tuo piatto: Masseria Buongusto, la bontà al prezzo giusto!", vorrei augurarti una splendida Vigilia di Grande Inverno.$B$BSe te lo sei meritato, forse riceverai i dolci della Masseria Buongusto come regalo per la Vigilia di Grande Inverno. Evviva!', 0),
(7025, 'itIT', '$N, sei proprio un bravo aiutante di Babbo Inverno! Divertiti alla Vigilia di Grande Inverno.$B$BEcco una piccola ricompensa per la tua gentilezza.', 0),
(7026, 'itIT', 'Ben fatto, soldato. Quando avremo raggiunto la quantità necessaria di pelli ti avviserò.$B$BContinua così!', 0),
(7045, 'itIT', 'Oh oh oh! Salve, avventuriero!$B$BI Goblin mi hanno detto che quest''anno meriti un regalo speciale ed è mio immenso piacere consegnartelo. Ecco! Che tu possa passare una splendida Vigilia di Grande Inverno, quest''anno e anche in tutti quelli a venire.', 0),
(7062, 'itIT', 'La Vigilia di Grande Inverno? Ahimè, in passato aveva un significato molto più importante per noi Nani. Oggigiorno, sembra che altri abbiano trasformato la leggenda di Babbo Inverno in qualcosa che li aiuta a vendere candele e regali.$B$BNon mi sorprende che Goli sia amareggiato da un simile cambiamento. Lui e i Nani come lui si aggrappano al passato come a uno stendardo di guerra. Personalmente, ritengo che festeggiare un po'' sia sempre una cosa positiva, ma è importante ricordare l''origine della Vigilia.', 0),
(7063, 'itIT', 'La maggior parte della gente ha dimenticato le leggende e le tradizioni che circondano il Grande Inverno anni fa. So che i Goblin stanno riportando in auge la festività per i loro scopi personali, ma il fatto che la cittadinanza pensi alla Vigilia, sebbene per altri motivi, contribuisce a mantenere viva la tradizione.$B$BIl tuo desiderio di andare oltre l''aspetto materiale della festività e scoprirne le radici è una cosa ammirevole, giovane $c. La tua natura erudita ti fa onore.', 0),
(7121, 'itIT', 'Sai, $N, fa piacere vedere facce nuove in giro, ma con un po'' di fortuna parteciperai presto a qualche operazione e allora non sarai più una faccia nuova!$B$BTorna a trovarmi, devo parlarti di alcune cose...', 0),
(7385, 'itIT', 'Il sangue dei nostri nemici è stato versato. Lo miscelerò con quello già raccolto. Una volta raggiunta la quantità necessaria per l''offerta, il Signore del Ghiaccio si scaglierà su questi cani dei Piccatonante con tutta la furia del Clan Lupi Bianchi!', 0),
(7386, 'itIT', 'Ben fatto, $N. Adesso userò il potere di questi talismani per potenziare la magia raccolta finora. Una volta accumulato potere a sufficienza, concentrerò le energie raccolte e chiamerò il Signore della Foresta in nostro aiuto.', 0),
(7737, 'itIT', 'Continua a portarmi del residuo!', 0),
(7781, 'itIT', 'Non c''è bisogno di spiegarti quale sia la portata della tua impresa, $N. Questo giorno resterà nella storia. Una vittoria come non se ne vedevano da anni nell''Alleanza, e come forse non se ne sono mai viste in assoluto!', 0),
(7782, 'itIT', '<Il Primo Maresciallo Afrasiabi si inchina.>

Scegli la tua ricompensa... e che i festeggiamenti abbiano inizio!', 0),
(7785, 'itIT', 'Che gli dei ti proteggano nella tua crociata. Che il padrone benedica i tuoi sforzi.', 0),
(7848, 'itIT', 'Ora sono in grado di trasportarti nel Nucleo Ardente. Chiedi e sarà fatto.', 0),
(8149, 'itIT', 'Uther è stato un eroe fra gli eroi. Non posso nemmeno immaginare il dolore che deve aver provato quando Arthas ha tradito l''intera umanità: era il suo miglior studente e lo amava come un figlio. Ciononostante, si oppose ad Arthas e per questo sarà ricordato per sempre come un vero Paladino. Combatté fino alla morte, curandosi solo di salvare gli altri.$B$BGrazie, $N. Hai reso un enorme tributo al grande eroe, onorando il suo spirito e quello della Sagra del Raccolto.', 0),
(8150, 'itIT', 'Grommash, significa "Cuore del gigante". Ha tenuto fede al suo nome e dimostrato molte altre doti affrontando da solo Mannoroth. Credo che avesse ragione il Capoguerra quando diceva che la maledizione degli Orchi è iniziata e ha avuto fine con Grommash. Trovo appropriato, e forse catartico, che il sacrificio di Grommash sia la sorgente da cui sgorga oggi l''Orda.$B$BGrazie, $N. Oggi hai reso omaggio a un grande eroe, onorando il suo spirito e quello della Sagra del Raccolto.', 0),
(8249, 'itIT', 'Che questi pugnali trovino un posto nel cuore di qualcuno.$B$BLetteralmente.', 0),
(8307, 'itIT', 'Questo libro contiene diverse ricette comuni e anche qualcuna inusuale. Dopo averlo sfogliato per qualche secondo, noti una ricetta con la carne di Vermisabbio.', 0),
(8308, 'itIT', 'Be'', questo spiega tante cose. Se trovassi mai il modo per arrivare ad Ahn''qiraj, prova a cercare il vecchio Brann. Temo che sia inerme senza la sua scimmia.', 0),
(8311, 'itIT', 'Accidenti, li hai presi tutti! Sei grande!$B$BGrazie per averlo fatto al posto mio. Tieni, prendi questi dolcetti alla zucca, secondo me ti piaceranno!$B$BBuona Veglia delle Ombre, $N!', 0),
(8312, 'itIT', 'Caspita, li hai presi tutti! Sei grande!$B$BGrazie per averlo fatto al posto mio. Tieni, prendi questi dolcetti alla zucca, secondo me ti piaceranno!$B$BBuona Veglia delle Ombre, $N!', 0),
(8313, 'itIT', 'Diamo un''occhiata...$B$BSembra abbastanza semplice. Chiamano in modo diverso alcune erbe, ma sono abbastanza facili da identificare. Vieni, ti faccio vedere!', 0),
(8317, 'itIT', 'Eccellente! Mi hai salvato. Questi gnocchi sono piuttosto buoni. Non mi aspettavo che i Martello del Crepuscolo avessero simili gusti.', 0),
(8325, 'itIT', 'Hai completato con successo il tuo primo incarico... e questo merita un plauso. Questo mi fa sperare che ti rivelerai migliore di quei giovani Elfi del Sangue che non seguono gli insegnamenti dei loro maestri. I tuoi successi futuri saranno ricompensati non solo con la conoscenza, ma anche con doni tangibili.$B$BA ogni modo, il tuo lavoro qui non è finito. C''è ancora molto da imparare...', 0),
(8326, 'itIT', 'Ora la torre e le aree circostanti dovrebbero essere relativamente sicure, anche se per poco. Hai agito bene nel darci un po'' di sicurezza, ma se vogliamo sopravvivere nel lungo periodo, dobbiamo riprendere il controllo dell''isola. E questo significherà affrontare minacce molto più grandi dei Dragoni di Mana erranti e delle linci.$B$BPrendi, $N... Di certo ne farai buon uso nelle missioni che ti attendono.', 0),
(8327, 'itIT', 'La Magistra Erona mi ha detto che stavi arrivando di gran fretta, $N. L''Accademia di Falthrien a ovest, quel grande edificio fluttuante con le guglie decorate, è in una pessima situazione. Dovrai riconquistarla da uno dei Miserabili, un $R caduto in balia delle passioni più grette.$B$BSpero tu sia pronto per l''incarico. Non sarà solo una lezione sul concetto di pericolo, ma anche su quello che avviene quando si rinuncia alla propria natura.', 0),
(8334, 'itIT', 'Anche se la morte dei Guardialberi non mi rallegra in nessun modo, mi fa capire che sei in grado di affrontare l''impresa più importante qui sull''Isola di Solealto. Prendi... e fanne buon uso. Avrai bisogno di oggetti di valore e di mente acuta per ciò che ti attende. Riuscire a riprendere il controllo dell''isola dipende da questo.', 0),
(8335, 'itIT', 'La testa di Felendren... sei da lodare, $N. Hai avuto successo dove altri, come Felendren, hanno miseramente fallito. Forse è davvero il momento per te di diventare un elemento attivo nella società degli Elfi del Sangue.$B$BIl tuo successo qui dimostra che sei in grado di sopravvivere alle grandi minacce che incombono su Cantoeterno... e credimi, ce ne sono tante.', 0),
(8338, 'itIT', 'Questo è... molto interessante. E quando dico interessante, intendo dire più inquietante di qualunque altra cosa.$B$BI nostri sforzi per riacquisire il controllo dell''isola dopo la distruzione del Pozzo Solare sono stati vani. Credo che sia per colpa della forza maligna che sta corrompendo l''isola. Qualunque sia la sua natura, questa scaglia potrebbe aiutarci a capire cosa sta succedendo.$B$BHai fatto bene a portarmela, $N. Ecco un compenso per la tua solerzia. Grazie.', 0),
(8347, 'itIT', 'Salute, $c! Mi avevano detto che un giovane $R pieno di risorse, un tempo al servizio della Magistra Erona, sarebbe venuto da queste parti ad aiutare noi staffette. Un aiuto ci farebbe sicuramente comodo, soprattutto da parte di qualcuno che ha dimostrato di essere così abile.$B$BSpero tu sia disponibile a fare un paio di lavoretti per noi.', 0),
(8353, 'itIT', 'Divertentissimo! Ben fatto, $N! Ecco il tuo dolcetto.$B$BBuona Veglia delle Ombre!', 0),
(8354, 'itIT', 'Divertentissimo! Ben fatto, $N! Ecco il tuo dolcetto.$B$BBuona Veglia delle Ombre!', 0),
(8356, 'itIT', 'Sei davvero possente, ah ah ah! Bene, grazie per la disponibilità. Ecco il tuo dolcetto.$B$BBuona Veglia delle Ombre, $N!', 0),
(8357, 'itIT', 'Sei un ballerino nato, $N!$B$BEcco il tuo dolcetto. Felice Veglia delle Ombre, e salutami il tuo amichetto malato! Spero si rimetta presto.', 0),
(8358, 'itIT', 'Caspita! Ben fatto, $N! Eccoti il dolcetto.$B$BBuona Veglia delle Ombre!', 0),
(8359, 'itIT', 'Sei davvero possente, ah ah ah! Bene, grazie per la disponibilità. Ecco il tuo dolcetto.$B$BBuona Veglia delle Ombre, $N!', 0),
(8463, 'itIT', 'Ottimo lavoro, $N.', 0),
(8468, 'itIT', 'Finalmente quel furfante di Thaelis ha avuto ciò che si meritava. Bel lavoro, $N. Ora i Miserabili dovrebbero starsene tranquilli per un po''.', 0),
(8470, 'itIT', 'Questo totem... è uno di quelli dei Legnomorto, ma è completamente marcio. Qualsiasi corruzione abbia trasformato i nostri fratelli in nostri nemici è sicuramente presente in questo oggetto.$B$BSei stata saggia a portarcelo, $N. Forse attraverso lo studio e un rituale riusciremo a scoprire cosa sta inquinando le menti dei nostri fratelli. Grazie, amica. Ti prego di accettare questo per il disturbo.', 0),
(8472, 'itIT', 'Hai fatto un ottimo lavoro, $N. Questi nuclei ci torneranno molto utili, adesso che i nostri santuari arcani non funzionano a pieno regime.', 0),
(8473, 'itIT', 'Dunque è finita. Siano maledetti questi tempi che ci hanno costretti a prendere misure drastiche... e sia maledetto il Flagello!$B$BDobbiamo proteggere le nostre terre a qualsiasi costo, $N, e ci riusciremo!', 0),
(8474, 'itIT', 'Questo pendente... l''ho dato al Vecchio Scorzabianca dopo che la sua gente ci ha aiutato a ricostruire il nostro villaggio.

Questo significa che è...

<L''Elfa del Sangue si schiarisce la gola mentre cerca di ricomporsi.>

Apprezzo che tu l''abbia consegnato a me, $n. C''è un favore che vorrei chiederti.', 0),
(8475, 'itIT', 'Non ci aspettiamo una riduzione degli attacchi da parte del Flagello a breve, ma apprezziamo comunque qualsiasi aiuto per proteggere la Fenditura.', 0),
(8476, 'itIT', 'Bel lavoro, $N. Se ci fossero altre persone come te riporteremmo le nostre terre al loro antico splendore in poco tempo.', 0),
(8477, 'itIT', 'Le voci che circolavano erano vere, $n. Questo martello è resistente e leggero allo stesso tempo. Dovrei riuscire a completare diversi dei miei progetti rimasti in sospeso. Ovviamente, il primo oggetto spetterà a te.', 0),
(8480, 'itIT', 'Ottimo lavoro, $N. Facciamo vedere a quei Miserabili di che pasta siamo fatti!', 0),
(8482, 'itIT', 'Sono scritti in nanico... sei sicuro di averli trovati addosso a un Elfo della Notte?$B$BDa quello che riesco a capire, chiunque abbia scritto questa lettera non è il responsabile del malfunzionamento, ma è stato mandato qui per spiarne le conseguenze. Definiscono i nostri tentativi spericolati e pericolosi... vorrei tanto sapere di chi si tratta.$B$BMa certo! Quell''inviato da Forgiardente! Siamo stati degli sciocchi a fidarci di un emissario dell''Alleanza!', 0),
(8483, 'itIT', 'Quella spia ha avuto ciò che si meritava.$B$BHo avvisato il Generale dei Guardaboschi e credimi, i Nani la pagheranno cara per il loro tradimento.$B$BHai reso un grosso servizio alla tua gente oggi, $N.', 0),
(8486, 'itIT', 'Grazie, $N. Ora che le presenze sono sotto controllo possiamo mandare qualcuno per valutare l''entità dei danni. Spero non sia niente di irreparabile.', 0),
(8487, 'itIT', 'Eccellente. Lancerò un incantesimo di ingrandimento su questi campioni in modo da analizzare meglio la corruzione nel terreno.', 0),
(8488, 'itIT', 'Non c''è niente da fare, $N. La natura stessa del terreno è stata alterata... la corruzione è irreversibile. Grazie comunque per il tuo aiuto. Ho un ultimo favore da chiederti.', 0),
(8490, 'itIT', 'Eccellente. Le difese dovrebbero tenere a bada il Flagello per un altro po''. Grazie per il tuo aiuto, $N.', 0),
(8491, 'itIT', 'Queste andranno benissimo, $N. Prendi questo pezzo d''armatura come ricompensa. Potrò realizzarne degli altri con le pellicce che mi hai portato.', 0),
(8561, 'itIT', 'Ce l''hai fatta! I sussurri degli Imperatori Gemelli sono cessati.$B$BPrendi questo come ricompensa. La sua mera vista getterà nel terrore i cuori dei Qiraji... ricorderà loro la sorte dei loro capi caduti e il mortale che li ha uccisi.', 0),
(8579, 'itIT', '$N, ora vedo che non sei un mortale come tutti gli altri. Le tue possibilità contro il Dio Antico, per quanto infinitamente piccole, a questo punto sono comunque maggiori delle nostre. Dopotutto, lui si aspetta l''assalto dei draghi, non di uno come te.$B$BRifacendoci a quando, mille anni fa, Anacronos ed Elmocervo sconfissero i Qiraji grazie all''alleanza tra le razze dei mortali e dei draghi, anche noi vogliamo stringere un patto. Guadagnati la fiducia dello Stormo dei Draghi di Bronzo e ti sarai guadagnato la nostra. Solo allora ti faremo diventare un vero campione.', 0),
(8594, 'itIT', 'Con i materiali che hai portato e con le scaglie dei nostri nemici Qiraji caduti ho realizzato questi spallacci, mortale. Possano fornirti la protezione di cui hai bisogno e possa la loro vista gettare nel panico i nostri nemici.', 0),
(8595, 'itIT', '$N, continui a servirci bene. Il nostro patto rimane saldo.', 0),
(8602, 'itIT', 'Con i materiali che hai portato e con le scaglie dei nostri nemici Qiraji caduti ho realizzato questi spallacci, mortale. Possano fornirti la protezione di cui hai bisogno e possa la loro vista gettare nel panico i nostri nemici.', 0),
(8621, 'itIT', 'Ben fatto, $N. Hai dimostrato di essere un mortale fuori dal comune.$B$BEccoti quanto promesso, nella speranza che ti aiutino a schiacciare i vili Qiraji.', 0),
(8622, 'itIT', '$N, se devo dire la verità, non mi aspettavo che tornassi sano e salvo.$B$BHai realizzato un destino più grande di quello di molti immortali.$B$BUccidendo C''thun non solo hai salvato tutta Azeroth, ma hai anche rovesciato le sorti degli eventi cosmici in modi a te incomprensibili.$B$BAccetta questo Pettorale Corazzato come simbolo della gloria e degli oneri che ti accompagneranno come conseguenza delle tue azioni.$B$BChe il suo potere possa aiutarti nelle sfide che ancora ti attendono, deicida!', 0),
(8623, 'itIT', 'Ce l''hai fatta! I sussurri degli Imperatori Gemelli sono cessati.$B$BPrendi questo come ricompensa. La sua mera vista getterà nel terrore i cuori dei Qiraji... ricorderà loro la sorte dei loro capi caduti e il mortale che li ha uccisi.', 0),
(8626, 'itIT', 'Ben fatto, $N. Hai dimostrato di essere una mortale fuori dal comune.$B$BEccoti quanto promesso, nella speranza che ti aiutino a schiacciare i vili Qiraji.', 0),
(8627, 'itIT', '$N, se devo dire la verità, non mi aspettavo che tornassi sana e salva.$B$BHai realizzato un destino più grande di quello di molti immortali.$B$BUccidendo C''thun non solo hai salvato tutta Azeroth, ma hai anche rovesciato le sorti degli eventi cosmici in modi a te incomprensibili.$B$BAccetta questo Pettorale Corazzato come simbolo della gloria e degli oneri che ti accompagneranno come conseguenza delle tue azioni.$B$BChe il suo potere possa aiutarti nelle sfide che ancora ti attendono, deicida!', 0),
(8629, 'itIT', 'Sì... la pelle del Vermisabbio fornirà una protezione eccellente. Unita alle parti più forti dei Qiraji che abbiamo ucciso venendo qui, dovrebbe formare un''armatura formidabile. Possa esserti utile nell''affrontare gli innominabili orrori che ti attendono là dentro!', 0),
(8630, 'itIT', 'Con i materiali che hai portato e con le scaglie dei nostri nemici Qiraji caduti ho realizzato questi spallacci, mortale. Possano fornirti la protezione di cui hai bisogno e possa la loro vista gettare nel panico i nostri nemici.', 0),
(8655, 'itIT', 'Ben fatto, $N. Hai dimostrato di essere una mortale fuori dal comune.$B$BEccoti quanto promesso, nella speranza che ti aiutino a schiacciare i vili Qiraji.', 0),
(8657, 'itIT', 'Ce l''hai fatta! I sussurri degli Imperatori Gemelli sono cessati.$B$BPrendi questo come ricompensa. La sua mera vista getterà nel terrore i cuori dei Qiraji... ricorderà loro la sorte dei loro capi caduti e la mortale che li ha uccisi.', 0),
(8658, 'itIT', 'Sì... la pelle del Vermisabbio fornirà una protezione eccellente. Unita alle parti più forti dei Qiraji che abbiamo ucciso venendo qui, dovrebbe formare un''armatura formidabile. Possa esserti utile nell''affrontare gli innominabili orrori che ti attendono là dentro!', 0),
(8659, 'itIT', 'Con i materiali che hai portato e con le scaglie dei nostri nemici Qiraji caduti ho realizzato questi spallacci, mortale. Possano fornirti la protezione di cui hai bisogno e possa la loro vista gettare nel panico i nostri nemici.', 0),
(8660, 'itIT', 'Ben fatto, $N. Hai dimostrato di essere una mortale fuori dal comune.$B$BEccoti quanto promesso, nella speranza che ti aiutino a schiacciare i vili Qiraji.', 0),
(8663, 'itIT', 'Sì... la pelle del Vermisabbio fornirà una protezione eccellente. Unita alle parti più forti dei Qiraji che abbiamo ucciso venendo qui, dovrebbe formare un''armatura formidabile. Possa esserti utile nell''affrontare gli innominabili orrori che ti attendono là dentro!', 0),
(8704, 'itIT', 'Ora sostituirò la gemma dell''anello. Vedrai che il prodotto finito sarà molto più... gradevole.', 0),
(8706, 'itIT', 'Ben fatto, $c. Questa elsa è un''opera d''arte... è perfettamente bilanciata.$B$B$N, ecco la tua arma. Brandiscila con grande sicurezza e annienta i nostri nemici!', 0),
(8784, 'itIT', 'Un ritrovamento eccezionale, $N, semplicemente meraviglioso! Con questo potremo certamente comprendere meglio cosa si agita nella mente contorta del nostro nemico.', 0),
(8789, 'itIT', 'Queste armi infuse di Elementio falceranno i Qiraji e il loro dio con incredibile facilità.', 0),
(8790, 'itIT', '$N, fa'' buon uso di questi oggetti. Procura loro quelle sofferenze che tanto desiderano infliggere agli altri.', 0),
(8791, 'itIT', '$N, non posso che farti i miei complimenti e offrirti un potente manufatto a tua scelta. Hai reso un grande servizio alla gente di Kalimdor.', 0),
(8802, 'itIT', 'Il Maestro mi ha lasciato questi per te, campione: una collezione di manufatti dallo scrigno senza tempo, risalenti fino a migliaia di anni fa. A te la scelta.', 0),
(8867, 'itIT', 'Ben fatto, $N.$B$BOra che sei entrato nello spirito della festa, perché non accetti questo invito per il festival di Radaluna?$B$BÈ una festa molto bella, se hai tempo da perdere. Condividiamo cibo, bevande, storie e, ovviamente, altri fuochi d''artificio!$B$BApri l''invito mentre sei nel Circolo del Chiaro di Luna Maggiore e sarai trasportato a Radaluna.', 0),
(8868, 'itIT', 'Davvero ben fatto, $N. Sconfiggendo Bifido, hai rimandato il suo spirito tra le acque di Elune''ara. Sebbene lui stesso sia stato benedetto da Elune e non possa morire, la sua rabbia scemerà per un altro anno.$B$BLa tua vittoria è una celebrazione, $N. Una celebrazione della forza di Bifido, tua e dei tuoi alleati e della pace che hai concesso a questo tragico eroe del passato.', 0),
(8871, 'itIT', 'Salute, $N. Sei qui per partecipare ai festeggiamenti?', 0),
(8873, 'itIT', 'Benvenuto, $N. Vuoi partecipare ai festeggiamenti?', 0),
(8883, 'itIT', '$N, benvenuto a Nottequieta, la sede della Celebrazione della Luna! Anche se normalmente il nostro villaggio è inaccessibile alla gente di Azeroth, durante questi giorni di festa, apriamo a tutti il nostro cuore.$B$BDivertiti... e quando sei pronto, torna a parlare con me o con mia sorella.', 0),
(8885, 'itIT', 'Finalmente! Anche se gli Scagliasalda non sono fuggiti come speravo, è stato comunque divertente vederli in preda al panico mentre tu uccidevi il loro Capo Tribù. Hai la mia gratitudine, $N, e quella dei Sin''dorei di Lunargenta!$B$BScegli uno di questi oggetti come ricompensa per quello che hai fatto.', 0),
(8886, 'itIT', 'Ce l''hai fatta! Mi hai salvato dalla rovina e mi hai permesso di vendicarmi di quelle odiose creature!$B$BOra, se riuscissi a convincere quei Guardaboschi ad aiutarmi con questo carico, potrei finalmente andarmene da qui! Tornerò quando Velendris avrà riconquistato il cantiere navale.$B$BTieni, prendi queste monete. È tutto quello che ho, ed è il minimo che possa fare per sdebitarmi.', 0),
(8887, 'itIT', 'Non so come ringraziarti, $n! Non pensavo che quei disgustosi Murloc Scagliasalda avessero rubato anche le mie rotte di navigazione! Senza di esse non avrei saputo dove andare una volta riconquistato l''ancoraggio e riparata la nave.

Grazie mille! Tieni, prendi queste monete come segno della mia gratitudine.', 0),
(8888, 'itIT', 'Il magistro è preoccupato per la mia salute? Che gentile... certo, se avesse mostrato la stessa attenzione prima, quando eravamo al Pinnacolo...$B$BOra non ha più importanza. Ascoltami attentamente, $c, perché ho un favore da chiederti.', 0),
(8889, 'itIT', 'Ti ringrazio per il tuo aiuto, anche se mi rattrista sapere che alcuni miei compagni apprendisti sono morti.$B$BOra che il Pinnacolo non ha più potere, credo che resterò un po'' qui in attesa che la situazione si calmi, per poi andare a recuperare i loro resti.', 0),
(8890, 'itIT', 'No! Sono arrivato troppo tardi. È tutta colpa mia.

Le mie ricerche per purificare le fonti di magia alternative mi sono sfuggite di mano prima ancora che potessi fermarle. Se solo fossi andato lì di persona... o se avessero dato retta ai miei avvertimenti!

Ho la coscienza sporca, $c. Voglio comunque ringraziarti per aver messo a riposo le anime torturate dei miei ex apprendisti. È una magra consolazione sapere che non vagheranno più in quello stato, al quale un $r preferirebbe la morte.', 0),
(8891, 'itIT', 'Eccola qua, $N, la prova del mio crimine. Questo diario contiene tutti i miei studi scellerati.$B$BHo proseguito le mie ricerche, incurante di ogni avvertimento, ma quando ho aperto gli occhi ormai era troppo tardi. Preso dal rimorso, ho cercato di rimediare al mio errore, ma a quel punto alcuni dei miei allievi si erano già spinti troppo oltre. Ho fatto evacuare il Pinnacolo per evitare che venissero contagiati dalla corruzione, ma nella fretta mi sono dimenticato di chiudere le fonti di potere.$B$BBrucerò questo libro in modo che nessun altro possa essere tentato dal suo contenuto. Io volevo solo aiutare i Sin''dorei.', 0),
(8892, 'itIT', 'Ben fatto, $N. Questo gli insegnerà a non giocare con noi!', 0),
(8894, 'itIT', 'Così dovrebbe andar bene. Grazie per il tuo aiuto, $c. Ora devo ripulire tutto quanto prima che il magistro torni al Pinnacolo di Lungovespro.$B$BPrendi questo denaro, è tutto quello che ho al momento. Inoltre, apprezzerei molto se uccidessi altre di queste anomalie sulla via del ritorno.', 0),
(8895, 'itIT', 'Grazie per avermi consegnato questa lettera, $N. La stavo aspettando.', 0),
(9035, 'itIT', 'Ora sono scappati. Li ho messi in fuga con una bella Palla di Fuoco! Purtroppo, hanno gettato il nostro prezioso carico nel fiume.', 0),
(9062, 'itIT', 'Il libro è completamente fradicio. L''Istruttore Antheol non la prenderà affatto bene.$B$BTieni questo denaro... mi è venuta un''idea.', 0),
(9064, 'itIT', 'Mi stai dicendo che quei due incompetenti hanno cercato di corromperti per farti dichiarare il falso? Hai fatto bene a venire da me, $N.', 0),
(9066, 'itIT', 'Ottimo lavoro, $N. Non preoccuparti, non rimarranno in quella forma per sempre. Il loro apprendistato, invece, riprenderà solo quando se lo meriteranno.', 0),
(9076, 'itIT', 'Lo hai ucciso! I miei uomini devono averlo senz''altro indebolito prima.$B$BSto scherzando, $c. Hai fatto un ottimo lavoro. Presto ti farai un nome, a patto di stare alla larga dai guai.', 0),
(9119, 'itIT', 'Guardati intorno... le cose non sono esattamente in ordine.$B$BC''è un serio malfunzionamento al Santuario dell''Ovest. Dobbiamo fare del nostro meglio per impedire che la situazione peggiori.', 0),
(9138, 'itIT', 'Sei stato grande, $N, anche se ci attende ancora parecchio lavoro se vogliamo scacciare definitivamente il Flagello da Quel''Thalas!$B$BTieni, prendi queste monete... non è molto, ma te le sei meritate.', 0),
(9139, 'itIT', 'Il tuo successo a Brumadoro ci permette di compiere un altro passo avanti verso la riconquista della nostra terra. Non illuderti però, $c. La guerra è tutt''altro che conclusa.$B$BTieni questa ricompensa, te la sei ampiamente meritata. Potrebbe tornarti utile quando assalterai Ventolesto.', 0),
(9140, 'itIT', 'Ce l''hai fatta, $N. Hai riconquistato i tre villaggi in mano al Flagello! Ora possiamo concentrare più efficacemente le nostre forze contro il Flagello alla Fenditura Morta e a Mortorium, a sud.$B$BScegli la tua ricompensa tra questi oggetti. Spero continuerai ad aiutarci anche in futuro... lo apprezzeremmo molto!', 0),
(9143, 'itIT', 'Apprezzo i tuoi sforzi, $c. Grazie! Perlomeno le vittime di questa spedizione non sono morte invano.', 0),
(9144, 'itIT', 'Aiutami, straniera. Devo... assolutamente... raggiungere Tranquillien.

<L''Elfo del Sangue perde di nuovo conoscenza e il suo sguardo si perde nel vuoto.>', 0),
(9145, 'itIT', 'Sono felice di sapere che Lethvalin stia bene e che abbia scelto saggiamente di rivolgersi a te piuttosto che aspettare.$B$BMi auguro che la Guardaboschi Salissa sia riuscita a raggiungere l''Enclave dei Lungopasso sana e salva.', 0),
(9146, 'itIT', 'Questa è davvero una pessima notizia. Ho sopravvalutato le capacità di comando di Tomathren. Invierò subito un gruppo per mettere in salvo lui e Valanna.$B$BPurtroppo non abbiamo più avuto notizie della Guardaboschi Salissa, dunque temo il peggio per lei.$B$BOggi hai reso un grosso servizio ai Lungopasso, $c. Accetta uno di questi oggetti come segno della nostra gratitudine.', 0),
(9147, 'itIT', 'Appena in tempo, $N! Ero sul punto di scavare una fossa per il nostro amico qui.$B$BLa mia pozione sembra funzionare... si sta riprendendo.$B$BEhi, credo stia cercando di attirare la tua attenzione. Perché non provi a parlargli?', 0),
(9148, 'itIT', 'Finalmente! Abbiamo atteso la risposta del Reggente per settimane! Dai qua...

<Vandril comincia a leggere la lettera.>

Dice di avvertire una presenza oscura nelle Terre Spettrali... mi sta forse prendendo in giro?!? Lo sapevo già!

E questa sarebbe la risposta che stavamo aspettando?', 0),
(9149, 'itIT', 'Eccellente! Queste colonne vertebrali saranno molto utili per la mia ricerca! Quando troverò una cura per la Piaga e il mio nome diventerà famoso in tutto il mondo, mi ricorderò di te!$B$BNel frattempo, prendi questa ricompensa. Ti tornerà utile se decidi di tornare alla costa.', 0),
(9150, 'itIT', 'Queste essenze sono davvero potenti, $N. Hai fatto un ottimo lavoro, complimenti.', 0),
(9151, 'itIT', 'Ti manda Darenis? Molto bene, credo che il tuo aiuto ci tornerà utile nella lotta contro le forze di Dar''khan.', 0),
(9152, 'itIT', 'Ora che ho recuperato il resto delle mie provviste posso finalmente aprire bottega. Il Gran Esecutore sarà felice di sapere che la guerra contro Dar''khan e il Flagello può cominciare.$B$BOvviamente ti meriti una ricompensa per quello che hai fatto. Tieni, $c, prendi queste monete. Torna a farmi visita se dovessi avere bisogno di oggetti e prodotti.', 0),
(9155, 'itIT', 'Niente male, $N, continua così. Abbiamo bisogno di gente come te da queste parti.', 0),
(9156, 'itIT', 'Ah... Luzran e Nocchemarce! Nonostante conservino il loro aspetto orrendo, non sembrano più così cattivi.$B$BScegli una di queste ricompense, $N... te la sei meritata.', 0),
(9157, 'itIT', 'Con questi medaglioni potremo evocare di nuovo Aquantion. Quell''elementale ribelle la pagherà e le nostre morti saranno vendicate!', 0),
(9158, 'itIT', 'Te la sei cavata bene, $N. È importante che la Piaga non colpisca gli animali sani di Cantoeterno. Se non hai niente da fare, ho altri incarichi da assegnarti.', 0),
(9159, 'itIT', 'Ho deciso di assegnarti una ricompensa adeguata all''impegno che hai profuso per il tuo compito. Abbiamo bisogno di altri alleati con il tuo coraggio e la tua determinazione, $N.', 0),
(9160, 'itIT', 'Sono delusa per non aver scoperto subito i piani degli Elfi della Notte ad An''daroth. Tuttavia, quegli oggetti simili a piccoli alberi cresciuti magicamente con in cima dei globi d''energia sembrano interessanti. Dovremo essere più diretti nel raccogliere informazioni.$B$BTieni, prendi queste monete e queste pozioni. Sono certa che ti torneranno utili prima che avremo finito di occuparci di questi Elfi della Notte.', 0),
(9161, 'itIT', 'Dopo aver sfogliato le prime pagine di questo vecchio volume, giungi alla conclusione che un tempo apparteneva a Dar''khan Drathir.', 0),
(9162, 'itIT', 'Queste informazioni sono molto preziose, $N. Sapevamo tutti che Dar''khan voleva rubare il potere del Pozzo Solare per il Flagello, ma tutto il resto è una novità assoluta. Dobbiamo mostrarle al Magistro Kaendris nel Santuario del Sole.', 0),
(9163, 'itIT', 'La situazione è seria! Questi piani mostrano le forze degli Elfi della Notte ad An''daroth, e questo lo sapevamo già, ma anche ad An''owyn, una Linea di Faglia Nexus più remota a sud-est.$B$BC''è un terzo Nexus a est che non viene menzionato, il cui nome è An''telas. Ho un brutto presentimento, $c.', 0),
(9164, 'itIT', 'Grazie, $N. Senza il tuo aiuto il Flagello si sarebbe preso le menti e le anime di quei prigionieri.', 0),
(9166, 'itIT', 'È stato terribile! Gli Elfi della Notte! Hanno evocato il loro Cristallo della Luna qui per qualche piano malvagio, ma io sono riuscito a fuggire e a radunare un gruppo con i nostri esploratori e invocatori provenienti dal vicino Santuario del Sole. Abbiamo ucciso la maggior parte degli Elfi e il resto del gruppo sta dando la caccia ai superstiti!$B$BSono felice che tu sia qui. Mi sono rimasti solo un paio di esploratori a proteggermi! Non è sicuro qua fuori!$B$BConcedimi un attimo per esaminare questi piani e scoprire cos''hanno in mente gli Elfi della Notte.', 0),
(9167, 'itIT', 'Oggi abbiamo sferrato un duro colpo contro il Flagello.$B$BCon la morte del traditore, in breve tempo ci riprenderemo le nostre terre e torneremo al nostro antico splendore.', 0),
(9169, 'itIT', 'Che sollievo, $c! Ti assicuro che se non avessi disattivato quelle Sfere della Chiaroveggenza ci troveremmo in una situazione peggiore di quella in cui siamo ora! Pensa... circondati dai nemici e con uno di loro in grado di spiare ogni nostra mossa!$B$BOra però, grazie a te, non dobbiamo più preoccuparci di tutto questo! Voglio ricompensarti per i tuoi sforzi. Ho giusto alcune cose qui che a me non servono più.$B$BGrazie ancora, $N!', 0),
(9170, 'itIT', 'Presto gli eserciti di Dar''khan cadranno! Il Flagello non può nulla contro la forza combinata dei Sin''dorei e dei Reietti.', 0),
(9171, 'itIT', 'Ottimo, queste andranno bene. No, non dirmi come te le sei procurate, non lo voglio sapere! Cucinerò queste zampe come solo io so fare. Diventeranno un piatto squisito. Metto un po'' di spezie qui, aggiungo un pizzico d''erbe là e poi il tocco finale... alcuni ingredienti arcani et voilà, ecco un pasto degno di una regina... o, in questo caso, di una dama.$B$BMi sei stato di grande aiuto, $c. Tieni, prendi questa ricetta e alcuni assaggini.', 0),
(9172, 'itIT', 'Non può essere... questa è la scrittura di Dar''khan! Questo diario deve contenere informazioni sui punti deboli del nostro nemico.$B$BHai fatto bene a rivolgerti a noi, $N. I Lungopasso hanno dimostrato una grande saggezza nel lasciare che ci occupassimo di questa faccenda. Prendi questa armatura... dovrebbe aiutarti a sostenere la nostra causa.', 0),
(9173, 'itIT', 'Sono sicuro che Dama Sylvanas sarà felice di sapere che abbiamo fatto progressi.$B$BTieni, prendi queste monete come ricompensa per i tuoi sforzi.', 0),
(9174, 'itIT', 'Hai vendicato le nostre morti e spezzato la morsa di Aquantion sulle nostre anime. Ora potremo finalmente riposare in pace.', 0),
(9175, 'itIT', 'Hai detto di averla trovata addosso a una creatura del Flagello al Pinnacolo di Ventolesto e che c''è inciso qualcosa sopra? Fammi vedere!$B$BOttimo lavoro, $N. Ti sei meritato queste monete.', 0),
(9176, 'itIT', 'Le voci erano fondate! La Pietra della Luce e la Pietra del Fuoco esistono davvero! Dobbiamo sfruttare il loro potere, lo stesso che Dar''khan ha cercato di rubarci, come arma contro di lui.$B$BSe usate al momento giusto, le energie del Pozzo Solare intrappolate all''interno di questi manufatti lo annienteranno!', 0),
(9192, 'itIT', 'Hai fatto davvero un bel massacro, $c. Ora i minatori potranno tornare al lavoro. Scommetto che saranno dispiaciuti di interrompere la loro pausa, ma ci sono armi e armature da costruire e per farlo è necessario estrarre il minerale.$B$BTieni, questa è la tua ricompensa. Vai a farti riparare le armi e la corazza e prenditi qualcosa da bere, offro io.', 0),
(9193, 'itIT', 'È stata una cosa disgustosa ma necessaria, fidati. Ci hai fatto un grosso favore portando a termine questo incarico, $c. Ti prego di accettare questo come segno della nostra generosità e gratitudine.', 0),
(9199, 'itIT', 'Mummie riportate in vita dai Sacerdoti Troll... davvero astuto! I Troll Pinombroso stanno cercando di rinforzare le proprie file ricorrendo alla negromanzia. Scommetto che questi Oracoli usavano i feticci per il loro rituale di rianimazione.$B$BHai fatto un ottimo lavoro, $c, degno della tua reputazione in costante crescita. Accetta questo in segno di gratitudine.', 0),
(9207, 'itIT', 'La mia apprendista non è riuscita a portare a termine questo compito da sola? Gnoll o no, quando torna le darò una bella sgridata. A proposito, come mai lei non è qui con te?

<Il magistro sospira.>

Quell''apprendista è una vera pena, sarà dura addestrarla a dovere. Grazie per avermi portato questi campioni, $c. Li stiamo studiando per scoprire delle proprietà speciali che possano aiutarci a combattere il Flagello.

Prendi queste monete in segno della mia gratitudine.', 0),
(9212, 'itIT', '$c, sei stato davvero un eroe a tirarla fuori da lì viva. Immagino dovremo lanciare un''offensiva per ripulire anche quelle catacombe... come se non avessimo già abbastanza problemi con i Troll vivi!$B$BHai compiuto una grande impresa oggi e per questo meriti una ricompensa. Scegli uno tra questi oggetti.', 0),
(9214, 'itIT', 'Invierò immediatamente dei Guardaboschi a verificare i danni che hai causato ai Troll Pinombroso. A giudicare dalle armi che mi hai portato, in breve tempo dovremmo riuscire a spazzare via quelli che rimangono e a lanciare un''offensiva contro il Flagello.$B$BPrendi queste monete come ricompensa.', 0),
(9215, 'itIT', 'Ah, ecco da dove veniva quella puzza insopportabile... la Testa di Kel''gash. Hai fatto un ottimo lavoro, $c!

Ora che il loro Capo Tribù è morto, i Troll Pinombroso dovrebbero piombare nel caos più totale. Considerando inoltre che hai sfoltito le loro file di recente, questa potrebbe essere l''occasione ideale per lanciare la nostra controffensiva e sbarazzarci di loro una volta per tutte.

Ti ringrazio, $n. Scegli la tua ricompensa tra questi oggetti.', 0),
(9216, 'itIT', 'Prendi questa pozione, $N. Una volta bevuta, la tua forza fisica contro il Flagello aumenterà. Se ne vuoi ancora, portami altri cuori.', 0),
(9218, 'itIT', 'Prendi, $N. Sentirai subito la differenza!$B$BSe dovessi trovare altra Polvere Spinale, portamela. Non andrà sprecata. Gli effetti collaterali? Potresti accusare dei problemi alle articolazioni, ma è solo una cosa temporanea, te lo assicuro!', 0),
(9220, 'itIT', 'Il Flagello ha assaggiato la nostra ira, $N. Non ci vorrà molto prima che la loro dannata cittadella cada in rovina.', 0),
(9252, 'itIT', 'Grazie mille, $N. Il nostro è un compito ingrato, ma oggi ci hai aiutati a renderlo un po'' più facile.', 0),
(9253, 'itIT', 'Deve averti mandato qualcuno da Brezzaserena. Sapevo che era solo questione di tempo prima che arrivassero gli aiuti.', 0),
(9254, 'itIT', 'La mia vecchia mentore è davvero gentile a preoccuparsi per me. Peccato che lei abbia perso la fiducia nella mia ricerca tanto tempo fa.$B$BNon sprecare tempo a cercare di convincermi a tornare da lei. Scegli: puoi aiutarmi nella mia ricerca o andartene via.', 0),
(9255, 'itIT', 'Questi appunti sono... scioccanti. Se sono corretti significa che il danno causato alla terra nella Fenditura Morta è irreversibile.$B$BAvviserò subito il Gran Magistro. Ora la nostra razza ha un motivo in più per lasciare questo mondo e andare in cerca del proprio destino nelle Terre Esterne.', 0),
(9256, 'itIT', 'Grazie per essere venuto, $N. La situazione è peggiore di quel che credevamo. I Miserabili hanno conquistato tutto l''Ancoraggio di Vela del Sole.', 0),
(9258, 'itIT', 'Ah, è mio fratello che ti manda. Ho giusto bisogno d''aiuto per un incarico.', 0),
(9268, 'itIT', 'Non ti fermare, $N. Noi Goblin non perdoniamo facilmente!', 0),
(9274, 'itIT', 'Ti sono grato per il tuo aiuto, $N. Mi addolora vedere gli spiriti dei miei antenati ridotti in quello stato. Spero che ora possano finalmente riposare in pace.', 0),
(9275, 'itIT', 'Ah, eccellente! Sapevo che saresti stato perfetto per avvelenare quel cibo. Con un po'' di fortuna, i Troll Pinombroso si abbufferanno per poi crollare a terra stecchiti. Questo dovrebbe permettere ai Lungopasso di sbarazzarsi di loro e a me di tornare a Tranquillien.$B$BÈ stato un piacere lavorare con te, $c!', 0),
(9276, 'itIT', 'Te la sei cavata alla grande, $N! Vediamo se saprai disimpegnarti altrettanto bene con qualcosa di un po'' più complicato.', 0),
(9277, 'itIT', 'Incredibile! Dovresti parlare con il capitano per entrare a far parte dei Lungopasso.$B$BGrazie a te abbiamo guadagnato il tempo che ci serve per radunare le nostre forze. In effetti, non sono rimasti più molti Troll dopo il tuo intervento! Forse ora possiamo unirci a Tranquillien e attaccare Mortorium.$B$BCredo che tu ti sia meritato una ricompensa. Scegli quella che preferisci.', 0),
(9279, 'itIT', 'Per la mia anima eterna, $N, sono felice di rivederti! Non so perché la Exodar sia precipitata. Sono rimasti in vita solo quelli di noi che si trovavano in questa sezione della nave.$B$BNon ci rimane molto tempo, se vogliamo salvare quante più persone possibili!', 0),
(9281, 'itIT', 'Grazie dell''aiuto, $N. Tremavo al solo pensiero di dovermi avventurare nei boschi così vicino a Mortorium.', 0),
(9282, 'itIT', 'Ti manda Kaendris? Potrei avere un incarico per te, $c.', 0),
(9293, 'itIT', 'Così dovrebbe andare. Grazie, $c!$B$BMentre eri in viaggio, sono riuscita a mettere insieme un''apparecchiatura in grado di effettuare un''analisi dei campioni. Dovrebbe volerci un attimo.', 0),
(9314, 'itIT', 'Oh, tu devi essere una di quei superstiti di cui abbiamo sentito parlare!$B$BSono lieta di vederti qui. Non preoccuparti, invieremo subito qualcuno a dare un''occhiata alla gamba ferita di Aeun.$B$BSono molto interessata a sentire la tua storia di superstite: per essere giunta fin qui, devi essere molto coraggiosa.', 0),
(9315, 'itIT', 'Ti chiedo scusa per le informazioni scadenti, $c. Se avessi saputo di questa Anok''suten te l''avrei detto sicuramente.$B$BSiamo rimasti in pochi e la situazione ci sta sfuggendo di mano!', 0),
(9327, 'itIT', 'So che noi Reietti sembriamo dei mostri ai tuoi occhi, ma ti assicuro che non siamo qui per nuocere alla tua gente, ma per combattere un nemico comune: Dar''khan il traditore! Egli è tornato e ora comanda il Flagello che sta invadendo questa terra da Mortorium.$B$BLa nostra Regina, Dama Sylvanas Ventolesto, era un''Elfa ed è originaria di queste terre. Anche lei vuole Dar''khan morto, così come lo vuole la tua gente.$B$BLo sconfiggeremo insieme, $c!', 0),
(9328, 'itIT', 'Ecco un volto che non mi aspettavo di vedere tanto presto.$B$BSono ottime notizie, $N. Più di quanto tu possa immaginare.', 0),
(9329, 'itIT', 'Noi Reietti siamo qui per combattere al fianco degli Elfi del Sangue contro un nemico comune: Dar''khan! Egli è tornato e ora comanda il Flagello che sta invadendo questa terra da Mortorium, a sud.$B$BDama Sylvanas Ventolesto, un''Elfa originaria di queste terre, ha un conto aperto con Dar''khan e lo vuole morto!$B$BLo sconfiggeremo, $c, e tu ci aiuterai!', 0),
(9330, 'itIT', 'Questo fuoco così caldo e luminoso... proviene da Roccavento? Incredibile! Devi aver vissuto una vera e propria avventura! Ovviamente, ti pagherò per questo. Qualora trovassi qualcos''altro di simile, vieni a parlare con me.', 0),
(9332, 'itIT', '$N, questo fuoco brucia di un''antica pena. Hai detto di averlo estratto dalle radici di Teldrassil? Affascinante! Ecco la tua ricompensa. Se dovessi trovare qualcos''altro di simile, torna da me: forse potrei usarlo.', 0),
(9349, 'itIT', 'Un''ottima cucina richiede ottimi ingredienti... e queste uova hanno un aspetto magnifico!$B$BHo appena finito di pulire la padella: se vuoi unirti a me per mangiare, sei la benvenuta!', 0),
(9351, 'itIT', 'Perfetto! In effetti, credo che andrà così bene che dovrò riprogettare il motore per gestire tutta la potenza in più. Se riusciremo mai ad andarcene da qui, dovrò mostrare il mio progetto a tutta l''Area 52!', 0),
(9352, 'itIT', 'Elfi della Notte? Qui? Come osano!$B$BCredi che abbiano a che fare con il malfunzionamento del mio santuario? Se hai delle informazioni, faresti meglio a riferirle immediatamente al Capitano Marchiasole!', 0),
(9355, 'itIT', 'Ben fatto, $N. Però non è ancora il momento di congratularci a vicenda. Sono sicuro che avremo ancora a che fare con quei vermi. Se mostreranno di nuovo le loro teste da queste parti, i Figli saranno pronti a riceverli!', 0),
(9356, 'itIT', 'Uova di Devastatore... Bam!$B$BBacon di Vilcinghiale... Bam!$B$BAli di Condor... Bam! Bam!$B$BChe bella colazione! Devi assolutamente assaggiarla.', 0),
(9358, 'itIT', 'Sei qui per aiutarci? Perché non l''hai detto prima? C''è sempre bisogno di gente disposta a darci una mano!', 0),
(9359, 'itIT', 'Sei qui per aiutarci? Ottimo!$B$BLa battaglia contro i Troll Amani ci è costata parecchie vittime, e combattenti in gamba come te sono sempre i benvenuti.', 0),
(9360, 'itIT', 'I Troll ci tengono inchiodati qui mentre progettano un attacco contro Brezzaserena. Non ce lo aspettavamo.', 0),
(9361, 'itIT', 'Hmm...$B$BSe condita a dovere, dovrebbe essere commestibile. Però non dire a Screed da dove viene la sua colazione, d''accordo?', 0),
(9363, 'itIT', 'Grazie per queste preziose informazioni, $N. Ora che conosciamo i piani dei Troll, possiamo prepararci per un attacco.$B$BNon ci faremo cogliere di sorpresa.', 0),
(9371, 'itIT', 'Oh, eccoti, grazie al cielo. Ci aspetta molto lavoro da fare.', 0),
(9372, 'itIT', 'Ben fatto, $N. Questi Campioni di Sangue contribuiranno enormemente alla mia ricerca. Inoltre, ne beneficerà lo studio generale delle creature delle Terre Esterne, portato avanti dalla Spedizione.$B$BSe riuscissi a isolare le cause della continua mutazione delle creature, forse potrei creare un antidoto.', 0),
(9373, 'itIT', '$c, grazie per avermela riportata. Mi stavo giusto chiedendo come mai non avessi ricevuto notizie dalla Spedizione da così tanto tempo. Chissà a quando risale questo messaggio e cosa ha sopraffatto il suo portatore.$B$BEcco qualche moneta per il tuo disturbo.', 0),
(9383, 'itIT', '$N, mi congratulo con te. Il Cristallo di Contenimento sembra resistere, ma non sappiamo per quanto. Lo terremo d''occhio mentre ne prepariamo altri.', 0),
(9385, 'itIT', 'Ben fatto, $N. Quelle bestiacce avranno finalmente capito chi è che comanda!', 0),
(9394, 'itIT', 'Chi sei? Di certo non uno degli apprendisti del magistro!$B$BSuppongo ti abbiano mandato qui per aiutarmi a ripulire questo disastro!', 0),
(9395, 'itIT', 'Ah, la Magistra Albalunga si è finalmente degnata di rispondere alle mie semplici richieste. Dovrei denunciare il suo comportamento maleducato e insolente al Reggente di Lunargenta!$B$BMa torniamo a noi. Ora che sei qui, pensi che riuscirò a ricevere le provviste che stavo aspettando per il mio ricevimento?', 0),
(9398, 'itIT', 'Ottimo lavoro, $N. Essere costretti e togliere la vita è sempre spiacevole, anche nel caso di bestie pericolose come gli Sferzaroccia.$B$BTi ringrazio per aver portato a termine questo triste compito.', 0),
(9399, 'itIT', 'Ce l''hai fatta! $N, ti sono debitore. Guarda quanti Cappalercia stanno spuntando fuori!$B$BSotto la mia guida, impareranno tutto sul nostro vecchio stile di vita. Te lo prometto.', 0),
(9405, 'itIT', '$c, non dire altro: ho compreso la richiesta di Nazgrel.', 0),
(9409, 'itIT', 'Ottimo lavoro! Questo basterà a rigenerare i nostri cristalli curativi consumati.$B$BE visto che sei qui, se sei disponibile, avrei un altro incarico da affidarti.', 0),
(9415, 'itIT', 'L''Alleanza ha bisogno di tutti i soldati abili che trova. L''Orda riceve continui rinforzi dalla parte settentrionale del continente e tenere il passo è stata dura.$B$BLascia che ti spieghi la situazione.', 0),
(9417, 'itIT', 'Ottimo lavoro, $N! Ti proclamo ufficialmente Barbalunga onorario.$B$BResta con noi e bevi qualcosa, che ne dici?', 0),
(9418, 'itIT', 'Grazie a questo Globo, ho riconquistato la libertà. Ecco la tua ricompensa, mortale: il nostro debito è estinto.', 0),
(9420, 'itIT', 'Hai fatto la tua parte e io farò la mia!$B$BÈ tutto tuo, trattalo bene.', 0),
(9423, 'itIT', 'Sedai, mio caro fratello...$B$BOrchi vigliacchi! Era disarmato, come hanno potuto ucciderlo?$B$B$N, ti ringrazio per l''aiuto ma ora voglio rimanere da solo con i miei pensieri.', 0),
(9424, 'itIT', 'Sì... vendetta! Molto bene.$B$BPrendi questo: era un regalo di Sedai. Vederlo fa diventare triste Makuru.', 0),
(9426, 'itIT', 'Sento che la presenza demoniaca nelle Pozze si indebolisce.$B$BOttimo lavoro, $N.', 0),
(9427, 'itIT', 'L''essenza di Aggonar è sopravvissuta sotto forma della sua malvagia progenie: Aggonis. Ora che hai sconfitto il demone, possiamo lavorare per riportare le Pozze all''antica purezza.$B$B$N, grazie. Hai fatto davvero la differenza.', 0),
(9430, 'itIT', 'Sei molto fortunato. Hai trovato anche una reliquia speciale, proprio come speravo.', 0),
(9436, 'itIT', 'Ben fatto. Che cosa curiosa...$B$BL''iscrizione su questo totem è in una lingua che nessun Troll sarebbe mai in grado di imparare, ma che noi conosciamo. In essa viene nominato il proprietario, alleato di un Elementale dell''Acqua di nome Naias, e lo indica come degno di canalizzare il suo potere.$B$BChe cosa inaspettata, ma non del tutto negativa, $N. Vorrei che mi aiutassi ad andare più a fondo.', 0),
(9437, 'itIT', 'Ottimo lavoro, $N! Non appena Ithania si sarà ripresa e avrò completato i preparativi, lasceremo questa palude per tornare alla civiltà.', 0),
(9452, 'itIT', '$N, spero che i Murloc non ti abbiano dato troppo fastidio. Sono in debito con te per quello che hai fatto.$B$BForse potrei insegnarti l''arte della pesca? E ti regalerò anche una canna da pesca e un''esca.', 0),
(9454, 'itIT', 'Ben fatto, $N, ben fatto!$B$BEcco, tieni, ho cucinato alcuni filetti mentre eri via. Scommetto che vorresti anche la ricetta, eh?', 0),
(9455, 'itIT', 'Come ha fatto una cosa del genere a finire nello stomaco di un Cacciatore Furtivo? Che i detriti causati dall''impatto abbiano contaminato altre bestie?', 0),
(9456, 'itIT', 'Spero solo che non sia troppo tardi...', 0),
(9457, 'itIT', 'Riesco ad avvertire il potere puro contenuto in questa gemma, $N. La manderò a Lunargenta perché i nostri Magistri possano studiarla ulteriormente, ma sono piuttosto sicuro che si rivelerà utile nella nostra lotta contro gli Amani.$B$BIl tuo aiuto per recuperare questa gemma si è rivelato inestimabile e farò in modo che i Lungopasso ricordino il tuo nome $R: colui che ha reso possibile il ritrovamento.', 0),
(9490, 'itIT', 'Sì, ricordo questi artigli affilati!$B$B$N, accetta questa ricompensa: hai affrontato un grande pericolo e la meriti tutta!', 0),
(9498, 'itIT', '$R, benvenuta al Torrione del Falco! Tutti gli alleati dell''Orda sono ben accetti, soprattutto quelli raccomandati da Martik.', 0),
(9506, 'itIT', 'Sei davvero piena di risorse! Grazie all''attrezzatura nautica ora potremo scoprire di quanto abbiamo deviato dalla nostra rotta.$B$BUn momento, questo cos''è? C''è qualcosa arrotolato nella mappa. Vediamo...$B$BSono gli ordini del Magnate Trucirazzi della S.P.R. & Co. A quanto pare, dovevano sottrarre dall''isola tutti i frammenti di cristallo, quindi dirottare le nostre navi.$B$BPer la peluria frontale di Barbabronzea! È dunque per questo che ci hanno costretto ad attraccare? Come potevano conoscere la nostra rotta?$B$BSento puzza di traditori...', 0),
(9512, 'itIT', 'Benedetto sia il tuo cuore, straniero. Questo solleverà il morale a tutta la ciurma.', 0),
(9513, 'itIT', 'Lode a Elune! Finalmente gli spiriti avranno il riposo che meritano.', 0),
(9514, 'itIT', 'Non sono in grado di leggere queste rune, ma so chi potrebbe...', 0),
(9515, 'itIT', 'Ora che il Signore della Guerra Sriss''tiz è morto, le probabilità di un''invasione naga sono trascurabili. Siamo al sicuro, almeno per un po''...$B$B$N, devo ammettere di essermi sbagliata sul tuo conto. Hai dimostrato di non avere nulla in comune con quella feccia di Archimonde. Accetta questo dono da parte degli Elfi della Notte.', 0),
(9523, 'itIT', 'Mio padre sarebbe fiero! Il suo figliolo fa centro alle prime rovine elfiche che incontra... con il tuo aiuto, naturalmente. Sì, non preoccuparti, non mi prenderò i tuoi meriti. Ti chiami $N, giusto? A Forgiardente presto sapranno tutto di te.', 0),
(9527, 'itIT', 'Grazie, $N. Adesso i loro spiriti conosceranno la pace.', 0),
(9530, 'itIT', 'Devo avvisarti, $N: il tuo prossimo compito sarà pericoloso e non ti giudicherò male se non dovessi accettare.', 0),
(9531, 'itIT', 'Non posso crederci! Era lo Gnomo... Avrei dovuto capirlo!', 0),
(9537, 'itIT', 'Incredibile! Faceva tutto parte del loro piano!$B$BQuesta informazione deve giungere al re e ai tuoi capi. Le implicazioni sono sconvolgenti.', 0),
(9543, 'itIT', '$N, posso esserti d''aiuto? Sembri turbato.', 0),
(9544, 'itIT', '[Mezzorso] La profezia narrava di un eroe che sarebbe giunto a liberarci dall''oppressivo dominio dei Braccioirsuto... e che gli stessi spiriti ci avrebbero annunciato il suo arrivo.$B$BEd eccoti qua.$B$BMi prostro dinanzi a te, o grande!', 0),
(9545, 'itIT', 'Spero che la visione ti abbia aiutato a mettere nella giusta prospettiva la morte di Sedai. La Reliquia ti ha mostrato una serie di eventi probabili che conducono al presente. Forse le cose non sono andare a quel modo, non lo sapremo mai.$B$BSapendo ciò che sai ora, avresti agito in maniera diversa?$B$BChi può dire se il nostro conflitto con gli Orchi proseguirà? Ciò che importa davvero è aprirsi alle varie possibilità.', 0),
(9558, 'itIT', '$c, come hai fatto a trovarci? Non importa: immagino che tu sia qui per darci una mano. Allora mettiamoci al lavoro!', 0),
(9559, 'itIT', 'Per secoli abbiamo vissuto in pace con le creature della terra. Diversi mesi fa, però, Kurz ha iniziato a vedere oscuri presagi. La pace di cui abbiamo goduto finora sarebbe stata infranta e l''entità di questa catastrofe impossibile da decifrare!$B$BGli dei avrebbero scosso la nostra terra, spingendo sia gli alleati che i nemici contro di noi. Ma c''era anche qualcos''altro... Dal caos, sarebbe sorto un eroe: un eroe non di sangue Pinosaldo che ci avrebbe salvato dalla distruzione.$B$BL''eroe della profezia sei tu.', 0),
(9560, 'itIT', 'Non solo la profezia è vera, ma quest''armatura è fantastica! Di certo è un''armatura adatta a un campione! E io sono disposto a vendertela a un prezzo scontato, senza-peli.$B$BScherzo... Il primo pezzo è in omaggio.', 0),
(9562, 'itIT', 'Mmm... Che grano delizioso... Parkat sarà soddisfatto!', 0),
(9563, 'itIT', 'Sì! $r, direi che sei un tipo in gamba. Credo di potermi fidare di te.', 0),
(9566, 'itIT', 'Questi Cristalli di Sangue che hai visto... i miei esploratori si sono imbattuti in molti altri esemplari a nord.$B$BTi ringrazio per il tuo aiuto, ma ora devo chiederti di lasciarmi conferire con gli anziani del villaggio. Ti chiamerò dopo che mi sarò confrontato con loro.', 0),
(9567, 'itIT', 'Ben fatto, $N. Vediamo cosa posso ricavare da questo glifo, in modo da pianificare la nostra prossima mossa.', 0),
(9569, 'itIT', 'Senza il loro capo e senza i Cristalli Corrotti che presto finiremo di recuperare, i Satiri potranno essere tenuti a bada senza grandi difficoltà. Solo la Luce sa quante di queste dannate creature sono ancora là fuori.$B$BL''Araldo Mikolaas e io ti siamo grati per l''aiuto che ci hai fornito nel neutralizzare sul nascere la minaccia dei Satiri. Questo episodio ci ricorderà sempre che la chiave per vincere contro la Legione e i suoi seguaci è la vigilanza costante.', 0),
(9570, 'itIT', 'L''Eroina Promessa ha vinto!$B$BLa profezia si è realizzata quasi del tutto. Ora, riguardo a quella pelle...', 0),
(9571, 'itIT', 'Questa è l''armatura più resistente che abbia mai realizzato! Fanne buon uso, $N.', 0),
(9573, 'itIT', 'Questa potrebbe essere l''occasione che aspettavamo! Farò partire subito l''attacco! $N, i Pinosaldo ti ringraziano per i tuoi servigi!', 0),
(9574, 'itIT', 'Questi sono più che sufficienti per la mia ricerca. Grazie, $N. Nel caso ti imbattessi in altre creature locali contaminate dai cristalli, avvertimi immediatamente.', 0),
(9576, 'itIT', 'Curioso... Non credo di aver mai visto dei Murloc indossare un ornamento, di qualsiasi tipo.$B$BConsiderata la nota influenza corruttiva dei frammenti di cristallo, probabilmente il Murloc che lo indossava credeva gli conferisse un certo potere sugli altri del gruppo. Di fatto, potrebbe davvero esser diventato più grosso e forte dei suoi compagni Murloc.', 0),
(9580, 'itIT', 'Queste dovrebbero bastare per un po''. Inoltre, prepararle mi terrà certamente occupato. Grazie per il tuo aiuto, $N.', 0),
(9581, 'itIT', 'Poiché proviene da una delle regioni meno contaminate di Brumacremisi, questo frammento di cristallo farà da pietra di paragone per tutti gli altri campioni.$B$BNon vale la pena inviarlo ai nostri ricercatori finché non avrò anche gli altri campioni, ma è un buon inizio. Se sei disposta ad aiutarci a raccogliere anche gli altri, vedrò di ricompensarti per il disturbo.', 0),
(9594, 'itIT', 'Hai fatto bene a portarmela, $N. Senza dubbio, si tratta di un frammento dell''armatura di una Vilguardia.$B$BDunque è come temevo. I Satiri Nazzivus stanno riallacciando i rapporti con la Legione Infuocata. Se non li fermiamo, i Satiri e i loro alleati demoniaci ci annienteranno. Avverto immediatamente l''Araldo Mikolaas.', 0),
(9616, 'itIT', 'Per il capo geometrico e sbarbato di O''ros! $N, hai fatto bene a portarmi questo avviso. Dunque gli Elfi del Sangue vogliono... be'', il nostro sangue. Velen sarà subito informato! Intanto, tu accetta questa ricompensa.', 0),
(9622, 'itIT', 'Visioni, dici? Interessante... E questa profezia si è realizzata?$B$BMa tu dici che hanno visto il Nucleo Energetico della Exodar, e che anche O''ros fosse presente nella visione... Cosa può significare?', 0),
(9624, 'itIT', 'Hai avuto difficoltà a trovarle? Ogni volta per me diventa sempre più difficile.$B$BPresto dovrò smettere del tutto, perché non potrò permettermi di perdere tutto quel tempo. Intanto grazie per aver raccolto queste, $N: mi hai dato la possibilità di preparare un''ultima torta prima della fine della stagione.', 0),
(9625, 'itIT', 'Be'', visto che sei arrivata sin qui, ti diamo subito qualcosa da fare.', 0),
(9629, 'itIT', 'Ben fatto, $N. Temevo che il Marcatore non funzionasse, ma a quanto pare tutto è andato secondo i piani.', 0),
(9634, 'itIT', 'Ben fatto, $N. I devastatori dovranno comunque essere tenuti d''occhio per qualche tempo, ma è un buon inizio.', 0),
(9636, 'itIT', 'Magnifico! E diciamolo, quando mai un ingegnere ha delle parti che gli avanzano? Oh oh! Forse posso vendere quelle di troppo e acquistare un po'' di Gelato alla Fragola di Tigule e Foror. Adoro le fragole! Pensi che qui ne crescano?$B$BVa bene, va bene. L''hai meritato, $N. Divertiti!', 0),
(9641, 'itIT', 'Ben fatto. Con questi potrò ricreare degli altri cristalli purificati.$B$BQuanto a te, puoi scegliere un cristallo tra i tipi che riesco a ricomporre. Ciascuno di essi è utile per cacciare un certo tipo di preda.', 0),
(9642, 'itIT', 'Molto bene. Ecco i miei cristalli, $N. Fanne buon uso.', 0),
(9643, 'itIT', 'Bene, sembrano sufficientemente robuste per i nostri fini. Grazie per il tuo aiuto, $N. Il tuo contributo alla difesa del Presidio Vermiglio non passerà inosservato.', 0),
(9646, 'itIT', 'Ben fatto. Da quel che ho sentito su quell''orso, non dev''essere stata una lotta facile. $N, ti sei più che guadagnata la tua ricompensa.', 0),
(9663, 'itIT', 'Ben fatto, $N. Non era una prova facile, ma l''hai superata brillantemente. Occorre superare molte prove simili prima di poter diventare membro della Mano di Argus.', 0),
(9667, 'itIT', 'Ancora una volta hai dimostrato che la profezia diceva il vero, $N. A te va l''eterna gratitudine del Gran Capo... e una di queste Reliquie dei Pinosaldo.', 0),
(9668, 'itIT', 'Me lo sentivo che saresti giunta fin qui, $c. Se desideri continuare, io sono disposto a insegnarti.', 0),
(9694, 'itIT', 'Sei tornata... e tutta intera!$B$B$N, ho una buona notizia. Abbiamo ricevuto informazioni sulla posizione di altri superstiti: è stato scoperto un altro punto d''impatto! Non appena avrò finito di occuparmene, tornerò a farmi vivo.', 0),
(9697, 'itIT', 'Molto bene... era ora che mi inviassero un aiuto! C''è talmente tanto da fare e io devo stare qui a organizzare tutto.$B$BSpero che tu non abbia paura di sporcarti le mani.', 0),
(9701, 'itIT', 'Cosa?!? I Signori del Pantano di Cresta Boleta stanno MANGIANDO i baccelli degli Sporiani? Non è una bella notizia!', 0),
(9702, 'itIT', 'Che stranezza. I resti di questi funghi sono allo stesso tempo insoliti e familiari.$B$BMi serve un po'' di tempo per rifletterci sopra. Tu, intanto, non andartene.', 0),
(9704, 'itIT', 'La staffetta è stata derubata di tutto tranne che di un pacco, che corrisponde alla descrizione del pacco di Erona fatta da Alarion.', 0),
(9705, 'itIT', 'Per il Pozzo Solare! È la terza staffetta che perdiamo questo mese.$B$BApprezzo il coraggio che hai dimostrato avventurandoti nel Viale dell''Alba. Le guardie devono stare più attente a questi dannati Miserabili.', 0),
(9708, 'itIT', 'Ora quadra tutto. La presenza e le azioni degli Ogre spiegano quello che sta succedendo. Ho capito perché la chiamano la Palude di Fungomozzo!$B$BDobbiamo fare qualcosa, ma cosa? Potremmo semplicemente eliminare tutti gli Ogre, ma anche loro hanno diritto di stare lì come tutte le altre creature delle paludi!', 0),
(9709, 'itIT', 'Perfetti! Grazie, $c!$B$BSei stato veramente attento a non alterare i delicati equilibri della natura e abbiamo raccolto così tanti dati in così poco tempo!$B$BOra dobbiamo solo verificare se il nostro piano per dare ai Signori del Pantano una nuova fonte di cibo avrà successo.', 0),
(9716, 'itIT', 'È colpa dei Naga! Perché stanno facendo questo? Da quello che racconti, sembra che la diminuzione del livello delle acque delle paludi dipenda dalla Pompa del Vapore!$B$BQuesto spiega anche perché ci sono così ostili. Non c''è tempo da perdere, abbiamo ancora bisogno del tuo aiuto.', 0),
(9718, 'itIT', 'È come sospettavo. I Naga hanno costruito delle stazioni di pompaggio su tutti i laghi più grandi delle Paludi di Zangar.$B$BSe vogliamo dare un futuro alle paludi, dobbiamo fermarli!', 0),
(9720, 'itIT', 'Allora ce l''hai fatta. Per ora le paludi sono al sicuro.$B$BNon sperare che questa sia l''ultima volta che sentiamo parlare dei Naga. Dobbiamo rimanere vigili, mentre proseguiamo la nostra missione nelle Terre Esterne.', 0),
(9724, 'itIT', 'Le notizie che porti sull''attività dei Naga nelle Paludi di Zangar sono terribili. Ysiel è stata saggia a contattarci. Non ha dimenticato che la spedizione non esisterebbe senza il supporto del Circolo.', 0),
(9728, 'itIT', 'Buon lavoro, $N. Faresti bene a sopprimere i sentimenti di rimorso che ti affliggono. I Naga sono creature malvagie, anche più di quelli di Azeroth.', 0),
(9729, 'itIT', 'Fhwoor è un gigante buono. Qualche tempo fa lo abbiamo salvato dai Naga e da allora è rimasto con noi per aiutarci.$B$BPossiamo solo sperare che i Naga capiscano che se siamo riusciti a penetrare nel loro villaggio e a rubare il loro oggetto più prezioso, possiamo fare ben altro. Magari ora torneranno nel loro Bacino Idrico e ci lasceranno in pace.', 0),
(9730, 'itIT', 'Non mi piacciono i Naga di Azeroth e tanto meno mi piacciono questi qui. È un peccato che la nostra missione non possa essere pacifica, ma non mi vedrai certo versare lacrime per un Naga morto.$B$BEccoti la ricompensa per aver ucciso il capo dei Crestascura, $N.', 0),
(9731, 'itIT', 'I Naga hanno trasformato il Lago dei Serpenti in un gigantesco scolo delle acque delle Paludi di Zangar. Che cosa staranno facendo?$B$BHai fatto bene a portarci le informazioni, $N. Invieremo subito una squadra a investigare sullo scarico che hai scoperto. Nel frattempo ho un altro compito da assegnarti.', 0),
(9732, 'itIT', 'Felice di rivederti, $N. Da quando sei andato via, le cose non hanno fatto che peggiorare al Rifugio Cenariano.', 0),
(9739, 'itIT', 'Ce l''hai fatta? Hai la gratitudine di tutto il mio popolo.$B$BSpero che tu capisca... i nostri giovani nascono da qui. Non possiamo permettere a quelle bestie di divorare i sacchi!', 0),
(9743, 'itIT', 'Ce l''hai fatta! Parlerò di te con gli altri Sporiani! $N, il cacciatore di giganti!', 0),
(9747, 'itIT', 'Grazie, $N. Finalmente dormirò più sereno. Non fossi stato così vecchio e indebolito, avrei affrontato io stesso i miei nemici.$B$BPrendi quest''oro. Non è molto, ma la tua gentilezza va ricompensata.', 0),
(9752, 'itIT', 'Hai salvato una delle mie Druide. Non so come ringraziarti, $N.$B$BHai la mia gratitudine e quella di tutta la spedizione.', 0),
(9758, 'itIT', 'Ah, bene, eccoti qui! Sei arrivato giusto in tempo... abbiamo parecchie cose da fare!', 0),
(9776, 'itIT', 'Se l''Anacoreta Ahuurn ti considera un amico, allora devi essere degno di fiducia. Ti prego di perdonare la mia diffidenza, $r, ma spesso è l''unica arma che si frappone tra la mia gente e la morte. Sei il benvenuto tra noi... e probabilmente con il tempo la fiducia reciproca crescerà.', 0),
(9777, 'itIT', 'Sono delle ottime spore e ci basteranno per un bel po'' di tempo. Grazie per averci aiutato a rifornire le nostre riserve, $N.', 0),
(9778, 'itIT', 'Ti ha mandato Ysiel? Certo che mi tornerai utile! C''è sempre bisogno di un paio di braccia forti in più.', 0),
(9780, 'itIT', 'Grazie dell''aiuto, $N. Non dimenticheremo mai la tua generosità.', 0),
(9781, 'itIT', 'Ben fatto. In questo modo, nell''immediato futuro diminuirà la domanda di cibo nei dintorni... anche se dobbiamo darci da fare per cercare delle nuove fonti di sussistenza. Pesce e funghi sono sufficienti, ma la varietà non deve essere mai sottostimata.', 0),
(9782, 'itIT', 'Mmm, il suolo sembra essere esaurito, quindi non può essere l''origine del problema, come pensavo. E allora quale elemento ci manca per svelare la causa di tutta questa morte?', 0),
(9783, 'itIT', 'Ti ringrazio per l''aiuto che mi stai dando con questo difficile compito, $N. Non abbiamo ancora finito con Melmamorta, ma ora possiamo concentrarci su come recuperare l''area.', 0),
(9785, 'itIT', 'Sei tornato. Hai ricevuto la benedizione degli antichi?', 0),
(9786, 'itIT', 'I Perduti Limofurioso hanno conquistato le rovine? Curioso. Forse ricordano qualcosa del loro retaggio e del significato di quel luogo. Dobbiamo saperne di più, $N. Il tempio potrebbe nascondere la chiave per redimere i Perduti e riunire i molti rivoli dei Draenei.', 0),
(9787, 'itIT', 'Dovrebbero bastare, $N. Sembrano essere ossessionati dagli uccelli. Strano, visto che non esistono specie di uccelli native delle Paludi di Zangar. Cosa può voler dire?$B$BChe abbiano incontrato un Arakkoa? Sono un popolo di Sciamani e potrebbero averlo scambiato per l''incarnazione di un potente Uccello Spiritico.', 0),
(9788, 'itIT', 'Le mie cose! Ci sono tutte!$B$BTi ringrazio, $N. Come promesso, ti regalerò uno dei miei oggetti. Non ho molto da offrire, ma la mia gente condivide sempre ciò che ha... per poco che sia.', 0),
(9789, 'itIT', 'Un buon inizio. Ma è solo il primo passo.$B$BI mammuceronti piccoli non dimostrano nulla. È ora che affronti una sfida maggiore.', 0),
(9792, 'itIT', 'Considero Ikuti come un fratello. Se sei una sua amica allora qui sei la benvenuta, $N, e hai la nostra gratitudine per aver aiutato la nostra gente.', 0),
(9793, 'itIT', 'Mmm... Ricordo di aver sentito i nostri esploratori parlare delle rovine degli insediamenti Draenei nella foresta, al confine settentrionale. Personalmente non conosco molto le rovine, ma puoi parlare con uno degli esploratori per saperne di più.', 0),
(9799, 'itIT', 'Sembrano degli ottimi campioni. Grazie per aver eseguito il lavoro sul campo. Una volta trovato il tempo di esaminarli, dovrei essere in grado di dire cosa andrà fatto per ripristinare i Campi di Ammen.', 0),
(9801, 'itIT', 'Andranno benissimo. Dammi un momento per mescolare la pozione.', 0),
(9803, 'itIT', 'Hanno rifiutato? Ovviamente sono liberissimi di seguire la loro strada, ma la loro scelta mi sorprende. Pensavo che tutti i $R, anche i Corrotti e i Perduti, ricordassero di essere parte di un solo popolo.$B$BCerto, comprendo che sia stata una follia il tentativo di ingannarli, ma come ha fatto a non comprendere che le nostre intenzioni erano buone?', 0),
(9805, 'itIT', 'Le tue gesta hanno fermato la diffusione dell''inquinamento, ma sono insorti altri problemi.', 0),
(9806, 'itIT', 'Sono delle ottime spore, $N! Gli Altostelo sono vitali per ricostruire la nostra città, ma ne siamo a corto a causa degli attacchi dei Signori del Pantano.', 0),
(9808, 'itIT', 'Questi ci aiuteranno a commerciare con gli altri Sporiani. Sporeggar ti è grata, $N.', 0),
(9810, 'itIT', 'Gli elementi hanno annunciato la tua vittoria nel momento in cui l''essenza corrotta è stata distrutta! Il Circolo della Terra ti ringrazia e desidera che tu scelga una ricompensa.', 0),
(9811, 'itIT', 'Così hai ucciso Dar''khan, $R? Notevole. Ho la sensazione che i nostri popoli presto saranno ottimi amici.', 0),
(9815, 'itIT', '$N, il Circolo della Terra ti ringrazia. Così come gli elementi. I tuoi continui sforzi per purificare il nostro mondo sono molto apprezzati e tenuti in considerazione.', 0),
(9817, 'itIT', 'Ora gli Scagliacremisi ci penseranno due volte prima di attaccare di nuovo gli esploratori della spedizione. Prendi la ricompensa, $N. Te la sei meritata.', 0),
(9827, 'itIT', 'Sembra il basidio di un Gigante del Pantano, ma non ne avevo mai visto uno in queste condizioni. Avevo sentito che i Giganti di Melmamorta avevano iniziato ad avvizzire, ma questo è in uno stato peggiore di quanto mi aspettassi.$B$BUn tempo Melmamorta era un lago simile agli altri della palude, dove i funghi giganti trovavano terreno fertile per crescere. Con il recedere delle acque, sembra che non riescano più a produrre spore. Se continua così, potrebbero scomparire del tutto.', 0),
(9830, 'itIT', 'Grazie per avermelo portato, $N. Sarà di grande aiuto per dimostrare l''utilità del veleno senza consumare tutte le mie riserve.', 0),
(9833, 'itIT', 'Ottima notizia. La strada non è ancora sicura, ma ora i messaggeri troveranno il modo di passare indenni.', 0),
(9834, 'itIT', 'Maktu pensa che sono delle buone pelli. Diventeranno un''ottima armatura.$B$BChi lo sa? Magari ne avanzeranno un po'' e Maktu potrà fare un''armatura anche per i Draenei.', 0),
(9835, 'itIT', 'Per ora la minaccia degli Ango''rosh è rientrata, ma sono certo che torneranno presto all''attacco. Ho dimenticato molte cose della mia vita da Draenei, ma non la testardaggine degli Ogre.', 0),
(9839, 'itIT', 'Finalmente! Hai la nostra gratitudine per l''aiuto che ci hai dato nel difendere il Rifugio di Orebor. Farò in modo che il racconto delle tue gesta giunga a Telaar, la città dei Kurenai nella regione di Nagrand. La nostra gente avrà molte opportunità di collaborare.', 0),
(9849, 'itIT', 'Gurok! Gurok tradisce elementi!', 0),
(9850, 'itIT', 'Notevole. Molto notevole.$B$BHai del potenziale. Adesso ti darò la possibilità di divertirti davvero!', 0),
(9851, 'itIT', 'Ce l''hai fatta! Hai abbattuto Banthar! Non ho mai avuto dubbi, $N.$B$BEcco, credo che la tua ricompensa sia ben meritata.', 0),
(9852, 'itIT', '$N! Tu infondi gioia al cuore di questo vecchio Nano.$B$BHai dimostrato il tuo valore e ora fai parte dell''élite! Altri sono scappati terrorizzati o sono morti, schiacciati dalle zampe della bestia. Tu hai usato intelligenza, astuzia e determinazione per dimostrare la tua supremazia nella caccia.$B$BPrendi. E sappi che ti accoglierò sempre a braccia aperte quando vorrai cacciare con me!', 0),
(9854, 'itIT', 'Ogni giorno è un dono. Godine al massimo. Poiché domani avanzeremo ancora più rapidamente lungo le piane di oggi. Apriremo ancora di più le braccia e cercheremo di ottenere ciò che stanotte possiamo solamente sognare, pur sapendo che potremmo non riuscirci.', 0),
(9855, 'itIT', '$c, hai nuovamente dimostrato la tua abilità. Ora devi dare la caccia al più feroce dei Grifalchi.', 0),
(9856, 'itIT', 'Il suo occhio sembra ancora vivo. Credi che possa ancora vedere nella tua anima?$B$B$N, ora puoi considerarti parte dell''élite di cacciatori del bivacco. E ti avvicini sempre più alla preda più pericolosa si questa terra, Tusker!$B$BQuesto è tuo di diritto. Spero ti torni utile.', 0),
(9859, 'itIT', 'Caspita! Ce l''hai fatta! È davvero lo zoccolo di Bach''lor''s!$B$BEhm, sembra che io cominci a sentirmi meglio. Ecco, lascia che ti dia qualcosa per celebrare la tua abilità nella caccia!', 0),
(9861, 'itIT', 'È una richiesta d''aiuto, $r. Una forza esterna sta tentando di sovvertire gli elementi.', 0),
(9863, 'itIT', '$N, hai dato speranza ai Figli dei Fulmini. Se il nostro capo non ci protegge, forse ci sono altri in grado di farlo. Come te.', 0),
(9864, 'itIT', 'Mi hanno narrato storie sulla mia gente. Dicono che un tempo eravamo guerrieri...', 0),
(9867, 'itIT', 'Quindi, questo è il volto del nostro nemico? Lo farò piantare su una picca e collocare fuori Garadar, vicino ai cancelli. Qualora decidessero di attaccarci ancora, dovranno guardare negli occhi le conseguenze delle loro azioni...', 0),
(9868, 'itIT', 'Cosa importa? La Madre Anziana sta morendo. Non vale la pena vivere ancora...', 0),
(9869, 'itIT', 'Ah, grazie del messaggio. Mi chiedo se non ti andrebbe di aiutare il Circolo della Terra. Gli elementi sono in flusso. Possiamo avere tutto l''aiuto che ci serve.', 0),
(9870, 'itIT', 'Ah, grazie del messaggio. Mi chiedo se non ti andrebbe di aiutare il Circolo della Terra. Gli elementi sono in flusso. Possiamo avere tutto l''aiuto che ci serve.', 0),
(9878, 'itIT', 'Dubito che gli Orchi capiranno o apprezzeranno ciò che hai appena fatto, ma Nagrand ne ha giovano molto. Grazie per aver risolto il problema...', 0),
(9879, 'itIT', 'Sì, conosco il Totem... Ma la storia nasconde ben altro. Tuttavia, non possiedo l''autorità per rivelarti tali informazioni. Solo i prescelti possono esserne messi a conoscenza.', 0),
(9882, 'itIT', 'Sono colpito. Per la maggior parte, sono in condizioni eccellenti.$B$BMetterò una buona parola con la nostra gente.', 0),
(9889, 'itIT', 'Lascia vivere me e dirò tutto quello che tu vuole!', 0),
(9890, 'itIT', 'Rallenta, $N. Sono solo un misero ladro. Non so che fare con queste informazioni.', 0),
(9891, 'itIT', 'Così pensano che sia loro diritto scacciare e massacrare gli Orchi per un capriccio, eh? Di certo non ha niente a che fare con il fatto che il nostro capo è un codardo impotente... Se solo avesse una frazione dell''ardore di suo padre...', 0),
(9893, 'itIT', 'Eccellente. Questo ci farà restare in affari mentre aspettiamo che gli Sha''tar finiscano di fare quello che hanno bisogno di fare dentro a Oshu''gun.', 0),
(9894, 'itIT', 'Hai la mia gratitudine e quella degli altri custodi, $N. Saranno rincuorati di sapere che possono continuare i loro studi a sud senza il pericolo di essere attaccati.', 0),
(9895, 'itIT', 'Ora che hai visto con i tuoi occhi i sintomi dello squilibrio, tienili bene a mente durante i tuoi viaggi.', 0),
(9897, 'itIT', 'Be'', non ho visto se hai aiutato o meno a salvare Kristen, ma se ti ha dato uno dei suoi mucchi di pelli, allora per me sei a posto.$B$BEcco la tua ricompensa.', 0),
(9900, 'itIT', 'Non dovremo più preoccuparci di Gava''xi, grazie a te. Adesso pensiamo alla ricompensa.', 0),
(9901, 'itIT', 'Ben fatto, $N. Credo che tu e io siamo riusciti a offuscare un''intera squadra di Prospettori. Quando tornerò a Forgiardente, sono sicuro che potrò scegliermi il mio prossimo incarico.', 0),
(9902, 'itIT', 'Grazie, $N. Magari un giorno, con l''aiuto dei Draenei, riusciremo a liberare questa palude dai Naga. Non voglio nemmeno immaginare cosa debba essere servirli.$B$BAnche se non ne parla spesso, un tempo Maktu era uno schiavo.', 0),
(9903, 'itIT', 'Sono sicura che il guaglione sapeva che i giorni suoi erano giunti al termine. Con tutti quanti i nuovi arrivi, l''ordine vecchio nun poteva durare. È meglio che lo spirito suo riposi.', 0),
(9906, 'itIT', 'La nostra missione non è ancora finita. Dobbiamo dare una lezione anche a qualcun altro!', 0),
(9907, 'itIT', 'Se neanche questo gli farà gelare il sangue nelle vene, allora nulla lo farà. $N, hai reso giustizia ai Mag''har. E i Mag''har ricompensano bene la giustizia.', 0),
(9910, 'itIT', 'Forse desideri un altro incarico? Uno più delicato, eh?', 0),
(9911, 'itIT', 'Sei sicura che sia reale? Voglio dire, sapevo che nella palude ci sono degli animali cresciuti, ma ci sono creature giganti e insetti GIGANTI.$B$BPensandoci bene, gli Sporiani parlavano di una Manta Fatua che li terrorizzava prima dell''incursione dei Signori del Pantano.$B$BE se tutte quelle storie fossero vere? Oh. La terrò io in custodia e informerò la spedizione di questa scoperta.', 0),
(9912, 'itIT', 'Benvenuto al Rifugio Cenariano, $N. Spero che tu sia qui per aiutarci con la nostra missione. C''è molto lavoro da fare.', 0),
(9913, 'itIT', 'Pronto a lavorare, $R? Credo di avere l''incarico perfetto per te.', 0),
(9914, 'itIT', 'Non ho mai avuto dubbi su di te. Sembrano tutti in ottime condizioni, a parte un po'' di polvere e qualche graffio. Comunque, ritengo che valgano quanto avevamo concordato.$B$BSpero che potremo continuare a fare affari in futuro.', 0),
(9916, 'itIT', 'La maggior parte dei nostri possedimenti è andata distrutta o è stata rubata durante gli attacchi. Non posso offrirti molto, ma ci sono degli oggetti che ti potrebbero tornare utili.', 0),
(9918, 'itIT', 'Santo cielo! Si tratta di un piccolo gruppo di ricognizione e caccia? Devi dire a Mo''mor cos''hai scoperto.', 0),
(9919, 'itIT', 'Ci hai aiutato a proteggere la prossima generazione di Sporiani, $r. L''unico modo che abbiamo per ringraziarti è darti il benvenuto nelle nostre case. Rimani un po'' tra noi e parla con gli altri Sporiani. Ti faranno molte domande, ma spero che non ti dispiaccia.', 0),
(9921, 'itIT', 'Eccellente. Hai individuato questo Lantresor che era menzionato nella lettera dello stupido?$B$BIn ogni caso, non dobbiamo fermarci. Ho ricevuto rapporti su altri Ogre che devono essere sistemati subito!', 0),
(9922, 'itIT', 'Eccellente lavoro! Sto facendo ricerche sulla Tribù Fortemaglio di cui aveva parlato il Tenente dei Rocciadura. Ora le tue imprese devono essere messe alla prova.', 0),
(9923, 'itIT', 'Mi dispiace molto, $R. Continua a cacciarsi nei guai. Vorrei potergli mettere un guinzaglio...', 0),
(9924, 'itIT', 'Grazie infinite, $N. D''ora in avanti, si occuperà sua madre di lui.', 0),
(9925, 'itIT', '$N, tu mi fai sorridere. O meglio, lo faresti se avessi un volto.$B$BContinua così e diventeremo molto amici.', 0),
(9927, 'itIT', 'Riesci a immaginare la loro confusione su quanto sta succedendo, $R? Sarà favoloso.', 0),
(9928, 'itIT', 'Eccellente! Il nostro prossimo bersaglio sono le Rovine dei Teschio Ridente.', 0),
(9931, 'itIT', 'Il piano è perfetto, $N. Vedo già i frutti del tuo lavoro.', 0),
(9932, 'itIT', 'Devo ammetterlo, non mi sentivo così vivo da anni. Hai dimostrato grande abilità, $N.', 0),
(9933, 'itIT', 'Ti prego, $N, prendi ciò che desideri dall''offerta di pace. Dopotutto, senza i tuoi sforzi, tutto ciò non sarebbe stato possibile.', 0),
(9935, 'itIT', 'La Vecchia è stata uccisa! Che notizia meravigliosa, $N. Ecco la tua ricompensa.', 0),
(9936, 'itIT', 'La Vecchia è stata uccisa! Che notizia meravigliosa, $N. Ecco la tua ricompensa.', 0),
(9937, 'itIT', 'La stretta sanguinosa di Durn è svanita! Un futuro migliore aspetta Nagrand grazie a te. Ben fatto!', 0),
(9938, 'itIT', 'La stretta sanguinosa di Durn è svanita! Un futuro migliore aspetta Nagrand grazie a te. Ben fatto!', 0),
(9939, 'itIT', 'Questa è una grande vittoria per la gente di Garadar! Ben fatto, $N!', 0),
(9940, 'itIT', 'Questa è una grande vittoria per la gente di Telaar! Ben fatto, $N!', 0),
(9944, 'itIT', 'Trenta Orchi, $r! Di quei trenta, solo Ungriz e io siamo sopravvissuti. Abbiamo trovato il giovane Orco Faucisaure in fin di vita vicino a Solenuovo. Sembra che fosse lì per un altro motivo...', 0),
(9945, 'itIT', 'È un buon inizio, ma il loro capo dev''essere eliminato se vogliamo che si ricordino per sempre delle tue azioni.', 0),
(9946, 'itIT', 'Infilzeremo questa testa sui cancelli di Garadar in modo che tutti possano vederla. Gli Ogre ci penseranno due volte prima d''interrompere i riti sacri Mag''hari.', 0),
(9948, 'itIT', 'Hai compiuto l''impossibile e hai riportato i nostri fratelli e le nostre sorelle disperse. $N, sei una leggenda per i Mag''har. Tutti conosceranno il tuo nome e le gesta compiute per aiutarci.', 0),
(9954, 'itIT', 'Questa volta, mi hanno rinchiuso per bene, $N. Cho''war, il re dei Fortemaglio, ha la chiave.', 0),
(9955, 'itIT', 'Grazie, $N. Corki è stato mandato a vivere con gli Elfi della Notte a Spinaguzza. Spero che riescano a tenerlo fuori dai guai.$B$BA proposito di quella ricompensa...', 0),
(9956, 'itIT', 'Incredibile! Come ha trasportato tutto quanto fino a qui senza aiuto?', 0),
(9957, 'itIT', 'Sono felice che ti abbiano mandato dal rifugio. I Druidi della macchia sono stati massacrati! Siamo sopravvissuti solo io e un altro... che è pazzo.$B$BNon so cosa sia successo, ma voglio scoprirlo. Qualunque cosa fosse... è avvenuta in fretta e non sembrava naturale.$B$BVuoi aiutarmi?', 0),
(9968, 'itIT', 'Che strano. I campioni degli esemplari malvagi sono infusi con quello che mi sembra essere puro mana.$B$BA quanto pare qualunque cosa abbia provocato tutta questa morte è anche dietro a questo forte campo di energia residua. Ma per qualche ragione le falene di Terokk non sono morte, ma solo cadute in uno stato di agitazione.$B$BSembra che questa strana energia sia una specie di effetto collaterale prodotto da ciò che ha attaccato la macchia.', 0),
(9971, 'itIT', 'Dunque avevo ragione. Era il cadavere di un Corrotto? E confermi che c''era uno strano oggetto per terra accanto a lui?$B$BNon ha senso. Che ci faceva un Corrotto qui? E cosa aveva con sé?$B$BÈ la causa di tutta questa morte?', 0),
(9978, 'itIT', 'Va bene, va bene... ti dirò quello che so... ma non è molto!', 0),
(9979, 'itIT', 'Sì? Come posso aiutarti oggi, $r?', 0),
(9983, 'itIT', 'Il mio aspetto ti disturba? Sai che cosa sono?', 0),
(9986, 'itIT', 'Ben fatto, $N. Abbiamo già troppe cose di cui preoccuparci, senza dover vivere con l''ansia che gli Arakkoa attacchino i nostri mercanti e i nostri messaggeri.', 0),
(9990, 'itIT', 'Eterei? Merce consegnata a Tuurem? Parti meccaniche esotiche? E un Elfo del Sangue che si prepara a consegnare quest''ultima scatola al Presidio di Alardente?$B$BChe significa tutto questo?!? E qual è la correlazione con ciò che è avvenuto ai Druidi alla Macchia Cenariana?$B$BCredo che dovremmo guardare all''interno di quella scatola.', 0),
(9991, 'itIT', 'Eccellente lavoro, $N! Adesso possiamo pianificare il nostro contrattacco.', 0),
(9992, 'itIT', 'Grazie per avermi portato questi semi. Ne ho quasi abbastanza per la prima spedizione!', 0),
(9993, 'itIT', 'È un buon inizio, ma se vogliamo ricavare una buona quantità di olio ce ne serviranno altri!', 0),
(9994, 'itIT', 'Oh no! È una notizia orribile! Non posso credere che tutti i nostri amici cenariani, tranne due, siano morti.$B$BVa bene, vediamo questi componenti. Spero solo che non siano ciò che penso.$B$BSì, come temevo si tratta di parti di una bomba. Le nostre spie a Shattrath ci hanno riferito che alcuni Eterei stanno importando merci proibite da altre dimensioni parallele con cui sono in contatto.', 0),
(9996, 'itIT', 'È un buon inizio, ma stando a quanto hai visto lì nella corte interna, nonché alle informazioni che ho ricevuto, abbiamo una questione molto più urgente da risolvere!', 0),
(9999, 'itIT', 'È come sospettavo. Non esistono modi convenzionali per distruggere il Vilacciaio. Ma non tutto è perduto...', 0),
(10001, 'itIT', 'Con un po'' di fortuna, la mia conoscenza saprà come distruggere le Fornaci. Dopotutto, era un ingegnere della Legione...', 0),
(10004, 'itIT', 'Calma, occhi chiari! Sal''salabim ti aiuterà.', 0),
(10005, 'itIT', 'Una bomba che utilizza mana allo stato puro in grado di spazzare via intere città! Ma perché? Perché gli Elfi del Sangue dovrebbero creare una cosa del genere e usarla su di noi? La Macchia Cenariana era un luogo di pace e tranquillità.$B$BQualunque sia la ragione, essa risiede nella testa del Custode Ramos e io non ho idea di come curarlo. Forse la sua mente guarirà col tempo?$B$BA ogni modo, voglio ringraziarti per avermi aiutato a capire cos''è successo. Posso solo sperare che questa tragedia non si verifichi mai più!', 0),
(10007, 'itIT', 'La situazione inizia a migliorare. Credo che riusciremo a impedire ai Vilorchi di inviare rinforzi qui. Potremmo riuscire a mantenere il controllo di quest''avamposto.', 0),
(10009, 'itIT', 'Ehi, patto è patto. Ma quando Sal''salabim ti dice, tu non arrabbia, va bene?', 0),
(10010, 'itIT', 'Ma certo! Rivolgeremo le loro armi contro loro stessi!', 0),
(10011, 'itIT', 'Abbiamo vinto! I progressi della Legione sono stati fermati!$B$BTi offro una ricompensa per le tue gesta eroiche!', 0),
(10018, 'itIT', 'Sono perfette, $N! Non avrei potuto chiedere di meglio.', 0),
(10020, 'itIT', 'Grazie, $N. È faticoso prendersi cura dei bisognosi, ma col passare del tempo ho scoperto che è molto gratificante.', 0),
(10021, 'itIT', 'Hai la mia gratitudine, $N. Siamo i Custodi della Luce e non possiamo tralasciare le nostre responsabilità, anche nei momenti di maggiore difficoltà.', 0),
(10022, 'itIT', 'Mi inchino alla tua abilità, $N. Hai dimostrato di saper cacciare meglio di me.$B$BNon dimenticherò che mi hai aiutato a creare questo mantello. Sarà un pezzo davvero unico e lo indosserò con orgoglio.', 0),
(10028, 'itIT', 'Spero che non siano le uniche urne intatte in città. È un buon inizio, ma temo che ce ne serviranno molte altre.', 0),
(10031, 'itIT', 'Hai fatto ciò che andava fatto, non c''è nulla da perdonare. Sebbene mi rattristi sapere che si erano trasformati in orribili non morti, grazie al tuo intervento... ora riposano in pace.$B$BGrazie per averli liberati, $N. Accetta un piccolo segno della mia riconoscenza per te e la tua abnegazione.', 0),
(10035, 'itIT', 'Sono piuttosto colpita, $c. Torgos era una delle creature più potenti che io conoscessi in questa parte della Foresta di Terokk.$B$BBene, immagino che questo valga quanto qualcosa proveniente dal tesoro della Fortezza di Alleria. Scegli pure.', 0),
(10037, 'itIT', 'Grazie! Non ricordo quand''è stata l''ultima volta che ho mangiato delle anguille!$B$BCome le cucino?', 0),
(10038, 'itIT', 'Era ora che si facesse vivo qualcuno. Ho inviato quel rapporto alla Fortezza di Alleria più di una settimana fa!$B$BDannata burocrazia!', 0),
(10040, 'itIT', 'Rieccoti, finalmente! Bene. Cos''hai scoperto? Chi sono?', 0),
(10042, 'itIT', 'Sono notizie davvero terribili! A quanto pare ho fatto bene a inviarti in aiuto di Weeks. L''ultima cosa che vogliamo è il Concilio dell''Ombra alle nostre porte!$B$B$N, come ricompensa per i tuoi sforzi a Grangol''var, ti concedo il diritto di scegliere uno qualsiasi di questi oggetti come ricompensa.', 0),
(10047, 'itIT', '$N, ti ringrazio dal profondo del mio cuore. C''è ancora molto da fare, ma mi rallegra sapere che abbiamo donato il meritato riposo ad alcuni fratelli.', 0),
(10050, 'itIT', 'I Figli apprezzano i tuoi sforzi, anche se pochi vogliono parlare dei Bastioni.', 0),
(10051, 'itIT', 'Isla Crinostella è appena andata via, ma mi ha spiegato in dettaglio cosa succede al Presidio di Alardente. È comprensibile che sia piuttosto sconvolta per quello che è accaduto alla Macchia Cenariana. Maledetti Elfi del Sangue!$B$BMi ha detto che senza di te non si sarebbe mai salvata e noi non avremmo ricevuto queste informazioni. La Fortezza di Alleria è in debito con te.$B$BTi prego, accetta questo dono da parte nostra.', 0),
(10055, 'itIT', 'Sono in condizioni migliori di quanto pensassi! Ovviamente, ci vorrà un bel po'' di lavoro per togliere tutta la ruggine, il carbone e così via... ma non mi lamento.', 0),
(10057, 'itIT', 'Possiamo solo sperare che, calmando i fantasmi degli ufficiali, anche gli spiriti dei fanti troveranno pace. $N, grazie ancora per il tuo aiuto.', 0),
(10076, 'itIT', 'Grandioso, $N. Questo ci aiuterà nella battaglia contro la feccia dell''Orda che è comparsa nelle Terre Esterne.', 0),
(10078, 'itIT', 'Questo è lo spirito giusto!$B$BFinalmente sono arrivati un po'' di rinforzi, ma non so quale sia il loro atteggiamento nei confronti dell''Orda. Da dove vengo io, se uno ti punta addosso un''arma è un tuo nemico... e devi trattarlo come tale!', 0),
(10079, 'itIT', 'Per la barba... bronzea di Barbabronzea! Ce l''hai fatta! $N, sei un eroe!', 0),
(10086, 'itIT', 'Questa roba è ottima! Un po'' piegata e bruciacchiata, ma la scarsa qualità del materiale non mi ha mai impedito di creare esplosivi potenti e precisi.$B$BGrazie, $N. Hai occhio per la spazzatura di qualità!', 0),
(10087, 'itIT', 'Lo sapevo! Da quaggiù non ho potuto assistere alla distruzione, ma posso immaginare lo spettacolo. Splendido!$B$BBen fatto, $N. Il Comando di Thrallmar sarà felice di sapere del tuo successo!', 0),
(10093, 'itIT', 'Così hai conosciuto il Veggente Kryv. È un uomo saggio e dotato di talento. Ogni $r che abbia ottenuto la sua amicizia, è anche mio amico.$B$BMettiti a tuo agio e presentati agli altri abitanti del Tempio.', 0),
(10096, 'itIT', 'Bene! Quelle bestie delle paludi non avevano il diritto di invadere la casa degli Sporelok!$B$BSarebbe meglio che quelle creature imparassero a vivere in armonia, ma quando non è possibile, dobbiamo intervenire per sistemare le cose.$B$BEcco qua, prendine uno in segno di ringraziamento.', 0),
(10099, 'itIT', 'Sono felice che tu abbia eliminato... come hai detto che si chiamava? Z''kral?$B$BDalla tua descrizione, sembra più una bestia che un essere intelligente. Comunque, l''unica cosa che conta è che sia morto.', 0),
(10103, 'itIT', 'Se devo essere onesto, mi aspettavo di più. Vabbuo'', mi accontenterò. Benvenuta all''Avamposto Rattomarcio.', 0),
(10107, 'itIT', 'Allora, qual è la tua decisione? Entrerai in guerra o ci aiuterai?', 0),
(10108, 'itIT', 'Allora, qual è la tua decisione? Entrerai in guerra o ci aiuterai?', 0),
(10109, 'itIT', 'Eccellente! Ancora qualche ritocco e quest''affare sarà come nuovo. Oh sì, la tua chiave! Prendi.$B$BA proposito, devo sistemare ancora un paio di cose sul Saltabot. Ehm, fa'' attenzione.', 0),
(10112, 'itIT', 'Sì, devo dire che ora mi è tutto più chiaro.$B$BE credo che la tua efficienza nell''affrontare la questione meriti più delle semplici informazioni che cerchi.', 0),
(10113, 'itIT', 'Immagino che dovremo trovare qualcun altro che vada a prendere i rifornimenti. Mi sembri possente, $c. T''interessa un lavoro o sei qui per cacciare?', 0),
(10114, 'itIT', 'Sono contento di sapere che sta bene. Sei qui per unirti alla caccia?', 0),
(10115, 'itIT', 'Hai fatto un buon lavoro, $N. I Limoaguzzo non erano più salvabili, ma non sono sicuro che i Draenei avrebbero agito con altrettanta rapidità per risolvere la situazione.', 0),
(10116, 'itIT', 'Rimarchevole! Ci sono altri che hanno provato a reclamare la taglia, ma non hanno mai fatto ritorno. Non ci vuole una grossa immaginazione per capire cosa sia loro successo.$B$BSono felice di non dovermi più preoccupare di Mummaki e della sua banda.', 0),
(10118, 'itIT', 'Penso che il messaggio sia chiaro. Forse mo'' i compagni miei nun terranno più paura di combattere i Limoaguzzo. E se la terranno, dovranno tenere la vergogna per la mancanza di coraggio.', 0),
(10120, 'itIT', 'Sei il nuovo messaggero di Orion? Spero per te che te la caverai meglio dell''ultimo! La Legione ci sta con il fiato sul collo, non riusciresti mai a raggiungere Thrallmar a piedi. Quando sarai pronto, la mia fedele viverna ti porterà a destinazione sano e salvo.', 0),
(10121, 'itIT', 'Mentre volavi fin qui dal Portale Oscuro, sicuramente hai notato i guerrieri della Legione disseminati per il territorio. Anche se li abbiamo sconfitti cinque anni fa nella Battaglia per il Monte Hyjal, quei demoni maledetti continuano a tornare. Se è una sfida che cercano, l''Orda risponderà come si deve!$B$BNoi Orchi abbiamo diversi conti in sospeso con la Legione. $N, tu che mi dici? Vuoi che ti parli del nostro nemico?', 0),
(10123, 'itIT', 'Ottimo lavoro! La frequenza degli attacchi diminuirà sicuramente... almeno finché non arriveranno altri Signori del Terrore.$B$BMa c''è anche una cattiva notizia: ho i tuoi nuovi ordini...', 0),
(10124, 'itIT', 'Quindi sei stato tu a sgomberare Golavile, eh? Mi fa piacere: teniamo bisogno di soldati come te, che sanno tenere testa ai nemici!', 0),
(10129, 'itIT', 'Li abbiamo rallentati di settimane! Ottimo lavoro, $N. La Legione nun si aspettava na resistenza come chesta.', 0),
(10132, 'itIT', 'Ottimo lavoro.$B$BSecondo me, dobbiamo solo uccidere abbastanza Colossi e non dovremo più preoccuparci della Cresta o di quello strano cristallo nel mezzo.$B$BScegli la tua ricompensa da parte della Spedizione Cenariana.', 0),
(10134, 'itIT', 'Umpf. A me sembra solo un grosso pezzo di cristallo grezzo.$B$BDevo ammettere che emana una debole aura malvagia, ma non sono qui per questo. Il mio compito è porre fine alla minaccia dei Colossi.', 0),
(10136, 'itIT', '$N, le generazioni future canteranno il tuo valore in questa giornata! Vorrei che Thrall fosse qui per festeggiare la vittoria insieme a noi. La Legione è sconfitta e la Penisola del Fuoco Infernale è di nuovo sotto il controllo dell''Orda! Forse c''è una speranza per questo povero pianeta... e per il nostro popolo.$B$BLok''tar ogar!', 0),
(10140, 'itIT', '$N, la nostra spedizione in questo mondo dimenticato dalla Luce è giunta a un punto morto. Abbiamo incontrato una resistenza più feroce di quanto immaginassimo.$B$BCome se non bastasse la Legione Infuocata, questa terra è abitata da orrori mai visti prima.', 0),
(10141, 'itIT', 'Il Comandante delle Forze Danath deve aver sottovalutato la mia richiesta di rinforzi. Sembri in gamba, ma... io avevo chiesto un intero battaglione!$B$BSai, abbiamo un piccolo problema di demoni...', 0),
(10142, 'itIT', 'Ottimo lavoro! La frequenza degli attacchi diminuirà sicuramente... almeno finché non arriveranno altri Signori del Terrore.$B$BMa c''è anche una cattiva notizia: ho i tuoi nuovi ordini...', 0),
(10143, 'itIT', 'Felice di conoscerti.$B$BMa ora basta chiacchiere e ascolta: ho una missione di vitale importanza da assegnarti e voglio che la porti a termine... senza morire!', 0),
(10144, 'itIT', 'Ben fatto, $N. Disattivando i Portali, hai impedito l''arrivo di rinforzi della Legione per molto tempo!$B$BComunque non possiamo ancora riposare sugli allori...', 0),
(10146, 'itIT', 'Li abbiamo rallentati, non c''è dubbio! $N, mi hai appena messo di buonumore... e per me è un evento raro!', 0),
(10159, 'itIT', 'Ora che non ci sono più devastatori, i viaggi da e per il Rifugio Cenariano nelle Paludi di Zangar dovrebbero essere più facili.$B$BLa Spedizione Cenariana ti è debitrice.', 0),
(10161, 'itIT', 'Alcuni sono ridotti troppo male, ma dovrebbero essercene a sufficienza. Grazie a un pizzico di ingegneria creativa, sono sicuro di potercela fare!', 0),
(10162, 'itIT', '$N, voli come se nun avessi mai fatto altro! Sei stato incredibile! Le Viverne Distruttrici non tengono nemmeno nu graffio!', 0),
(10163, 'itIT', '$N, voli come se non avessi mai fatto altro! Sei stato incredibile! I Grifoni Distruttori non hanno nemmeno un graffio!', 0),
(10166, 'itIT', 'Non appartengo più a questo mondo e devo ammettere la sconfitta. La terra è cambiata per sempre e niente sarà più lo stesso.

Lascia il pendente qui con me, $n. Forse un giorno, parecchio tempo dopo che gli Elfi non ci saranno più, un nuovo albero crescerà in questo punto, in mezzo a una foresta bruciata e ai tronchi dei Treant morti.', 0),
(10176, 'itIT', 'Sei stata in gamba, $N. Ora che hai distrutto il campo d''indebolimento, sarà molto più facile per me preparare l''incantesimo che spezzerà finalmente la maledizione.', 0),
(10182, 'itIT', 'Hai agito bene, $N. Non avverto più alcun senso d''inquietudine nello spirito di Dathric. Darei molto per poter parlare con lui un''ultima volta, ma mi basta sapere che può finalmente riposare.', 0),
(10188, 'itIT', 'Ah, la sua magnificenza è immutata. Riesci ad avvertire il potere che emana?$B$BOvviamente, abbiamo ancora molto da fare, ma hai la mia più sentita gratitudine per avermi portato il Sigillo.', 0),
(10197, 'itIT', 'Eccellente! Quando avrò finito con te, riuscirai a camminare tra le truppe dei Furia del Sole senza che nessuno ti noti.', 0),
(10198, 'itIT', 'La Manaforgia Duro è nei guai? Sono certo che Thalodien sarà felicissimo di sentirlo, ma prima concludiamo questa missione.', 0),
(10200, 'itIT', '$N, non smetti mai di stupirmi. Hai dimostrato grande padronanza della furtività alla Manaforgia Coruu.', 0),
(10202, 'itIT', 'Era ora che ti facessi vedere. Iniziavo a chiedermi se i Veggenti fossero davvero interessati.', 0),
(10208, 'itIT', 'Ben fatto! Quasi riuscivo a sentire le vibrazioni dell''esplosione da accà!$B$BTeniamo n''altra missione di bombardamento per te.', 0),
(10213, 'itIT', 'Siamo stati abbattuti dalla Legione Infuocata, anche se avevamo sventolato la bandiera bianca. Chi poteva immaginare che fossero così crudeli?$B$BNon possiamo venire con te al Presidio di Frangiguglia, dobbiamo riparare il nostro Zeppelin e rimetterci in viaggio.', 0),
(10220, 'itIT', 'Gli Implacabili hanno assaggiato la forza dell''Orda. Scommetto che presto saranno propensi ad ascoltare la mia proposta d''alleanza.', 0),
(10222, 'itIT', 'Quanto hai fatto oggi non servirà a riportare in vita i caduti, ma forse placherà i loro spiriti. Tuttavia, se devo essere sincero, nulla potrà mai placare la mia rabbia per le azioni di Kael''thas.', 0),
(10228, 'itIT', 'Libro dei morti? Mai sentito... Ma di che si tratta? Chi ti manda?', 0),
(10229, 'itIT', 'Ho studiato la storia antica per tutta la mia non vita e non ho mai visto un libro come questo. Narra l''intera storia dell''Armeria, inclusi gli eventi successivi alla sua distruzione.$B$BGli Implacabili hanno continuato a scriverla, anche dopo essere caduti in battaglia. Grazie a questo volume, potremo capire gli Implacabili e convincerli ad allearsi con noi.', 0),
(10230, 'itIT', 'Ottimo lavoro, $N. Questo antico corno ci permetterà di evocare gli Implacabili.$B$BSempre che loro vogliano.', 0),
(10231, 'itIT', 'D''accordo, d''accordo! Non farci del male. Il libro ce l''avevamo, sì... ma l''abbiamo venduto...', 0),
(10236, 'itIT', 'Urrà! Hai trovato dei pezzi di ricambio! Ora posso rimettere in funzione il Segatronchi. Se riuscirò a guadagnare abbastanza, forse potrò tornare alla Baia del Bottino.$B$BSpero proprio che mio cugino Screed Buonasorte si schianti con il suo stupido Zeppelin! Non posso credere che sia riuscito a convincermi a trasferirmi nelle Terre Esterne.', 0),
(10238, 'itIT', 'Grazie per aver salvato i miei Peoni. Forse adesso potrò fargli riparare il Segatronchi con le parti di ricambio che mi hai portato. Così guadagnerò un po'' di soldi e potrò andarmene dalle Terre Esterne. Non vedo l''ora di tornare alla Baia del Bottino!', 0),
(10240, 'itIT', 'Ottimo lavoro. Incrocia le dita, $N. Ora attiverò lo scudo.', 0),
(10242, 'itIT', 'Un esame del sangue, eh? Sarà un piacere. Adoro lavorare con il sangue...', 0),
(10250, 'itIT', 'Sono felice di sapere che gli Implacabili si sono uniti a te in combattimento. Sospettavo che si sarebbero mostrati al suono del loro Corno da Battaglia, ma non potevo averne la certezza. Forse abbiamo donato loro un po'' di quella vendetta che perseguono così disperatamente.$B$BHai ucciso Urtrak, dobbiamo riferire la tua vittoria al Comandante Hogarth ai Bastioni della Spedizione. Sicuramente apprezzerà i rischi che hai corso in suo nome.', 0),
(10251, 'itIT', 'I segnali erano chiari, ma io non ho voluto vederli.$B$BLa Legione diventa ogni giorno più forte. Anche da queste parti...$B$BAvessi saputo... avessi saputo che il mio ragazzo comunicava con i demoni... Gli hanno offerto il potere e poi gli hanno dato un assaggio di quel potere. È bastato quello...$B$BIl libro è sparito. Ora è in mano a Levixus... i suoi piani sono noti solo a me e al suo oscuro padrone.$B$BStraniera, non so se in vita tua tu abbia mai fatto del bene, ma sappi questo: quel ragazzo va fermato.', 0),
(10258, 'itIT', 'Abbiamo perso la battaglia contro i Vilorchi molto tempo fa. Uccidendo Urtrak, ci hai restituito un po'' dell''onore che avevamo perduto.$B$BPrendi una delle nostre armi e usala quando combatterai contro i nostri più odiati nemici: tutti coloro che non saranno schiavi della nostra maledizione accorreranno in tuo aiuto.$B$BPrima di andartene, coloro che sono morti nella Torre d''Assedio vorrebbero onorarti per aver distrutto i nostri nemici.', 0),
(10270, 'itIT', 'Quest''adattatore dovrebbe andar bene per il momento. Quando i soldi cominceranno a piovere, lo miglioreremo.$B$BMa basta parlare. Ogni momento passato a chiacchierare porta a una perdita dei profitti.', 0),
(10271, 'itIT', 'E pensare che quei dannati Eterei avrebbero venduto tutta questa essenza agli Elfi del Sangue come fosse una caramella...', 0),
(10272, 'itIT', 'Queste vanno benissimo, $N. Grazie per averci aiutato.$B$BPrima di continuare, tuttavia, dobbiamo occuparci di un''altra cosa.', 0),
(10273, 'itIT', 'Ora che quel fastidioso Etereo è sistemato, possiamo concentrarci su questi Draghi Fatui. Ho avuto modo di esaminare le uova e ho scoperto diverse cose.', 0),
(10274, 'itIT', 'Ben fatto, $N. Davvero ben fatto. I Dragoidi Fatui inizialmente non accoglieranno un Drago Blu, ma con il tempo e la dimostrazione della mia autorità, mi accetteranno. Ora che sono divisi, isolati e senza un capo definitivo, dobbiamo fare attenzione che non cedano a poteri malvagi, tenendoli sempre sotto controllo.', 0),
(10275, 'itIT', 'Davvero molto bene. Il Principe del Nexus sarà soddisfatto!$B$BOra che abbiamo il secondo punto, ci dirà dov''è il terzo e la posizione approssimativa del cristallo!', 0),
(10276, 'itIT', 'Nei miei sogni più sfrenati, non avrei mai pensato che avresti trovato il cristallo!$B$BE che me lo consegnassi davvero! Hai idea di quanto sia potente?$B$BLa tua irreprensibile abnegazione è fonte d''ispirazione, $N! Mi hai dato molto a cui pensare.', 0),
(10278, 'itIT', 'Incredibile. $N, hai toccato il Vuoto! Hai salvato il lavoro di tutta la mia vita. Però c''è ancora altro da fare e tu puoi aiutarmi.', 0),
(10279, 'itIT', 'Dobbiamo prepararci per le battaglie che ci attendono...', 0),
(10280, 'itIT', 'Hai recuperato la Canzone dello Spirito! È il cristallo Ata''mal che il Profeta Velen aveva lasciato in custodia al suo popolo prima di partire per la tragica missione a Exodar.$B$BStrano che non avesse previsto che sarebbe caduto nelle mani della Legione Infuocata, anche se per breve tempo.$B$BO forse lo fece? Forse aveva previsto tutto questo e lo lasciò in quel luogo in modo che tu potessi recuperare il cristallo e portarmelo.$B$BSento che questa è la verità. Sei una grande eroina del tuo popolo, $N!', 0),
(10288, 'itIT', 'Devi consegnare un rapporto alla Rocca dell''Onore? Non c''è problema: grazie ai miei grifoni, arriveremo lì in men che non si dica... e tutti interi!', 0),
(10289, 'itIT', 'Radunerò tutte le truppe disponibili e le invierò in aiuto di Orion al Portale Oscuro. La Legione ricorderà a lungo il grido di battaglia dell''Orda! $N, oggi hai contribuito enormemente alla salvezza di Thrallmar. Mi aspetto grandi cose... se riuscirai a sopravvivere.', 0),
(10290, 'itIT', 'Ah, sì. È esattamente ciò che speravo. Se riusciamo a garantirci un rifornimento dai giganti, possiamo smettere di estrarre il minerale dalle formazioni di cristallo.', 0),
(10293, 'itIT', 'Ben fatto! Non vedo l''ora di esaminarlo.', 0),
(10301, 'itIT', 'Eccellente, $N. Ora, abbiamo tutto ciò che ci serve per tentare di spezzare l''incantesimo di Kael''thas.$B$BE se gli Elfi del Sangue ne risentiranno per la perdita del loro comandante locale, tanto meglio.', 0),
(10302, 'itIT', 'Hai finito? Questa sì che è una buona notizia. Speriamo di poter evitare di dover uccidere queste bestie mutanti, in futuro.$B$BCredo di aver individuato una via per giungere a una soluzione alternativa al problema, ma avrò bisogno del tuo aiuto.', 0),
(10305, 'itIT', 'Ah, sì. Avevo sentito che l''Abiuratrice Belmara possedeva un libro di racconti, ma non sapevo che l''avesse portato con sé nelle Terre Esterne. Sono certo che il suo spirito riposerà in pace sapendo che l''hai trovato e riportato nei suoi alloggi.', 0),
(10306, 'itIT', 'Eravamo soliti notare che Luminrath indossava quel mantello con tutto. Per lui, il rosso si abbinava tanto con il bianco quanto con il nero, il viola, il blu, il giallo, l''arancione e il verde. Non indossava mai la stessa tonaca due giorni di seguito, ma il mantello l''aveva sempre con sé.', 0),
(10308, 'itIT', 'Traditori, tutti quanti!$B$BBel lavoro, $c! Se capiterai ancora da quelle parti, sappi che mi piace ampliare la mia collezione di fregi!', 0),
(10315, 'itIT', 'Dobbiamo sfruttare ogni occasione che ci si presenta per spingerli a interrompere le loro operazioni nelle Manaforge.$B$BNon hanno l''aria di esseri con cui si ragiona facilmente. E mi sembra chiaro che, qualunque cosa abbia in mente il loro capo, sono pazzi.$B$BCome ricompensa per i tuoi fedeli servigi al Consorzio, vorrei offrirti monete del tuo regno. Sempre che questo non ti offenda.', 0),
(10316, 'itIT', 'Un globo luminoso posizionato in cima a un piedistallo di forma quadrata. A prima vista, sembrerebbe un ricettacolo di energia magica. Ma di che tipo e utilizzata per cosa?', 0),
(10318, 'itIT', 'Un Demone Guardiano Maestro Supremo? Bizzarro! Che ci fa qui la Legione Infuocata?$B$BQuindi, alcuni Elfi del Sangue stanno disertando. Lo terremo a mente qualora decidessimo mai di prendere quel luogo con la forza. Almeno abbiamo ricevuto delle buone notizie, non trovi?$B$BTi prego, $N, accetta questo dono insieme alla mia più profonda gratitudine.', 0),
(10319, 'itIT', 'Ottimo lavoro, $N. Il Filatterio sarà la chiave per la nostra vittoria. Quando affronterai Naberius, lo distruggerò, rendendolo vulnerabile ai tuoi attacchi.', 0),
(10320, 'itIT', '$N, la sconfitta di Naberius è una grande impresa. Non posso fare a meno di pensare che potremmo avere avuto una possibilità contro le forze di Kael''thas se quel giorno l''apprendista non ci avesse tradito.', 0),
(10324, 'itIT', 'Meraviglioso! Ti stai rivelando una cacciatrice provetta, $N.$B$BTi piacerebbe assomigliarmi un po''? Be'', ecco la tua chance! Mentre eri a caccia, ho creato questi dalle pelli di cervo nobile che mi avanzavano. Scegline uno!', 0),
(10325, 'itIT', 'Affrontare i demoni della Legione Infuocata e i cultisti pazzi che li venerano non è impresa da poco, $N. Hai mostrato grande dedizione e coraggio. Continua così e la tua fama tra gli Aldor continuerà a crescere.', 0),
(10326, 'itIT', 'Continui a dimostrare il tuo valore, $N. Combatti i nemici della Luce ovunque li troverai; le tue gesta saranno adeguatamente ricompensate.', 0),
(10327, 'itIT', 'Continui a dimostrare il tuo valore, $N. Combatti i nemici della Luce ovunque li troverai; le tue gesta saranno adeguatamente ricompensate.', 0),
(10330, 'itIT', 'Abbiamo sentito del trambusto e stavamo per andarcene. È bello vedere che non ti hanno conciato troppo male.', 0),
(10331, 'itIT', 'Grazie al cielo! Ora posso rimettermi a lavorare. Penserai che sono pazzo a lavorare sull''oggetto che mi conferirà il titolo di allievo senza una forgia vera e propria, ma non posso correre il rischio che gli altri apprendisti copino il mio progetto.', 0),
(10332, 'itIT', 'Il Maestro Rhonsus mi ha insegnato tutto ciò che so. Onorerò la sua memoria usando le mie capacità per servire gli abitanti di Kirin''Var.', 0),
(10338, 'itIT', 'E con questa fanno tre manaforge bloccate, $N. Kael''thas starà dando in escandescenze.', 0),
(10340, 'itIT', 'Ah ah ah! Un nuovo $r, appena arrivato dalla terraferma! Be'', non preoccuparti: il Presidio di Torre Infranta fa venire la nausea, ma non sparisce!$B$BE poi l''ho visto rovesciarsi solo una volta... al massimo due.', 0),
(10341, 'itIT', 'Hai agito bene, $N. L''esercito di Kael non si riprenderà facilmente dal colpo inflitto oggi.', 0),
(10344, 'itIT', 'Hai parlato con Runetog? Quello è proprio un Nano in gamba! Mantiene i suoi grifoni in buono stato e pronti a combattere.$B$BIo sono Grifongar, Comandante del Presidio di Torre Infranta. Non è un bel posto, lo so... ma questo ammasso di rocce è il punto di partenza ideale per sferrare attacchi al Fuoco Infernale. Vedrai grifoni che volano avanti e indietro ininterrottamente!$B$BVuoi qualche consiglio? Tieni il tuo equipaggiamento in ordine, lo stomaco vuoto e l''occhio sull''orizzonte: se il Presidio di Torre Infranta inizia a traballare, afferra qualcosa di solido!', 0),
(10345, 'itIT', 'Mi hai salvato le fasce, $N. Il Protettorato sarà informato di quanto hai fatto per me.', 0),
(10346, 'itIT', 'Stavolta com''è andata? Sei in ottima forma... anzi, direi che sei pronto per un altro passaggio!', 0),
(10349, 'itIT', 'Perfetto! Non vedevo l''ora di mettere le mani su uno di questi pezzi, ma Tola''thion non si decideva mai.$B$BDovrebbe essere qui per aiutarmi a indagare su ciò che accade alla Cresta del Cielo Infranto, ma non fa altro che inviare al macello dei poveracci come te (senza offesa).$B$BDammi il cristallo: forse posso scoprire che cosa lo collega ai Colossi.', 0),
(10353, 'itIT', 'E Ya-Six? Ce l''ha fatta?$B$BSpero vivamente di sì. Non sono riuscito a inviargli dei rinforzi... Gli Etereum adesso coprono l''intera zona.$B$BLe mie scuse, ho quasi dimenticato la tua ricompensa.', 0),
(10365, 'itIT', 'La Legione Infuocata è in combutta con Kael? Ah! Voren''thal avrà di che gioire quando sentirà questa notizia.$B$BPensi che migliaia di pellegrini venuti da Azeroth vogliano allearsi con la Legione Infuocata? Io ne dubito!', 0),
(10367, 'itIT', '$N, grazie a te presto la mia gente sarà libera.', 0),
(10368, 'itIT', '$N, riesco a sentire gli spiriti che tornano da noi.', 0),
(10369, 'itIT', 'È vero, $N: un tempo ero Naladu il Protettore della Terra.$B$BSono stato io a tradire gli altri Anziani Cappalercia, allettato da una falsa promessa di potere. Puoi disprezzarmi, se lo desideri. Ciò che conta è che finalmente la mia tribù è di nuovo libera e gli spiriti sono tornati da noi.$B$BNon mi unirò agli altri, ma finalmente posso morire in pace. Che lo Spirito della Terra possa trovare un nuovo servitore fra i miei fratelli.', 0),
(10382, 'itIT', 'Salve, $c. Finalmente quel vecchio Nano rugoso si è deciso a mandarci un aiuto!', 0),
(10388, 'itIT', '$N, sei arrivata appena in tempo! I nostri esploratori hanno scoperto che le postazioni della Legione sulla Cresta alle nostre spalle sono delle "Fornaci". È lì che i demoni creano i loro infernali Vilrazziatori. Se agiamo in fretta, possiamo fermare la produzione!', 0),
(10390, 'itIT', 'Ben fatto, $c: una Fornace in meno di cui preoccuparci! La Legione avrà bisogno di un po'' di tempo prima di rimetterla in funzione. Ci hai fornito l''unica cosa che ci manca: il tempo.', 0),
(10391, 'itIT', '$N, sapevo che eri una tenace... ma stavolta ti sei superata! Abbiamo sentito esplodere quei dannati cannoni da qui! Stavolta la Legione dovrebbe avere imparato a non sottovalutare i Figli di Durotar!', 0),
(10394, 'itIT', '$N, devo dire che mi hai molto colpito. Non credevo avessi la stoffa per una missione del genere. Ben fatto. Davvero ben fatto.', 0),
(10397, 'itIT', 'Ottimo lavoro! Dovremmo aver ridotto drasticamente il numero di demoni in quest''area! $N, non so come ringraziarti per il tuo aiuto.', 0),
(10399, 'itIT', '$N, avevo previsto la tua vittoria! Oggi i Naaru benedetti ti sorridono.', 0),
(10403, 'itIT', '$r, sei qui per aiutare la mia tribù? Strano. In questa terra, sono pochi coloro ai quali interessi la sorte dei Corrotti.', 0),
(10406, 'itIT', 'Grazie a te, i loro piani sono falliti! Resta solo una cosa da fare... Salhadaar.', 0),
(10408, 'itIT', 'Sono passati mille anni, forse più, da quando Salhadaar ha iniziato la sua crociata per sterminare tutti coloro che osavano sbarrargli la strada. Fatico a credere che sia sparito per sempre... Hai reso a tutti noi un enorme servigio, $N, e per questo noi ti ricompenseremo.', 0),
(10413, 'itIT', 'COSA?!? Hai affrontato un orrore del Vuoto? E respiri ancora?!? Incredibile!$B$BQuesto campione vale un mucchio d''oro. Una scoperta simile merita una ricompensa.', 0),
(10419, 'itIT', 'Il potere contenuto in questo tomo è incredibile. Tuttavia, una persona di grande intelletto può condensarlo in una singola runa.', 0),
(10420, 'itIT', 'Guarda il Vil Materiale che si disintegra. Guarda mentre il metallo si trasforma in polvere.$B$BLa Luce purifica tutto e rimane solo il più puro dei residui.', 0),
(10421, 'itIT', 'I Vil Materiali sono cancellati da questo mondo. Rimangono solo i residui della Luce.', 0),
(10424, 'itIT', 'Questi risultati sono identici a quelli di Mehdrad, ma perché? L''unica spiegazione possibile che mi viene in mente è che qualche attrezzatura che genera la cupola si sia guastata o sia sparita. Questo indebolirebbe significativamente le cupole e le sbilancerebbe come sembrano indicare i controlli.', 0),
(10428, 'itIT', 'La mia famiglia... Cosa ho fatto... Cosa avrei potuto fare?$B$BPerché una simile punizione?', 0),
(10430, 'itIT', 'Ha un aspetto un po'' strano. Ghabar non aveva in mente la Landa Fatua quando lo ha progettato.$B$BNon fare quella faccia, $N. La Landa Fatua è nulla in confronto a certi ambienti in cui ho lavorato. Ciò nonostante, una cupola guasta è sempre fonte di preoccupazioni.', 0),
(10432, 'itIT', 'Che notizia incredibile, $N. Davvero incredibile!$B$BVoren''thal vorrà essere informato appena possibile.', 0),
(10435, 'itIT', 'Ottimo lavoro! La parte più difficile del progetto è conclusa. Ora, dobbiamo solo trovare un modo per portarli all''Area 52 e stuzzicare l''interesse della Spedizione Cenariana. Dovremmo guadagnare abbastanza da soddisfare i nostri bisogni e per un piccolo extra.', 0),
(10436, 'itIT', 'Ben fatto. Sembra che sia tutto a posto. Possiamo cominciare.', 0),
(10443, 'itIT', 'Devi essere l''aiuto che ho richiesto al Tempio di Telhamat.$B$BSanto cielo, sono proprio felice di vederti! C''è molto da fare e ho proprio la missione giusta per farti iniziare.', 0),
(10444, 'itIT', 'Parti di una bomba. Dunque i miei sospetti erano fondati. Ma avrei preferito sbagliarmi.$B$BVa bene... ci aspetta del lavoro non molto piacevole.', 0),
(10446, 'itIT', 'CE L''HAI FATTA! CI HAI SALVATI! HAI SALVATO LA FORTEZZA DI ALLERIA!!!$B$BCon le loro forze decimate, il loro capo morto e la bomba di mana distrutta, ci sentiamo tutti sollevati.$B$B$N, non ho mai visto una tale abnegazione... un tale eroismo! Ti prego, accetta questo da parte di tutti noi.', 0),
(10449, 'itIT', 'Ah, sì. Il Sangue del Clan Tritaossa. Questi Orchi mi incuriosiscono... sono sempre gli stessi nemici depravati, ma più forti e potenti che mai.$B$BIniziamo?', 0),
(10450, 'itIT', 'Ah! Così hai incontrato i nostri cugini depravati, i Tritaossa. Ben fatto, $N. Mi dispiace solo che non siano stati di più a morire e spargere sangue per placare la mia ira!', 0),
(10455, 'itIT', 'Sei stata rapida. Sei sicura di averne eliminate abbastanza?$B$BOttimo. Se sei disponibile, avrei un altro incarico da affidarti.', 0),
(10456, 'itIT', 'Bene. Vedrò di realizzare qualcosa di utile a partire da queste code.$B$BSenza dubbio l''Orda troverà il modo di rimpiazzare i Metalupi uccisi, ma abbiamo guadagnato un po'' di tempo.$B$B$N, se sei disponibile avrei un altro favore da chiederti in difesa di Sylvanaar e della Selva Vivente.', 0),
(10457, 'itIT', 'Ora che hai rinforzato le difese della Selva, mi sento molto più sicura.$B$BTi sei guadagnata la nostra gratitudine e il nostro apprezzamento.$B$BE ovviamente mi è appena venuto in mente un altro favore da chiederti!', 0),
(10458, 'itIT', 'Quando tutte le anime elementali della regione saranno state chiuse nel totem, comunicheremo con loro e scopriremo se è possibile fare qualcosa per la Valle di Torvaluna.', 0),
(10476, 'itIT', 'Cominci a dimostrare di essere una valida alleata e combattente. Continua così.', 0),
(10477, 'itIT', 'Continui a dimostrare il tuo valore, $N. Che le forze non ti abbandonino mai.', 0),
(10478, 'itIT', 'Continui a dimostrare la tua forza e il tuo onore, $N.', 0),
(10479, 'itIT', 'La tua forza è indubbiamente grande, $N. Affrontare gli Ogre delle Terre Esterne non è impresa da tutti.', 0),
(10480, 'itIT', 'Resta solo l''aria, $N.', 0),
(10481, 'itIT', 'Consentimi di ricompensarti per aver compiuto un''impresa tanto ardua.$B$BOra, dobbiamo metterci al lavoro! Stai indietro, così potrò collocare il totem e liberare le anime.', 0),
(10482, 'itIT', 'Molto bene. Sono sicuro che la Cittadella del Fuoco Infernale sentirà molto la loro mancanza. Anche se quel bastione oscuro incombe su di noi e sembra quasi insormontabile, è solo grazie a gesti coraggiosi come il tuo che vinceremo sui Vilorchi!', 0),
(10483, 'itIT', 'Ah, hai preso un Fregio agli Orchi Guerci Insanguinati? Bene! È oltraggioso che usino i nostri simboli contro di noi, prendendo i giro chi è morto per mano di quelle maledette bestie rosse!', 0),
(10484, 'itIT', 'Grazie, $N. Alla vista di questi Talismani, il mio cuore si gonfia di tristezza. Sono la prova tangibile delle sofferenze inflitte dai Vilorchi alla Rocca dell''Onore. Ciononostante, il tuo successo mi rincuora. Se riusciremo a uccidere abbastanza Orchi, potremmo vincere questa guerra.', 0),
(10485, 'itIT', 'Ce l''hai fatta! Morkh è morto! Ora abbiamo una possibilità di sconfiggere quelle bestie dei Vilorchi!$B$BGrazie, $N. Il tuo aiuto in questa guerra è inestimabile.', 0),
(10502, 'itIT', 'Il primo passo per rendere sicuri Sylvanaar e la Selva è stato compiuto.$B$BOra che i loro ranghi sono ridotti, i Magliorosso ci penseranno due volte prima di attaccarci.$B$BSe solo fosse l''unico clan di Ogre di cui preoccuparsi...', 0),
(10504, 'itIT', 'Portando a termine le missioni contro i Magliorosso e i Lamacurva hai assicurato a Sylvanaar un futuro più sicuro. Noi non intendiamo espanderci oltre quest''area, che a suo tempo trovammo libera, ma non per questo possiamo tollerare aggressioni nei nostri confronti.$B$BPoiché ci ha reso un buon servizio, desidero ricompensarti con l''apprezzamento dell''Alleanza.', 0),
(10506, 'itIT', 'Sono felice di sentire che ha funzionato. Meno sono le creature della Natura costrette a morire, meglio è.$B$BE dopo tutto ciò che hai già fatto per noi, ammetto che comincio ad affezionarmi anche a te.$B$BAbbi cura di te, $N.', 0),
(10507, 'itIT', '$N, sei un individuo di enorme potere. I Veggenti devono considerarsi fortunati a essere tuoi alleati.$B$BCol diffondersi della notizia dei nuovi alleati di Kael, sempre più persone abbracciano la nostra visione delle cose. Il fatto che possiamo vantare un simile vittoria contro i nuovi padroni di Kael''thas ci pone in una posizione molto favorevole.$B$BNon dimenticherò quanto hai fatto.', 0),
(10508, 'itIT', '$N, non smetti mai di stupirmi! È un bene che tu stia dalla nostra parte.', 0),
(10509, 'itIT', 'Non puoi capire ciò che questo significa per i Veggenti, $N. Ho bisogno di qualche attimo per riprendere fiato e valutare la situazione.', 0),
(10510, 'itIT', 'Oh, a vederli sembrano proprio dei campioni stupendi. Non vedo l''ora di riprendere in mano i miei strumenti per esaminarli come si deve!$B$BGrazie!', 0),
(10511, 'itIT', 'Cos''è questo odore? Oh no, non dirmi che è la birra degli Ogre...$B$BHo quasi timore a provare questa roba. Oh be'', al diavolo! Salute!', 0),
(10512, 'itIT', 'Ah ah ah! Proprio come pensavo. Evidentemente gli Ogre berrebbero di tutto.$B$BChe stupidi!$B$BBe'', devo ammettere che anche se sono rimasto senza birra, la mia vacanza è iniziata ugualmente col piede giusto.$B$BSai che ti dico? Abbiamo un mucchio di roba di cui non abbiamo bisogno, posso donarti qualcosa?', 0),
(10513, 'itIT', 'Parole di dannazione? Mai sentite. Accetta un consiglio: lascia che i morti riposino in pace.$B$BMa giacché sei qui, mi servirebbe un aiuto con alcune faccende. Cosa ne dici?', 0),
(10514, 'itIT', 'Dici che c''erano molti più Scorticatori di quanto ti aspettassi? Sembra che sia giunto il momento di fare pulizia.', 0),
(10515, 'itIT', 'Così quei dannati luridi animali impareranno a non uccidere i miei cinghiali. Ben fatto, $N!', 0),
(10516, 'itIT', 'Mi hai aiutata a preservare il mio onore e sono in grande debito con te. Ma il nostro lavoro qui non è ancora finito.', 0),
(10517, 'itIT', 'Molto bene. Sei davvero ingegnosa, $c, questo è sicuro.$B$BChissà se puoi renderti utile a Sylvanaar e a me in qualche altro modo?', 0),
(10518, 'itIT', 'L''Elmo di Gurn Grubnosh e lo Stendardo dei Lamacurva?$B$BMolto ingegnoso da parte tua e della Vendicatrice.$B$BFacendo concentrare l''attenzione dei Magliorosso sulla Rocca dei Lamacurva, avete allentato la pressione che stavano cominciando a esercitare su di noi.$B$BPer favore, $N, accetta un umile dono da parte dell''intera Sylvanaar.', 0),
(10519, 'itIT', 'Comprendi cos''è necessario fare? Trova i figli di Oronok. Trova i miei ragazzi...', 0),
(10522, 'itIT', 'Dobbiamo portarlo subito a mio padre.', 0),
(10523, 'itIT', 'Quando il Cifrario della Dannazione sarà completato, porremo fine a questa maledizione!', 0),
(10537, 'itIT', 'Significa "dimora dell''eroe" nella mia lingua natia. Persino ora, in quest''era in cui tutti gli eroi sono caduti, suona veritiero...$B$BSembra che, nonostante tutto, ne sorga sempre uno nuovo.', 0),
(10538, 'itIT', 'Molto bene. Ora posso eseguire i miei esami con facilità.$B$BGrazie, $N. Possiedi un talento considerevole.', 0),
(10550, 'itIT', 'È ora di preparare la trappola!', 0),
(10554, 'itIT', 'Ti do il benvenuto, $N. Mi fa piacere che tu abbia deciso di unirti alla nostra missione. Che la Luce possa sempre proteggerti.', 0),
(10557, 'itIT', 'Caspita, ce l''hai fatta! E non vedo lividi o tracce di fratture composte! Visto? Te l''avevo detto che avrebbe funzionato tutto perfettamente!$B$BEcco la tua paga, $N... anche se avevo aggiunto alcune voci di indennità mediche che non ti servono. Be'', è un bel bonus per te!', 0),
(10562, 'itIT', 'Grazie per aver sostituito i miei uomini, $N. Grazie al tuo aiuto, e a quello di altri, forse resisteremo. Sfortunatamente, resistere non basta. Dobbiamo lanciare un''offensiva.', 0),
(10567, 'itIT', 'Ce l''hai fatta!$B$BCon questo pendente potrò farti entrare in sintonia con gli Arakkoa di Grishna fino al punto di farti comprendere la loro lingua.$B$BIn questo modo potremo capire meglio gli Arakkoa stessi e la natura del loro Corvo. Avrò bisogno del tuo aiuto.', 0),
(10576, 'itIT', 'Ben fatto, $N. Spero che tu sia una brava attrice. La prossima parte del mio grande piano richiede un po'' di teatralità!', 0),
(10577, 'itIT', 'Ora devi solo andare a prendere il Cifrario. Facile, no?', 0),
(10579, 'itIT', 'Appena uniremo i tre frammenti del Cifrario, riscopriremo le antiche parole.$B$BRecuperare questo frammento è stato senza dubbio difficile. Meriti una ricompensa per tanto eroismo.', 0),
(10580, 'itIT', 'SYLVANAAR? IL COMANDANTE OMBROCIELO?$B$BERRORE DI COMPUTAZIONE!$B$BALLONTANARSI PRIMA CHE SIA COSTRETTO A RIPRODURRE SUONI IRRITANTI!', 0),
(10581, 'itIT', 'Così vuoi renderti utile? Bene, ho proprio ciò che fa per te.$B$BPenso che ti piacerà.', 0),
(10584, 'itIT', 'Eccellente! Perlomeno, con tutta l''energia che hai recuperato potremo alimentare i nostri macchinari ancora per un po''.$B$BLo Zephyrium Capacitorium è davvero ingordo, quanto a consumi elettrici!$B$BSpero che gli Elettromentali non ti abbiano procurato troppi fastidi. Avrei un''altra cosa da chiederti e ho come la sensazione che sarà un po'' più rischiosa.', 0),
(10595, 'itIT', 'Sono colpito da come sei sopravvissuta al massacro. Potresti essere la persona che ci serve per una missione pericolosa.', 0),
(10608, 'itIT', 'Era ora! Finalmente ci siamo liberati di quelle sporche creature!$B$BDunque, se sei certo di averle eliminate tutte, ho un piccolo incarico per te. Penso che ti piacerà.', 0),
(10609, 'itIT', 'Non hai idea dell''importanza che potrebbe avere questa ricerca. Grazie!$B$BSarà interessante studiare queste essenze. Sono particolarmente curioso di vedere se l''effetto fatuo che ha mutato le uova di Drago Nero in uova di Draco Fatuo possa aver potenziato le proprietà curative che cerco.$B$BAnzi, stavo giusto pensando che dovresti essere tu la prima persona a beneficiare dei miei preparati. Ecco, prendi questi campioni preliminari e usali quando dovesse sorgerne la necessità.', 0),
(10620, 'itIT', 'Ottimo lavoro per una novellina. A quanto pare abbiamo un gruppo di cervelloni che vuole "osservare" gli Eterei e la loro tecnologia su a nord. Saranno felici di sapere che hai reso la loro strada più sicura.$B$BEcco, prendi. Non ne abbiamo molte, ma forse ti torneranno utili in futuro.', 0),
(10625, 'itIT', 'Malacarne? T... Teron Malacarne? Ma... come?$B$BCome può Malacarne essere qui? È impossibile!$B$BLa leggenda di Teron Malacarne fa tremare di terrore tutti i Reietti. Secondo quanto si dice, Malacarne era uno Stregone di Gul''dan, molto potente. Quando fu ucciso da Orgrim Martelfato, Gul''dan prese l''anima dello Stregone caduto e la rinchiuse nel corpo di un Cavaliere di Roccavento caduto in battaglia. E così nacque il primo Cavaliere della Morte dell''Orda.', 0),
(10627, 'itIT', 'Dovrebbero andare bene. Ora, riforgiamoli in una forma più utile.', 0),
(10629, 'itIT', 'Puzzi orribilmente, ma hai trovato le mie chiavi! Grazie mille! Ora posso rimettere in funzione il Segatronchi e guadagnare qualche soldo. Presto potrò permettermi di lasciare le Terre Esterne. Non capisco chi te lo fa fare a restare qui: io odio questo posto! Non preferiresti la Baia del Bottino?$B$BPassare le giornate a pescare?', 0),
(10630, 'itIT', 'Ora tutti quei Gan''arg se ne andranno di sicuro e io potrò tornare alla Baia del Bottino nel giro di una settimana. Non vedo l''ora di pescare di nuovo! Trasferirmi nelle Terre Esterne è stato un errore. Vuoi un consiglio? Tornatene da dove sei venuto. Passa un po'' di tempo a Rovotorto! Oppure, se hai voglia di avventura, vai nel Cratere di Un''Goro. Ovunque, basta che non resti qui!', 0),
(10632, 'itIT', 'Ottimo lavoro, ragazza. Se i tuoi sforzi serviranno a salvare la vita di anche uno solo dei miei soldati, ne sarà valsa la pena.$B$BTrovo giusto che anche tu tragga beneficio dalle tue fatiche. Poiché presto avremo a disposizione delle nuove armi, perché non prendi una delle mie?', 0),
(10633, 'itIT', 'Malacarne? Non sentivo quel nome da anni!$B$BDopo la Seconda Guerra, Malacarne tornò qui con i suoi Cavalieri della Morte. Incapace di accettare la terribile natura della sua nuova forma e senza l''aiuto del suo amato comandante, Gul''dan, Malacarne si uccise.$B$BIl fatto che si aggiri per queste terre come spirito è una novità per me. Tuttavia, forse riuscirò a scoprire qualcosa con il tuo aiuto.', 0),
(10634, 'itIT', 'Devo avere i tre oggetti per poter divinare il fato di Malacarne.', 0),
(10635, 'itIT', 'Quando avrò i tre oggetti in mio possesso, potrò divinare l''ubicazione di Malacarne.', 0),
(10636, 'itIT', 'Solo con i tre oggetti riuniti potrò divinare il segreto che cerchi così disperatamente!', 0),
(10639, 'itIT', 'Hai fatto cosa? Sciocco!$B$BDevi riparare. Dopotutto, è colpa tua. Prendi uno di questi elmetti. Sono imbevuti delle Ceneri Eterne che mi hai portato. E, cosa più importante, ti consentiranno di vedere gli spiriti di Torvaluna, incluso Teron Malacarne.$B$BQualora lo trovassi, distruggilo.', 0),
(10649, 'itIT', 'È possibile avvertire la potenza del libro da diversi metri di distanza. La tentazione di tenerlo è... molto forte.', 0),
(10652, 'itIT', 'Salve, $c. Cerchiamo di non farci scoprire.$B$BNon dureremo molto se gli sgherri di Kael si accorgono di noi.', 0),
(10653, 'itIT', 'Affrontare i demoni della Legione Infuocata e i cultisti pazzi che li venerano non è impresa da poco, $N. Hai mostrato grande dedizione e coraggio. Continua così e la tua fama tra gli Aldor continuerà a crescere.', 0),
(10654, 'itIT', 'Continui a dimostrare il tuo valore, $N. Combatti i nemici della Luce ovunque li troverai; le tue gesta saranno adeguatamente ricompensate.', 0),
(10655, 'itIT', 'Continui a dimostrare il tuo valore, $N. Combatti i nemici della Luce ovunque li troverai; le tue gesta saranno adeguatamente ricompensate.', 0),
(10658, 'itIT', 'Eccellente! Così Kael''thas imparerà a non sottovalutare il nostro potere.', 0),
(10665, 'itIT', 'È ancora più potente di quanto mi aspettassi! Con una simile potenza, potrei forgiare una decina di lame!', 0),
(10667, 'itIT', 'Dovrebbe funzionare. Speravo me ne portassi un po'' di più, ma a essere onesto, siamo stati fortunati a riuscire a trovarne un po''.', 0),
(10671, 'itIT', 'Questi dovrebbero andar bene. Puzzano, vero?$B$BSperiamo ne valgano la pena... Sono felice che sia stata tu ad andare a caccia di questa roba al posto mio!', 0),
(10672, 'itIT', 'Ascolta, non c''è tempo da perdere. Ho osservato i Diemetradonti marcati e ho scoperto che fanno tutti capo a un gigantesco... No, colossale Diemetradonte chiamato Vilspina il Grandioso.', 0),
(10673, 'itIT', 'Finalmente! Mi sono impadronito della protezione totale dalla lava! Ovviamente, avrai la tua parte di questa tecnologia, $N. Te lo meriti!', 0),
(10674, 'itIT', 'Ehi, aspetta un secondo!$B$BHo un brutto presentimento...', 0),
(10675, 'itIT', 'Che gli serva da lezione! Grazie per aver messo fine a questo macabro connubio di magia e tecnologia.$B$BOra sei un''eroina universale degli Gnomi, quindi voglio renderti omaggio come ti si conviene... alcuni convertitori energetici e la scelta di una tra queste cose.$B$BSono certo che ne farai buon uso!', 0),
(10680, 'itIT', 'È un bene che tu sia qui, $R. Abbiamo molto lavoro da fare.', 0),
(10681, 'itIT', 'È un bene che tu sia qui, $R. Abbiamo molto lavoro da fare.', 0),
(10682, 'itIT', 'COSA?!? Ha ignorato te e le nostre proposte senza neanche rifletterci su?$B$BQuesto è un oltraggio! Noi ci rechiamo da loro con le migliori intenzioni e loro ci allontanano senza neanche cercare di raggiungere un compromesso?$B$BBene, l''hanno voluta loro!', 0),
(10690, 'itIT', 'Incredibile. Hai ucciso Rema da sola, senza aiuto?$B$BIn verità, a guardarti, forse ti si potrebbe credere. Sai, $c, stiamo proprio cercando una giovane forte come te. Da queste parti abbiamo bisogno di una mano, specialmente per risolvere la questione degli Ogre. Ricordati di tornare a parlarne con me.$B$BBe'', ti sei certamente guadagnata la ricompensa.$B$BScegli pure.', 0),
(10702, 'itIT', 'Fantastico! Qualora dovessi avere altro lavoro da Grunt, ti chiamerò.', 0),
(10703, 'itIT', 'Sì, ottimo lavoro! Ecco del denaro come ricompensa. Se ci servirà qualcuno per occuparsi della spazzatura, saprò chi chiamare.', 0),
(10704, 'itIT', 'Sono colpito, $N. Anche se non dovrei stupirmi dell''eroina che ci ha riportato il Cristallo di Ata''mal.$B$BDammi i due frammenti e farò in modo di unirli perché assumano la loro forma finale. A quel punto, potrai accedere ad Arcatraz.', 0),
(10706, 'itIT', 'Sì... Ma certo! Ora è tutto chiaro.', 0),
(10707, 'itIT', 'Il cristallo! Il suo potere... finalmente è in mano mia!', 0),
(10710, 'itIT', 'Caspita! Sei sopravvissuto di nuovo! Sono un ingegnere migliore di quanto non creda!$B$BEcco la tua paga! E torna da me, più tardi. Ho altri esperimenti da condurre e di cavie non ce n''è mai abbastanza!', 0),
(10711, 'itIT', 'Diamine! Di ritorno... e così presto! Ti ho visto fiondarti in cielo come un razzo! Ero sicuro che ti ci sarebbe voluto almeno un mese di cure e convalescenza per le ossa rotte, prima che fossi di nuovo in grado di camminare! Sei tosta, coraggiosa e temeraria! Ma soprattutto... sei coraggiosa!', 0),
(10712, 'itIT', 'Oh, hai raccolto i dati con la Banderuola Segna-Ventofatuo? Splendido! Questi dati, uniti alle mie analisi sulla magia druidica, torneranno molto, molto utili!$B$BOh, già mi vengono in mente mille applicazioni incredibili!', 0),
(10713, 'itIT', 'Grazie, $N.$B$BRipristinare la fauna sarà relativamente semplice. Far crescere nuovi alberi, specialmente senza ricorrere alla magia, è un procedimento molto più lento.', 0),
(10717, 'itIT', 'Oh, sembrano perfette. Questi cultisti sanno il fatto loro.$B$BPeccato che tanta abilità sia mal indirizzata.$B$BOra che abbiamo le reti, mi aiuteresti a risolvere un paio di faccende?', 0),
(10719, 'itIT', 'Interessante e al tempo stesso inquietante. Chissà se Samia conosce questo Kolphis Scagliascura?', 0),
(10753, 'itIT', 'Non sono fiera di aver distrutto ciò che Elune ha creato, ma questa corruzione andava fermata. Ben fatto, $c.', 0),
(10778, 'itIT', 'Ben fatto. Un simile tesoro non merita di essere rinchiuso in un buio forziere. Faremo in modo di utilizzarlo per uno scopo nobile.', 0),
(10781, 'itIT', 'Indagheremo sul Sigillo Cremisi. Rappresentano una minaccia per tutta la vita su Draenor. Prevedo che un giorno il loro maestro oscuro dovrà pagare per i suoi crimini. Forse, sarai proprio tu a portarlo davanti alla giustizia.', 0),
(10792, 'itIT', 'Ah! Riuscivo a vedere il fuoco e il fumo di Zeth''gor da qui! Che i maledetti Guerci Insanguinati diventino cenere e spariscano dalla vista di tutti i VERI Orchi!$B$BGrazie, $N. Hai eliminato un insulto allo spirito di ogni Orco.', 0),
(10793, 'itIT', 'Hai ucciso il loro Conquistatore? Allora non abbiamo molto tempo...$B$BIl Sigillo Cremisi è un gruppo composto da seguaci d''élite di Illidan. Sono i vertici della catena di comando delle truppe Illidari fuori dal Tempio Nero. Questi soldati comunicano direttamente con il Traditore, eseguendo i suoi ordini senza fare domande.$B$BSono gli esseri che senza dubbio guideranno l''assalto a questo mondo, schiacciando tutti coloro che li ostacoleranno.', 0),
(10795, 'itIT', 'Morto Dorgok, gli Ogre Magliorosso sono senza guida e non dovrebbero più costituire una minaccia finché non s''imporrà un nuovo capo.$B$BGrazie, $c. Ora possiamo dormire più tranquilli.', 0),
(10797, 'itIT', 'Ah, che statuetta carina. Assomiglia molto ai Gronn che comandano gli Ogre Lamacurva.$B$BStrano che tu l''abbia trovata nelle mani di uno dei capi dei Magliorosso.', 0),
(10798, 'itIT', 'Ah, un''inviata della tanto decantata Alleanza. Dimmi, lacchè, perché a implorare il mio aiuto in questa faccenda ci sei tu e non il tuo illustre comandante?$B$BForse perché ha paura di me? Quanto alla tua presenza qui, almeno è indicativa di ciò che non sei... ma la domanda è: che cosa sei?', 0),
(10799, 'itIT', 'Molto bene. La prima, semplice e nient''affatto magica parte della nostra missione è stata completata. Adesso dammi le ghiandole: devo eseguire la parte complessa.', 0),
(10801, 'itIT', 'Mmm, una trappola basata sull''essenza del fuoco di drago? Chissà come fa il Barone a procurarsi sostanze tanto rare...$B$BMa non importa. Ciò che importa è che ce ne serviremo per uccidere un figlio di Gruul!', 0),
(10804, 'itIT', 'Che $r gentile e compassionevole!', 0),
(10808, 'itIT', 'Per anni ho cercato un modo per fermare il Conclave Oscuro e tu sei riuscito dove io ho fallito. I loro rituali malvagi non ci minacceranno più.$B$BSpesso, mi sento in colpa per aver abbandonato i miei compagni tanti anni fa, ma ora finalmente so di aver preso la decisione giusta. Se allora la mia coscienza non avesse vacillato, sarei diventato un''altra ombra come loro.', 0),
(10809, 'itIT', 'Quindi hai ucciso quel maledetto Kruush! Ben fatto, $N! Davvero ben fatto! La sua morte renderà inoffensivi i Predoni Worg. Anzi, spero che tu ne abbia ucciso qualcuno nella tua sortita a Zeth''gor!$B$BEcco la tua ricompensa: te la sei meritata!', 0),
(10810, 'itIT', 'Ah, cos''hai lì con te? Fammi dare un''occhiata più da vicino... Sì, proprio come pensavo. Va bene, lascia che te la ripari.', 0),
(10811, 'itIT', 'I miei figli mi hanno parlato delle tue gesta eroiche, $r. C''è ancora qualcosa che puoi fare.', 0),
(10812, 'itIT', 'La maschera che hai in mano è una Maschera Antigas dei Vilfedeli e, a quanto pare, è perfettamente integra. I danni che con essa potremo causare a Fornace Collera sono incalcolabili. $N, ti interessa aiutarci?', 0),
(10813, 'itIT', '$N, ti sono debitore! Ancora una volta, sei penetrato all''interno di Zeth''gor e il tuo cuore ha dovuto sopportarne il peso dell''oscurità. Studierò l''Occhio e forse riuscirò a svelare i segreti del suo padrone, Grillok.$B$BSperiamo che non riesca più a usare la magia!', 0),
(10814, 'itIT', 'Ci aiuterai?', 0),
(10817, 'itIT', 'Oggi, ti sei guadagnato il mio pieno rispetto, $N.$B$BUccidere un Vilorco non è impresa da poco. Massacrarne un esercito è... be'', eroico.', 0),
(10819, 'itIT', 'Che significa tutto questo? Nessuno mi disturba senza motivo! Parla, o ti farò tacere per sempre!', 0),
(10820, 'itIT', 'Questo insegnerà loro a non eseguire i miei ordini...$B$BA proposito... dov''è Urlarovina? Perché sei stata tu a riferirmi di questa rivolta e non lei?', 0),
(10829, 'itIT', 'Salve, $R. Gli uccelli sui miei rami mi hanno annunciato il tuo arrivo.$B$BSei qui per aiutarmi a liberare gli alberi della selva dalla possessione di cui sono vittime?', 0),
(10830, 'itIT', 'Il male sta lasciando la Selva del Corvo! Lo senti anche tu, $N?$B$BHai salvato noi e tutta la fauna circostante da una distruzione certa!$B$BPer occasioni del genere conservo tra i miei rami quattro anelli magici, da donare a una vera eroina.$B$BTu certamente sei una di quelle eroine! A nome di tutta la Selva del Corvo, grazie!', 0),
(10834, 'itIT', 'Ah, sì. A volte, chi ha perso una mano o una gamba in battaglia, sente ancora l''arto mancante. Mi chiedo se anche Grillok percepisca il suo Occhio perduto nei suoi sogni tenebrosi.$B$BLo sognerò anch''io e, se avremo fortuna, scoprirò per quale motivo Grillok e gli Orchi Guerci Insanguinati hanno ceduto ai demoni.', 0),
(10839, 'itIT', 'Ho sentito l''esplosione da qui. Non con le orecchie, ma con il cuore.$B$BSe neanche il tocco del Naaru benedetto, A''dal, basta a redimere gli Arakkoa, allora nulla può farlo. Coloro che non si sono votati alla Luce servono il male.$B$BDevono essere distrutti.', 0),
(10840, 'itIT', 'Accà, nelle zone selvagge delle Terre Esterne, siamo deboli e teniamo pochi eroi che ci difendono, ma tu li hai spaventati, $c. Penso che li Eterei nun dimenticheranno presto il braccio forte di $N.', 0),
(10847, 'itIT', 'La tua audacia merita di essere riconosciuta. I Guardiani di Skettis non si separano volontariamente dai loro beni.$B$BMa gli atti eroici del passato ora contano poco. Vedremo se tale valore sopravvivrà in futuro, perché lo sguardo di Terokk è diretto a sud.$B$BQuesti occhi vedono tutto.', 0),
(10848, 'itIT', 'Quegli spiriti malvagi meritavano di morire, perché avrebbero causato la morte di altri innocenti.$B$BNon c''è speranza di redimere coloro che sono caduti nella stretta di Terokk. Ma dobbiamo sferrare loro un duro colpo nel nome della Luce.', 0),
(10849, 'itIT', 'La storia di Rilak è sinistra. Come puoi vedere dallo stato della carovana, la Foresta di Terokk è oggi un luogo di oscurità e tristezza.', 0),
(10852, 'itIT', 'Hai trovato tutti i miei amici! Ora posso giocare con qualcuno. Grazie, signora $N.$B$BVisto che non sono più solo... vuoi uno dei miei giocattoli? Così avrai anche tu qualcosa con cui giocare.', 0),
(10861, 'itIT', 'È un lavoro ingrato eliminare la prole di qualcuno, ma ignorare il male crescente sarebbe comunque sbagliato. Hai agito bene. La benedizione di A''dal splende nel tuo cuore.', 0),
(10869, 'itIT', 'Ben fatto, $c. Gli Arakkoa hanno imparato a temere la potenza dell''Alleanza.', 0),
(10873, 'itIT', 'Ne hai salvati molti. Pensavamo che non li avremmo più rivisti. Non sappiamo come ringraziarti, $N.', 0),
(10874, 'itIT', 'Abbiamo visto da qui il fumo maledetto. Sei davvero prode, $c.', 0),
(10877, 'itIT', 'È incredibile che tu ce l''abbia fatta. La Reliquia del Terrore è molto più potente di quanto temessi. Solo una prode eroina avrebbe potuto sopravvivere al lungo viaggio di ritorno portando con sé una tale blasfema malvagità.', 0),
(10878, 'itIT', 'Per ora posso tirare un sospiro di sollievo, $N. Il Concilio dell''Ombra si terrà in disparte per un po''.$B$BÈ fatto di assassini e codardi, e la tua prova di coraggio li terrà a bada.', 0),
(10879, 'itIT', 'Plaudo al tuo valore in battaglia, $c. Hai dimostrato di essere un vero difensore della Luce. Possa la benedizione di A''dal accompagnarti nelle ore più buie.$B$BMa osserva l''orizzonte; un cielo oscuro sovrasta Skettis. Terokk sta senz''altro pianificando la sua prossima mossa. Per ora Shattrath è al sicuro, ma nessuno sa quale orrore dovremo affrontare in futuro.', 0),
(10880, 'itIT', 'Ah, sì... è stato scritto utilizzando una forma base del codice cifrato dell''Ombra. Non lo conosco alla perfezione, ma dovrei riuscire a tradurlo.$B$BImpari molte cose poco edificanti quando vivi tra emarginati e rifugiati nella Città Bassa.', 0),
(10881, 'itIT', 'Forse la Luce mi ha abbandonato, ma io non ho abbandonato la Luce. Un tempo queste reliquie erano sacre per la mia gente.$B$BPermettere che il Concilio dell''Ombra usi il loro potere per compiere il male è... inimmaginabile!', 0),
(10887, 'itIT', 'Hai salvato Akuno, un mio caro amico. Sono in debito con te, $N.', 0),
(10889, 'itIT', 'I Guardiani di Skettis macchinano dal loro covo. Shattrath è in pericolo. Di certo subiremo la vendetta di Terokk.$B$BRaduna al più presto una squadra di difesa! Parla con il Difensore Grashna e informalo che sei pronta a impugnare le armi contro i nostri assalitori!', 0),
(10895, 'itIT', 'Ho visto il fumo e le fiamme da qui! Ottimo lavoro, $N! I nostri Cavalieri di Grifoni non smettono di lodarti: ci vuole del fegato per compiere un''impresa del genere.', 0),
(10896, 'itIT', 'Hai fatto molto per aiutare la Foresta di Terokk, $N. Con la gran parte delle colonie di acari distrutta potremmo riuscire a riprenderci questa terra devastata.', 0),
(10898, 'itIT', 'Ahimè, il povero Alaceleste era sotto l''influsso della maledizione di Luanga l''Imprigionato!$B$BAlaceleste aveva raggiunto Vol Shalas nel tentativo di far proseliti nella via della Luce. Non hanno reagito bene dopo ciò che ha fatto, specialmente quando è arrivato a Skettis.$B$BLuanga era uno degli Agenti più temuti di Terokk. Hai agito bene liberando Alaceleste! Ti ringrazio.', 0),
(10903, 'itIT', 'Sì, è vero: negli ultimi giorni, le condizioni del Colonnello Jules sono peggiorate notevolmente. L''Anacoreta Barada sta pregando per lui, speriamo sia possibile curarlo.', 0),
(10904, 'itIT', 'Quelle munizioni puzzano più di quanto pensassi!$B$BPresto, dammele e io le tratterò con la forza della Natura, in modo che risultino estremamente letali per i loro vili padroni e le loro creazioni innaturali.', 0),
(10909, 'itIT', 'Gli Orchi Manomozza sono malvagi senza speranza di redenzione, ma il mio cuore è triste al pensiero che la via per la salvezza del Colonnello Jules comporti un tale spargimento di sangue.', 0),
(10910, 'itIT', 'È un sollievo per noi che il Signore della Selva Antelarion ti abbia inviata qui. Il problema è molto più grave di quanto temessimo inizialmente!', 0),
(10911, 'itIT', 'Sei davvero strabiliante!$B$BBenissimo. Tolti di mezzo i portali Distorcenti, rimane una sola cosa da fare.', 0),
(10914, 'itIT', 'Ce l''hai fatta, $N! Grazie a te abbiamo realizzato una nuova scoperta...', 0),
(10915, 'itIT', 'Abbiamo vinto! Questa sconfitta farà perdere agli Auchenai diverse settimane.', 0),
(10916, 'itIT', '$N, hai trovato le Perle della Preghiera! Ben fatto! Sei davvero meraviglioso: un momento prima stai sterminando gli orrori che infestano la Penisola del Fuoco, quello dopo trovi dei tesori perduti. Il tuo popolo è una vera fonte d''ispirazione!$B$BPer fortuna hai recuperato le Perle: sono indispensabili per l''esorcismo che sta per essere compiuto.', 0),
(10920, 'itIT', 'Ho sentito da qui il rumore della battaglia, $c. Il suono della vittoria ha riempito il mio cuore di speranza. Se tu puoi sconfiggere nemici così terribili, forse io posso trovare la forza di portare via i miei compagni da questo luogo orribile.', 0),
(10921, 'itIT', 'Le Vedove Malazanna sono state sconfitte. Ne hai uccise molte, e anche la loro malvagia madre è caduta sotto i tuoi colpi. Ho troppo veleno in circolo per combattere.$B$BTieni, prendi un po'' del mio equipaggiamento. Mi allevierà il carico e ti fornirà gli strumenti necessari per tornare al Campo Base Sha''tari.', 0),
(10922, 'itIT', 'Un verme delle ossa! Fantastico! Potrebbe essere la prima volta nella storia che Letoll scopre qualcosa.', 0),
(10923, 'itIT', 'Una grande malvagità è stata cacciata da Terokk. Gli Sha''tar sono in debito con te.', 0),
(10924, 'itIT', 'Dovrebbe essere una riserva sufficiente per i miei bisogni.$B$BSpero che l''Imp non ti abbia fatto impazzire. Ha una lingua davvero biforcuta.', 0),
(10926, 'itIT', 'Mi fa piacere sapere che alcuni dei nostri guerrieri si siano battuti bene contro le Vedove Malazanna. Invieremo immediatamente una squadra di recupero.', 0),
(10927, 'itIT', 'Ottimo lavoro, $c. Quella galleria rappresenta il nostro cordone di salvataggio in questa palude.', 0),
(10929, 'itIT', 'Gnomi delle Sabbie? Sì, certo... Il deserto può fare strane cose a una persona.$B$BCredo che grazie a questi vermi siamo a un passo da qualcosa di sensazionale!', 0),
(10930, 'itIT', 'Fantastico! Guarda qua! Questo coso ha una specie di polvere dentro il suo affare. Bah! Non voglio annoiarti con il gergo scientifico. Sono riuscito a estrarre qualche dente ai cuccioli per farci questi affilatissimi coltelli. Ne vuoi uno?', 0),
(10935, 'itIT', '$N, ce l''hai fatta! Hai salvato il Colonnello Jules e scacciato l''oscurità dalla sua anima. Che gesto nobile! Sei un vero eroe!', 0),
(10936, 'itIT', 'Era ora! Ho saputo cosa hai fatto insieme a quel Sacerdote Draenei. Avete terrorizzato il mio messaggero!$B$BVisto che ora non hai niente da fare, ho una piccola missione da affidarti nella Cittadella del Fuoco Infernale.', 0),
(10937, 'itIT', 'Finché non l''ho sentito dalla tua voce, non ci ho creduto. I nostri esploratori già iniziano a informarci che i Manomozza sono allo sbando senza il loro prezioso Maestro Istruttore a dare gli ordini.$B$B$N, hai fatto molta strada: accetta questa armatura e la mia gratitudine. Indossala con orgoglio, te la sei meritata!', 0),
(10942, 'itIT', 'Umpf, sei tu che mi accompagnerai? Mi chiamo Salandria! Sono qui fin da quando ero molto piccola. I miei genitori sono morti nella guerra e quindi ho dovuto vivere nell''orfanotrofio.$B$BNon è male, ma ho sempre voluto vedere il mondo. Non sono nemmeno mai stata fuori dalla città. Ho già fatto un elenco di tutti i bei posti che voglio visitare e delle cose fantastiche che voglio fare.$B$BQuando vuoi, sono pronta!', 0),
(10945, 'itIT', 'Ti ringrazio per avermi dato la possibilità di rivedere Salandria. Mi è mancata moltissimo nell''ultimo anno, ma siamo rimaste buone amiche.$B$BAbbiamo deciso che quando saremo grandi, diventeremo entrambe delle avventuriere, proprio come te!', 0),
(10950, 'itIT', 'Oh! Che posto meraviglioso! Voglio dire, sembra molto vecchio... E qualcuno lo ha fatto saltare in aria! Però non sono mai stata in un luogo così affascinante!$B$BOooh, e hai visto il cielo?$B$BBello!', 0),
(10951, 'itIT', 'Questo posto è molto più bello di quanto mi hanno raccontato. Fantastico! È vero che è stato creato da un potente Mago di nome Medivh?$B$BCosa c''è dall''altra parte? Tu ci sei stato, vero? Dovremmo proprio andare dall''altra parte del Portale Oscuro.', 0),
(10952, 'itIT', 'Questo posto è molto più bello di quanto raccontassero le storie della Matrona. Fantastico! Ha detto che è stato creato da un potente Mago di nome Medivh.$B$BCosa c''è dall''altra parte? Tu ci sei stato, vero? Dovremmo proprio andare dall''altra parte del Portale Oscuro.', 0),
(10953, 'itIT', 'Una bambina qui? Quale avventatezza! Ti prometto che nessuno le torcerà un capello, ma non farla avvicinare a Incineratus.$B$BMmm, sfortunatamente è un''Elfa del Sangue. Avesse un profondo legame con il mondo, potremmo insegnarle qualcosa per farci aiutare a curare le sue ferite. Forse la sua esposizione agli elementi le farà capire meglio i meccanismi che li regolano.$B$BVai in pace e abbi cura di lei.', 0),
(10954, 'itIT', 'Dornaa mi mancava tantissimo. Grazie per averla portata da me. Mi sento un po'' solo qui, in compagnia di solo Eterei. E tutti sono talmente seri, quando si parla di Oshu''gun.$B$BTornerò a fare visita all''orfanotrofio quando avrò superato l''esame di Oreficeria. La settima scorsa ci ero quasi riuscito, ma credo che la prossima andrà meglio.', 0),
(10966, 'itIT', 'Fa bene allo spirito sapere che ci stanno eroi come te capaci di donare con generosità il tempo loro.$B$BPosso dirti sin da mo'' che i giorni che hai passato con Dornaa hanno fatto n''ottima impressione. Fa bene ai guaglioni uscire da accà per vedere il mondo.$B$BTieni. La creatura vuole che ti prenda cura di una delle mascotte preferite sue, come ti sei preso cura di issa. È nu modo per ricordarla.$B$BNun la deludere.', 0),
(10967, 'itIT', 'Fa bene allo spirito sapere che ci stanno eroi come te capaci di donare con generosità il tempo loro.$B$BPosso dirti sin da mo'' che i giorni che hai passato con Salandria hanno fatto n''ottima impressione. Fa bene ai guaglioni uscire da accà per vedere il mondo.$B$BTieni. La creatura vuole che ti prenda cura di una delle mascotte preferite sue, come ti sei preso cura di issa. È nu modo per ricordarla.$B$BNun la deludere.', 0),
(10968, 'itIT', 'Ci speravo, ma spesso sono stato preso dallo sconforto credendo che fosse solo un inganno della mia mente. Questa bambina è eccezionale!$B$BHa una grande padronanza degli elementi pur non avendo mai ricevuto alcun addestramento. Deve avere ereditato questo potere da un antico antenato.$B$BInvierò una lettera alla Matrona degli Orfani di Shattrath domandandole di affidarci la bambina.$B$BNel frattempo, ti chiedo di proteggerla.', 0),
(10970, 'itIT', 'Indietro, $N. Potrebbe anche trattarsi di una trappola degli Etereum.', 0),
(10971, 'itIT', 'Sembra più di una misura identificativa. C''è una specie di codice scritto sulle medagliette. Sono sul punto di violarlo. Forse se ne avessi ancora qualcuna.', 0),
(10972, 'itIT', '$N, siamo vicini alla verità.', 0),
(10975, 'itIT', '$N, c''è sempre altro lavoro da fare. Ora cerca una camera di stasi ed elimina qualsiasi essere malvagio si trovi al suo interno!', 0),
(10983, 'itIT', 'Grok dice che sono saggio? Non saprei.$B$BForse è perché sono l''unico che sta davvero cercando di salvare il nostro clan prima che il Clan Lamacurva, Gruul e i suoi figli ci annientino.$B$BSpero che tu sia qui per salvarci da morte certa, $c.', 0),
(10984, 'itIT', 'Aiuterai Grok? A Grok serve aiuto! Al Clan Magliorosso serve aiuto!', 0),
(10989, 'itIT', 'Finalmente Chort mi ha mandato una persona che ha l''aspetto di qualcuno in grado di aiutarci. Sto cercando di salvare i Magliorosso dall''annientamento a opera del Clan Lamacurva e dei Figli di Gruul che lo sostengono.$B$BSpero che aiuterai la nostra società segreta a riconquistare la propria libertà.', 0),
(10995, 'itIT', 'Dev''essere stato uno scontro molto difficile, $c. Ma ora che non sento più il suo fiato sul collo, mi sento molto sollevato.$B$BInvierò questo teschio a Chort affinché lo custodisca. Comincio a pensare che, con il tuo aiuto, potremmo anche farcela.', 0),
(10996, 'itIT', 'Dici che è vuota? Peccato... ma ora capirai a quale sciocca crudeltà siamo sottoposti.$B$BCon la caduta di Maggoc, siamo un passo più vicini alla realizzazione del mio sogno: una patria per gli Ogre, che saranno finalmente liberi di determinare da soli il proprio destino.', 0),
(10997, 'itIT', 'Per fortuna anche Slaag è morto. Non saremo più minacciati dalla terribile prospettiva di un suo ritorno!$B$BSe non ti dispiace, prenderei in consegna lo stendardo per usarlo come simbolo di speranza per tutti gli Ogre delle montagne.$B$BGrazie, $N.', 0),
(10998, 'itIT', 'Esito persino a toccare un oggetto del male tanto corrotto. Eppure dobbiamo leggerlo, se vogliamo scoprire come fare per stanare Skulloc dal suo nascondiglio.', 0),
(11000, 'itIT', 'È finita, finalmente! Ci hai liberati dalla nostra schiavitù nei confronti dei Figli di Gruul. Hai salvato il Clan Magliorosso da estinzione certa.$B$BLe parole non possono bastare a esprimere la gratitudine che TUTTI gli Ogre delle Montagne Spinaguzza ti devono... tanto i Magliorosso quanto i Lamacurva!$B$BGuarda, gli Ogre si stanno già radunando per renderti onore. Lasciamo che Gruul e il suo fantoccio, Maulgar, si lecchino le ferite nel loro covo. Ora raggiungi i tuoi Ogre, o nostra Regina!', 0),
(11004, 'itIT', 'Ti ringrazio, $N. Ne darò un po'' al Comandante... per assecondarlo. Puoi tenere il resto, magari potrà servirti a qualcosa.', 0),
(11005, 'itIT', 'Hai agito bene, $N. Hai sferrato un duro colpo al nemico uccidendo i suoi Sacerdoti dell''Artiglio.', 0),
(11006, 'itIT', 'Continua a portarmi la polvere, preparerò tutti gli elisir che ti servono.$B$BOrdini del Comandante.', 0),
(11008, 'itIT', 'Ottimo lavoro, $N! Così quegli uomini uccello impareranno il significato di superiorità aerea!', 0),
(11015, 'itIT', 'Per oggi hai finito. Torna domani, se sarai ancora in vita.', 0),
(11016, 'itIT', 'Per oggi hai finito. Torna domani, se sarai ancora in vita.', 0),
(11017, 'itIT', 'Per oggi hai finito. Torna domani, se sarai ancora in vita.', 0),
(11018, 'itIT', 'Per oggi hai finito. Torna domani, se sarai ancora in vita.', 0),
(11021, 'itIT', 'Cosa mi hai portato? Non riesco a mettere a fuoco le scritture su questo tomo, $N... La perdita di sangue... deve avermi offuscato la vista.', 0),
(11024, 'itIT', 'Non è possibile... questo era di un Sacerdote dell''Artiglio. Come l''hai avuto?', 0),
(11029, 'itIT', 'Ottimo! Questo libro elenca i discendenti degli antichi nemici di Terokk. Secondo una profezia, alla loro morte seguirà il ritorno di Terokk.', 0),
(11040, 'itIT', 'Alcuni di questi pezzi non so nemmeno a cosa servano! Sono certo che troverò il modo di usarne qualcuno, ma non avrei mai immaginato di dover imparare a pensare come uno Gnomo!', 0),
(11050, 'itIT', 'Sei un vero eroe, $N.', 0),
(11051, 'itIT', 'Vorremmo tanto che il nostro procedimento per la creazione delle Rune Oscure fosse totalmente affidabile. Purtroppo non lo è. Ti prego, prendi questa borsa e guarda al suo interno per vedere cosa abbiamo ricavato oggi. Noi non abbiamo il coraggio di farlo.$B$BRicorda: se ottieni una Runa Oscura, portala a Gahk per scambiarla con una Runa Oscura Forgiata nel Cristallo. A quel punto potrai di nuovo sabotare il Connettore di Shartuul.$B$BE non dimenticare di tornare domani a prendere il Cristallo dell''Esilio. I demoni da bandire non mancano mai.', 0),
(11055, 'itIT', 'Un duro giorno di lavoro! Ma ne vale la pena, non trovi? Ti scalda il cuore vedere quegli inutili insetti spaccarsi la schiena con i cristalli... Comunque, per oggi è tutto. Torna domani per un''altra giornata di allenamento nell''uso dello Stivale Rotante.', 0),
(11056, 'itIT', 'Ottimo, $N. Terrò fede alla mia parola... vedrai.', 0),
(11070, 'itIT', 'Be'', sembra che ora sia tu il capitano, soldato. Buona fortuna! Ti servirà!', 0),
(11071, 'itIT', 'Non avrei mai immaginato che ci fosse qualcuno tanto abile da sconfiggere Spezzacielo. Sai cosa significa, vero? Ora sei il Top Orc! Devi difendere il titolo.', 0),
(11073, 'itIT', 'Ci hai resi tutti molto orgogliosi, $N. Comunicherò a Shattrath la notizia della tua impresa. I Guardacieli ti saranno per sempre debitori.', 0),
(11074, 'itIT', 'Ottimo! Prendi. Ho preparato questo pacco con gli oggetti che hai trovato. Ti permetteranno di evocare Terokk.$B$BFa'' attenzione, $N. È il più potente Arakkoa che sia mai esistito. Non sottovalutarlo!', 0),
(11076, 'itIT', 'Ben fatto, $N. Torna domani per ricevere un''altra missione nelle profondità della miniera.', 0),
(11077, 'itIT', 'Per oggi può bastare, Sovrintendente. Torna domani per un altro giro di pulizie.', 0),
(11085, 'itIT', 'Grazie per aver salvato uno dei nostri esploratori, $N. Perdiamo uomini validi ogni giorno e non abbiamo reclute a sufficienza per rimpiazzarli.', 0),
(11086, 'itIT', 'Eccellente lavoro, capitano. Sire Illidan sarà informato del tuo eroismo!', 0),
(11090, 'itIT', 'Tornerà, ma per il momento la guerra della Legione contro Sire Illidan non è più così aspra. Sarà informato delle tue gesta, Capitano.', 0),
(11092, 'itIT', 'Sire Illidan in persona ha chiesto che ti promuovessi al grado di Comandante! Non è mai accaduto. Sarai il primo Fauci di Drago che non appartiene al Tempio Nero a raggiungere questo grado.', 0),
(11093, 'itIT', 'Grazie per esserti occupato della manta, $N. Solo il cielo sa quanto siano efficienti a stomaco pieno. Non vogliamo che i nostri ragazzi vengano abbattuti, perché le loro mante sono troppo deboli per volare.', 0),
(11096, 'itIT', 'Bel lavoro, asso. Sento che ti integrerai alla perfezione.', 0),
(11103, 'itIT', 'Le sabbie del tempo scorrono naturalmente in avanti. Possono anche essere riportate indietro, ma con grande difficoltà.', 0),
(11105, 'itIT', 'Le sabbie del tempo scorrono naturalmente in avanti. Possono anche essere riportate indietro, ma con grande difficoltà.', 0),
(11107, 'itIT', 'Sei il primo Gran Signore delle Fauci di Drago, $N. Il maestro stesso ha deciso di recarsi qui per promuoverti.', 0),
(11129, 'itIT', 'Ottimo lavoro, $N! Kyle è tornato a casa appena finito di mangiare ed è andato dritto a letto. Grazie dell''aiuto.', 0),
(11153, 'itIT', 'È questo che volevo sentire! Non c''è dubbio, $N: hai stoffa da vendere!$B$BNon è che potresti tornare domani, quando avremo creato altri esplosivi? Ti farei tornare subito laggiù, ma Feknut, il mio assistente, non è ancora tornato con il guano di pipistrello.$B$BChissà come mai ci mette tanto...', 0),
(11157, 'itIT', 'Ottimo lavoro! Con un po'' di fortuna, la distruzione delle uova e dei cuccioli dovrebbe scacciare quelle bestie infuocate e prevenire la propagazione delle fiamme magiche.$B$BUn momento... cos''è questo suono? Sembrerebbe un battito d''ali.', 0),
(11167, 'itIT', 'Sono felice di rivederti tutto intero. Il rischio di infettarsi maneggiando quei contenitori non è da sottovalutare. Forse avrei dovuto avvertirti prima.', 0),
(11168, 'itIT', '$N, continui a dimostrare la tua competenza! Spero che questa tossina basti a potenziare la Piaga al livello necessario.$B$BPerlomeno dovrebbe indebolire la vittima e renderla più predisposta a infettarsi.', 0),
(11170, 'itIT', 'Umpf! I rapporti dal campo di battaglia sono... poco incoraggianti!', 0),
(11175, 'itIT', 'Grrr. Lo sapevo! È trooooooppo protettivo! Che vergogna...$B$BNon che mi dispiaccia vederti, sia chiaro... Anzi, al contrario: siamo tutti felici che tu sia qui, perché abbiamo bisogno d''aiuto!', 0),
(11176, 'itIT', 'Ti ha chiesto Irena di venire qui, vero? Ottimo, abbiamo del lavoro per te!', 0),
(11182, 'itIT', 'È increscioso che un predatore debba essere usato per abbatterne un altro... ma è l''ordine naturale delle cose.$B$BForse ora i Proto-Drachi e il loro draghetti possono tornare a vivere in pace. Anche se ne dubito, visto che ormai i Vrykul si sono risvegliati.', 0),
(11190, 'itIT', 'Che tu sia benedetto, $N!$B$BPoggiale pure lì dove ti trovi: le farò subito venire a prendere dai ragazzi. Finalmente possiamo smetterla di preoccuparci: d''ora in poi le munizioni per bombardare Skorn non mancheranno.', 0),
(11199, 'itIT', 'Magnifico! Un aiuto! Appena in tempo!', 0),
(11202, 'itIT', 'Bene!$B$BCosa dicevi riguardo a ciò che ha trovato nei carri? I Reietti stanno spargendo la Piaga sui Vrykul laggiù?', 0),
(11213, 'itIT', 'Meno male che Nazeer ha mandato qualcuno. Abbiamo dei nuovi vicini che non hanno fatto altro che crearci problemi da quando sono arrivati.', 0),
(11215, 'itIT', 'Qualsiasi tipo di aiuto ci tornerà utile! Abbiamo intenzione di restare qui e sfruttare al massimo quello che abbiamo, finché non riceveremo le provviste dello Zeppelin.', 0),
(11221, 'itIT', 'I cannoni ci rallentano? Glieli faccio vedere io, i cannoni!', 0),
(11224, 'itIT', '$c, ti sono debitrice. Ora che abbiamo recuperato la maggior parte dei muli e dell''equipaggiamento, potremo aumentare il numero di soldati di stanza al Forte di Guardia dell''Ovest.$B$BTi prego, accetta questa ricompensa.', 0),
(11228, 'itIT', 'Il Nano dice la verità. Non possiamo permetterci di perdere questo porto: è uno dei due attracchi sicuri per l''Alleanza in questo inferno ghiacciato. L''altro si trova qualche centinaio di miglia a ovest, sulla Costa della Tundra Boreale.', 0),
(11229, 'itIT', '$N, spero tu sia pronto a combattere! La flotta della Regina ha bisogno di te!', 0),
(11230, 'itIT', 'Ottimo lavoro: hai dato una bella lezione a quei maledetti. I miei uomini finiranno il lavoro.', 0),
(11231, 'itIT', 'Che tu sia benedetto! Grazie al tuo aiuto, la Luce risplende persino nei luoghi più oscuri.$B$BTi prego di accettare questa ricompensa. Io penserò ad aiutare coloro che hai liberato... o perlomeno quelli fedeli alla Luce e all''Alleanza che sono tornati qui al Forte.', 0),
(11232, 'itIT', 'Eccellente. Dirò alle nostre truppe di terra che possono avanzare.', 0),
(11233, 'itIT', 'Questa è una vittoria inconfutabile per la nostra fazione. Anselm sarà felicissimo di saperlo.', 0),
(11234, 'itIT', 'Era ora! L''Alleanza è stata una spina nel fianco per troppo tempo.$B$BComunque, non è ancora il momento di festeggiare. Guarda a ovest: abbiamo visite.', 0),
(11235, 'itIT', 'Ottimo lavoro, $N. Era ora!$B$BPerò ciò che mi hai riferito su quel luogo mi turba e temo che i nostri affanni non siano ancora finiti!', 0),
(11237, 'itIT', '$N, non possiamo permetterlo!', 0),
(11241, 'itIT', 'Lo Speziale Hanes è vivo? Ha bruciato tutti i rifornimenti dell''Alleanza? Deve essersi divertito un sacco.$B$B$N, l''Ordine Reale degli Speziali ti è debitore. Ti ringraziamo dal profondo dei nostri cuori oscuri.', 0),
(11243, 'itIT', '$N, hai fornito ai nostri difensori il supporto di cui avevano bisogno. Grazie a te, il loro morale è alle stelle. Credo che possano portare a termine la carneficina da soli. Ho un compito più importante da affidarti...', 0),
(11244, 'itIT', 'Ciò che i Vrykul hanno fatto ai nostri esploratori è stato un crudele sfoggio di ferocia. Hanno adottato la tattica del terrore per scalfire la nostra determinazione e metterci in fuga.$B$BBe'', non ha funzionato.$B$BStiamo per dimostrare a quei mostri cosa significhi pestare i piedi all''Alleanza!', 0),
(11250, 'itIT', 'Queste sono notizie eccellenti! $N, sapevo che ce l''avresti fatta!$B$BPer fortuna c''è ancora qualcuno in grado di produrre dei risultati!$B$BBe'', qui ci vuole una ricompensa. Coraggio, scegli pure liberamente.', 0),
(11255, 'itIT', 'I soldati che hai salvato ci hanno fornito un bel po'' di informazioni. I mostri si fanno chiamare "Vrykul". La tribù che si è stabilita a Cranio del Drago è guidata da un mistico di nome Yanis, agli ordini di un certo Ingvar il Saccheggiatore.', 0),
(11256, 'itIT', '$c, sarà interessante imparare qualcosa di più sul tuo popolo, mentre combattiamo insieme.$B$BDiamo il via all''operazione?', 0),
(11259, 'itIT', '$N, il tuo braccio è forte.$B$BFinalmente le Viverne dei Venti si sono rese utili, invece di passare tutto il giorno a dormire.', 0),
(11260, 'itIT', 'Sì, sembrerebbe un rituale malvagio e hai fatto la cosa giusta.$B$BGrazie per avermi portato questo rotolo, non vedo l''ora di studiarne le implicazioni. Se posso azzardare una previsione, direi che i Vrykul hanno trovato il modo di trascendere la morte... perlomeno per chi ne è degno.$B$BSconfiggendo il Thane di Geloskorn, ne hai dimostrato il poco valore. Chissà cosa sarebbe potuto diventare, e quale terrore avrebbe sparso su di noi, se non lo avessi ucciso.', 0),
(11261, 'itIT', 'Queste sono davvero ottime notizie! Ci hai fatto guadagnare un altro po'' di tempo per prepararci a partire.$B$BTi prego di scegliere una di queste ricompense.', 0),
(11262, 'itIT', 'Lavoro eccellente, $N. Senza il loro capo dovremmo trovare meno difficoltà contro i Vrykul.$B$BUn servigio del genere deve essere ricompensato!', 0),
(11263, 'itIT', '$N, ti ringrazio davvero. So che non devi nulla a me o al mio popolo.$B$BPerò ciò che mi hai riferito su quel luogo mi turba e temo che i nostri affanni non siano ancora finiti!', 0),
(11265, 'itIT', 'La notizia del tuo successo mi toglie un gran peso dallo stomaco. Sorrido pensando che alcuni di quelli che hai liberato sono Taunka.$B$BTi prego di accettare questo dono in cambio di ciò che hai fatto. Mi occuperò della salute di coloro che hai liberato.', 0),
(11266, 'itIT', '$N, non possiamo permetterlo!', 0),
(11269, 'itIT', 'Grazie al cielo! Dovrebbero bastare per completare l''ordine in tempo. Ovviamente, non dormirò fino all''arrivo delle truppe. Sempre meglio che sfidare le ire del Capitano Adams!$B$BHo sentito quello che si dice su di lui!', 0),
(11270, 'itIT', 'Hai dimostrato di poter eseguire gli ordini. Molto bene. Se avessi una moneta di rame per ogni idiota arrogante che è venuto qui nella sua armatura scintillante, pensando di poter ignorare la catena di comando... be'', avrei un bel gruzzolo.$B$BVisto che conosci la disciplina, ho altri incarichi per una persona del tuo calibro.', 0),
(11271, 'itIT', 'Grazie al tuo aiuto, saremo preparati per il viaggio. Non ho molto da offrirti in cambio, ma puoi scegliere qualcosa dalla mia attrezzatura da combattimento di riserva.', 0),
(11275, 'itIT', '$N, sono tutte ottime corna. Lasciamele esaminare, così potrò scegliere quello da usare nella caccia.$B$BDarò le altre agli artigiani affinché le intaglino.', 0),
(11277, 'itIT', 'Te la sei cavata bene! Ora che le Tavolette sono al sicuro, possiamo provare a salvare Daegarn per recuperare il Cifrario che ci permetterà di decodificare queste antiche reliquie!$B$BTu pensa a salvare Daegarn, io proteggo le Tavolette.', 0),
(11278, 'itIT', 'Ci vorrà un po'' di tempo per decodificare queste Tavolette. Da uno studio preliminare, ho scoperto solo che qui vivevano gli antenati degli Umani. Probabilmente i Vrykul li hanno uccisi tutti. Comunque, ne sapremo di più appena avrò capito cosa c''è scritto nelle reliquie.', 0),
(11279, 'itIT', 'Come?!? Non può essere.$B$BMALEDIZIONE!$B$BQuesto ceppo della Piaga non ha avuto alcun effetto sui Proto-Draghetti, tranne circondarli di un bagliore verde!$B$BIl mio sogno di utilizzarla contro chiunque venisse in contatto con noi è andato in fumo!', 0),
(11282, 'itIT', 'Complimenti, bella strage di Vrykul! Ho visto che infilavi stendardo di Sylvanas in loro cadaveri. Andiamo alla grande!', 0),
(11283, 'itIT', 'Devi aver fatto tanta pratica con uccisioni. Sei in gamba quasi quanto Gorth!', 0),
(11284, 'itIT', 'Ce l''hai fatta? Per la Luce, sei un miracolo vivente! Iniziavo a temere di dover spiegare personalmente al Capitano Adams per quale motivo le armi dei suoi uomini non sarebbero state pronte in tempo!', 0),
(11285, 'itIT', 'Scommetto che hai bruciato tutto. Ci sono posti che sono ancora intatti... ma Gorth si accontenta.', 0),
(11287, 'itIT', 'Mia madre non dovrebbe preoccuparsi tanto. Comunque ti ringrazio per essere venuto.$B$BVisto che sei qui, perché non mi dai una mano?', 0),
(11289, 'itIT', 'Molti uomini e donne sono morti per recuperare questa lama. Ahimè, temo che il valoroso Ares non sarà stato l''ultimo.$B$BMa tu hai compiuto la volontà della Luce. La Lama Sacra sarà impugnata da Ser Tirion Fordring in persona. Persino ora, la Crociata d''Argento avanza verso la Corona di Ghiaccio. Ser Fordring ha giurato di abbattere personalmente le mura di quel luogo maledetto! Grazie alla Lama, avrà una possibilità di sconfiggere il Re dei Lich.$B$BSer Fordring è la nostra speranza.', 0),
(11293, 'itIT', 'Ben fatto! La tua pubblicità farà bene ai nostri affari.$B$BEcco la ricompensa che ti avevo promesso: i Maltorzo mantengono sempre la parola.$B$BAh... se vuoi continuare a pubblicizzare il buon nome dei Maltorzo, torna pure quando vuoi!', 0),
(11294, 'itIT', 'Ottimo lavoro! Così imparano, quegli arroganti Maltorzo!$B$BEcco la ricompensa che ti avevamo promesso. I Birratuono mantengono la parola, mentre i Maltorzo sono solo chiacchiera e puzza.$B$BHai scelto bene.$B$BSe vuoi continuare così, torna a trovarci un altro giorno per continuare a spargere la voce.', 0),
(11295, 'itIT', 'Sei qui per aiutare? Bene, bene...$B$BGorth si era stancato di uccidere i Vrykul tutto il giorno. Un aiuto mi fa comodo!', 0),
(11296, 'itIT', '$c, hai compiuto un gesto davvero molto coraggioso. Non sapevo che il tuo popolo fosse capace di tale altruismo.$B$BLa prossima volta, darò retta ai consigli degli anziani e resterò alla larga dal Bosco di Legnotorvo. Ti suggerisco di fare lo stesso.', 0),
(11300, 'itIT', 'Che storia affascinante! C''è davvero qualcosa che giudica questi esseri? E perché? A quale scopo?$B$BBe'', non pensiamo a queste sciocchezze, se ne occuperà qualcun altro. Abbiamo di nuovo Cifrario e Tavolette... e ci sono costati solo due vite.', 0),
(11301, 'itIT', 'Che bei cervelli! Meravigliosi! Esattamente ciò che mi serviva.$B$B$N, ti ringrazio davvero. Ora mostrerò a Malthus la verità che non poteva scorgere attraverso i suoi boccali di birra.', 0),
(11303, 'itIT', 'Siamo tutti pronti per la festa... manca solo l''ospite d''onore.', 0),
(11304, 'itIT', 'Amico mio, questo ceppo è tutt''altro che inutile! Quegli imbecilli all''Attracco della Vendetta avevano tutte le risposte sotto il loro naso!', 0),
(11305, 'itIT', 'Questo andrà bene. È il momento di un po'' di vero lavoro da Speziale, $N!', 0),
(11306, 'itIT', 'Eccellente! $N, sei un ottimo allievo.$B$BOra arriva la parte divertente: la diffusione!', 0),
(11307, 'itIT', 'La Piaga non ha disintegrato i soggetti? $N, ne sei certo?$B$BDev''esserci un fattore esterno che non abbiamo considerato! Forse la bassa temperatura di questo clima? O forse... una mutazione del ceppo!', 0),
(11308, 'itIT', 'Che vuoi? Non lo vedi che ho da fare?', 0),
(11309, 'itIT', 'Eccellente! Sì, sì! Questi andranno benissimo!', 0),
(11310, 'itIT', 'Ottimo lavoro, $N. Senti un po'': non ti interesserebbe un impiego un po'' più... stabile? Non mi dispiacerebbe un po'' d''aiuto!', 0),
(11311, 'itIT', 'L''influsso degli spiriti elementali è svanito, ma tornerà. Abbiamo guadagnato del tempo per completare il lavoro qui e andarcene.', 0),
(11315, 'itIT', '$N, grazie per l''aiuto. Quando finalmente torneremo nella Radura Fremente, sarà di nuovo il bel posto di un tempo.', 0),
(11316, 'itIT', 'Ben fatto, $N. Quando la regione ha iniziato a mutare, se ci fossero stati alleati come te al nostro fianco, forse saremmo riuscite a preservare ciò che abbiamo perduto.', 0),
(11317, 'itIT', 'Percepisco il cambiamento dentro di te.$B$BSei pronto per ciò che ti attende?', 0),
(11318, 'itIT', 'Ottimo lavoro! Ci vuole tempo per imparare a controllare un montone ma, una volta che ce l''hai fatta, vorresti che ogni montone fosse da corsa.$B$BCome sarebbe a dire "Dov''è la mia ricompensa?!?" AH AH AH! Hai potuto cavalcare il montone più veloce in circolazione! Non ti basta? Che ne dici di questo...$B$BLa tua ricompensa è la possibilità di aiutare gli altri alla Festa della Birra. C''è molto lavoro... e molte ricompense... per giovani e capaci Corridori di Montoni.', 0),
(11319, 'itIT', 'Il Nucleo di Ghiaccio ha funzionato? Devo ricordarmene. Sono sicura che quei Protettori non si fermeranno solo perché abbiamo avuto successo una volta.', 0),
(11322, 'itIT', 'Percepisco il cambiamento dentro di te.$B$BSei pronto per ciò che ti attende?', 0),
(11323, 'itIT', 'Non riconosco il tuo aspetto, né il tuo odore... Non appartieni al mio branco. Raccontami la tua storia: finché sono intrappolato qui dentro, non ho nulla da fare.', 0),
(11324, 'itIT', 'Garwal non era un Worg! Conosco quelle creature... si chiamano Worgen!$B$BEppure Ulfang ha detto che è sceso a sud dai Colli Bradi... Che strano, lì non ci sono Worgen.$B$BGrazie per aver restituito a Ulfang il posto che gli spetta all''interno del branco. Ora potremo entrambi tornare a dormire in santa pace.$B$BTi prego di accettare questo pegno della mia gratitudine.', 0),
(11325, 'itIT', 'Non riconosco il tuo aspetto, né il tuo odore... Non appartieni al mio branco. Raccontami la tua storia: finché sono intrappolato qui dentro, non ho nulla da fare.', 0),
(11326, 'itIT', 'Garwal non era un Worg! Dalla tua descrizione, l''essere in cui si è trasformato sembrerebbe essere un Worgen!$B$BEppure Ulfang ha detto che è sceso a sud dai Colli Bradi... Che strano, lì non ci sono Worgen.$B$BGrazie per aver restituito a Ulfang il posto che gli spetta all''interno del branco. Ora potremo entrambi tornare a dormire in santa pace.$B$BTi prego di accettare questo pegno della mia gratitudine.', 0),
(11327, 'itIT', 'Per tutti... Ma che diavolo...?!? Guarda che roba!$B$BDobbiamo riportarla al più presto al Forte!', 0),
(11328, 'itIT', 'Oh... Ah, allora cambia tutto!$B$BFammi vedere quella roba. Mi piace giocherellare con l''alchimia!$B$BInteresshante... molto interesshante... Credo di shapere cosha devo fare. Un po'' di questo, un pizzico di quello...$B$BUna spruzzata di queshto torcibudella ci shtarebbe bene... hic!', 0),
(11329, 'itIT', 'Be''... Certo che sono brutti forte! Comunque non importa: basta che facciano il loro dovere. Non vedo l''ora che la Spedizione passi e se ne vada, così potrò tornare a pescare solo per la mia cena.', 0),
(11343, 'itIT', 'Non capisco... Le creature che hai visto assomigliavano ai Vrykul che attaccano Valguardia?', 0),
(11348, 'itIT', 'Hai sconfitto il Vincolatore Murdis, e questo è un bene, ma i Nani del Ferro non si arrenderanno facilmente.$B$BNe sappiamo sempre di più sulla loro manipolazione delle rune: potrebbe tornarci utile, la prossima volta che li incontreremo.', 0),
(11352, 'itIT', 'Hai sconfitto il Vincolatore Murdis, e questo è un bene, ma i Nani del Ferro non si arrenderanno facilmente.$B$BAvanzando verso nord, sono sicuro che il mio popolo li incontrerà di nuovo. La prossima volta, saremo pronti a schiacciarli prima che si riorganizzino.', 0),
(11356, 'itIT', 'Sei qui per far visita ai bambini! Splendido! Ne hanno viste talmente tante nelle loro giovani vite. È bello che conoscano eroi veri come te. Ne saranno felici!', 0),
(11357, 'itIT', 'I bambini amano guardare le eroine al lavoro. Spero che, un giorno, ognuno di questi orfani diventi un valido membro dell''Orda e viva la propria vita con orgoglio e onore!$B$BAh! Mi lacrimano gli occhi pensando a destini così gloriosi...', 0),
(11359, 'itIT', 'Hai abbattuto Megalith, e questo è un bene, ma non riesco a togliermi dalla testa le sue ultime parole.$B$BSei proprio sicuro che abbia detto "Forgiapietra"?$B$BNon conosco alcun luogo con quel nome, ma sembrerebbe una parola originaria dei Titani. Perché interessa tanto ai Nani del Ferro? $N, meglio dare un''occhiata: dobbiamo trovare questo posto prima che i Nani del Ferro possano mettere in atto il loro piano.', 0),
(11361, 'itIT', 'Ben fatto, $N! Bambini, osservate bene questa grande $c. Crescete forti e coraggiosi come lei e un giorno anche voi potrete combattere per l''Orda.', 0),
(11367, 'itIT', 'Hai abbattuto Megalith, e questo è un bene, ma non riesco a togliermi dalla testa le sue ultime parole.$B$BSei proprio sicuro che abbia detto "Forgiapietra"?$B$BIl nostro popolo non ha mai sentito questo nome, ma sembrerebbe una creazione di quei "Titani" di cui parlano gli stranieri. $N, i Nani del Ferro sono sempre stati nemici astuti e pericolosi: dobbiamo osservare i giganti e trovare questa Forgiapietra prima che i Nani possano mettere in atto i loro piani.', 0),
(11377, 'itIT', 'Oh, che buon profumino! Spero che tu abbia conciato per le feste quell''uccellaccio.$B$BTi prego, serviti pure dalle mie scorte. Sono certo che una persona del tuo talento saprà farne buon uso.', 0),
(11380, 'itIT', 'Sono le bacche più succose che abbia mai visto. Mi sento più intelligente solo guardandole.$B$BPerché non prendi un po'' della carne o del pesce che ho in dispensa? A me non servono più così tante scorte. Sono certo che riuscirai a cucinare qualcosa di delizioso.', 0),
(11381, 'itIT', 'Mai sentito un profumo simile venire da una zuppa spirituale. Un pizzico di pepe e sarà perfetta.$B$BCome promesso, ecco la tua parte. E visto che hai fatto un lavoro eccezionale, ti lascerò prendere qualcosa dalle mie scorte.', 0),
(11390, 'itIT', 'Ottimo lavoro, anche se credo ti serva una rinfrescata sulle basi del pilotaggio.$B$BBe'', non importa: un pilota vale l''altro. Ecco la tua paga del giorno.', 0),
(11391, 'itIT', 'Bel colpo, campionessa!$B$BEcco la tua paga. Torna domani per un altro giro, d''accordo?', 0),
(11408, 'itIT', 'Ce l''hai fatta! Dobbiamo preparaci a n''invasione di clienti. Verranno di sicuro! Grazie!$B$BAh, già... Tieni ragione. Ti avevamo promesso na ricompensa. Nun posso dimenticarlo...$B$BTorna pure nu altro giorno, se vuoi aiutarci a spargere ancora di più la voce.', 0),
(11409, 'itIT', 'Non è andata male... sicuro di non essere un Nano?$B$BPotrai partecipare a molte altre corse e non solo grazie a me. C''è gente che cerca dei bravi Corridori di Montoni sparsa per tutta la Sede della Festa della Birra. Quindi renditi utile.$B$BAh, non dimenticare che quelle redini sono state ottenute con metodi legali. Volevo chiarire questo punto.', 0),
(11410, 'itIT', 'Finalmente possiamo pescare in santa pace! Ovviamente, appena pescheremo qualcosa, si farà viva la Spedizione e vorrà tutto per sé.$B$B$N, ti siamo immensamente grati. Non sparire dalla circolazione.', 0),
(11414, 'itIT', 'L''odore del loro sangue sul tuo muso mi inebria. I fratelli non dovrebbero rivoltarsi gli uni contro gli altri.', 0),
(11415, 'itIT', 'L''odore del loro sangue sul tuo muso mi inebria. I fratelli non dovrebbero rivoltarsi gli uni contro gli altri.', 0),
(11421, 'itIT', 'Ottimo lavoro, $N! Hai eliminato un bel po'' di Cavalcadraghi e fatto arrabbiare i loro comandanti.$B$BSei pronto per tornare a Valguardia e riferire la buona notizia a Zorek? Nel caso, mi è venuta un''idea folle!', 0),
(11424, 'itIT', 'Umpf... Per ora devo accontentarmi di queste, anche se sembrano un po'' strane.$B$BHo maneggiato pezzi di corpo per anni e niente mi ha mai dato una sensazione così strana. Comunque, ti ho dato la mia parola: ecco la tua ricompensa.', 0),
(11426, 'itIT', 'Fantastico! Quelle scimmie troppo cresciute scopriranno presto cosa si ottiene a pestare i piedi all''Alleanza!', 0),
(11428, 'itIT', 'Quando ho appreso che i Protettori si erano rivoltati contro di noi, mi si è spezzato il cuore. Un tempo, li consideravamo nostri fratelli ed erano i nostri migliori amici.$B$BPiango i miei fratelli e sorelle perduti. Senza il tuo aiuto, non avremmo alcuna speranza per il futuro. $N, sarai sempre il benvenuto in mezzo a noi.', 0),
(11429, 'itIT', 'Per l''Alleanza! $N, sei davvero forte! Abbastanza da spaccare qualche cranio di Vrykul a Nifflevar.', 0),
(11430, 'itIT', 'Impiegheranno un po'' di tempo per trovare un sostituto degno di Yavus, quindi è il momento perfetto per mettere in atto il piano di Zorek! Mentre corrono a riprendere il controllo di Nifflevar, li attaccherai usando il loro stesso Lancia Arpioni!', 0),
(11432, 'itIT', 'Hai fatto ciò che era necessario. Alcuni troverebbero disonorevole uccidere chi non può difendersi ma, in questo caso, sarebbe stata una follia agire altrimenti.$B$BD''altronde, non potevamo permettere che venissero risvegliati attraverso dei rituali del genere, giusto?$B$B$N, sei stato molto coraggioso in quelle catacombe.', 0),
(11433, 'itIT', 'Hai fatto ciò che era necessario. Gli stolti troverebbero disonorevole uccidere chi non può difendersi mentre si sta risvegliando ma, in questo caso, sarebbe stata una follia agire diversamente.$B$BD''altronde, non potevamo permettere che venissero risvegliati attraverso dei rituali del genere, giusto?$B$B$r, sei stato molto coraggioso in quelle catacombe.', 0),
(11434, 'itIT', '$N, io e te insieme sfonderemo! Con la mia bellezza e il tuo... atteggiamento positivo, faremo sicuramente molta strada.', 0),
(11436, 'itIT', '$N, sei pazzo?!? Quale razza di imbecille userebbe un Lancia Arpioni come mezzo di trasporto?$B$BComunque, credo serva essere folli per combinare ciò che hai fatto sul promontorio! Ottimo lavoro! Abbiamo saputo che Ingvar, il capo degli Scorticadraghi, è furioso! Un giorno, forse, potrai gettarlo con il viso nel fango... in nome della nostra adorata Alleanza.', 0),
(11441, 'itIT', 'Oh! Oh! Oh! Sei qui per la birra gratis?', 0),
(11443, 'itIT', 'Però! Sei davvero efficiente! Bene, ora dammi quelle casse. Devo protocollarle, inventariarle e tutta un''altra serie di cose per cui non sei stato istruito e che non potresti capire. Non preoccuparti: riferirò a Keller che hai fatto un ottimo lavoro! Già! Sì... be'', ora puoi andartene. Sciò, sciò!', 0),
(11446, 'itIT', 'Come?!? Una birra gratis? Ah, già... Se ricordo bene, quest''anno abbiamo deciso così.', 0),
(11451, 'itIT', 'Che poesia commovente. Grazie!', 0),
(11452, 'itIT', 'Non sono sicuro che sia una cosa buona! Se il Re dei Lich è fuggito con Ymiron, allora sono guai. Purtroppo, non sei riuscito a ucciderlo insieme alla sua Regina.$B$BComunque, hai sferrato un duro colpo ai loro piani e ci hai fornito il tempo che ci serviva.$B$BChissà... visto che ti sposti così di frequente, magari un giorno potresti incontrare nuovamente Re Ymiron! Sono sicuro che, in quell''occasione, non se la caverà altrettanto bene.', 0),
(11453, 'itIT', 'Non sono sicuro che sia una cosa buona! Se il Re dei Lich è fuggito con Ymiron, allora sono guai. Purtroppo, non sei riuscito a ucciderlo insieme alla sua Regina.$B$BComunque, hai sferrato un duro colpo ai loro piani e ci hai fornito il tempo che ci serviva.$B$BChissà... visto che ti sposti così di frequente, magari un giorno potresti incontrare nuovamente Re Ymiron! Sono sicuro che, in quell''occasione, non se la caverà altrettanto bene.', 0),
(11455, 'itIT', 'Ottimo lavoro! Non sarà appassionante come saccheggiare i sette mari, ma che io sia dannato se mi lascio scappare un''opportunità del genere come un misero mozzo!', 0),
(11456, 'itIT', 'Grazie, $N. Il mio popolo sta passando un brutto periodo.', 0),
(11457, 'itIT', '$N, continui a dimostrare il tuo valore. Non dimenticheremo mai le tue gesta.', 0),
(11458, 'itIT', '$N, sei un alleato formidabile. Il mio popolo ti sarà per sempre debitore.', 0),
(11459, 'itIT', 'Non hai capito una parola di quello che ti ha detto Zeh''gehn, vero? Certo che no.$B$BVediamo...', 0),
(11460, 'itIT', 'Bene, $N. Vedo che sta nascendo un legame. Ti ha accettato come suo padrone.', 0),
(11464, 'itIT', 'Ben, fatto, $N: ecco la tua parte. Se vuoi, ho altro lavoro per te.$B$BSu quest''isola, i pirati scrocconi non mancano.', 0),
(11465, 'itIT', 'Sono nemici astuti... e pazienti! Dobbiamo smetterla di sottovalutarli: i Vrykul sono cacciatori letali!$B$BComunque, la missione è compiuta. Forse è arrivato il momento di farti cacciare un animale un po'' più sfuggente di un tacchino grassoccio, che ne dici?', 0),
(11466, 'itIT', '$N, mi stupisci! E non sono uno che si stupisce facilmente.', 0),
(11467, 'itIT', 'Io prendo l''oro che Conrad mi doveva. Il resto è tutto tuo.$B$BCasomai avessi bisogno di qualcosa di più duraturo, sono certo di poter organizzare qualcosa. Nel frattempo, ti auguro di avere sempre il vento in poppa!', 0),
(11468, 'itIT', 'Sì, i falchi possiedono un forte senso del territorio e spesso si spostano in stormi. Probabilmente avrei dovuto dirtelo PRIMA di farti entrare in azione.', 0),
(11469, 'itIT', 'Bleah! Mai sentita una puzza così!$B$BForza, poggialo qui. Lancerò il mio incantesimo e lo trasformerò in sapone da redazza!', 0),
(11470, 'itIT', 'Molto bene! Benissimo! Il legame fra te e il tuo falcone è fortissimo! Chissà... in futuro potresti svolgere delle missioni di perlustrazione contro i Vrykul!', 0),
(11471, 'itIT', 'Finalmente i giorni di Jonah Sterling sono finiti! Non avrebbe mai pensato che questa "servetta" potesse giocargli uno scherzo del genere.$B$BQuando la notizia della sua morte si spargerà fra i pirati, il mio comando sarà consolidato. $N, la mia ciurma non creerà più alcun problema ai tuoi alleati.', 0),
(11472, 'itIT', 'Questa è un''ottima notizia! Ora altri maschi nuoteranno attraverso lo Stretto per raggiungere le femmine. Presto, le isole saranno piene di cuccioli.$B$BGrazie, $r. Qualunque cosa tu abbia fatto in passato, sappi che hai contribuito al futuro di Kamagua!$B$BDovremo continuare a lavorare sodo, se vogliamo che si ripopolino. Torna domani, così potremo aiutare un''altra coppia a incontrarsi.', 0),
(11473, 'itIT', 'Ué, cumpà! Stai accà per parlare a quattr''occhi con me, sì?', 0),
(11474, 'itIT', 'Più della metà della mia squadra è morta o dispersa, ragazzino. Questo è il nostro ultimo disperato tentativo in cima al promontorio. Quei maledetti Nani del Ferro ci hanno scacciati dalle Rovine di Ivald e da quelle di Baelgun. Ho un piano per farci rientrare prima che seppelliscano tutti i nostri ritrovamenti e le informazioni vadano perdute per sempre.', 0),
(11475, 'itIT', 'Ora che ho di nuovo i miei attrezzi da lavoro, posso iniziare a costruire. O meglio... potrò farlo quando avrò anche il materiale necessario. Devi portarmi anche quello.', 0),
(11476, 'itIT', 'Grazie assai, cumpà! Il gracidone è proprio nu babà!', 0),
(11477, 'itIT', 'Ottimo lavoro, $N. Abbiamo rallentato il seppellimento.', 0),
(11479, 'itIT', 'Che brutta notizia. Dan era un mio vecchio amico... e mi doveva dei soldi! Comunque, se era in combutta con quei farabutti dei Mari del Sud, ha avuto ciò che meritava.$B$BPer quanto riguarda te, amico mio, sei in ascesa. Letteralmente.', 0),
(11480, 'itIT', 'Bene bene bene... Finalmente eccoti qui, $N. Salti fuori dal nulla nel Capo di Granfurto, nessuno sa niente di te, tranne un Goblin amico di quello sciocco di Terry...$B$BDiciamo che sono un po''... scettica... sulle tue reali intenzioni.', 0),
(11481, 'itIT', 'Un altro soldato da Shattrath? Che bella sorpresa!

Vorrei che non fossi sola, ma mi adeguerò. Qualsiasi cosa stia accadendo qui, potrebbe piombarci addosso in qualsiasi momento.

Guardati in giro, $c. C''è molto da fare. Accomodati e fai la tua parte.', 0),
(11483, 'itIT', 'Eccellente! Quando avrò ricoperto lo scheletro con la pelle, sarà un clone perfetto dei Costrutti usati dai Nani del Ferro.', 0),
(11484, 'itIT', 'Appena avrò completato la struttura portante, il Costrutto sarà pronto.', 0),
(11485, 'itIT', '$N, sei quasi pronto a far scendere in campo quest''opera d''arte!', 0),
(11489, 'itIT', 'Ottimo! Funziona alla perfezione!', 0),
(11490, 'itIT', 'Non è un caso che oggi le nostre strade si siano incrociate.$B$BPercepisco i fili del destino...', 0),
(11491, 'itIT', 'Gliel''hai fatta vedere! Ora è il momento di fare sul serio.$B$BSpero che ti senta pronto...', 0),
(11494, 'itIT', 'Ancora una volta, Walt dimostra di essere il Nano migliore di tutti! Lebronski, che ne pensi adesso del mio Costrutto?$B$BGrazie, $N. I dati si dimostreranno sicuramente preziosissimi... non appena avrò capito come estrarli dal Costrutto.', 0),
(11495, 'itIT', 'Incredibile! Che intenzioni hanno, quelle minacce ferrose? Cosa stanno combinando nelle Cime Tempestose? E cosa sarebbe questo Loken?!? $N, trasmetterò le informazioni alla nostra base principale a Dracombra. Inoltre, dirò loro che il tuo aiuto è stato fondamentale nel recupero di queste informazioni.', 0),
(11501, 'itIT', 'Fantastico! Come se non bastasse avere costantemente il Flagello alle calcagna, ora dobbiamo preoccuparci anche di un antico Costrutto dei Titani infuriato!$B$B$r, ho bisogno di un po'' di tempo per elaborare queste informazioni. Nel frattempo, qui il lavoro non manca.', 0),
(11507, 'itIT', 'Orfus è un buon Tuskarr e uno dei nostri guerrieri più valorosi. Ero sicuro che non ci avrebbe delusi.$B$BMostrami ciò che hai portato.', 0),
(11508, 'itIT', 'Arrr, compagno. A Grezzix non è mai piaciuto sporcarsi le mani! La vita del pirata è bella, finché a Grezzix non tocca lavorare.$B$BHo visto quei manufatti. Per questo sono qui e non a Granfurto! Sono oggetti molto, molto cattivi...$B$BBe'', la vita è tua, giusto? Tu vuoi entrare a Granfurto e Grezzix può aiutarti.', 0),
(11511, 'itIT', '$N, devi recuperare tutti i manufatti. Quando li avrai tutti e quattro, potrai rimetterli nelle loro tombe.', 0),
(11512, 'itIT', '$N, devi recuperare tutti i manufatti. Quando li avrai tutti e quattro, potrai rimetterli nelle loro tombe.', 0),
(11516, 'itIT', 'Ottimo lavoro, $N. I demoni potrebbero riparare il varco, col tempo. Immagino che allora lo faremo saltare di nuovo in aria.', 0),
(11523, 'itIT', 'Ben fatto, $N. I cristalli stanno pian piano riprendendo energia. Approdo del Sole sarà nostro in un lampo!', 0),
(11525, 'itIT', 'Eccellente. Gli Avvistatori Convertiti ci aiuteranno a mettere in sicurezza il nostro perimetro.', 0),
(11526, 'itIT', 'È carino da parte di Theris preoccuparsi per me, ma qui abbiamo problemi più seri. Molto più seri.', 0),
(11527, 'itIT', 'Spero che quegli infidi topi di fogna abbiano imparato la lezione! Ora è il momento di andare al Bombardone, compagno!', 0),
(11529, 'itIT', 'Ogni promessa è debito, filibustiere!', 0),
(11530, 'itIT', '$N, devi recuperare tutti i manufatti. Quando li avrai tutti e quattro, potrai rimetterli nelle loro tombe.', 0),
(11533, 'itIT', 'Ogni demone che uccidiamo oggi è uno in meno da affrontare domani. Continua così.', 0),
(11537, 'itIT', 'La tua dedizione è esemplare, $N. Mostreremo alle forze della Legione Infuocata di cosa siamo capaci.', 0),
(11543, 'itIT', 'Ben fatto, $N. Passerà del tempo prima che al porto arrivino altri rinforzi.', 0),
(11547, 'itIT', 'Sì, sì. Diamo un''occhiata, va bene?$B$BSembra tutto in ordine. Molto bene. Ecco il tuo traslocatore.$B$BSe qualcuna delle tue letture è sbagliata non c''è modo di sapere dove finirai... E ricorda: in tal caso la colpa sarà solo tua.', 0),
(11548, 'itIT', 'Sei un''anima virtuosa, $N. Nel caos della guerra e nell''euforia della vittoria è facile dimenticarsi dei caduti. Gli amici e i familiari delle vittime ti ringraziano.', 0),
(11549, 'itIT', 'Sei davvero una persona generosa e un alleato prezioso. D''ora in poi tutti ti conosceranno come $N del Sole Infranto e tutti coloro che combattono qui sapranno delle tue imprese!', 0),
(11559, 'itIT', 'Sono per me? Cos''è, una specie di trucco? No?$B$BOh, be'', allora grazie! Dammi tutti i bivalve che hai trovato e concluderemo questo affare!', 0),
(11560, 'itIT', 'Adesso, qualsiasi cosa accada, i Murloc Pinnafredda perlomeno hanno un futuro.$B$BIl tuo altruismo va senz''altro lodato e ricompensato, $N!', 0),
(11561, 'itIT', 'Molto bene. Sento l''odore del rame del loro sangue sulle tue mani.$B$BHai cominciato col piede giusto, $r.', 0),
(11562, 'itIT', 'Ah, dunque tu devi essere il cosiddetto tirapiedi del Re Mrgl-Mrgl. Quell''Elfo della Notte ti ha mandato per placarmi?$B$BBene... ho proprio un lavoretto che solo qualcuno potente come te può portare a termine!', 0),
(11563, 'itIT', 'Non male. Con questa faremo un bel banchetto!$B$BOra che il Re delle Orche è morto gli attacchi contro di noi dovrebbero diminuire, con le Orche impegnate a lottare tra loro per la successione.', 0),
(11566, 'itIT', 'Non mi rende felice, ma era un''azione necessaria. Questa chela la prendo io.$B$BGrazie per tutto l''aiuto che ci hai dato, $N. Ora che Claximus è stato sconfitto, forse riusciremo a riunire i restanti Murloc e a sigillare quelle caverne.$B$BTi prego, amico mio, prendi... è il minimo che possa fare per ringraziarti del tuo aiuto!', 0),
(11567, 'itIT', '$N, devi recuperare tutti i manufatti. Quando li avrai tutti e quattro, potrai rimetterli nelle loro tombe.', 0),
(11568, 'itIT', 'Brutte notizie, $N. Il mio popolo è in pericolo e dev''essere avvisato. Quelle aberrazioni marine non avranno pietà dei Kalu''ak.', 0),
(11569, 'itIT', 'Presto, dammela!', 0),
(11570, 'itIT', 'Che notizia meravigliosa! E dici che Lurgglbr ha scoperto che sono state delle emanazioni magiche a far impazzire tutti?$B$BLa magia di Ibernia sta crescendo in potenza. La Guerra del Nexus... la lotta tra lo Stormo dei Draghi Blu e tutti gli altri draghi sta cominciando a produrre degli effetti collaterali.$B$BPresto ci coinvolgerà tutti!', 0),
(11571, 'itIT', 'Ora potrò usare l''essenza di Scalder per infonderti la mia conoscenza della lingua dei Murloc Pinnafredda.', 0),
(11572, 'itIT', '$N, i Kalu''ak ti ringraziano per tutto ciò che hai fatto. Ora dobbiamo prepararci a combattere e avvisare i nostri fratelli e sorelle dall''altra parte del mare riguardo a ciò che sta per accadere.$B$BSpero solo che non sia troppo tardi...', 0),
(11574, 'itIT', 'Puoi riferire alla tua amica che salvarla è stato un piacere, oltre che un dovere.$B$BCredo che l''incontro che abbiamo avuto con lei sia solo un tassello di un rompicapo più grande.$B$BDalaran sta impiegando tutte le sue risorse per la risoluzione di questo mistero e, a essere sinceri, un po'' di aiuto non ci dispiacerebbe...', 0),
(11575, 'itIT', 'Puoi riferire alla tua amica che salvarla è stato un piacere, oltre che un dovere.$B$BCredo che l''incontro che abbiamo avuto con lei sia solo un tassello di un rompicapo più grande.$B$BDalaran sta impiegando tutte le sue risorse per la risoluzione di questo mistero e, a essere sinceri, un po'' di aiuto non ci dispiacerebbe...', 0),
(11576, 'itIT', 'Affascinante! Sembrerebbe l''anomalia più grande registrata finora.$B$BAnche se temo che il peggio debba ancora venire.', 0),
(11581, 'itIT', 'Dissacra il Falò dell''Alleanza nelle Marche Occidentali!', 0),
(11582, 'itIT', 'Questi dati sono reali?$B$BMa è impossibile! Devo fare subito rapporto a Dalaran!', 0),
(11587, 'itIT', 'Ottimo lavoro, $N.$B$BIl Kirin Tor accetta con grazia il tuo aiuto. Sappi che qualsiasi assistenza ci fornirai verrà sempre ricompensata.$B$BPer cominciare, accetta questa umile offerta in segno di apprezzamento da parte di Dalaran.', 0),
(11590, 'itIT', 'Ottimo lavoro, $N.$B$BLo sottoporremo subito a interrogatorio.', 0),
(11592, 'itIT', 'Sangue e tuono! Hai salvato le relazioni appena allacciate con i Taunka.$B$BGrazie per aver rimediato alla situazione. Aka''magosh, $N!', 0),
(11593, 'itIT', 'Grazie, $c. Noi siamo l''Orda, non abbandoniamo i nostri caduti!$B$BMa tutto questo non sarebbe dovuto mai accadere. Mordiferro è stato un idiota!', 0),
(11594, 'itIT', 'Ben fatto, $c! Devi possedere una grande esperienza in fatto di lotta contro i non morti. E se non l''avevi prima, ce l''hai adesso!$B$BTi assicuro che ti servirà, se vorrai sopravvivere a Nordania.', 0),
(11596, 'itIT', 'Appena in tempo... I Nerubiani sembrano essere raddoppiati in meno di una settimana! Ogni aiuto è ben accetto.', 0),
(11598, 'itIT', 'Li hai rallentati, ma sicuramente altri si uniranno alla lotta. Mentre ti trovavi nella cava, hai per caso visto alcune delle loro sacche di uova?', 0),
(11600, 'itIT', 'Pensi che sia solo un caso che il Flagello abbia ucciso William? Io sento puzza di bruciato.$B$BC''è qualcosa sotto, lo sento: dobbiamo trovare Thassarian.', 0),
(11601, 'itIT', 'Purtroppo non posso aiutarti, amico mio. Ma forse conosco qualcuno che può farlo.', 0),
(11602, 'itIT', 'Nonostante i nostri sforzi, non accennano a diminuire. Prima o poi succederà qualcosa di decisivo.', 0),
(11603, 'itIT', 'Mmm... non troppo amaro... non troppo secco... proprio come ai vecchi tempi, con i ragazzi in caserma.', 0),
(11604, 'itIT', 'Che vuoi? Ho già abbastanza problemi per conto mio!', 0),
(11606, 'itIT', 'Se i miei calcoli sono corretti, e spesso non lo sono, serviranno dalle 10 alle 20 Cariche di Profondità di Nitronite.$B$BOh sì, dovrai piazzare queste bellezze nelle loro depressioni.', 0),
(11607, 'itIT', 'La situazione sta tornando alla normalità, qui nel mondo degli spiriti. Ottimo lavoro, $N. Gli spiriti degli antenati sono stati fortunati a incontrarti nel momento del bisogno.', 0),
(11610, 'itIT', 'Gli antenati hanno ritrovato la via di casa ed è te che devono ringraziare, $N. Gli artigiani di Kaskala torneranno alla cava e faranno sì che la strada tracciata dai loro antenati non venga interrotta. Quanto a noi, gli antenati continueranno a seguirti con interesse. Il tuo cammino, infatti, sembra essere appena iniziato.', 0),
(11611, 'itIT', 'Molti sono sopravvissuti. Perlomeno, quelli abbastanza intelligenti da sapere che ci troviamo nel gigantesco edificio di pietra e metallo...$B$BA ogni modo, ottimo lavoro. Ho saputo che hai liberato più di un Peone.$B$BSì, parlano tutti di te alla... ehm... fortezza.', 0),
(11612, 'itIT', 'Ora che quegli strani Maghi sanno che la gente di Kaskala e i loro alleati non cederanno la cava tanto facilmente, non dobbiamo mollare, ma sconfiggerli del tutto.$B$BAnche i miei fratelli a Kaskala sono stati attaccati e per questo non potranno darci man forte, ma sono certo che con il tuo aiuto riusciremo a fermare questi predoni.', 0),
(11613, 'itIT', 'Hai reso alla mia gente un grande servizio, $N. Ma devo chiederti un altro favore.', 0),
(11617, 'itIT', 'Quei Cacciatori di Maghi non avranno vita facile nel saccheggiare la cava e rubare i nostri manufatti. Grazie al tuo aiuto, riconquisteremo la cava e giustizia sarà fatta.', 0),
(11619, 'itIT', '$N, ce l''hai fatta! Gli spiriti dei Tuskarr uccisi ora possono riposare in pace. La loro morte è stata vendicata!', 0),
(11620, 'itIT', 'Hsssssssssssss! Sei qui per deridermi, $r?', 0),
(11623, 'itIT', 'Il Curatore e i suoi credevano che la cava fosse un bersaglio facile per le loro razzie, ma tu hai dimostrato loro il contrario. $N, ti sono profondamente grato per il tuo aiuto. Sono certo che i nostri antenati proteggeranno il tuo cammino.', 0),
(11624, 'itIT', 'Sei sciocco a venire qui, $r.$B$BCosa cerchi?', 0),
(11625, 'itIT', 'Sssssssssì! Uccideremo la bestia dei Kvaldir! Quei bruti impareranno che non si deve scherzare con una Sacerdotessa delle Squame!', 0),
(11626, 'itIT', 'Adesso gli spiriti della mia gente possono riposare in pace. Mi hai aiutato a rendere onore a mio padre... Forse un giorno sarò forte come te.', 0),
(11627, 'itIT', 'Sono soddisfatta, anche se senza dubbio continueranno a litigare ancora per un po''.$B$BC''è però un''altra cosa che vorrei tu facessi per me prima di tornare dalla tua Parlaspiriti.', 0),
(11629, 'itIT', 'Imperean ti ha dato una sua essenza primordiale? Già, sento l''ululare dei venti!$B$BConosco il rituale che fa al caso nostro. Dobbiamo sbrigarci, prima che l''essenza si disgreghi!', 0),
(11631, 'itIT', 'Hanno imprigionato il suo spirito. $N, dobbiamo porre fine alla sua tortura!$B$BDevi scendere nelle profondità di Magmoth e trovare il modo di liberarlo!', 0),
(11635, 'itIT', 'Grazie per il conforto, $c. Se solo la vera libertà fosse altrettanto facile da ottenere.', 0),
(11637, 'itIT', 'Sono libero. Grazie, $N.$B$BE ora ho un''ultima richiesta da farti.', 0),
(11638, 'itIT', 'Grazie per aver liberato il suo spirito da Kaganishu e di avermi riportato i suoi resti. Non abbiamo grandi ricompense da offrirti, ma puoi prendere qualsiasi cosa ti attiri di più.$B$BE ora riporterò il mio maestro nel mondo dei vivi a cui appartiene.', 0),
(11641, 'itIT', 'Hai dimostrato la tua temerarietà e prodezza in combattimento. Saresti un grande $C Taunka. Se solo il nostro Capo Tribù fosse dello stesso avviso!$B$BSiamo fortunati a poter contare sul tuo aiuto per far evacuare il villaggio prima che il Flagello lo invada.', 0),
(11642, 'itIT', 'Tu sei il nuovo pilota del carro, vero? Mi sta bene! Dobbiamo solo rimettere in sesto questi affari. Già... se provi ad attraversare le Pianure di Nasam senza un carro, sei già morto in partenza.', 0),
(11643, 'itIT', 'Ottimo lavoro, amico mio! Ora, dove ho messo quei pezzi di ricambio?', 0),
(11644, 'itIT', 'Ottimo lavoro, amico mio! Ora, dove ho messo quel Martellatore Asintotico Pneumatico?', 0),
(11645, 'itIT', 'Oh, $N, sei il migliore!$B$BEcco il denaro che ti avevo promesso.', 0),
(11646, 'itIT', 'È stato saggio da parte di Donathan mandarti quassù.$B$BSi dà il caso che abbia bisogno di una persona estranea al Kirin Tor.', 0),
(11648, 'itIT', 'Eccellente! Queste informazioni si riveleranno essenziali.$B$BBen fatto, amico mio.', 0),
(11649, 'itIT', 'Mi dispiace per la perdita di quelle Tempeste, ma devo rispettare la mia parola... anche se l''ho data a un mortale come te.$B$BE ora vediamo di aiutarti...', 0),
(11650, 'itIT', 'Ah, ora sì che ci siamo! Adesso non dobbiamo far altro che mettere tutto insieme.$B$BCome se tu potessi aiutarmi a farlo...$B$BBe'', non temere: ora che ho di nuovo i miei attrezzi ci metterò un attimo!', 0),
(11651, 'itIT', 'Dato lo stato attuale delle rotte dei nostri trasporti e delle navi da carico, non siamo riusciti a portare a Cantaguerra neanche un dannato Motore d''Assedio. Questi carri sono tutto ciò che ci rimane della spedizione originaria. Ora che sono operativi, usali per schiacciare l''offensiva del Flagello nelle Pianure di Nasam.', 0),
(11656, 'itIT', 'La dimostrazione che non siamo ancora sconfitti potrebbe spingere i Kvaldir a non assaltare anche gli altri nostri accampamenti. Forse i Kvaldir non attaccheranno, se saranno certi di subire una rappresaglia.', 0),
(11658, 'itIT', 'Ottimo, ma che puzza queste vesti!$B$BPersonalmente, non indosserei questi stracci neanche morta. Dovremo frugare un po'' per cercare qualcosa che ti vada bene.', 0),
(11659, 'itIT', 'Temevo che avessero catturato Grumm, ma non avrei mai pensato che avrebbero potuto fargli qualcosa di tanto orribile. Non ho mai visto qualcuno sopravvivere dopo aver perso una battaglia contro il Flagello.$B$BGrazie per avermi informato sulla sua sorte, $N. Era un potente $C e come tale lo ricorderemo.', 0),
(11660, 'itIT', 'Devi chiamare Orabus usando il Corno del Vecchio Marinaio.', 0),
(11662, 'itIT', 'Waltor è stato saggio a mandarti da me, $r. Gli dei sono alleati di chi porta giustizia. E tu sarai colui che punirà i malvagi!', 0),
(11663, 'itIT', 'Perdonami, $N. So che non dev''essere stato piacevole.$B$BSe non fosse per il fatto che ci troviamo in una situazione disperata, non ti avrei mai chiesto di aiutarci in quel modo.$B$BAllora... cos''hai scoperto?', 0),
(11664, 'itIT', 'Si sussurra nel vento, amico mio. Il tuo nome è noto agli elementi. Oggi hai reso un grande servizio a Mootoo e per questo sarai ricompensato.', 0),
(11666, 'itIT', 'Ma guarda qui... ne hai preso uno bello grosso! Stasera questo vecchio si concederà una bella cenetta.', 0),
(11667, 'itIT', 'Eccolo! Riconoscerei tra mille quella cicatrice.$B$BPer essere del tutto onesto, pensavo fosse più... grande. Be'', credo che lo lascerò andare e riproverò un altro giorno.', 0),
(11670, 'itIT', 'Per tutti i chiavistelli, ce l''hai fatta!$B$BBene, ora quei fastidiosi Magnatauri e i loro tirapiedi Neboldi dovrebbero volgere la loro attenzione sull''Orda.$B$BCome potrò mai ripagarti, $N?', 0),
(11671, 'itIT', 'Rotta?$B$BFammi vedere...', 0),
(11672, 'itIT', 'Aspettavamo il tuo arrivo, $N. Benvenuto a Nordania.', 0),
(11673, 'itIT', 'Eh? Cosa?$B$BBonker chi?$B$BNon ho idea di chi stai parlando, ma mi fido della tua parola. Se l''hai salvato, o salvata, da Magmoth, allora immagino che meriti una ricompensa.$B$BVediamo un po'' cosa c''è qui...', 0),
(11674, 'itIT', 'Ti manda la Madre Anziana... Devo averla delusa.$B$BMa quando ho visto quel grande oggetto cadere dal cielo, non ho potuto attendere che fosse pronto un intero gruppo di staffettisti e di braccatori delle nevi per accompagnarmi. La conoscenza non aspetta nessuno.', 0),
(11675, 'itIT', 'Cos''altro possiamo fare, se non alleviare la loro sofferenza? A ogni modo, erano venuti qui per morire, quindi forse non è il caso di piangerli troppo. Perlomeno li hai fatti morire con dignità.$B$BOra, però, dobbiamo porre fine alla causa della piaga.', 0),
(11676, 'itIT', 'Ciascun prigioniero salvato è un''Aberrazione non morta in meno da combattere. Hai reso un grande servizio all''Orda.', 0),
(11678, 'itIT', 'Non mi resta... molto... su questo... mondo, $r.', 0),
(11679, 'itIT', 'I frivoli giochi cui vi dedicate non hanno alcuna importanza qui...$B$BTu e i tuoi alleati di Dalaran vi date da fare per questioni inutili mentre qui è in ballo il futuro stesso di questo mondo.$B$BTuttavia, risolvere il vostro problema potrebbe far divertire un po'' i miei drachi.$B$BMostrami questa chiave...', 0),
(11680, 'itIT', 'Ci siamo, la chiave è nostra!', 0),
(11681, 'itIT', 'La tua impresa eroica non sarà dimenticata, $c.$B$BIntanto accetta questo, insieme alla mia più sincera gratitudine.', 0),
(11682, 'itIT', 'E così, $r, sei di nuovo al mio cospetto.$B$BQuando avrai sentito ciò che ho da dire, forse te ne pentirai.', 0),
(11683, 'itIT', 'Grazie, $N.$B$BIl Re dei Lich e il suo Flagello sono una sventura per Nordania. Non dobbiamo fermarci finché non saranno tutti morti e il loro Re non verrà ucciso!', 0),
(11685, 'itIT', 'Questi dovrebbero bastare per formare il nucleo di un potente elementale, ma la sola pietra non basta per dargli vita.', 0),
(11687, 'itIT', 'Corno Peloso è morto?$B$BNon avrei mai dovuto lasciarlo andare da solo.', 0),
(11688, 'itIT', 'Credo di avercela fatta, $r!', 0),
(11690, 'itIT', 'Sei un vero eroe, $N. I miei kodo sarebbero morti laggiù, senza di te. Hai la gratitudine mia e di tutti i soldati e viandanti che useranno questi kodo per rafforzare la nostra presenza qui in Nordania!', 0),
(11692, 'itIT', 'Hai bisogno di qualcosa, $c?', 0),
(11693, 'itIT', 'Ottimo lavoro ma, se fossi in te, alla prima occasione mi farei una doccia.$B$BE ora cerchiamo di risolvere il problema alla radice.', 0),
(11694, 'itIT', 'Sapevo che ce l''avresti fatta. Ora avrei un altro compito da assegnarti...', 0),
(11697, 'itIT', 'Ehilà! E tu chi sei?$B$BTi manda Bixie? Ottimo! Portami via da qui!', 0),
(11698, 'itIT', 'Grazie, $N.$B$BIl Re dei Lich e il suo Flagello sono spaventosi, ma non possiamo fermarci finché non saranno tutti morti e sepolti!', 0),
(11699, 'itIT', 'Straordinario! Ora basterà una modifica qui, un ritocchino là...', 0),
(11700, 'itIT', 'Tinky ha una gemella malvagia?!?$B$BBe'', se ha detto che è tutto a posto e che è in grado di tornare all''Aerodromo da sola, per me va bene.', 0),
(11701, 'itIT', 'Quante novità, $N! Con tutto quel che sta accadendo qui intorno, è una sorpresa che l''Aerodromo sia ancora in piedi.$B$BGrazie a te, però, dobbiamo preoccuparci di un nemico in meno.$B$BAvevo giusto messo da parte delle cose per occasioni come queste. Scegli pure!', 0),
(11704, 'itIT', 'Dei soccorsi, finalmente! E, a giudicare dal tuo aspetto, da parte dell''Alleanza.$B$BBene... voialtri siete dei combattenti molto esperti. Ed è proprio ciò di cui abbiamo bisogno.', 0),
(11708, 'itIT', 'Ti manda il vecchio, eh? Ti ha raccontato tutto quello che sta succedendo qui?$B$BBene... diamoci subito da fare, allora!', 0),
(11710, 'itIT', 'Perfetto, $c! Sembrano anche tutti in ottime condizioni.$B$BSe solo ora trovassi il modo di riparare questo dannato affare...', 0),
(11711, 'itIT', 'Ottimo lavoro, $N. Uno sporco e inutile parassita dell''Alleanza in meno a cui badare...$B$BSe cerchi altri incarichi, so che il Tauren e l''Elfo del Sangue qui vicino hanno bisogno di aiuto.$B$BNaturalmente, anche noi abbiamo i nostri problemi...', 0),
(11712, 'itIT', 'Ce l''hai fatta e... ha funzionato!$B$BNon riesco a credere che tu ne abbia salvati così tanti. Siamo proprio fortunati ad averti al nostro fianco!', 0),
(11714, 'itIT', 'Ben fatto, $N! Grazie!', 0),
(11719, 'itIT', 'Corno Forte Primordiale sarà entusiasta! È meglio di quel che credessi!$B$BForse è ora che ti dica la verità.', 0),
(11720, 'itIT', 'La Sporasangue che hai raccolto potrebbe essere sufficiente a darci un vantaggio sui Magnatauri di Gammoth... con il tuo aiuto, naturalmente.', 0),
(11721, 'itIT', 'Ben fatto, $N! Per me e Laurith sarebbe un onore se portassi la testa di quella belva a Malogrido. Lo renderesti estremamente felice.', 0),
(11724, 'itIT', 'Alkor è morto, eh? Che peccato... Quanto all''uovo, ormai non ci serve più. Adesso abbiamo problemi più urgenti da risolvere.', 0),
(11727, 'itIT', 'Per la barba di Magni! Arriva l''artiglieria pesante!', 0),
(11729, 'itIT', 'Il mio cacciavite... hai trovato il mio cacciavite! Mi stavo giusto chiedendo dove fosse finito.$B$BMmm, l''hai trovato all''interno di uno di quei loro robot? Mi sta venendo un''idea...', 0),
(11730, 'itIT', 'Caspita! E hai anche riportato il Cacciavite tutto intero!$B$BLa riprogrammazione di quei robot si rivelerà una mossa decisiva nella lotta contro il Mastro Meccanico Mecazod. Ti sei meritato una bella ricompensa...', 0),
(11732, 'itIT', 'Dissacra il Falò dell''Alleanza negli Altopiani d''Arathi!', 0),
(11733, 'itIT', 'Benvenuto a Ibernia, $c.$B$BQua, sotto la Cupola di Transito, ci troviamo a un lancio di sasso dal Nexus, la fortezza del grande Aspetto Malygos e del suo Stormo dei Draghi Blu.$B$BFa'' come se fossi a casa tua.', 0),
(11749, 'itIT', 'Dissacra il Falò dell''Alleanza a Loch Modan!', 0),
(11755, 'itIT', 'Dissacra il Falò dell''Alleanza nelle Entroterre!', 0),
(11766, 'itIT', 'Dissacra il Falò dell''Orda nelle Maleterre!', 0),
(11786, 'itIT', 'Dissacra il Falò dell''Orda nelle Radure di Tirisfal!', 0),
(11788, 'itIT', 'Caspita, sei sopravvissuto!$B$BBene, ora non ci resta che occuparci del Mastro Meccanico Mecazod in persona.', 0),
(11789, 'itIT', 'Grazie, $N. Si riprenderà lentamente, ma almeno non morirà.$B$BCome? La Solcatempeste era occupata dai cultisti? Sarà meglio avvisare qualcuno... e portare delle prove.', 0),
(11791, 'itIT', 'Grazie per il tuo interesse, $N. Eravamo già stati avvisati non molto tempo fa.$B$BIl Consigliere Talbot mi ha assicurato che si tratta di un caso isolato e che dal punto di vista militare non c''è motivo di preoccuparsi.$B$BLe autorità civili si attiveranno per perseguire tutti i responsabili.', 0),
(11792, 'itIT', 'Cautela, $N. Non possiamo esaminare queste prove davanti a occhi indiscreti.', 0),
(11793, 'itIT', 'Parla velocemente, $c. Che informazioni possiedi sui cultisti?', 0),
(11794, 'itIT', 'Ben fatto, $N. Tuttavia, non riesco a togliermi di dosso la sensazione che rivedremo presto questi dannati Cultisti della Morte.$B$BL''oscurità riesce spesso a nascondersi sotto gli occhi di tutti.', 0),
(11795, 'itIT', 'Grazie ancora, $N. Con il tuo aiuto, posso ancora sperare di completare questa disastrosa missione e tornare da Frizzapistone a fare rapporto e rendere omaggio ai morti come si deve.', 0),
(11796, 'itIT', 'Grazie ancora, $N. Senza di te, questa missione sarebbe stata un vero e proprio disastro.', 0),
(11797, 'itIT', 'Ottimo lavoro, $N. Hai fatto vedere ai ragazzi come si fa. L''unico Strisciatore buono è uno Strisciatore morto!', 0),
(11807, 'itIT', 'Onora il Falò delle Montagne Spinaguzza.', 0),
(11821, 'itIT', 'Onora il Falò di Nagrand.', 0),
(11836, 'itIT', 'Onora il Falò di Silitus.', 0),
(11838, 'itIT', 'Onora il Falò di Tanaris.', 0),
(11843, 'itIT', 'Onora il Falò delle Montagne Spinaguzza.', 0),
(11856, 'itIT', 'Onora il Falò delle Vette di Petrartiglio.', 0),
(11865, 'itIT', 'Stai compiendo la volontà della Madre Terra, $N, ma non c''è tempo per godersi i frutti della vittoria. Abbiamo scoperto il nascondiglio del capo dei Mastri Bracconieri.', 0),
(11866, 'itIT', 'Queste me le appenderò al collo. Che odano il nostro messaggio e che queste orecchie siano il mezzo con cui lo recapiteremo!', 0),
(11867, 'itIT', 'Queste me le appenderò al collo. Che odano il nostro messaggio e che queste orecchie siano il mezzo con cui lo recapiteremo!', 0),
(11868, 'itIT', 'Forse la sua morte servirà da esempio per tutti quelli che uccidono gli animali per sport o per arricchirsi.', 0),
(11869, 'itIT', 'Adesso vedremo la loro reazione non appena scopriranno la fine dei loro simili!', 0),
(11870, 'itIT', 'Ti manda Cenius? Arrivi giusto in tempo!', 0),
(11871, 'itIT', 'Ben fatto, $N. E ora colpiremo il capo dei pirati!', 0),
(11872, 'itIT', 'Ottimo lavoro, $N. Fra poco Nesingwary non avrà più scampo!', 0),
(11880, 'itIT', 'Grazie per l''aiuto. Non sai cosa significhi avere a che fare con il "Dottor" Patatafritta, qui. Mentre effettua i suoi "controlli" sui miei progressi, è impegnato anche a piazzare le sue invenzioni a uso militare.', 0),
(11885, 'itIT', 'Ottimo! Prendi. Ho preparato questo pacco con oggetti che simboleggiano i nemici che hai sconfitto. Ti permetteranno di evocare Terokk.$B$BFa'' attenzione, $N. È il più potente Arakkoa che sia mai esistito. Non sottovalutarlo!', 0),
(11886, 'itIT', 'Tutto ciò è molto preoccupante. Dietro le agitazioni locali degli elementi dell''acqua e del fuoco, sembrerebbe esserci un piano più ampio. È il caso di indagare...', 0),
(11887, 'itIT', 'Strumenti gnomeschi? Per me? Con questi, ricostruire le Macchine Volanti gnomesche sarà più facile del previsto.', 0),
(11888, 'itIT', 'Non mi sorprende che il Capo Tribù non abbia tempo per ascoltare i nostri problemi. Gli sforzi dell''ambasciatore andranno sicuramente a vuoto.$B$BMa almeno ci sei tu. Vediamo se ha fatto bene a mandarti.', 0),
(11889, 'itIT', 'Li batteremo se ci attaccheranno da terra e li abbatteremo se ci attaccheranno dall''aria! E se quei non morti figli di nessuno ci dovessero attaccare dal mare, li affonderemmo senza pietà!', 0),
(11890, 'itIT', 'Non sono buone notizie.$B$BLa mia gente lascerà presto il villaggio. Proveremo a forzare le linee del Flagello per raggiungere la nostra capitale, Foscogelo, a Dracombra.$B$BPrima, però, dobbiamo far fronte al guaio causato dagli Gnomi con la loro follia.', 0),
(11891, 'itIT', 'Vogliono evocare un Signore del Gelo nel nostro mondo? No! Non devono spostare l''equilibrio!', 0),
(11894, 'itIT', 'Fantastico! Un altro paio di modifiche e finalmente sarò un Goblin volante!', 0),
(11895, 'itIT', 'Sento il potere della tempesta scorrere in te!$B$B$N, sei pronto. Possiamo iniziare.', 0),
(11896, 'itIT', 'Eliminati gli sgherri robotici, è il momento di puntare più in alto. Purtroppo sento già il potere della tempesta svanire in te.$B$BA ogni modo ha servito al suo scopo. Inoltre, non ho dubbi che saprai affrontare la fase successiva del piano anche senza di esso.', 0),
(11897, 'itIT', 'Ottimo lavoro, $N. Senza di te, Forte degli Arditi non avrebbe potuto respingere l''attacco. Grazie al tuo aiuto, potremo combattere ancora un altro giorno.', 0),
(11899, 'itIT', 'Ora dobbiamo liberare le anime che hai catturato.', 0),
(11900, 'itIT', 'È peggio di quanto mi aspettassi.$B$BMalygos sta canalizzando troppo potere in questo posto. Se non lo fermeremo, Azeroth diventerà come le Terre Esterne!$B$BPer fortuna credo di aver trovato una soluzione temporanea...', 0),
(11902, 'itIT', 'Quei poveri ragazzi... erano condannati fin dall''inizio!$B$BQuesta faccenda puzza di tradimento. Forse un infiltrato del Culto dei Dannati. Maledetti pazzi!', 0),
(11903, 'itIT', 'Hai comunicato col Flagello nell''unica lingua che conoscono: quella della violenza e della morte. Purtroppo continuano ad arrivarne altri!', 0),
(11904, 'itIT', 'Grazie, $N. Nel prossimo futuro, questi minerali potrebbero rivelarsi di importanza vitale per l''Alleanza. Mi fa piacere pensare che oggi abbiamo fatto la differenza.', 0),
(11905, 'itIT', 'Ottimo lavoro, $N. Le scosse hanno già cominciato a diradarsi.$B$BCon un po'' di fortuna, i tuoi sforzi ci faranno guadagnare il tempo necessario per sventare il piano di Malygos.', 0),
(11906, 'itIT', 'È tipico dei Taunka lasciare un''area così come la si è trovata.$B$BPresto ci trasferiremo nella nostra capitale, Foscogelo. Tu ci hai aiutati a partire prima del previsto.$B$BGrazie.', 0),
(11907, 'itIT', 'Grazie, $N.$B$BDistrutte quelle strane creature, ripulire il resto delle pozze non dovrebbe essere un problema.$B$BSiamo in debito con te.', 0),
(11908, 'itIT', 'Eccellente! Qui dovrebbero esserci le informazioni che mi servono.', 0),
(11910, 'itIT', 'Sì, sì, questi andranno benissimo.$B$BGrazie, $r.', 0),
(11912, 'itIT', 'Be'', non è molto, ma dovrebbe tenerci in vita ancora per qualche giorno.$B$BPrendi: dovrebbe bastare a ricompensare i tuoi sforzi.', 0),
(11913, 'itIT', 'Ti ringrazio, $N. Non vorrei mai vedere i superstiti dell''attacco a Borgoardito mangiare del grano appestato.', 0),
(11914, 'itIT', 'I tuoi servigi a Dalaran non passeranno inosservati, $r.$B$BSpero intanto che questa ricompensa sia sufficiente.', 0),
(11916, 'itIT', 'Temo che tu sia arrivato troppo tardi, campione. La maggior parte dei miei fratelli e delle mie sorelle ha abbandonato Taunka''le per cercare rifugio nella lontana Dracombra, a est.$B$BQui c''è molto lavoro da fare, ma sono pochi quelli disposti a occuparsene...', 0),
(11917, 'itIT', 'Hai fatto bene. Potrà sembrarti una cosa da niente, ma persino questo gesto può aiutarci a vincere la battaglia. Prendi questa ricompensa e la mia benedizione. Torna più tardi, ho altre cose da farti fare.', 0),
(11918, 'itIT', 'Bene, $c, ora che ti sei fatto una prima idea sul nemico che dovrai affrontare, possiamo metterci al lavoro.', 0),
(11919, 'itIT', 'Non devi avere sulla coscienza la sorte di questi giovani drachi, $r: Malygos è l''unico responsabile della loro fine.$B$BDal canto mio, sto lavorando incessantemente per scoprire il segreto di queste rune. Non falceremo più vite dello stretto necessario.', 0),
(11920, 'itIT', 'Cultisti? Sottocoperta? Farò frustare tutto il mio equipaggio!$B$BAscolta... perché non lasciamo che sia l''Ammiraglio Gransella a occuparsi di questa... situazione?', 0),
(11922, 'itIT', 'Ben fatto! Diventerai un vero giocoliere più velocemente della miccia di un petardo! Ora sbrigati: è con la prossima prova che la situazione si fa davvero... scottante.', 0),
(11927, 'itIT', 'Grazie per essere accorso in mio aiuto. Non sapevo chi altri contattare.', 0),
(11928, 'itIT', 'Sei qui per aiutarci? Arrivi appena in tempo allora!', 0),
(11931, 'itIT', 'Ottimo lavoro, $r.$B$BSperiamo di trovare qualcosa da usare contro Malygos.', 0),
(11932, 'itIT', 'Ricordo l''uomo di cui parli. Portava il segno di Karkut.$B$BPossa Karkut proteggere i nostri caduti.', 0),
(11933, 'itIT', 'Questo fuoco mi è nuovo... Eppure hai detto che proviene da Exodar. Affascinante! Ovviamente ti pagherò per essere salita a bordo di quella nave. Qualora trovassi qualcos''altro di simile, vieni a parlare con me.', 0),
(11935, 'itIT', 'Che fiamma gloriosa! L''hai presa a Lunargenta? Incredibile! Chissà cosa potremmo ottenere, se possedessimo le fiamme di tutte le quattro città?', 0),
(11936, 'itIT', 'Mi addolora ordinare la distruzione di uova di drago, che siano nemiche o meno.$B$BSperiamo che il fine possa giustificare i mezzi...', 0),
(11938, 'itIT', 'Questo dovrebbe farci guadagnare del tempo. Isidorus ha collaborato, ma per quel Lich dovrò faticare ancora un po''.', 0),
(11942, 'itIT', 'Ottimo lavoro, $N. E ora non ci resta che scoprire un''ultima informazione.', 0),
(11944, 'itIT', 'Dovremmo aver guadagnato del tempo. Speriamo che il Forte degli Arditi ci mandi dei rinforzi, anche se è assai improbabile.', 0),
(11945, 'itIT', 'Grazie, $N. Questi rifornimenti nutriranno i nostri figli e cugini. Anche se Kaskala dovesse cadere, le nostre tribù sopravvivrebbero.', 0),
(11946, 'itIT', 'Non possiamo aspettare che io recuperi le forze.$B$BDevo fare affidamento su di te per preparare il piano...', 0),
(11947, 'itIT', 'Hai fatto bene. Potrà sembrarti una cosa da niente, ma persino questo gesto può aiutarci a vincere la battaglia. Prendi questa ricompensa e la mia benedizione. Torna più tardi, ho altre cose da farti fare.', 0),
(11948, 'itIT', 'Hai fatto bene. Potrà sembrarti una cosa da niente, ma persino questo gesto può aiutarci a vincere la battaglia. Prendi questa ricompensa e la mia benedizione. Torna più tardi, ho altre cose da farti fare.', 0),
(11949, 'itIT', 'Grazie, $N. Se mai sopravvivrò all''attacco, sarò in grande debito con te.', 0),
(11950, 'itIT', 'Ti manda Ataika, vero? Non mi convincerai.$B$BNon tutto è perduto. Gli spiriti sono ancora con noi.', 0),
(11951, 'itIT', 'Grazie, $N.$B$BLa prigionia mi ha fisicamente prostrata e sto recuperando le forze molto, molto lentamente.$B$BUserò il potere di questi cristalli saggiamente: essi sono un sottoprodotto delle malvagie trame di Malygos ma, con un po'' di fortuna, giocheranno un ruolo nella sua sconfitta.', 0),
(11952, 'itIT', 'Hai fatto bene. Potrà sembrarti una cosa da niente, ma persino questo gesto può aiutarci a vincere la battaglia. Prendi questa ricompensa e la mia benedizione. Torna più tardi, ho altre cose da farti fare.', 0),
(11953, 'itIT', 'Hai fatto bene. Potrà sembrarti una cosa da niente, ma persino questo gesto può aiutarci a vincere la battaglia. Prendi questa ricompensa e la mia benedizione. Torna più tardi, ho altre cose da farti fare.', 0),
(11954, 'itIT', 'Hai fatto bene. Potrà sembrarti una cosa da niente, ma persino questo gesto può aiutarci a vincere la battaglia. Prendi questa ricompensa e la mia benedizione. Torna più tardi, ho altre cose da farti fare.', 0),
(11956, 'itIT', 'Appena in tempo, $N. Tenere in pugno un Lich non è facile come sembra.', 0),
(11957, 'itIT', 'Ora che Saragosa non c''è più il mondo è un posto migliore, ma il nostro lavoro non è affatto finito.$B$BÈ il momento di colpire Malygos!', 0),
(11958, 'itIT', 'Non mi fa piacere chiederti di fare queste cose per conto nostro. Tutto ciò che possiamo fare è prepararci in fretta alla partenza, anche se non sappiamo ancora dove andare.$B$BI miei Occultisti mi dicono che sei qui per salvare la terra da Colui che Cammina nell''Ombra.$B$BSpero salverai anche i suoi abitanti.', 0),
(11959, 'itIT', 'La morte di Loguhn per mano tua è esattamente ciò di cui aveva bisogno il mio popolo. Ora approfitteremo della lotta interna tra i Volvar per la sua successione.$B$BDovrebbe essere sufficiente.', 0),
(11960, 'itIT', 'Pare tu ne abbia salvati abbastanza. Grazie, $r.$B$BOra i Volvar avranno la possibilità di vivere al nostro fianco. Sempre se riusciamo a sopravvivere, s''intende.$B$BCredi di poter tornare domani per aiutarci a salvare altri cuccioli?', 0),
(11961, 'itIT', 'Avverti la presenza di Issliruk, $N? Egli non vuole che i suoi figli periscano per mano dei mostri della nebbia.', 0),
(11962, 'itIT', 'Minerali da Borgoardito? Non ne aspettavamo, in questo periodo. È successo qualcosa?', 0),
(11963, 'itIT', 'Hilda ci invierà delle armi? È una notizia fantastica, $N! E io che stavo per ordinare ai ragazzi di fare i bagagli.', 0),
(11964, 'itIT', 'Ah, e cos''è che sento? Che aroma delizioso! Sicuramente brucerà di una fiamma pura e luminosa!$B$BPrendi questo bocciolo, $N. Prendilo e lasciami... Devo occuparmi di questo prezioso combustibile...', 0),
(11965, 'itIT', 'Grazie ancora per averci aiutato, $N. La popolazione di Borgoardito si ricorderà sempre di te.', 0),
(11966, 'itIT', 'Ah, e cos''è che sento? Che aroma delizioso! Sicuramente brucerà di una fiamma pura e luminosa!$B$BPrendi questo bocciolo, $N. Prendilo e lasciami... Devo occuparmi di questo prezioso combustibile...', 0),
(11967, 'itIT', 'Sì, la notizia del salvataggio di Keristrasza è giunta al mio orecchio: meriti un elogio!$B$BNon vedo l''ora di poterle parlare di nuovo.', 0),
(11968, 'itIT', 'Ci hai reso un grande favore, $r. La battaglia non è ancora vinta, ma ora la mia gente ha una possibilità di vittoria.', 0),
(11969, 'itIT', 'Abbiamo sferrato un duro colpo a Malygos, ma a caro prezzo.', 0),
(11970, 'itIT', 'Ti dirò con piacere tutto ciò che so in proposito.', 0),
(11972, 'itIT', 'Sì, questi frammenti contengono l''ultima essenza rimasta su questa terra del Signore del Gelo. Ce ne libereremo e bandiremo Ahune nei gelidi inferi.$B$BGrazie, $N. Il tuo nome risuonerà nei canti del Circolo della Terra fino alla fine dei giorni. Onoraci accettando queste vestigia, simbolo della tua affinità al calore e alla luce.', 0),
(11975, 'itIT', 'Hai visto? Mi hanno sorriso!$B$BOra so come si sentono quando sono sul palco durante i concerti! Sento scorrermi dentro la loro energia e la potenza della loro musica!$B$BProprio come descritto nelle loro canzoni!$B$BHo deciso: da grande farò la rock star!', 0),
(11982, 'itIT', 'Ogni volta che riusciamo a riempire la fossa, i Nani del Ferro la svuotano. Non basta attaccarli dall''alto per impadronirci della città. Devi aiutare i Terrigeni che combattono nella piazza qui sotto.', 0),
(11983, 'itIT', 'Grazie per quello che hai fatto, Comandante $N. Avevano perso tutto, ma tu hai ridato loro uno scopo e la speranza di un nuovo futuro... con una nuova vita.', 0),
(11984, 'itIT', 'Ottimo lavoro, $c. Budd continuerà a farci comodo ancora per un po''.$B$BCi occuperemo subito della tua gabbia. Ecco la tua parte della taglia.$B$BAh... e benvenuto all''accampamento. Fatti un giro, vedrai che ti troveremo qualcosa da fare...', 0),
(11985, 'itIT', 'Ben fatto, $N. Ora che i Nani del Ferro sono privi del loro comandante, non dovrebbe essere difficile annientare ciò che resta delle loro difese. I Terrigeni si occuperanno dei sopravvissuti.', 0),
(11986, 'itIT', 'Hai trovato il Diario di Brann? Incredibile! La Lega non ha sue notizie da molto tempo. Iniziavamo a temere che fosse stato catturato o ucciso. Che cos''ha scoperto, all''interno di Thor Modan?', 0),
(11989, 'itIT', 'Ecco fatto!$B$BOra siamo fratelli di sangue, cumpà. Ci sta nu legame fra me e te.$B$B$r, sient''a me attentamente. Ci sta da fare assai.', 0),
(11991, 'itIT', 'Ah... sì! Ottimo lavoro, cumpà.$B$BDa accà riesco a leggere benissimo chello che ci sta scritto sulle mura...', 0),
(11995, 'itIT', 'Ti stavo aspettando, $c. Abbiamo parecchio lavoro da fare, io e te.', 0),
(11998, 'itIT', 'Ricapitoliamo, $r: non ti conosco, ma mi porti un barile del miglior Torcibudella in circolazione. Dov''è la fregatura?', 0),
(11999, 'itIT', 'Che strano... stanno cercando un''alleanza con gli Etereum. Gli Eterei potrebbero rivelarsi un potente alleato per Malygos e i suoi folli piani.$B$BDobbiamo intervenire!', 0),
(12000, 'itIT', 'Che strano... stanno cercando un''alleanza con gli Etereum. Gli Eterei potrebbero rivelarsi un potente alleato per Malygos e i suoi folli piani.$B$BDobbiamo intervenire!', 0),
(12004, 'itIT', 'Peccato che Goramosh abbia rivelato che l''accordo era già stato raggiunto.$B$BA ogni modo, sono due pericoli in meno di cui preoccuparci. Ora pensiamo a questioni più urgenti.', 0),
(12006, 'itIT', 'Ottimo lavoro! Se non altro, hai soddisfatto la mia richiesta.$B$BGrazie, $r.', 0),
(12007, 'itIT', 'È chello giusto, cumpà!$B$BÈ persino più prezioso di chello che pensavo. Darà nu poco di speranza al popolo mio in chesti tempi oscuri.$B$BMo'' non ci sta tempo da perdere: scopriamo dove sta nascosto il prossimo manufatto.', 0),
(12008, 'itIT', 'Mentre ti battevi per la causa dell''Orda altrove, molti altri hanno lavorato per allargare il nostro dominio su Nordania. Anche in questo momento ci sono forze che stanno creando delle basi nelle aree gelide di queste terre desolate.$B$BStiamo circondando il Flagello su ogni lato. La vittoria si avvicina, mentre i nostri eserciti si ammassano ai piedi di Angrathar, il Cancello dell''Ira. Presto distruggeremo il cancello ed entreremo nella Corona di Ghiaccio.$B$BMa c''è ancora parecchio da fare...$B$BPrima dobbiamo fermare i Nerubiani!', 0),
(12009, 'itIT', 'Io sono solo un povero costruttore di trappole. Il mondo è impazzito tutto d''un tratto. Non ha senso.$B$BSpero tu riesca a rimettere le cose a posto.', 0),
(12011, 'itIT', 'È una cosa che avrei preferito non sapere, $r.$B$BNo, no... hai fatto bene a dirmelo, ma temo che il mio vecchio nemico sia tornato a popolare queste acque.', 0),
(12012, 'itIT', 'Sono davvero cattive notizie. Dobbiamo fare tutto quanto il possibile per impedire chesta guerra.', 0),
(12013, 'itIT', 'Hai tutta la mia gratitudine, $N.$B$BSe non l''hai già fatto, dovresti avvertire i tuoi superiori del pericolo scatenato dallo Stormo dei Draghi Blu. Distruggendo l''ancora della linea di faglia sotto ai Giardini, minacciano di annientarci tutti!', 0),
(12016, 'itIT', 'Se sei riuscito a uccidere Kili''ua, forse sarai in grado di eliminare anche Tu''u''gwar.$B$BO forse no, chi lo sa...', 0),
(12017, 'itIT', 'Dobbiamo festeggiare il tuo successo, mio giovane amico! C''è del sangue in acqua ed è quello del nostro nemico!$B$BTi sarò riconoscente in eterno, così come lo saranno tutti i Kalu''ak dopo che avrò sparso la notizia!$B$BPrendi qualcosa come ricompensa.', 0),
(12019, 'itIT', 'Ottimo lavoro, $N. Speravo di lasciare mia sorella fuori da questa vicenda... Grazie a te è viva e sta bene.$B$BIl mio dovere nei confronti del mio re e del mio esercito è stato assolto, ma ormai è chiaro che non sono più il benvenuto tra i miei compagni: dovrò trovare la mia strada, combattendo da solo le mie guerre e seguendo solo gli ordini impartiti dal mio cuore.$B$B$c, forse un giorno ci incontreremo di nuovo. In attesa di quel momento, accetta questo in segno di gratitudine da parte mia.', 0),
(12020, 'itIT', 'E così hai fermato i Ferroscuro... mentre eri ubriaco? $c, questo è il vero spirito della Festa della Birra! Immagino che ora, sempre nel pieno rispetto dello spirito della festa, vorrai la tua ricompensa in Gettoni.$B$B$N, grazie ancora e goditi il resto della Festa della Birra.', 0),
(12022, 'itIT', 'Hai appena avuto un esempio della migliore ingegneria degli Gnomi! B.I.R.R.A. sopporta tutto, da vero campione!$B$BOra sei pronto per affrontare i Ferroscuro se dovessero farsi vivi nuovamente.', 0),
(12027, 'itIT', 'Grazie al cielo hai trovato Emily! Si è allontanata senza di me e ho temuto che si perdesse.$B$BMeno male, anche Ser Flaccidino è sano e salvo.', 0),
(12028, 'itIT', 'Fantasmi e follie senza senso? Non può essere!$B$BDobbiamo consultare qualcun altro.', 0),
(12030, 'itIT', 'Ti stavo aspettando, $r. Ho visto il tuo spirito volare qui e ho avvertito la presenza del Mistico dietro al tuo sguardo.$B$BIl tuo destino ora è legato a quello dei Kalu''ak.', 0),
(12031, 'itIT', 'Non si è trattato di un compito piacevole, ma era un atto di pietà necessario.$B$BOra c''è un''altra cosa devi fare per i Kalu''ak.', 0),
(12034, 'itIT', 'Via terra e via aria: è così che metteremo fine alla minaccia Anub''ar.', 0),
(12035, 'itIT', 'Ottimo lavoro! Finalmente torno a sentirmi utile... e questa è già una gran cosa.', 0),
(12039, 'itIT', 'È così leggero... come se non pesasse affatto! Avrò bisogno di tempo per analizzare il metallo e vedere come si può utilizzare! Esperimenti! Devo fare degli esperimenti!$B$BMi terrò in contatto con te, $N. Se dovessi scoprire qualcosa, sarai il primo a saperlo.', 0),
(12040, 'itIT', 'Sono migliaia e fuoriescono da ogni crepa oscura a Nordania. Da solo non hai alcuna possibilità, ma insieme... forse...', 0),
(12046, 'itIT', 'Bene... queste dovrebbero andare. Le bombe a frammentazione sono quasi ultimate.$B$BAspetta... cos''è successo ai miei frammenti di ghiaccio? Narf mi aveva detto che i frammenti di quegli elementali erano incantati e invece si stanno sciogliendo come ghiaccioli!', 0),
(12047, 'itIT', 'Eccellente! Ora non resta che provare le nuove bombe. Ci vorrà solo un istante!', 0),
(12048, 'itIT', '$N, questi armamenti sono in ottime condizioni. Mi metterò subito al lavoro. Se dovessi riuscire a creare qualcosa, sarai il primo a saperlo!', 0),
(12053, 'itIT', 'Li abbiamo annientati a terra! Presto li spazzeremo via anche dall''aria!', 0),
(12055, 'itIT', '$N, se non mi sbaglio hai scoperto la chiave che ci permetterà di capire esattamente le intenzioni dei Cacciatori di Maghi!', 0),
(12059, 'itIT', '$N, se non mi sbaglio hai scoperto la chiave che ci permetterà di capire esattamente le intenzioni dei Cacciatori di Maghi!', 0),
(12063, 'itIT', 'Mio padre è ancora vivo! Dobbiamo salvarlo! Non posso farcela da solo, $r. Devi aiutarmi!', 0),
(12065, 'itIT', 'È molto strano che abbia impresso queste informazioni su di te con la magia.$B$BOra non solo sappiamo che hanno deviato il flusso di potere proveniente dai Giardini di Lunanuova, ma che stanno anche modificando il potere in qualche modo. A cosa gli serve tutta quella magia?$B$BQuesta faccenda non mi piace per niente, $N!', 0),
(12066, 'itIT', 'È molto strano che abbia impresso queste informazioni su di te con la magia.$B$BOra non solo sappiamo che hanno deviato il flusso di potere proveniente dai Giardini di Lunanuova, ma che stanno anche modificando il potere in qualche modo. A cosa gli serve tutta quella magia?$B$BQuesta faccenda non mi piace per niente, $N!', 0),
(12068, 'itIT', 'Ce l''abbiamo fatta, $N!$B$BTeniamo tutto quanto il necessario per eseguire il rituale di purificazione.', 0),
(12069, 'itIT', '$N, sei davvero coraggioso. Hai reso un enorme servizio all''Orda liberando il Gran Capo.', 0),
(12070, 'itIT', 'Hai donato ai nostri alleati la forza necessaria per continuare a combattere e di questo ti ringrazio. Ciononostante, dobbiamo escogitare un modo per porre fine alla battaglia prima di venire sopraffatti.', 0),
(12081, 'itIT', 'So che Kurun è molto soddisfatto di te. La caduta di Thor Modan è una grande conquista, ma non basta a liberare i nostri fratelli.', 0),
(12082, 'itIT', 'E così sei sopravvissuto a una piccola avventura con il nostro amico, eh?$B$BGià solo questa dovrebbe bastare come ricompensa. Però mi sento generoso. Ecco, tieni.', 0),
(12083, 'itIT', 'Lo stanno usando per potenziare le loro forze? È assurdo... i Cacciatori di Maghi non sono così potenti.$B$BQuesto vuol dire che stanno usando la magia solo nel punto in cui hanno deviato la linea di faglia.$B$BCi servono ulteriori informazioni se vogliamo scoprire dove si trovano e fermarli!', 0),
(12084, 'itIT', 'Lo stanno usando per potenziare le loro forze? È assurdo... i Cacciatori di Maghi non sono così potenti.$B$BQuesto vuol dire che stanno usando la magia solo nel punto in cui hanno deviato la linea di faglia.$B$BMi servono ulteriori informazioni se voglio ideare un piano per fermarli!', 0),
(12086, 'itIT', 'Thassarian? Sì, è stato qui... e allora? In questo momento abbiamo problemi più urgenti, amico mio.', 0),
(12088, 'itIT', 'Leryssa mi sta cercando? Devi aiutarmi, $N. Dobbiamo mettere fine a tutto questo prima che le succeda qualcosa.', 0),
(12089, 'itIT', 'Non è stato il primo dei nostri incantatori a tradirci e certamente non sarà l''ultimo. Peccato, perché era uno dei nostri maghi migliori. Era capace di evocare un banchetto in grado di farti venire l''acquolina in bocca e farti battere il cuore dalla gioia...$B$BBah!', 0),
(12090, 'itIT', 'Hai ucciso quel mostruoso figlio di una cavalla, eh? Be'', questo significa che i nostri soldati avranno un problema in meno di cui occuparsi nelle Distese Ghiacciate.', 0),
(12091, 'itIT', 'Ottimo lavoro, $N. Era ora che qualcuno mettesse fine alla serie di uccisioni di quella bestiaccia!', 0),
(12092, 'itIT', 'Grazie, $r! Il tuo intervento ci permetterà di preservare i figli più imponenti di Nordania.$B$BPresto andrò a parlare con gli antichi che hai salvato per vedere se saranno disposti ad aiutarci in caso di bisogno.', 0),
(12093, 'itIT', 'Bene. Ora dobbiamo agire rapidamente, prima che i figli del ferro si accorgano che le loro rune sono diventate inoffensive.', 0),
(12094, 'itIT', 'Sento il potere infuso nel frammento. Spero sia sufficiente per spezzare la magia runica.', 0),
(12095, 'itIT', 'Perché credi che avrai successo dove Rokhan ha fallito?', 0),
(12096, 'itIT', 'Ti ringrazio, $c.$B$BNon appena avrò finito di osservare cosa hanno in mente questi disgustosi speziali, mi dirigerò nella foresta per convincere gli antichi a schierarsi dalla nostra parte.$B$BNella peggiore delle ipotesi, cercherò di persuaderli a non attaccare chi li ha salvati!', 0),
(12097, 'itIT', 'Ce l''hai fatta! I soldati al Cancello dell''Ira sono in debito con te, $N! Questo permetterà ad alcuni di loro di sopravvivere un altro giorno.', 0),
(12099, 'itIT', 'Quindi il processo non funziona sempre? Spero non dipenda tutto dal caso, ma perlomeno siamo sulla strada giusta. Senza il tuo aiuto, tutto questo non sarebbe stato possibile. Qualora venissi a sapere qualcosa di più riguardo alle macchinazioni dei Nani del Ferro, e ai loro piani per contrastare i Figli della Pietra, vienici a cercare. Ti ascolteremo di sicuro, $N.', 0),
(12100, 'itIT', 'Mi addolora dover uccidere gli animali, ma è necessario. Ora dobbiamo passare alla fase successiva: la Vaccinazione.', 0),
(12102, 'itIT', 'Non è stato difficile, vero?$B$BOra concedimi un istante per preparare il vaccino.', 0),
(12105, 'itIT', 'Immaginavo che il problema dei Worgen non si limitasse a un isolato villaggio ostile.$B$BAbbiamo degli uomini vicino alla Miniera di Pietracava, forse faremmo bene a condurre una piccola ricerca.', 0),
(12109, 'itIT', 'Ti manda Dumont? Molto bene. Vediamo cosa puoi fare per noi.', 0),
(12111, 'itIT', 'Hai compiuto un gesto nobile, $N. Scegli la tua ricompensa.', 0),
(12113, 'itIT', 'Eccellente!$B$BPer accompagnare una pinta, non c''è niente di meglio di un bel pezzo di carne.', 0),
(12114, 'itIT', 'Grazie, $c.$B$BAppena ne avrò il tempo andrò a dare un''occhiata.', 0),
(12116, 'itIT', 'Visceri? Che scelta curiosa, $r.$B$BKraz cercherà di scoprire qualcosa da questi. Grazie per aver affrontato le profondità di quel luogo.', 0),
(12117, 'itIT', 'Cos''hai detto, $r? Ti manda Hotawa?$B$BBene, bene... c''è molto da fare e abbiamo bisogno di tutto l''aiuto possibile!', 0),
(12119, 'itIT', 'Una lettera di presentazione per incontrare la Regina? Fa'' un po'' vedere.$B$BDi qualunque cosa si tratti, spero per te che sia importante. Il cielo oggi è pieno di Draghi Blu che ci attaccano!', 0),
(12120, 'itIT', 'Finora te la sei cavata bene, $N, ma adesso si inizia a fare sul serio.', 0),
(12121, 'itIT', 'La venuta tua mi era stata annunciata. Hai fatto bene a venire da me.', 0),
(12122, 'itIT', 'Una lettera di presentazione per incontrare la Regina? Fa'' un po'' vedere.$B$BDi qualunque cosa si tratti, spero per te che sia importante. Il cielo oggi è pieno di Draghi Blu che ci attaccano!', 0),
(12125, 'itIT', 'Non montarti la testa. Era un compito semplice, che avrebbe potuto svolgere anche un bambino.', 0),
(12127, 'itIT', 'Sento già il Gelo scorrere dentro me, $N.', 0),
(12128, 'itIT', 'Uhm... Non mi sembri un debole assistente ricercatore, per fortuna! I Nani del Ferro si preparano alla guerra e la mia squadra non è ancora tornata. Abbiamo proprio bisogno di un po'' d''aiuto.', 0),
(12129, 'itIT', 'Li hai tutti? Ottimo! Non vedo l''ora di scoprire che faccia faranno, una volta completato il Golem.', 0),
(12132, 'itIT', 'Ho pagato a caro prezzo il mio potere, $N. Molti cavalieri, sia della Luce che della Morte, hanno perso le loro vite nella battaglia finale alla Cappella della Luce. Il futuro non promette niente di buono, ma almeno ora so cosa attendermi. Il Re dei Lich non mollerà mai la presa e solo per questo deve morire!', 0),
(12134, 'itIT', 'Uccidere quei mostri non riporterà in vita mio padre... ma non è più questo ciò che importa, giusto?', 0),
(12137, 'itIT', 'Hai fatto un buon lavoro.$B$BSiediti e ascolta: dobbiamo discutere di molte cose.', 0),
(12138, 'itIT', 'Finalmente è pronto! Spero solo che non si rompa prima di completare il lavoro. Se non facciamo fuori il Thane che governa Dun Argol, il Capitano Gryan avrà una brutta sorpresa.', 0),
(12139, 'itIT', 'I roghi sono spenti! Tu e gli altri avete domato gli incendi!$B$BL''attacco del Cavaliere Senza Testa è fallito, ma finché lui e la sua testa non saranno distrutti, tornerà.$B$BOra, però, cerchiamo di far godere ai bambini la pace ritrovata. Sono onorata di aver assistito alle tue gesta coraggiose.', 0),
(12140, 'itIT', 'Con l''aiuto di uno Sciamano così potente, vinceremo di sicuro al Cancello dell''Ira!', 0),
(12141, 'itIT', 'Sei qui per aiutarmi? Grazie, $N.', 0),
(12144, 'itIT', 'Che liberazione, cumpà.', 0),
(12145, 'itIT', 'Pugnogelato, eh? Chisto nome nun mi è nuovo. Hai fatto nu ottimo lavoro, $C. Mo'' spero che potremo concentrarci nuovamente sulla minaccia dei draghi.', 0),
(12147, 'itIT', 'È davvero strano che un Magnatauro porti un oggetto del genere... e molto preoccupante. Hai fatto bene a mostrarmelo.', 0),
(12148, 'itIT', 'Dunque è vero. Non potevano scegliere un momento migliore per attaccare... tra il Flagello e lo Stormo Blu, è difficile che qualcuno si sia accorto di loro.', 0),
(12149, 'itIT', 'Ottimo lavoro. Nessuno ha saputo dirmi dove si trova questo capo, ma sono riuscita a sapere il nome di qualcuno che potrebbe avere la risposta che cerchiamo.', 0),
(12150, 'itIT', 'Grom''thar l''Araldo del Tuono. Bene. Facciamola finita una volta per tutte con questi Magnatauri.', 0),
(12151, 'itIT', 'Sei stata davvero formidabile.$B$BCon la morte di Grom''thar l''Araldo del Tuono possiamo lasciare che i Magnatauri rimasti combattano tra loro e rivolgere le nostre attenzioni verso questioni più urgenti.$B$BOttimo lavoro, $c.', 0),
(12152, 'itIT', 'È finita.$B$BCon il tuo altruismo, hai donato la pace eterna a molte anime, ponendo fine a eoni di tormenti.$B$BChe tali azioni illuminino il tuo spirito e allevino i tuoi fardelli, perché vedo che dovrai affrontare ancora molti pericoli.$B$BAddio, $N.', 0),
(12157, 'itIT', 'Non appena ho attraversato il ponte all''ingresso di Dracombra, un piccolo gruppo di Anub''ar mi ha teso un''imboscata! Quei mostri sapevano del mio arrivo. Mi hanno circondato e a stento sono riuscito a fuggire con la carne ancora attaccata alle ossa. Questo elenco va consegnato al Forte di Guardia Invernale, ma sono troppo mal ridotto per poter giungere fin lì.', 0),
(12158, 'itIT', 'Sei qui per aiutarmi, vero?', 0),
(12159, 'itIT', 'Riposate in pace, amici! Non temete: dirò a tutti che non ci siamo mai arresi!', 0),
(12160, 'itIT', 'Maledetta sfortuna! Abbiamo trovato una miniera funzionante da questo lato della collina ed è piena di membri del Flagello.$B$BSenza offesa, amico, ma il sopravvissuto che hai trovato sembra un po'' traumatizzato dalla perdita dei suoi amici. Arugal è morto da anni... ho persino visto la sua tomba.', 0),
(12161, 'itIT', 'Cerchi una conoscenza al di fuori della tua portata, per questo sei qui. Devo avvisarti, straniero, le risposte che ti darò potrebbero non piacerti.', 0),
(12164, 'itIT', 'È andata bene, $N, anche se probabilmente sentiremo ancora parlare di lui.$B$BUna cosa è certa: non lo vedremo più bazzicare da queste parti.', 0),
(12166, 'itIT', 'Abbiamo fatto il possibile per le creature della terra. Ora dobbiamo affrontare i responsabili di tutto questo!', 0),
(12167, 'itIT', 'Ottimo lavoro, $N.$B$BMi sbarazzerò di questi indumenti corrotti purificandoli nel Pozzo Lunare e distruggendoli con il potere della dea!', 0),
(12168, 'itIT', 'E così il capo dei cultisti è uscito allo scoperto. Ora abbiamo un nome.$B$BLa vanità e l''orgoglio saranno la sua rovina!', 0),
(12169, 'itIT', 'Con il Gran Cultista morto, possiamo eliminare il resto delle sue forze. La terra e le sue creature si riprenderanno col tempo.$B$BGrazie, $N. Possa la dea rischiarare il tuo cammino.', 0),
(12176, 'itIT', 'Ti sono debitore, cumpà. Accetta chesta ricompensa.', 0),
(12177, 'itIT', 'Cumpà, speriamo bene.', 0),
(12178, 'itIT', 'Credete che sia scema? Queste pelli odorano di farina!$B$BState insultando l''Orda con le vostre azioni!', 0),
(12184, 'itIT', 'Bene, dovrebbero essere sufficienti. Ora creiamo un corredo per trasformarti in un Nano del Ferro credibile.', 0),
(12188, 'itIT', 'Questi andranno bene, $N. Quei patetici spettri ti hanno creato problemi o sono corsi a piangere in un angolo?$B$BHanno la lacrima facile...', 0),
(12189, 'itIT', 'C''è stato un PICCOLO contrattempo. Tutti coloro che hanno provato a usare il morbo si sono vaporizzati. Stiamo lavorando per modificare la formula in modo che il suo uso non si riveli letale. La buona notizia è che dovrebbe mancare poco!', 0),
(12190, 'itIT', 'Molto bene! Ti manda il vecchio Prigmon, eh?$B$BCon questi riuscirò a preparare un bel pranzetto. Mi mancano giusto un paio di cose...', 0),
(12191, 'itIT', 'Incredibile... B.I.R.R.A. non si è rotto. Uhm... Chi l''avrebbe mai detto?$B$BVoglio dire... Ce l''hai fatta! Hai una mira perfetta... o, perlomeno, sufficiente per proteggere l''accampamento. Ora sei pronto per affrontare i Ferroscuro, se dovessero farsi vivi nuovamente.', 0),
(12192, 'itIT', 'E così hai fermato i Ferroscuro... mentre eri ubriaco? $c, questo è il vero spirito della Festa della Birra! Immagino che ora, sempre nel pieno rispetto dello spirito della festa, vorrai la tua ricompensa in Gettoni.$B$B$N, grazie ancora e goditi il resto della Festa della Birra.', 0),
(12200, 'itIT', 'Credo che il morbo sia pronto per una prova sul campo. Il caso vuole che la cittadella maledetta, Naxxramas, stia cingendo d''assedio il Forte di Guardia Invernale. I non morti si stanno risvegliando proprio sotto la terra sulla quale è stata costruita Guardia Invernale, ansiosi di obbedire agli ordini di Kel''Thuzad.$B$BL''Alleanza si trova chiaramente in inferiorità numerica e ha una minore potenza di fuoco. I morti che riposavano nel Mausoleo di Guardia Invernale sono stati risvegliati e bramano carne!$B$BForse potremmo far assaggiare loro il morbo, che ne dici?', 0),
(12205, 'itIT', 'Hai fatto davvero un ottimo lavoro, $r. Spero tu non abbia avuto pietà di loro.$B$BVediamo un po'' come posso premiare i tuoi sforzi...', 0),
(12207, 'itIT', 'Questa melma è infetta da un''oscurità molto più antica di quanto il suo aspetto terreno faccia supporre. La stessa regione ha memoria di questa malvagità da quando esiste.$B$B$N, dobbiamo scoprirne di più.', 0),
(12209, 'itIT', 'Ora non hai più la faccia di un novellino.$B$BLe armi e le armature che mi hai portato andranno bene. Come devo chiamarti, $c?', 0),
(12210, 'itIT', 'Sei qui per partecipare alla spartizione del bottino, eh?', 0),
(12211, 'itIT', 'Ah, bene! Per un attimo ho pensato di dover testare i ratti su qualcuno per assicurarmi che non avessero qualche problema.$B$BFinalmente facciamo progressi!', 0),
(12212, 'itIT', 'Ma che bei pezzi di carne!', 0),
(12213, 'itIT', 'Questo globo... è stato infettato da... una forza malvagia.$B$BNon so cosa altro scoprirò studiandola, ma una cosa è certa: devo distruggere il globo il prima possibile. La sua corruzione è troppo potente.', 0),
(12214, 'itIT', 'Ah, niente mi rende più felice di un lavoro ben fatto.$B$BHai reso un grande servizio a Venefica procurandoti quei cavalli, $c.', 0),
(12215, 'itIT', 'Ottimo lavoro, $c.$B$BOra gli animali della foresta dovrebbero tornare a svolgere il ruolo per cui la natura li ha creati: finire sulle nostre tavole!', 0),
(12216, 'itIT', 'Stupefacente!$B$BOra le nostre dispense sono quasi piene. $N, il tuo contributo è stato inestimabile.', 0),
(12217, 'itIT', 'Lo so, era un compito ingrato. Ciononostante, ora possiamo riposare tranquilli, sapendo che il nemico non può più spiarci.', 0),
(12218, 'itIT', 'Per quanto mi irriti l''idea di aver aiutato l''Alleanza, dichiaro il test sul campo riuscito! Prossima fermata: il Martello di Agmar!', 0),
(12219, 'itIT', 'Questa melma non è naturale, $N. La sua natura è corrotta e... malvagia.$B$BDobbiamo saperne di più.', 0),
(12220, 'itIT', 'L''energia nel globo è... devastante.$B$BUna forza oscura ha infettato il terreno vicino ai resti di Vordrassil. Dobbiamo indagare e scoprirne di più.', 0),
(12222, 'itIT', 'Con questi, il draco non avrà altra scelta che obbedirti. Non vedo l''ora di scoprire che faccia farà il Thane, quando si renderà conto che controlli il suo Proto-Draco.', 0),
(12223, 'itIT', 'Ben fatto, $N. Approfittiamo del vantaggio per farla finita una volta per tutte.', 0),
(12225, 'itIT', 'Cos''hai fatto?!?$B$BQuelli erano Frutti d''Ibisco! L''intero raccolto!$B$BQuei frutti magici avrebbero dovuto risolvere il problema della carenza di cibo! $N, ora dovrai rimediare al misfatto che hai commesso!', 0),
(12227, 'itIT', 'Allora, $N? È andato tutto bene?$B$BHmm, li abbiamo recuperati appena in tempo...', 0),
(12229, 'itIT', 'In questo sangue, c''è la stessa infezione della melma che mi hai portato prima. Non ho un bel presentimento, $N.', 0),
(12231, 'itIT', 'I Figli di Ursoc sono saggi. Le loro parole spiegano molto di ciò che abbiamo visto.', 0),
(12232, 'itIT', 'Che splendida giornata!$B$BSono sicuro che attirerò l''attenzione del Gran Esecutore, non avendo usato il tempo e le risorse degli speziali per completare il lavoro!$B$BEra esattamente quello che volevo, e tutto questo è stato possibile grazie a te.$B$BSe ti do una cosa, prometti di non rivelare il ruolo che hai avuto in questa faccenda?', 0),
(12234, 'itIT', 'Che cosa stai aspettando, $r? Consegnami gli ordini!', 0),
(12237, 'itIT', 'Ottimo lavoro, $N! Con il ritorno dei nostri cittadini, rimetteremo in funzione questo forte.', 0),
(12240, 'itIT', 'Sapevo che mia sorella non ci avrebbe delusi.$B$BHai fatto un ottimo lavoro, $N. La segheria della Furia resterà fuori uso per un po'', il che significa niente nuove baliste.$B$BGrazie per il tuo aiuto e per aver tenuto alto il nome della mia famiglia.', 0),
(12243, 'itIT', 'Ahhahahahahahahahaha!$B$BSenza i loro piani non possono andare da nessuna parte.$B$BQuesta è la fine della giovane Furia Scarlatta. Che peccato.$B$BAh ah!', 0),
(12245, 'itIT', 'Cosa? Credevi che li avremmo salvati?$B$BE perché mai? Perché vengano catturati un''altra volta?$B$BA Nordania non c''è posto per i buoni sentimenti, giovane $N. Ti consiglio di farci l''abitudine.', 0),
(12246, 'itIT', 'La corruzione presente in questo sangue è identica a quella della melma. Ho un brutto presentimento.', 0),
(12247, 'itIT', 'I Figli di Ursoc sono saggi. Le loro parole spiegano molto di ciò che abbiamo visto.', 0),
(12248, 'itIT', 'Sì! La magia di Vordrassil è ancora presente in queste ceneri. Forse c''è ancora speranza per Ursoc.', 0),
(12250, 'itIT', 'Grazie, $N. Questi li prendo io.$B$BIl potere di corruzione di questi semi è molto pericoloso, devo distruggerli subito.', 0),
(12255, 'itIT', 'Ben fatto, $N. Non credo che qualche carpentiere volesse fare un tentativo per domare il Proto-Draco, ma non potevamo permettere agli Scorticadraghi di stabilire una base nei Colli Bradi. Se solo anche l''Orda fosse così semplice da gestire...', 0),
(12256, 'itIT', 'Grazie al potere dei talismani, il draco sarà costretto a obbedirti. Il fato del Thane è segnato.', 0),
(12257, 'itIT', 'Hai fatto esattamente ciò che ti ho chiesto. Gli Scorticadraghi sono sulla difensiva e presto affronteremo il loro capo.', 0),
(12258, 'itIT', 'Forse ora riposeranno in pace e i loro spiriti liberi potranno ascendere alla Luce.$B$BI miei pensieri e le mie preghiere in questo momento sono rivolti a Ser Domadraghi e alle nostre forze al Cancello dell''Ira. Dobbiamo insistere qui, in modo da far guadagnare loro tempo per sconfiggere il Re dei Lich. Guardia Invernale non deve cadere.', 0),
(12259, 'itIT', 'I pochi Scorticadraghi rimasti non oseranno sfidarci, ora che hai sconfitto il Thane. Stermina i nemici senza pietà: è così che si comporta l''Orda.', 0),
(12260, 'itIT', 'Niente male, $c. Ora che l''immagine del Sacerdote è intrappolata all''interno dello specchio, c''è un''altra cosa che bisogna fare.', 0),
(12261, 'itIT', 'Eccellente. Quando inizieranno a fuggire terrorizzati la protezione sarà lì, pronta a massacrarli.', 0),
(12262, 'itIT', 'Ti hanno chiesto di risparmiargli le loro miserabili vite? Patetici.', 0),
(12263, 'itIT', 'Noi siamo lo Stormo dei Draghi Neri. Abbiamo seminato distruzione sulle terre di Azeroth per migliaia di anni. Il Culto dei Dannati adora la morte e noi li accontenteremo volentieri.', 0),
(12264, 'itIT', 'Udire le loro grida e assistere agli ultimi istanti delle loro patetiche vite è una sensazione gratificante, non sei d''accordo?$B$BA me fa questo effetto.', 0),
(12265, 'itIT', 'Bene. Non è finita qui.', 0),
(12266, 'itIT', 'Oh, sei tu, $N.$B$BSperavo che Serinar tornasse indietro una volta completata la missione. Immagino sia distratto da qualcosa, o da qualcuno, da uccidere. Si sta perdendo un''epica battaglia!$B$BSei ancora qui? Sparisci.', 0),
(12267, 'itIT', 'Le ossa della mia progenie sono state risparmiate da questa corruzione. Mi hai servito bene, per questo ti ricompenserò adeguatamente.', 0),
(12272, 'itIT', 'Questa potrebbe essere una svolta nella battaglia contro il Flagello. Hai dimostrato di essere un eroe dell''Alleanza, $N, almeno ai miei occhi.$B$BOra, se non ti dispiace, vorrei rimanere da solo per studiare questo minerale, in modo da scoprirne le impurità e i punti deboli.$B$BPuoi andare. Ti chiamerò non appena ci saranno novità.', 0),
(12275, 'itIT', 'Ho un brutto presentimento, amica mia. Temo che nella fretta di recuperare il Minerale Strano dalla Miniera di Guardia Invernale abbia mandato a morire l''agente Slinkin.', 0),
(12277, 'itIT', 'Slinkin non è morto invano, amico. Le informazioni che ha raccolto saranno fondamentali per sconfiggere il Re dei Lich. Ti prometto che ne faremo buon uso.', 0),
(12278, 'itIT', 'I moduli sono a posto: benvenuto nel Club, $N!$B$BRiceverai una nostra missiva il primo di ogni mese. Se ciò che hai ricevuto ti soddisfa, torna qui e te ne daremo ancora. In questo Club, non rifiutiamo mai nulla.', 0),
(12279, 'itIT', 'Ehi! Non sei Joe Zoppetto!', 0),
(12282, 'itIT', 'Bel lavoro, $N. Come predetto dal destino, tu sarai colui che ci condurrà attraverso questi tempi difficili. Il lungo viaggio sta per cominciare.', 0),
(12283, 'itIT', 'Maledizione! Non potevi portarmi buone notizie?', 0),
(12287, 'itIT', 'Zelig mi aveva avvertito del tuo arrivo, amico. Ti stavamo aspettando.$B$BIo sono Orik Cuorsincero, Paladino della Crociata d''Argento. La Sacerdotessa accanto al fuoco si chiama Tilda Darathan. Siamo qui per conto della Crociata d''Argento, per placare le sventurate anime dei dannati che cercano di fuggire da Guardia Invernale.', 0),
(12293, 'itIT', 'Ce l''hai fatta! Hai recuperato... ehm... la cassa che l''Orda ci aveva rubato! Grazie, $N.', 0),
(12294, 'itIT', 'Queste sono ottime notizie, $N. Grazie all''aiuto dei locali, avremo il supporto logistico necessario per avere la meglio sull''Orda in questa regione.$B$BSe ti interessa, ho altri compiti da farti svolgere.', 0),
(12295, 'itIT', '$N! Sono felice di incontrarti. Abbiamo sentito parlare di te. Ti do il benvenuto a Rioargento.$B$BQuesti Mastri Bracconieri sono un bel gruppetto di uomini e donne. Gente coraggiosa, che conosce molto bene questa terra. È un bel vantaggio averli convinti ad allearsi con noi, vedrai!', 0),
(12299, 'itIT', 'Niente male davvero. Forse non sei debole come alcuni dei tuoi compagni.', 0),
(12300, 'itIT', 'Non farlo, $N. La gente che ti ha inviato qui... Non dovresti fidarti di loro.', 0),
(12302, 'itIT', 'Chi sei? Sei qui per uccidermi?$B$BTi prego, non farlo!', 0),
(12306, 'itIT', 'E così vuoi unirti a noi, eh $N? Ti tratteremo bene, vedrai. I membri di chisto club ricevono solo il meglio!$B$BIl primo del mese ti mandiamo na birra. Se ti piace, e ne vuoi ancora, torna accà e potrai averne quanta ne vuoi.', 0),
(12308, 'itIT', 'Worgen. Maledetti, sudici Worgen dimenticati dalla Luce!$B$BÈ ora di mostrare ai locali in che modo noi, popoli civilizzati, trattiamo le bestie come loro.', 0),
(12310, 'itIT', 'Peccato che i Mastri Bracconieri si siano rivelati... degli esseri tormentati. Qualche uomo in più ci avrebbe fatto sicuramente comodo, in battaglia.$B$BPossano le loro anime riposare in pace.', 0),
(12311, 'itIT', 'Se riuscissimo a fermare anche gli attacchi del Flagello provenienti dall''esterno del forte potremmo inviare gli aiuti a Ser Domadraghi al Cancello dell''Ira.', 0),
(12312, 'itIT', 'Qualunque informazione sia contenuta in questo libro, deve essere della massima importanza! Ho sentito le urla e i lamenti all''interno della cripta mentre fuggivi!$B$BBisogna avvertire il Gran Comandante!', 0),
(12321, 'itIT', 'Tutto questo è assurdo! Avremmo dovuto sapere di quel dannato mausoleo. Il Duca August Trucemartello e Ambo Cash verranno inviati in prima linea in attesa del nostro prossimo assalto.$B$BDopo che avrai ripulito le miniere ti manderò da Trucemartello per iniziare il nostro attacco contro il Flagello di Naxxramas!$B$BLe informazioni che hai raccolto finora verranno inviate a Ser Domadraghi a Guardia Invernale con il nostro miglior grifone!', 0),
(12325, 'itIT', 'Ah, ecco che arriva il famoso eroe. Benvenuto, $N. Lascia che ti metta al corrente della situazione.$B$BLe forze più potenti di Thel''zan sono entrate nel Mausoleo di Guardia Invernale. Esse saccheggiano le sue sale in cerca di corpi e anime da inviare contro Guardia Invernale, mentre Naxxramas invia le terribili macchine della Piaga del Flagello per tenerci occupati!$B$BDobbiamo attaccare ora, nella speranza che Ser Domadraghi sia in grado di resistere un altro po'' al Cancello dell''Ira.', 0),
(12326, 'itIT', 'Non è importante il motivo per cui non indosso i pantaloni. Diciamo che sono stato colpito da un proiettile del Flagello in un punto sconveniente e finiamola qui, d''accordo?$B$BE così hai distrutto i Carri della Piaga nei campi e hai condotto qui i miei uomini sani e salvi. Impressionante. Sei il primo a riuscirci. Peccato che tu debba tornare nei Campi del Contagio. Purtroppo c''è stato un piccolo contrattempo.', 0),
(12327, 'itIT', 'Hai appreso qualcosa dalla visione? Mentre eri in trance, hai menzionato il villaggio di Solstizio. È la seconda volta che qualcuno me lo menziona, oggi.', 0),
(12328, 'itIT', 'Bene, questa sarà sufficiente.$B$BPreparerò la pozione in men che non si dica.', 0),
(12329, 'itIT', 'Mi chiedevo quando ti saresti fatto vivo. Me la dai una mano?', 0),
(12330, 'itIT', 'C''è... mancato poco.$B$BDobbiamo salvare Anya. Subito!', 0),
(12372, 'itIT', 'È incredibile quello che siete capaci di fare voi razze più giovani.$B$BSiamo in debito con te, $N. Tornerai per aiutarci di nuovo domani?', 0),
(12411, 'itIT', 'Vogliono andarmene da qui. Gli uomini-Worgen sono cattivi.', 0),
(12412, 'itIT', 'Sei tornato... e sei vivo!$B$BE che sciocchezze stai dicendo a proposito dei Worgen?', 0),
(12413, 'itIT', 'Niente male, $N. Forse mi tornerai più utile di quanto pensassi.', 0),
(12414, 'itIT', 'Caspita! Che bei cavalli! Il Capitano sarà davvero contento del nostro lavoro.', 0),
(12416, 'itIT', 'È un compito disgustoso, ma grazie per averlo portato a termine.$B$BNon possiamo permettere che il Flagello si spinga oltre verso la Lega dei Draghi o sarà la fine.', 0),
(12417, 'itIT', 'Nella terra, i miei fratelli potranno far sorgere una nuova vita. Li hai salvati da un destino assai peggiore della morte.$B$BNon so come esprimerti la mia gratitudine nella tua lingua, $r, ma sappi che apprezzo molto quello che hai fatto per me.', 0),
(12418, 'itIT', 'Hanno trasformato Dahlia...?$B$BDahlia ci è stata leale per molto tempo... se possono corrompere un essere con la sua dedizione, allora c''è poca speranza per le altre razze più giovani. Grazie per averla liberata. Spero possa trovare pace.$B$BOggi ci hai reso un grande onore, $r, aiutandoci in maniera disinteressata. Avvertirò il concilio di ciò che la tua razza ha fatto qui. Ora va'', con la nostra benedizione.', 0),
(12419, 'itIT', 'Dahlia è stata presa dal Flagello? Questo è un giorno triste per tutti noi.$B$BDovrò cercare una nuova protettrice una volta che ci saremo ripresi il santuario. Grazie per i tuoi sforzi... Il Santuario dei Draghi di Rubino è un luogo sacro per noi e i sacrifici compiuti dalla tua razza non verranno dimenticati tanto facilmente.$B$BSono contento di sapere che ci siano ancora degli eroi come te. Un giorno potrei aver bisogno nuovamente del tuo aiuto. Per il momento, ti auguro buona fortuna.', 0),
(12422, 'itIT', 'Mi lascerai andare? Senza chiedermi niente in cambio? Senti, non voglio problemi... Ora ho altre cose per la testa: quei mostri hanno ucciso mio padre e rapito mia sorella.', 0),
(12423, 'itIT', 'Ah! È uno scherzo?$B$BA malapena leggo i libri scritti in una lingua che riesco a capire!', 0),
(12424, 'itIT', 'Possibile? L''uomo che ha scritto questo diario temeva per la sorte delle sue figlie, così le ha mandate via da Rioargento.$B$BAbbiamo appena catturato una fuggitiva ai confini della città e ha più o meno l''età della figlia maggiore.$B$BAscolta, $N: questa storia è più grande di quanto non sembri... non possiamo bruciare il diario.', 0),
(12425, 'itIT', 'Cerchi una conoscenza al di fuori della tua portata, per questo sei qui. Devo avvisarti, straniero, le risposte che ti darò potrebbero non piacerti.', 0),
(12436, 'itIT', 'Ottimo lavoro, $N. Ognuno di questi prezzi di carne sfamerà due o tre Grunt. Niente male davvero.', 0),
(12438, 'itIT', 'Bel lavoro, $N. Avvertirò Illusia che un eroe ha risposto al suo appello e ha portato a termine l''incarico! Ecco la tua ricompensa.', 0),
(12441, 'itIT', 'Ottimo lavoro, $N! Avvertirò Drolfy che un''eroina ha accettato l''incarico e che Zampatroce è morto!', 0),
(12442, 'itIT', 'I piani malvagi della Furia Scarlatta subiranno un brusco rallentamento. Hai reso un grande servizio a Guardia Invernale, $N.', 0),
(12447, 'itIT', 'Mi sorprende che tu sia venuta ad aiutare un Drago Nero e che sia ancora viva dopo aver parlato con Nalice.$B$BLe sue parole sono piene di veleno, ma immagino che la Lega dei Draghi sia in grado di tenere sotto controllo anche la nostra razza ogni tanto.$B$BO forse sono solo gli eserciti dello Stormo Rosso ammassati intorno a lei.', 0),
(12448, 'itIT', 'È un compito disgustoso, ma grazie per averlo portato a termine.$B$BNon possiamo permettere che il Flagello si spinga oltre fuori dal santuario o tutte queste terre verranno sopraffatte.', 0),
(12449, 'itIT', 'Nella terra, i miei fratelli potranno far sorgere una nuova vita. Li hai salvati da un destino assai peggiore della morte.$B$BNon so come esprimerti la mia gratitudine nella tua lingua, $r, ma sappi che apprezzo molto quello che hai fatto per me.', 0),
(12450, 'itIT', 'Hanno trasformato Dahlia...?$B$BDahlia ci è stata leale per molto tempo... se possono corrompere un essere con la sua dedizione, allora c''è poca speranza per le altre razze più giovani. Grazie per averla liberata. Spero possa trovare pace.$B$BOggi ci hai reso un grande onore, $r, aiutandoci in maniera disinteressata. Forse non tutti i membri dell''Orda hanno il cuore malvagio come quello dei nostri antenati. Avvertirò il concilio di ciò che la tua razza ha fatto qui.', 0),
(12453, 'itIT', 'Grazie, $N. Ti sono molto grata per il tuo aiuto.', 0),
(12454, 'itIT', 'Non dispiacerti per il ruolo che hai avuto nel ciclo della vita. Nascita, morte e rinascita fanno tutte parte dell''ordine naturale.', 0),
(12455, 'itIT', 'Appena in tempo! Alcuni dei miei soldati si sono diretti nelle cripte a est e a ovest di qui. Inutile dire che sono stati subito sopraffatti dai Ghoul Decerebrati. Dobbiamo salvare i superstiti!', 0),
(12456, 'itIT', 'Non piangere per Alystros. Ha dedicato tutta la sua esistenza eterna a difendere il Santuario dei Draghi di Smeraldo e rinascerà.$B$BSpero che quando tornerà da noi non cadrà vittima della confusione dell''Incubo di Smeraldo che pare essersi impossessata della Sognatrice.', 0),
(12457, 'itIT', '$N, era dai tempi di Silitus che non vedevo un simile atto d''eroismo!$B$BMi assicurerò che ciascuno di quei soldati metta una buona parola con Ser Domadraghi per farti ottenere una promozione!$B$BOra pensiamo a faccende più urgenti: secondo dei rapporti ricevuti dai nostri esploratori, Thel''zan non sarebbe lontano.', 0),
(12458, 'itIT', 'Anche adesso riesco a sentire l''impulso della natura dentro questi semi.$B$BDobbiamo farne buon uso!', 0),
(12459, 'itIT', 'Eccellente. Proprio come ho sempre sospettato. Devo provare a mettermi in contatto con Ysera per ottenere la sua approvazione.$B$BSempre se riusciamo a liberarla dal suo incubo.$B$BGrazie, $N. Il tuo aiuto è stato indispensabile.', 0),
(12460, 'itIT', 'Ti manda l''Ambasciatrice Lauriel?$B$BSe dovessi parlare di nuovo con lei, dille che apprezziamo molto il suo aiuto. Siamo impegnati a combattere su troppi fronti.', 0),
(12461, 'itIT', 'Ti manda l''Ambasciatore Golluck?$B$BSe dovessi parlare di nuovo con lui, digli che apprezziamo molto il suo aiuto. Siamo impegnati a combattere su troppi fronti.', 0),
(12462, 'itIT', 'Questo dovrebbe dare un po'' di tempo ad Ambo per sistemare le cose.', 0),
(12468, 'itIT', 'È Krenna che ti manda? Si vede che non le stai molto simpatico. Ma, d''altra parte, chi è che le sta simpatico?$B$BNeutralizzare questo avamposto dei Vrykul sarà un lavoro molto, molto duro.', 0),
(12471, 'itIT', 'Grazie, $N. Hai dimostrato grande benevolenza nei confronti del mio clan.', 0),
(12481, 'itIT', 'Ottimo lavoro. Quel povero diavolo non ha nemmeno capito cosa stesse accadendo.', 0),
(12483, 'itIT', 'Oh, cumpà... Stufato di Scintillacorone! Riesco quasi a sentirne il sapore...', 0),
(12484, 'itIT', 'Non c''è niente di più bello che guardar bruciare il Flagello... hic!$B$BHo scritto una piccola canzone su questo argomento. Vuoi sentirla? Fa più o meno così...', 0),
(12486, 'itIT', 'Il Mistico ha saputo? Dici che ha sentito che qualcosa di terribile è accaduto al Chiaroveggente Passo Tetro?$B$BProprio come temevo!', 0),
(12487, 'itIT', 'Tu chi sei?$B$BDammi un buon motivo per il quale non dovrei ucciderti all''istante!', 0),
(12488, 'itIT', 'Ti manda il Martello di Agmar? Era ora!$B$BNo, non sono io ad avere bisogno d''aiuto, è solo che non ho nessun altro da mandare. Ci penserai tu.', 0),
(12491, 'itIT', 'Questa è la bevanda di Coren Birranera? La birra che ha tentato disperatamente di presentare alla Festa della Birra? Be''... ufficialmente non possiamo accettare la richiesta ma, in segno di rispetto per un birraio deceduto, magari ne berrò un sorso...', 0),
(12492, 'itIT', 'Finalmente Birranera ha iscritto la sua birra. Peccato sia dovuto morire per riuscirci...$B$BOh, be''... Un brindisi alla sua memoria?', 0),
(12503, 'itIT', 'Apprezziamo il tuo aiuto. Non fosse stato per te, non saremmo riusciti a respingere l''assalto dei Senza Vita.', 0),
(12520, 'itIT', 'Bene, bene, bene. Sembra che tu sia sopravvissuto ai rinocorni. E senza troppi problemi, se posso dirlo. Ma la caccia al rinocorno è ben altro che fissarlo negli occhi mentre ti carica e sperare di centrare il bersaglio. No, ti servirà ben altro per affrontare il loro patriarca che si vocifera viva nella giungla.', 0),
(12522, 'itIT', 'Là... Appoggialo là. Fai attenzione! Se rovini anche questo, saremo in grossi guai. Vediamo cosa riesco a fare.', 0),
(12523, 'itIT', 'Dovrebbe bastare qualche modifica. La mia povera macchina volante, però, finirà per assomigliare più a un Segatronchi della S.P.R. & Co. La poverina dovrà aspettare fino al nostro ritorno a Dalaran prima di poter tornare alla sua forma originale.', 0),
(12524, 'itIT', 'Questo dovrebbe rallentare le loro attività, ma temo che il caposquadra farà arrivare altri operai. Dobbiamo portare a termine il lavoro finché possiamo.', 0),
(12525, 'itIT', 'Che sollievo sapere che la S.P.R. & Co. non c''infastidirà più. Hai la gratitudine mia e di Hemet per aver risolto questo problema. In tutta coscienza, un $C non può puntare l''arma contro un''altra persona.', 0),
(12526, 'itIT', 'Cosa ti porta al santuario di Rahm?', 0),
(12528, 'itIT', 'Sei il nuovo schiavo?$B$BBene. Ne avevamo giusto bisogno.', 0),
(12529, 'itIT', 'Goregek mostra allo sciocco schiavo $r come si fa.', 0),
(12549, 'itIT', 'Be'', hai dimostrato di essere un abile $C, ma come te la cavi come braccatore?', 0),
(12551, 'itIT', 'Notevole, $c. Sei sicuro di non far parte della spedizione?$B$BNo, ne sono certa. Avresti sicuramente fatto qualche battuta sul naufragio.', 0),
(12558, 'itIT', 'Che magnifica pelliccia, degna di un animale tanto nobile! Mi rincuora sapere che le voci su Shango erano vere, $N. Hai braccato alla perfezione la creatura. Sei un vero $C.', 0),
(12561, 'itIT', 'Molto bene, $r. Sono contenta che tu non sia un seguace del Re dei Lich... Forse, c''è davvero qualcosa che puoi fare per noi.', 0),
(12566, 'itIT', 'Nanik ha finalmente trovato qualcuno che ci possa aiutare! Dimmi, $N, come hai fatto ad arrivare fin qui senza di lui? Nessuno conosce questa terra meglio dei Taunka.', 0),
(12584, 'itIT', 'Non senti il puro male che emana?$B$BDobbiamo usare le conoscenze e le magie a nostra disposizione, insieme al potere della Luce Sacra, per squarciare il velo di malvagità che circonda questo minerale maledetto. Dobbiamo capirne l''origine.$B$BSbrigati, dammi la saronite!', 0),
(12589, 'itIT', 'Non spari male, ma migliorerai con l''esercizio. Cosa ne dici di fare una piccola scommessa?', 0),
(12595, 'itIT', 'Quindi il vecchio Hemet non si era dimenticato di me. Immagino vorrà partecipare alla caccia una volta che noi avremo fatto tutto il lavoro sporco. Non preoccuparti, ci sono parecchi drachi qui in giro. Hemet sarà accontentato.', 0),
(12596, 'itIT', 'Era ora che riportassi qui la tua carcassa! Pensavo che ti avessimo perso contro il Flagello... non che sarebbe stata chissà quale perdita.$B$BSe vuoi continuare a servire la Crociata è meglio che ti impegni di più. Molto di più.$B$BPrendi nota, $r! I tuoi futuri turni di pattuglia saranno ricompensati in base al tempo impiegato.$B$BPuoi andare.', 0),
(12603, 'itIT', 'Sento fiducia nelle tue parole. Bene, l''esperienza tornerà utile quando affronteremo la Regina dei Drachi.', 0),
(12605, 'itIT', 'Ah, ben fatto. Abbiamo molti esemplari per Frizzalampo!', 0),
(12607, 'itIT', 'Perfetto! Ora, dobbiamo solo trovare una scaletta per Hemet...', 0),
(12608, 'itIT', 'I viventi... servono spontaneamente il Re dei Lich?$B$BPer tutto questo tempo ho cercato il nemico sbagliato, $r. Sbrighiamoci e scacciamo i cultisti da queste terre.', 0),
(12611, 'itIT', 'Continui a dimostrare il tuo valore, $N. Forse ti ho giudicato troppo frettolosamente.$B$BHo supposto che fossi qui con i bracconieri che sono giunti recentemente nelle mie terre, ma forse ti sei già lasciata alle spalle quegli avvenimenti.', 0),
(12617, 'itIT', 'Dici il vero. Gli invasori all''accampamento sono morti... Ma temo sia troppo tardi.', 0),
(12619, 'itIT', 'Bel lavoro, $N. Hai creato la tua prima Arma Runica. Essa ti consentirà di spargere caos e distruzione al tuo passaggio, lasciando a terra i cadaveri di tutti coloro che osano opporsi al Flagello.', 0),
(12620, 'itIT', 'Notevole. Non mi aspettavo che una semplice mortale si dimostrasse un''alleata tanto valida.$B$BTemo, tuttavia, che i nostri sforzi non siano stati sufficienti. Il Flagello non dà segno di volersi fermare.', 0),
(12621, 'itIT', 'Non possiamo più tornare indietro. Se sei d''accordo ad aiutarmi, devi farlo senza esitare.', 0),
(12624, 'itIT', 'Ce l''hai fatta! L''hai trovato davvero!$B$BNon so... Non so come ringraziarti!', 0),
(12630, 'itIT', 'Sai, mi ricordi moltissimo il mio Nass.$B$BForse per via del naso...', 0),
(12634, 'itIT', 'Be'', è meglio di quanto mi aspettassi da questo posto. Ora, la domanda fondamentale: riusciremo a distillare qualcosa di bevibile? Meglio darsi da fare.', 0),
(12637, 'itIT', 'Ora conosci la fine che qualcuno voleva farti fare.$B$BCome ti ho detto prima, il fatto che lo abbia trovato tu non è un caso. Creare un oggetto simile è molto difficile e nessuno sprecherebbe tante risorse per colpire un obiettivo casuale.$B$BC''è solo una possibile spiegazione: il Flagello vuole eliminarti...', 0),
(12638, 'itIT', 'Ora conosci la fine che qualcuno voleva farti fare.$B$BCome ti ho detto prima, il fatto che lo abbia trovato tu non è un caso. Creare un oggetto simile è molto difficile. Devi avere attirato l''attenzione dei Comandanti del Flagello.$B$BLa questione non è come, perché o chi... Ora dobbiamo solo capire come muoverci.', 0),
(12641, 'itIT', 'Si preparano alla battaglia, come previsto, ma c''è dell''altro. Avverto la presenza di un vecchio nemico, uno che ho annientato parecchio tempo fa...$B$BNon importa. Scateneremo tutta la potenza del Flagello prima che possano evacuare le loro case e organizzare le difese.', 0),
(12645, 'itIT', 'Due assaggiatori su tre sono d''accordo, eh? Non male come inizio. Davvero non male. Immagino che dovremo inventarci qualcosa per scusarci con Tamara.$B$BMmm... Come potrei chiamare questa creazione?', 0),
(12651, 'itIT', 'Quindi, ti manda Hemet? Stavamo per informarlo che qui è tutto a posto. Scusa se Marvin sembra ignorarti, ma si fa prendere molto dal lavoro.', 0),
(12654, 'itIT', 'Hai i Resti di Nerone! Ora, non mi resta che farne un trofeo. Sarà la parte difficile: trovare un modo per conservarli in modo che Hemet non si faccia una grassa risata a mie spese.', 0),
(12657, 'itIT', 'I corni di guerra presto risuoneranno lungo questa terra, risvegliando i morti e richiamando la macchina da guerra del Flagello. Guai a coloro che oseranno intralciare il nostro cammino!$B$BTu e i tuoi fratelli guiderete l''attacco, $N. La prossima volta che poserò il mio sguardo sulle Terre Scarlatte, voglio che la mia vista sia oscurata dalle legioni di Acherus. La marcia su Nuova Avalon comincia adesso.', 0),
(12658, 'itIT', 'Oh, come sono belle! Mi sono stufato di avere solo scoiattoli e polli meccanici a farmi compagnia. Sarà favoloso avere un cucciolo che non deve essere oliato!', 0),
(12660, 'itIT', 'Ti ringrazio, $r. Ti stai dimostrando una valida alleata.', 0),
(12671, 'itIT', 'Mi hai salvato la vita, lassù. Così si vola!', 0),
(12678, 'itIT', '$N, la senti anche tu quella sensazione di potere che scorre nel tuo corpo? I mortali non sono in grado di provare una cosa simile.$B$BLa prima linea ora è smantellata. Il Geist completerà l''opera e preparerà il terreno per Razuvious. Ora ci concentreremo su obiettivi più tattici.', 0),
(12680, 'itIT', 'Ora ti attende la vera sfida. Riuscirai a domare un Nerodestriero Selvaggio e ottenere con la forza ciò che desideri di più?', 0),
(12688, 'itIT', 'Grazie per aver liberato Helice e averla riportata sana e salva. Ci siamo preoccupati tutti quando non è tornata dalla sua ricerca di cristalli.', 0),
(12696, 'itIT', 'Ti manda la professoressa? Molto bene.', 0),
(12698, 'itIT', 'Ora che sanno che le miniere non sono più sicure, raddoppieranno i loro sforzi nella ritirata, lasciando le spalle scoperte ai nostri attacchi!', 0),
(12701, 'itIT', 'L''intera Flotta Scarlatta è stata spazzata via nel giro di pochi minuti! Riceverò un encomio dal Re dei Lich per questo! Ora tutto ciò che resta della Crociata Scarlatta sono gli abitanti di Nuova Avalon.$B$BInvierò subito i piromani e i negromanti a Borgorado, mentre tu consegnerai il mio rapporto al Gran Signore!', 0),
(12702, 'itIT', 'Sei bravo.$B$BForse un giorno buttiamo Goregek nel fiume così non dovrai più prendere le galline.', 0),
(12703, 'itIT', 'Il rituale è stato facile per te!$B$BTorna per uccidere ancora!', 0),
(12704, 'itIT', 'Tanti oggetti luccicanti! Sei bravo.$B$BMagari, dopo torni per trovarne altri?', 0),
(12705, 'itIT', 'Soo-Holu è forte, vero? Sono contento che ti abbia accettato per condividere il suo corpo nella battaglia.$B$BSi fida di più delle persone che ha già incontrato, quindi potresti tornare ad aiutarci ancora, eh?', 0),
(12707, 'itIT', 'Cumpà, uno a zero per le vittime!', 0),
(12709, 'itIT', 'Ma guarda accà!$B$BAmmira, $N. Chisto piezzo che hai recuperato mostra chiaramente che i Drakkari erano coscienti dell''indebolimento della terra causato della presenza del Flagello.$B$BIl Signore della Guerra si è sentito obbligato a sfruttare l''occasione che si è presentata a isso. Ha spinto i Profeti ad accidere li dei per tentare di pigliarne il potere, così da affrontare le forze del Re dei Lich.$B$BErano condannati in ogni caso, ma hanno scelto di diventare lo strumento della distruzione loro.', 0),
(12712, 'itIT', 'Sarebbe stato meglio che ti avessi inviato direttamente a Gundrak, invece di farti tornare qui.$B$BComunque, credo che ti tornerà utile sentire ciò che ho da dirti.', 0),
(12714, 'itIT', 'Borgorado è nostra! Migliaia di cadaveri sono sparsi a terra, in attesa di rinascere. Ora attaccheremo il nostro nemico con la rinnovata forza del Flagello!$B$BI Ghoul hanno già iniziato il loro assalto su Nuova Avalon seguiti dalle nostre forze, che hanno preso la Cripta della Rimembranza.', 0),
(12716, 'itIT', 'Perfetto! Ora dammi un momento per preparare ogni cosa.', 0),
(12717, 'itIT', 'Il Calderone della Piaga prende vita non appena i teschi vengono gettati al suo interno.$B$BDopo pochi secondi, alcune fiale di liquido oscuro galleggiano in superficie.', 0),
(12718, 'itIT', 'Il Calderone della Piaga prende vita non appena i teschi vengono gettati al suo interno.$B$BDopo pochi secondi, la scura e schiumosa Mistura Speciale di Noth è pronta.', 0),
(12721, 'itIT', 'No!$B$BNu altro dio distrutto e il potere suo rubato. E mo'' il Profeta di Akali ci minaccia direttamente.$B$BQuando verrà, lo farà per Har''koa. Nun permetteremo a isso di pigliare il potere suo.$B$BDobbiamo parlare n''altra volta con li dei, $N, che ci diranno cosa fare.', 0),
(12722, 'itIT', 'Ci sai fare con quell''arma, $N. Forse, Re dei Lich permettendo, potresti diventare uno dei miei vassalli. Che ne dici? Stratholme ha bisogno di un nuovo sindaco.', 0),
(12723, 'itIT', 'Pare che al giorno d''oggi lascino entrare chiunque nell''ordine oscuro. Ai miei tempi le cose erano molto diverse!$B$BRiguardo a questo corriere...', 0),
(12726, 'itIT', 'Ti sono grato, $N. Grazie a te, godiamo ancora dei favori della grande tempesta.', 0),
(12728, 'itIT', 'Ottimo! Ora il mio rapporto può considerarsi completo.$B$BSarà mia cura menzionare la tua disponibilità al consiglio, $N.', 0),
(12729, 'itIT', 'Sembra che la tua audacia non abbia limiti, $N.$B$BTi prego di darmi il cuore e l''essenza e io li combinerò costringendo il Profeta a manifestarsi di fronte a noi.', 0),
(12730, 'itIT', 'Ce l''hai fatta, $N! Sei la Campionessa di Zul''Drak!$B$BNon potremo mai ripagare completamente il debito che abbiamo contratto con te, ma gli Zandalari mi hanno dato alcuni oggetti che potrebbero interessarti.$B$BTi prego di accettare questo segno di apprezzamento. Sbrigati, perché sento di nuovo che ci sono dei guai in arrivo.', 0),
(12734, 'itIT', 'Rejek vede le macchie di sangue dei nemici sulla lama. Ora, Rejek ha una possente arma per diventare un grande $C!', 0),
(12738, 'itIT', 'Sono solo carne e ossa, non possono nulla contro il Flagello.$B$BNon abbiamo trovato altri nostri fratelli, ma ci siamo imbattuti in qualcosa di speciale.', 0),
(12741, 'itIT', 'Ora Rejek mostra alle codarde lingue grandi come usare gli elementi!', 0),
(12742, 'itIT', 'È una bella sensazione, vero? Tu non sei più uno di loro, $N. Ora appartieni al Flagello, per sempre...', 0),
(12743, 'itIT', 'È una bella sensazione, vero? Tu non sei più una di loro, $N. Ora appartieni al Flagello, per sempre...', 0),
(12745, 'itIT', 'È una bella sensazione, vero? Tu non sei più uno di loro, $N. Ora appartieni al Flagello, per sempre...', 0),
(12748, 'itIT', 'È una bella sensazione, vero? Tu non sei più uno di loro, $N. Ora appartieni al Flagello, per sempre...', 0),
(12751, 'itIT', 'Un''altra vittoria per il Flagello! Questi cani Scarlatti non potranno sfuggirci, né nascondersi. È solo questione di tempo ora...', 0),
(12758, 'itIT', 'Rejek vede che l''impresa è riuscita. Ora, Rejek proverà il suo nuovo elmo da guerra.', 0),
(12759, 'itIT', 'Con le trappole, sei quasi bravo come Zepik!', 0),
(12760, 'itIT', 'Sei un combattente; feroce... Torna presto per altre battaglie. Non bastano mai!', 0),
(12761, 'itIT', 'Grazie, pelleasciutta.$B$BTerrò i cristalli così saremo al sicuro. Magari, torna presto e aiutaci ancora.', 0),
(12762, 'itIT', 'Quanta energia in te... Sei pieno del potere dei Grandi!$B$BSono sincero, sono un po'' invidioso.', 0),
(12766, 'itIT', 'Tu devi essere $N. Ero stata avvertita del tuo arrivo.$B$BHo un incarico di cui solo tu puoi occuparti e portarlo a termine ti permetterà di entrare nelle grazie dei draghi locali.', 0),
(12767, 'itIT', 'Tu devi essere $N. Ero stato avvertito del tuo arrivo.$B$B$B$BHo un incarico di cui solo tu puoi occuparti e portarlo a termine ti permetterà di entrare nelle grazie dei draghi locali.', 0),
(12768, 'itIT', 'Già di ritorno, $N?$B$BCeristrasz mi aveva avvertito del tuo arrivo. Grazie per quello che hai fatto al Santuario dei Draghi di Rubino.', 0),
(12769, 'itIT', 'Già di ritorno, $N?$B$BVargastrasz mi aveva avvertito del tuo arrivo. Grazie per quello che hai fatto al Santuario dei Draghi di Rubino.', 0),
(12789, 'itIT', 'Eccellente. Valus deve aver ricevuto il mio rapporto.$B$BMettiamoci al lavoro, $r.', 0),
(12790, 'itIT', 'Ottimo, $c. Ora sai come scendere alla Foresta di Cristallo e anche come tornare.', 0),
(12791, 'itIT', 'Benvenuto a Dalaran.$B$BFarò in modo che l''anello sia restituito.', 0),
(12792, 'itIT', 'Il mio rapporto deve essere arrivato nelle mani di Kunz.$B$BSono felice di sapere che sta bene.', 0),
(12794, 'itIT', 'Benvenuto a Dalaran.$B$BFarò in modo che l''anello sia restituito.', 0),
(12795, 'itIT', 'In effetti... c''è qualcosa che puoi fare per renderti utile, $c.', 0),
(12800, 'itIT', 'Il Gran Signore e gli altri Cavalieri della Morte si stanno preparando ad attaccare! Elimineremo le ultime forme di vita da questo posto.', 0),
(12801, 'itIT', 'Non ci sarà alcuna espiazione per noi, $N. Siamo condannati a vagare sulla terra come mostri. Anche se la morsa del Re dei Lich si è allentata, gli spettri del nostro passato tormenteranno i nostri ricordi in eterno.$B$BDobbiamo riparare nell''unico modo che conosciamo: la morte...$B$BTi chiedo di unirti a me ad Acherus come Cavaliere della Spada d''Ebano. Insieme annienteremo il Re dei Lich e metteremo fine al Flagello.', 0),
(12802, 'itIT', 'Impressionante, cumpà! Il destino è stato magnanimo a farci incontrare.$B$BPresto vendicherò i fratelli miei, purificando Drak''Tharon... e tu riceverai il più grande tesoro suo.', 0),
(12803, 'itIT', 'Non appartieni a questa terra, ma non segui il Flagello.$B$BCosa devo pensare di te?', 0),
(12804, 'itIT', 'Questo sì che è un pasto come si deve! L''unica cosa positiva del naufragio è che non siamo stati costretti a mangiare carne essiccata per un mese! Grazie ancora, $N.', 0),
(12805, 'itIT', 'Ti ringrazio, $N. È una sventura che il pilastro sia crollato, ma abbiamo salvato ciò che potevamo.', 0),
(12806, 'itIT', 'Era ora, dannazione! Il Barone Sliver se l''è presa comoda a mandarti qui.$B$BAvrei dovuto tagliare quella zucca vuota che ha fra le spalle!', 0),
(12807, 'itIT', 'Nella sua follia, la Crociata d''Argento ha scelto di chiudere un occhio sulla presenza della Furia Scarlatta. Noi non commetteremo lo stesso errore.$B$BNon ci interessa se contribuisce alla battaglia contro il Re dei Lich: a nostro parere, non è degna di esistere. La stermineremo una volta per tutte!', 0),
(12815, 'itIT', 'Chisto è lo spirito giusto! Terrei bisogno che tu ripetessi l''impresa ogni giorno che staremo accà.$B$BSpero di rivederti domani. Il Grifone d''Ossa tuo ti aspetterà.', 0),
(12818, 'itIT', 'Questi andranno bene... Grazie!$B$BHai per caso visto Dim? L''ho mandato in missione tempo fa e non è mai tornato. Spero stia bene.$B$BA proposito... chissà dov''è Janks...', 0),
(12819, 'itIT', 'Ah ah! Eccoli! Ti ringrazio. Spero che tu non abbia avuto troppi problemi ad attraversare il campo.', 0),
(12820, 'itIT', 'Me ne stavo qui... a crogiolarmi nella mia magnificenza, e a un certo punto odo un colpo in lontananza! Poi un altro! E poi un''altra decina! E sul mio volto è apparso un sorriso al pensiero di tutti quei Magnatauri e Neboldi che si gettavano da soli tra le braccia della morte.$B$BFantastico, vero?', 0),
(12822, 'itIT', 'Ahahah! Così quei bruti impareranno a farci perdere tempo. Da oggi in poi tutti i Magnatauri saranno terrorizzati dalla pelle verde!', 0),
(12823, 'itIT', 'Tutta la montagna ha tremato! È stato meraviglioso? Scommetto di sì! Come potrebbe essere il contrario?$B$BE poi la Lega dell''Intelletto dice che tutte le mie invenzioni non fanno altro che esplodere. Accidenti se lo fanno! Ah!', 0),
(12826, 'itIT', 'Allora, non sono gli strumenti di distruzione più belli che tu abbia mai visto?', 0),
(12827, 'itIT', 'Spero che non abbiano fatto troppe storie. Fino a ora siamo stati piuttosto accomodanti con loro quando prendevano i nostri avanzi.', 0),
(12828, 'itIT', 'Ed ecco fatto! A volte mi stupisco di me stessa.$B$BGrazie mille!', 0),
(12829, 'itIT', 'Ah ah! Mi fa piacere vedere che ami il lavoro sporco.$B$BOttimo, davvero!', 0),
(12830, 'itIT', 'Ma che puzza orrenda! Hai dovuto affrontare alcuni di quei Neboldi, vero?$B$BLo apprezzo molto!', 0),
(12831, 'itIT', 'Dovrebbe andare... spero che Ricket riesca ad aiutarmi. Ce ne andiamo, allora?', 0),
(12832, 'itIT', 'Grazie per averci riportato il nostro minatore, $N! Dovrei riuscire senza problemi a preparare un antidoto.$B$BSe incontri di nuovo Tore, dille che con me ha chiuso. Va bene?', 0),
(12833, 'itIT', 'Mi piaci. A dirla tutta... sei grande!$B$BUrrà per te!', 0),
(12836, 'itIT', 'Eccellente!Sei proprio il tipo di $r che piace a me.', 0),
(12838, 'itIT', 'Dammele. Filtrerò quelle inutili e ti chiamerò se avrò trovato qualcosa di rilevante.$B$BIn ogni caso, torna domani: sappiamo che cambiano i loro piani ogni giorno.', 0),
(12843, 'itIT', 'Ce l''hai fatta! I nostri ragazzi sono tornati!', 0),
(12844, 'itIT', 'Grazie, $N! Cercheremo di riutilizzare al meglio queste parti!', 0),
(12846, 'itIT', 'Di sicuro non stai con le Hyldnir... allora che ci fai qui? Ah... stai cercando il nuovo prigioniero!', 0),
(12848, 'itIT', 'Il mio Cavaliere scelto ha trionfato. Non avevo dubbi! Sei pronto $N.', 0),
(12859, 'itIT', 'Strano, so che hai spento il fuoco, ma il fuoco brucia ancora. Magari questo coso non è buono come sembra? Moky ti pagherà comunque per quello che hai fatto. Spero che brucino anche i Troll!', 0),
(12861, 'itIT', 'Malartiglio ti ringrazia, $N. Anche se il Covo dei Malartiglio è perso per sempre e l''amicizia tra i Troll e i Malartiglio è persa per sempre... ora che ci penso, anche Mantorabbioso è perso per sempre. Anche cognato. Andato. Hai visto la compagna di Capo? Anche lei andata.$B$BMeglio che tu vai. Capo è triste.', 0),
(12870, 'itIT', 'Fantastico! Sei in gamba.$B$BScoliamoci una pinta! Festeggiamo questa grande scoperta!', 0),
(12887, 'itIT', 'Forse ora possiamo fare davvero qualcosa. Però non lasciarti ingannare: il Re dei Lich può ancora "vedere" attraverso i suoi servitori del Flagello.$B$BÈ per questo che sei qui.', 0),
(12891, 'itIT', 'Presto, dammi i componenti e sparisci!$B$BA cosa servono la verga, il gancio e la fune è abbastanza evidente, una volta uniti. Devo solo infondere le Essenze e saremo pronti per procedere.$B$BLa creazione è molto semplice, ma l''utilizzo è fenomenale!', 0),
(12892, 'itIT', 'Forse ora possiamo fare davvero qualcosa. Però non lasciarti ingannare: il Re dei Lich può ancora "vedere" attraverso i suoi servitori del Flagello.$B$BÈ per questo che sei qui.', 0),
(12893, 'itIT', 'Faremo buon uso di quei tre, quando finalmente avremo catturato la Volta.$B$BA proposito...', 0),
(12895, 'itIT', 'Certo, con la nostra fortuna dovevo immaginarlo. Be'', non ce lo faremo sfuggire così facilmente. Vediamo cosa dice quel biglietto.', 0),
(12896, 'itIT', 'Hai sconfitto il Generale Lucemesta e le sue armate? La Volta dell''Ombra è stata conquistata?', 0),
(12897, 'itIT', 'Hai sconfitto il Generale Lucemesta e le sue armate? La Volta dell''Ombra è stata conquistata?', 0),
(12898, 'itIT', 'Per fortuna sei tornato: come puoi vedere, siamo piuttosto impegnati.', 0),
(12899, 'itIT', 'Per fortuna sei tornato: come puoi vedere, siamo piuttosto impegnati.', 0),
(12901, 'itIT', 'È solo spazzatura inutile! È completamente inutile! Il metallo del Flagello non ci serve a niente. Ora cosa facciamo?', 0),
(12902, 'itIT', 'C''è una pergamena che fluttua sopra a uno strano altare. Deve essere ciò che sta cercando il Signore dei Crociati Lantinga.', 0),
(12903, 'itIT', 'Quei tre hanno compiuto un grande sacrificio. Non lo dimenticheremo. La loro morte non sarà vana. Vinceremo!', 0),
(12909, 'itIT', 'E così Boktar ha reclutato Gelo per una missione, eh? Be''... è meglio che sia una cosa importante. Sa che non è bene separare un cacciatore dal proprio animale!', 0),
(12932, 'itIT', 'Nun sei affatto male, cumpà. Farai dei soldi, se riuscirai a nun schiattare.', 0),
(12933, 'itIT', 'Caspita! Quando ho visto Barbalercia, ho pensato che fossi spacciato. Ben fatto!', 0),
(12934, 'itIT', 'Incredibile! Quando isso è apparso credevo che il posto sarebbe scoppiato! Hai dominato l''incontro!', 0),
(12935, 'itIT', 'Ho tenuto nu poco di paura, cumpà. Quando sono arrivate le foche e i pinguini... be'', in tutta onestà nun sapevo cosa pensare! Pareva assai ridicolo!', 0),
(12936, 'itIT', 'Conobbi Korrak quando ero nu guaglione e faticavo per il Clan Lupi Bianchi. Nun s''azzittiva mai! Penso che tu abbia appena reso nu grande servizio al mondo, $N.', 0),
(12938, 'itIT', '$N! È un piacere conoscerti, finalmente. Ti dobbiamo molto, ma abbiamo ancora bisogno di te.$B$BC''è una città dei Vrykul appena al di là delle montagne a ovest: Jotunheim.$B$BI suoi abitanti sono impegnati in una costante sfida di "ascensione". I vincitori vanno a Ymirheim per servire come Ymirjar, le truppe scelte del Re dei Lich, mentre i perdenti vengono trasformati in Vargul Piagati.$B$BSarai il mio strumento per fare in modo che emergano più Vargul che Ymirjar.', 0),
(12939, 'itIT', 'Già mi arrivano voci sul valore che hai dimostrato alla Sporgenza Crudele. Eccellente, $N... davvero eccellente!$B$B$B$BÈ arrivato il momento di emettere un decreto contro il Thane dei Vrykul che hai sconfitto così facilmente.', 0),
(12948, 'itIT', 'Ce l''hai fatta, $N! È stato lo scontro più bello di sempre! Cosa ci farai con chello che hai vinto? Io? Io me ne andrò a Dalaran, nei Sotterranei. Lì ci stanno nu sacco di cose da fare!', 0),
(12949, 'itIT', 'Grazie, $r. Dammi la chiave, faccio da solo.', 0),
(12951, 'itIT', 'Che cosa?!? Non possiamo permetterci di perdere UN Cavaliere della Morte, figuriamoci un intero contingente!!!', 0),
(12954, 'itIT', 'Ué, ma io ti conosco. Si è parlato per mesi delle vittorie tue al Circolo del Sangue! Nu peccato che tu abbia perso il titolo nun presentandoti per difenderlo! La fortuna viene e va, vero? Almeno sei ancora vivo.', 0),
(12955, 'itIT', '$N, hai compiuto una missione molto importante. Scacciandoli, hai impedito loro di interferire con ciò che dovremo chiederti di fare laggiù.', 0),
(12958, 'itIT', 'Ecco l''Emblema dell''Orefice di Dalaran, come promesso. Torna domani, sicuramente avrò ancora bisogno di te!', 0),
(12959, 'itIT', 'Ecco l''Emblema dell''Orefice di Dalaran, come promesso. Torna domani, sicuramente avrò ancora bisogno di te!', 0),
(12961, 'itIT', 'Ecco l''Emblema dell''Orefice di Dalaran, come promesso. Torna domani, sicuramente avrò ancora bisogno di te!', 0),
(12962, 'itIT', 'Ecco l''Emblema dell''Orefice di Dalaran, come promesso. Torna domani, sicuramente avrò ancora bisogno di te!', 0),
(12978, 'itIT', 'Forse c''è una speranza di vittoria, $N. Non siamo mai riusciti a sferrare un attacco ai Forgiatuono ma, grazie ai tuoi sforzi, Valduran potrebbe cadere!', 0),
(12979, 'itIT', 'Ora fa'' attenzione. Tieni quella piastra il più lontano possibile da me. Già la sola presenza è sufficiente a farmi del male.$B$BMa hai ragione, $N, sono piastre giganti rispetto alle dimensioni normali di un Golem da Guerra. Cosa ci facevano i Forgiatuono? C''è un solo modo per scoprirlo.', 0),
(12982, 'itIT', 'Grazie, $c. I Cavalieri della Morte che hai liberato ci permetteranno di mantenere la posizione... per ora.', 0),
(12984, 'itIT', 'Finalmente, Valduran è morto e i Forgiatuono si sono indeboliti; ma se ha detto la verità, dobbiamo continuare a combatterli anche se lui non c''è più. L''arma che stanno costruendo potrebbe rappresentare la nostra fine.', 0),
(12988, 'itIT', 'Ottimo lavoro! Oh, non fermerà i Nani del Ferro, ma impiegheranno molto tempo a ricostruire quelle forge. Oserei dire che siamo passati in vantaggio.', 0),
(12991, 'itIT', 'Un tempo non avrei mai potuto chiedere a nessuno di fare ciò che hai fatto tu oggi, ma la mia esperienza con i Nani del Ferro ha cancellato quei sentimenti. Abbiamo rallentato i progressi del nemico.', 0),
(12992, 'itIT', '$N è il migliore $r che ci sia!', 0),
(12995, 'itIT', 'Ben fatto, $N! Lasciamo che scoprano i cadaveri profanati dei loro compagni caduti, così ci penseranno due volte prima di attaccare!$B$BSe tornerai anche domani, ti farò avere altri Stendardi.', 0),
(12998, 'itIT', 'Con il cuore in mano a Narvir, il Colosso agirà a piena potenza! Non avremo altra scelta che affrontarlo.', 0),
(12999, 'itIT', '$N, sei qui!$B$BHo sentito parlare delle tue imprese alla Sporgenza Crudele. Molto bene. Sono felice che tu abbia deciso di aiutarmi a indebolire i Vrykul qui a Jotunheim.$B$B$B$BIo e te ci divertiremo un sacco, con loro!', 0),
(13007, 'itIT', 'Ben fatto! Davvero ben fatto! Il rifugio è salvo e i Forgiatuono sono stati sconfitti! Dobbiamo avvertire Brann prima che Loken decida di ricostruire il suo esercito. L''unico modo che abbiamo per essere certi che la vittoria di oggi sia definitiva è andare a Ulduar e sconfiggere Loken una volta per tutte!', 0),
(13008, 'itIT', '$N, ci sono ancora molti soldati della Crociata d''Argento in quel campo e nei Bastioni del Flagello. Ti sono grato dell''aiuto, ma c''è tanto da fare.', 0),
(13036, 'itIT', 'La Crociata d''Argento è riuscita laddove Alleanza e Orda avevano fallito. Purtroppo, questo successo è stato di breve durata. Siamo penetrati rapidamente nella Corona di Ghiaccio... e altrettanto rapidamente siamo stati respinti con la forza.$B$BLa ritorsione del Re dei Lich è stata immediata e brutale. Ora siamo costretti sulla difensiva.', 0),
(13039, 'itIT', 'Ma quanti sono?!? Ne abbiamo uccisi abbastanza da riempire dieci cimiteri, ma continuano ad arrivare. Amico mio, la situazione è preoccupante.', 0),
(13040, 'itIT', 'Grazie, $N. Inizierò subito gli esperimenti su questi campioni. Spero di trovare presto una cura.', 0),
(13042, 'itIT', 'Molto interessante... Direi che hai portato a termine l''incarico alla perfezione. Mi sorprende che il dottore usasse un Vargul come assistente, vista la natura dei suoi esperimenti.', 0),
(13046, 'itIT', 'Fissando il dente nella mascella di Arngrim, hai l''impressione che i tuoi sforzi abbiano placato i morsi della fame del vecchio Re... per ora.', 0),
(13047, 'itIT', 'No... non è possibile...$B$BNessuno può sconfiggere Thorim in un duello. Né un gigante, né una bestia... nessuno! E specialmente quel codardo di suo fratello.$B$BLo giuro sul nome dei miei avi...$B$BLoken la pagherà!', 0),
(13059, 'itIT', 'Grazie, $c... grazie infinite!$B$BMi hai donato la soddisfazione di sapere che il codardo che mi ha fatto questo marcirà per tutta l''eternità come me.$B$BOra vattene, prima che perda il controllo e ti uccida.', 0),
(13068, 'itIT', 'Attenzione! Torna indietro! Sono stato colpito dalla piaga e non voglio contagiare nessuno.', 0),
(13069, 'itIT', '$N, sei veramente un campione!$B$BTorneresti a parlare con me domani? Sono certo che ci saranno altri maledetti Proto-Drachi da abbattere.', 0),
(13070, 'itIT', 'Dobbiamo fare in fretta o il Flagello ci schiaccerà! Davvero $r, non ho tempo per istruirti! Devi entrare in azione e sperare per il meglio.', 0),
(13071, 'itIT', 'Sì, sì! $N è il migliore ladro di Proto-Drachi.$B$BTorna qui domani, così facciamo altro fuoco!!!', 0),
(13072, 'itIT', 'Bridenbrad ha contratto la Piaga? Non riesco a pensare a un destino peggiore per uno che abbia dedicato la sua vita alla Luce. Eppure non posso lasciarlo morire senza sollevare un dito per aiutarlo.$B$BNo, non diverrà un Non Morto. Troveremo il modo di salvare l''eroe!', 0),
(13073, 'itIT', 'Salve.$B$BSo della richiesta di Tirion e mi fido del suo giudizio. Proveremo a fare qualcosa per il Crociato Bridenbrad. Ciò che chiedi non è facile: il Flagello non appartiene a questo mondo e, negli anni, molti hanno già tentato invano di estirpare la sua corruzione.$B$BCiononostante, nel caso di un essere nobile e votato alla Luce, c''è ancora speranza.', 0),
(13074, 'itIT', 'Ottimo lavoro, giovanotto.', 0),
(13075, 'itIT', 'Tirion ti ha inviato da Remulos? Sono... lusingato. Per quanto nobili e altruisti, non chiediamo mai favori a esseri tanto potenti. Anche tu sei stato molto gentile a fare tanta strada solo per me e di questo ti ringrazio.$B$BSono pronto: pianta il seme.', 0),
(13076, 'itIT', 'Mi rattrista apprendere che sia stato tutto inutile, ma non è ancora il momento di arrendersi: ho incontrato altri esseri benevoli che potrebbero aiutarci.', 0),
(13077, 'itIT', 'Ti saluto, $r.$B$BIl tuo volto tradisce un''enorme preoccupazione. Dimmi cosa ti turba.', 0),
(13078, 'itIT', 'Grazie alle Lacrime di Dahlia e all''antica magia, darò un po'' di speranza al tuo valoroso Crociato.', 0),
(13079, 'itIT', 'Il Soffio di Alexstrasza... Ti sei rivolto alla Regina dei Draghi in persona? Te ne sono estremamente grato.$B$BComprendo pienamente i rischi di questa purificazione e sono pronto. Procedi pure.', 0),
(13080, 'itIT', 'La piaga del Flagello non è un nemico facile da sconfiggere. Le parole di Alexstrasza mi fanno pensare che forse possiamo ancora salvare il nostro Bridenbrad dall''inconcepibile destino della Non Morte, qualora dovesse cedere. Eppure non mi sono ancora arreso!$B$BDeve esserci ancora un sentiero della Luce da percorrere, un altro essere che possa evitare quest''orribile fato.', 0),
(13083, 'itIT', 'Sono felice che tu sia riuscito a salvarlo da un destino da $R. Grazie alla benedizione di A''dal, il suo eterno riposo non sarà corrotto dal male.$B$BDobbiamo trarre ispirazione dal suo lucente esempio e dal tuo altruismo. Grazie per tutto quello che hai fatto.', 0),
(13085, 'itIT', '$N, credo di sapere perché sei qui.', 0),
(13086, 'itIT', 'Amico mio, usi il Cannone come un vero Artigliere Goblin! Hai salvato l''Avanguardia e la Crociata d''Argento, supportando sul campo di battaglia il Gran Signore in persona! Incredibile!', 0),
(13088, 'itIT', 'Questa sazierà gli stomaci di quelle reclute! Ora ti insegno a cucinarla.', 0),
(13090, 'itIT', 'Grazie mille.', 0),
(13091, 'itIT', 'Non ho mai visto tanto terrore negli occhi di un Vrykul. Si credono i padroni del mondo!$B$BIo e te dimostreremo che si sbagliano di grosso.', 0),
(13100, 'itIT', 'Sembra ottimo! Grazie!', 0),
(13101, 'itIT', 'C''è cibo in abbondanza per tutti! I miei clienti saranno sicuramente soddisfatti.', 0),
(13102, 'itIT', 'So già che andrà a ruba! Grazie!', 0),
(13103, 'itIT', 'Ah, un pasto da intenditori!', 0),
(13106, 'itIT', 'Bene, abbiamo bisogno di tutto l''aiuto possibile. Olakin è stato inviato qui dalla Crociata d''Argento. Ma ora basta con le chiacchiere e mettiamoci al lavoro: dobbiamo distruggere le armate di carne del Flagello.', 0),
(13107, 'itIT', 'Perfetto! Speriamo solo che i Distruttori di Dalaran vincano almeno questa!', 0),
(13110, 'itIT', 'Il cammino del Crociato timoroso è minacciato da ogni parte dalle iniquità e dalla tirannia dei malvagi. L''unica salvezza è non deviare dal cammino. Oggi hai fatto questo e molto, molto di più.', 0),
(13118, 'itIT', 'Ottimo lavoro, $N. Se manterremo basso il loro numero, la Crociata d''Argento avrà il tempo necessario per posare le fondamenta.', 0),
(13122, 'itIT', 'Vediamo se posso usare queste pietre per avere una visuale di ciò che succede.', 0),
(13124, 'itIT', 'Ascolta bene, $r.$B$BIl tuo lavoro qui è appena iniziato!', 0),
(13125, 'itIT', '$N, è stata una vittoria ottenuta a fatica! I Luogotenenti saranno rimpiazzati ma, almeno per oggi, ai Bastioni del Flagello non si muove una foglia.', 0),
(13126, 'itIT', 'Proprio come speravo, $r. Insieme formiamo una bella squadra.$B$BChe la nostra collaborazione possa permetterci di superare le sfide che ci attendono!', 0),
(13127, 'itIT', 'La vittoria è a portata di mano, amico mio.$B$BNon perdere la concentrazione: adesso arriva la vera sfida.', 0),
(13130, 'itIT', 'Il Cuordilegno resiste a malattie, usura e infezioni. Questo, nello specifico, riesce addirittura a respingerle! La Muratura, grazie a ciò che il Boscostile le fa cadere addosso, funzionerà più o meno allo stesso modo.$B$BPresto potremo iniziare i lavori.', 0),
(13131, 'itIT', 'Ottimo! Ce l''hai fatta, amico mio.$B$BOra posso farmi vedere dal Capitano senza rischiare la pelle. Grazie mille!$B$BEccoti un po'' di bottino come ricompensa.', 0),
(13132, 'itIT', 'Perfetto! Ora i miei compagni possono riposare in pace.$B$BPrendi questo, ragazzo. E che non si dica che il vecchio Brigg non è generoso con quelli che gli fanno dei favori.$B$BÈ bello fare affari con te.', 0),
(13133, 'itIT', 'È un ottimo elemento e ci sarà di grande aiuto.$B$BOra dobbiamo assicurarci di usarlo come si deve per far cadere in trappola Vardmadra!', 0),
(13135, 'itIT', 'Ah, perfetto! Il Bombardiere sarà pronto in men che non si dica.', 0),
(13137, 'itIT', 'Per il momento, lascio Vardmadra in un luogo sicuro finché non potremo mettere in atto la vendetta finale!', 0),
(13138, 'itIT', 'Non c''è dubbio: è Saronite Grezza. Avevamo visto armi fatte di questo metallo in mano ai prescelti del Re dei Lich, ma è la prima volta che viene usata in questo modo. Le operazioni di scavo devono essere enormi.', 0),
(13139, 'itIT', 'Il tuo aiuto nella difesa del fronte è stato fondamentale. La prima vera vittoria in questa guerra è vicina, quindi il tuo prossimo passo sarà ancora più importante.$B$BRicorda, $N: il Flagello non si arrenderà senza combattere. Ti attende la sfida più difficile di tutte.', 0),
(13140, 'itIT', 'Le placche combaciano quasi perfettamente con i frammenti. Stanno usando i ritagli per "potenziare" i Ghoul. A quanto pare, il Flagello è talmente disperato da trasformare qualsiasi cosa in un''arma. Motivo in più per accelerare la distruzione di quel luogo abominevole!', 0),
(13141, 'itIT', 'Benedetta sia la Luce! Il Pinnacolo è nostro! Finalmente possiamo iniziare a costruire Forte Giustizia. Il Gran Signore Fordring e i Cavalieri sono già in viaggio verso la nostra nuova base. Raggiungili lì!', 0),
(13142, 'itIT', '$N, le parole non possono descrivere ciò che provo in questo momento! Ora che mi sono vendicata, non ho più uno scopo.$B$BSe solo potessi assistere alla caduta del Re dei Lich!$B$BMa non ingannarti: siamo ancora molto lontani dalla soluzione del "problema" Jotunheim. Continuerò a possedere questa Megera, finché i Vrykul non costituiranno più una minaccia.$B$BGuardati intorno: questa grotta è piena di oggetti di valore. Scegli la tua ricompensa.', 0),
(13143, 'itIT', 'Ho incatenato il disgraziato a quel palo e non vedo l''ora di averne altri a disposizione.$B$BFacciamo buon uso dell''Occhio.', 0),
(13144, 'itIT', 'Ah, bene! Mi piace l''odore della carne putrida bruciata al mattino! Profuma come... come di vittoria sul Flagello.', 0),
(13145, 'itIT', 'Ottimo lavoro. I Cavalieri della Morte rimasti fedeli ad Arthas sono più di quanti pensassi.$B$BNon si sta risparmiando nel tentativo di sostituire Acherus. Una cittadella fatta interamente di Saronite sarebbe difficile da distruggere, per fortuna non è necessario... Possiamo interrompere la produzione e abbattere i capi dei Cavalieri della Morte qui e ora, prima che diventino una vera minaccia.$B$BAncora più importante, dobbiamo distruggerne abbastanza da allontanare i Cavalieri della Morte dai loro capi, così potremo attaccare.', 0),
(13146, 'itIT', 'Non hanno alzato un dito contro di te, vero? Almeno sono prevedibili.', 0),
(13147, 'itIT', 'Che bisogno c''è di sacrificare i nostri uomini, quando loro sono così manipolabili?', 0),
(13149, 'itIT', 'Hai fatto un buon lavoro. Le truppe di Arthas hanno scoperto il grano infetto.$B$BOra ascoltami bene. C''è altro lavoro da fare.', 0),
(13151, 'itIT', 'Hai agito bene, $N.$B$BAbbiamo sventato il piano degli Infiniti e la trama della storia è intatta.$B$BTi ringrazio per il tuo prezioso aiuto, anche a nome dell''intero Stormo dei Draghi di Bronzo.', 0),
(13155, 'itIT', 'La Rocca Ignobile... Una prova evidente di quanto Arthas detesti perdere. Conficchiamo la lama a fondo!', 0),
(13160, 'itIT', 'Quando dormono non sono poi così minacciosi.', 0),
(13161, 'itIT', 'Credimi: il mondo sarà un posto migliore, senza Rokir.', 0),
(13162, 'itIT', 'Non nego che mi mancherà la sua risata... e il sorriso che appariva sul suo volto un attimo prima di uccidere qualcuno. Comunque ora ho un motivo in meno per guardarmi le spalle, quindi immagino di non potermi lamentare.', 0),
(13163, 'itIT', 'Finalmente è morto? Ottima notizia.', 0),
(13165, 'itIT', 'Il Re dei Lich è tornato a Nordania, ferito da Brandicenere, ma al secondo piano si trovano ancora gli ultimi resti del suo esercito.', 0),
(13168, 'itIT', 'Facile, vero? Qualunque essere intelligente riuscirà a controllare i non morti inferiori senza problemi. Sospetto che solo un vero negromante sia in grado di usare gli Occhi per assumere il controllo dei non morti più potenti. Comunque, non è un problema: ho già pensato a molti tipi di distruzione che possiamo scatenare usando anche i servitori più deboli.$B$BCi mettiamo al lavoro?', 0),
(13169, 'itIT', 'Li hai messi a nanna, eh?', 0),
(13170, 'itIT', 'Non hai dovuto nemmeno sporcarti le mani.', 0),
(13171, 'itIT', 'Ottimo lavoro. Il cielo non dovrebbe costituire una minaccia.', 0),
(13172, 'itIT', 'Sono praticamente senza difese. Non potrebbe essere più facile!', 0),
(13181, 'itIT', 'Proprio quello che volevo sentire! Una vittoria al Lago Lungoinverno, anche solo temporanea, è vitale per la nostra strategia globale contro L''Orda.', 0),
(13206, 'itIT', 'Ogni lama che rubiamo loro è una lama in meno nel corpo di un soldato.$B$BGrazie mille.', 0),
(13212, 'itIT', 'Be'', suppongo sia un bene aver "recuperato" il Crociato, anche se dubito che i suoi compagni avessero QUESTO in mente. Vediamo come possiamo fare per rimetterlo in piedi, così potremo piantarla con questa farsa e completare la missione.', 0),
(13213, 'itIT', '$N, il tuo nome ci è noto: hai battuto i nostri migliori guerrieri.$B$BForse credi che ciò mi preoccupi, ma non è così. Se perdono contro di te, vuol dire che non son degni e non meritano altro che essere dei miseri Vargul!$B$BPerò forse posso offrire una sfida diversa a te e ai tuoi amici: a Valhalas si svolgono combattimenti di ogni tipo e contro vari avversari.$B$BTorna a parlare con me, quando tu e i tuoi amici sarete pronti a proseguire. Vedremo se siete davvero valorosi!', 0),
(13215, 'itIT', 'Dovrei essere impressionato dal fatto che tu e i tuoi amici siete riusciti a battere un solo Sacerdote Nerubiano?$B$BSparisci, prima che ti scagli contro il mio Ghoul!', 0),
(13216, 'itIT', '$r, sconfiggere una Hyldnir è degno di nota, ma avevi l''aiuto dei tuoi amici.$B$BSei stato fortunato che il suo draco non abbia partecipato al combattimento.', 0),
(13217, 'itIT', '$N, inizio ad apprezzare il tuo valore in combattimento. Quindi ti odio.$B$BAvrei preferito vedere te e i tuoi amici schiacciati dal piede di quel Gigante di Carne!', 0),
(13218, 'itIT', 'Da qui non sono riuscito a vedere che trucco hai usato per battere il Thane, ma ti assicuro che non sopravvivrai alla prossima sfida.$B$BEsatto: so già chi sarà il tuo avversario. Fuggi, piccolo $r! Fuggi negli angoli più remoti del pianeta.$B$BOppure resta qui e muori, a me non interessa.', 0),
(13220, 'itIT', 'Olakin deve considerarsi fortunato: nessuno è mai stato salvato dalle grinfie del Flagello. Nessuno. Gli ricorderò che non basteranno filo ed eroismo a salvarlo una seconda volta.', 0),
(13230, 'itIT', '$N, non è più il momento di tollerare l''Alleanza.$B$BHa fatto di tutto per farsi odiare da noi! Vivrà nel terrore dell''Orda, finché non potrà più inquinare questo pianeta!', 0),
(13231, 'itIT', 'Quindi... è stata una disfatta totale. Non gliela perdonerò mai.$B$B$c, ricorda queste parole: L''Orda la pagherà cara e non avrò pietà!', 0),
(13232, 'itIT', '$c, hai compiuto un''impresa molto difficile... ma era la cosa giusta da fare.$B$BNon farti tormentare dal ricordo delle tue azioni, ma sfrutta il dolore e la pena che provi: rivolgili contro chi ha causato tutto questo.$B$BL''Orda deve pagare!', 0),
(13235, 'itIT', 'Ora che il suo campione dei Giganti di Carne è stato sconfitto, il Re dei Lich avrà capito che anche il resto delle sue armate è vulnerabile. Con te al nostro fianco, gli ricorderemo il significato della paura.', 0),
(13237, 'itIT', 'Davvero, $c?$B$BNon hai niente di rilevante da riferire?$B$B$B$BMi permetto di dissentire...', 0),
(13238, 'itIT', 'Troppo impegnato! Tsk! Ma se questa bambina praticamente vola da sola!$B$BLasciamo perdere. Mi accontenterò di te...', 0),
(13239, 'itIT', 'Woohooo! Li ho visti esplodere da quaggiù! Aggiungo un altro successo al mio elenco e inizio a imbottigliare la soluzione in vista dell''invasione. Ovviamente, se ti interessa, avrei bisogno di condurre qualche altro esperimento...', 0),
(13264, 'itIT', '$c, hai visto?$B$BA volte, l''intelligenza può darti un vantaggio contro un nemico apparentemente invincibile.', 0),
(13274, 'itIT', 'Eccolo! La chiave è quasi a portata di mano, ormai. Dobbiamo solo capire come unire l''involucro e il nucleo. Vediamo cosa ha scritto in proposito il Prospettore Soren...', 0),
(13278, 'itIT', 'Ben fatto, $c.$B$BIndagando un po'', forse riusciremo a scoprire come fanno a creare simili creature.', 0),
(13279, 'itIT', 'Ottimo lavoro, $c.$B$BQuando i nostri eserciti marceranno sulla cittadella, avremo un piano per impadronirci del Portale della Morte.', 0),
(13286, 'itIT', 'Il Capitano Bartlett ha fatto bene a inviarti da me.$B$BMentre lui si occupa del tuo conflitto con l''Orda, qualcuno deve concentrarsi esclusivamente sulla vera missione: la marcia sulla Rocca della Corona di Ghiaccio.$B$BChi, meglio di un ex servitore del Re dei Lich, può occuparsi di una cosa del genere?', 0),
(13288, 'itIT', '$c, hai visto?$B$BA volte, l''intelligenza può darti un vantaggio contro un nemico apparentemente invincibile.', 0),
(13290, 'itIT', 'Il Capitano ti ha mandato qui al posto suo, vero?$B$BMolto bene, $c. Rimboccati le maniche: è ora di mettersi al lavoro!', 0),
(13291, 'itIT', 'Ottimo!$B$BIo sono riuscito a riprodurre la soluzione. Non che ci volesse molto, ovviamente!$B$BDubito che vivrò abbastanza a lungo da vedere il giorno in cui quei cavernicoli dei Goblin escogiteranno qualcosa che uno Gnomo non riuscirà a replicare persino dormendo!', 0),
(13293, 'itIT', 'Sono davvero felice di vederti! Il capo ti ha mandato qui dal Martello?', 0),
(13294, 'itIT', 'Eccellente! Questi campioni sono ottimi.$B$BAncora una volta, useremo la forza del nemico per sconfiggerlo...', 0),
(13295, 'itIT', 'Ottimo lavoro, $c.$B$BQuando i nostri eserciti marceranno sulla cittadella, avremo un piano per impadronirci del Portale della Morte.', 0),
(13296, 'itIT', 'Il capo ti ha mandato qui dalla Spaccacieli? Ma che gentile!', 0),
(13298, 'itIT', 'Ben fatto, $c.$B$BIndagando un po'', forse riusciremo a scoprire come fanno a creare simili creature.', 0),
(13307, 'itIT', 'Hai eliminato i Porta Vessillo del Flagello e i loro servitori? Bene. Dobbiamo proseguire con i preparativi.', 0),
(13309, 'itIT', 'Ottimo lavoro! Abbiamo bisogno di gente in gamba come te! Se l''operazione non sarà già terminata, torna qui uno di questi giorni.', 0),
(13312, 'itIT', 'Hai ucciso Grimkor? Eccellente! Senza di lui, le nostre possibilità di occupare il Bastione sono notevolmente aumentate.', 0),
(13315, 'itIT', 'Molto bene, $c.$B$BOra che hai visto con i tuoi occhi cosa stiamo per affrontare, è il momento di mettersi al lavoro.', 0),
(13316, 'itIT', 'Spero che il tuo successo a Corp''rethar sia un presagio per la battaglia che ci attende. Il Re dei Lich non resterà con le mani in mano, mentre marciamo contro le porte della sua roccaforte.', 0),
(13318, 'itIT', 'Date le circostanze, è uno strumento molto efficace. Non sei d''accordo?', 0),
(13319, 'itIT', 'Ben fatto, $r. Ma non adagiarti sugli allori: i sovrintendenti che hai eliminato verranno sostituiti in men che non si dica.', 0),
(13321, 'itIT', 'Woohooo!$B$BCosì imparano!', 0),
(13334, 'itIT', 'Hai eliminato i Porta Vessillo del Flagello e i loro servitori? Bene. Dobbiamo proseguire con i preparativi.', 0),
(13336, 'itIT', 'Il Re traditore cadrà. Su questo non c''è dubbio.', 0),
(13337, 'itIT', 'Hai ucciso Grimkor? Eccellente! Senza di lui, le nostre possibilità di occupare il Bastione sono notevolmente aumentate.', 0),
(13338, 'itIT', 'Spero che il tuo successo a Corp''rethar sia un presagio per la battaglia che ci attende. Il Re dei Lich non resterà con le mani in mano, mentre marciamo contro le porte della sua roccaforte.', 0),
(13340, 'itIT', 'Altra carne da macello... Benvenuto all''inferno.$B$BI miei uomini guidano l''assalto alle Porte da questa posizione, mentre alcuni Infiltrati si stanno lanciando all''interno della città. Ci serve più gente su entrambi i fronti: ho il sospetto che questo attacco durerà a lungo.', 0),
(13341, 'itIT', 'Benvenuto all''inferno.$B$BI miei uomini guidano l''assalto alle Porte da questa posizione, mentre alcuni Infiltrati si stanno lanciando all''interno della città. Ci serve più gente su entrambi i fronti: ho il sospetto che questo attacco durerà a lungo.', 0),
(13342, 'itIT', 'Ottimo lavoro, $c.$B$BIl Messaggero ci ha già riferito alcune informazioni preziose.', 0),
(13345, 'itIT', 'Tutto ciò è davvero allarmante...', 0),
(13346, 'itIT', 'Alumeth ha subito una sonora sconfitta, ma sento che il suo spirito non è svanito...', 0),
(13351, 'itIT', 'Molto bene, $c.$B$BOra che hai visto con i tuoi occhi cosa stiamo per affrontare, è il momento di mettersi al lavoro.', 0),
(13352, 'itIT', 'Date le circostanze, è uno strumento molto efficace. Non sei d''accordo?', 0),
(13354, 'itIT', 'Ben fatto, $r. Ma non adagiarti sugli allori: i sovrintendenti che hai eliminato verranno sostituiti in men che non si dica.', 0),
(13356, 'itIT', 'Woohooo!$B$BCosì imparano!', 0),
(13358, 'itIT', 'Ottimo lavoro, $c.$B$BIl Messaggero ci ha già riferito alcune informazioni preziose.', 0),
(13360, 'itIT', 'Eccoti. Iniziavo a chiedermi quando ti saresti fatto vivo.', 0),
(13362, 'itIT', 'Il fantasma del bambino... il cuore di Arthas... rallenta un po''... mi fai girare la testa.', 0),
(13363, 'itIT', 'Sono parole gravi, $N. Se le avesse pronunciate chiunque altro, gli avrei dato del pazzo.', 0),
(13364, 'itIT', '$N, non considero ciò che è appena accaduto come un fallimento. Al contrario!$B$BSbirciando nel suo cuore, ho avuto conferma di ciò che volevo sapere. Arthas Menethil non esiste più: esiste solo il Re dei Lich.', 0),
(13366, 'itIT', 'Tutto ciò è davvero allarmante...', 0),
(13367, 'itIT', 'Alumeth ha subito una sonora sconfitta, ma sento che il suo spirito non è svanito...', 0),
(13384, 'itIT', 'Questo è un giorno molto triste non solo per le razze dei draghi, ma per tutte le creature viventi di Azeroth. Abbiamo perso uno dei nostri più premurosi, intelligenti e vecchi amici. Ora la magia non ha più il suo Guardiano.$B$BSperiamo che negli anni a venire questa si riveli una decisione saggia, $N. C''è ancora una tempesta all''orizzonte e adesso siamo orfani di uno dei nostri più potenti difensori.', 0),
(13385, 'itIT', 'Questo è un giorno molto triste non solo per le razze dei draghi, ma per tutte le creature viventi di Azeroth. Abbiamo perso uno dei nostri più premurosi, intelligenti e vecchi amici. Ora la magia non ha più il suo Guardiano.$B$BSperiamo che negli anni a venire questa si riveli una decisione saggia, $N. C''è ancora una tempesta all''orizzonte e adesso siamo orfani di uno dei nostri più potenti difensori.', 0),
(13386, 'itIT', 'Salve $N. Thassarian mi aveva preannunciato il tuo arrivo. I suoi amici sono anche miei amici. Be'', perlomeno quelli vivi... frequenta gente strana.', 0),
(13387, 'itIT', 'Thassarian aveva ragione: sei in gamba! Ottimo lavoro!', 0),
(13388, 'itIT', 'Le bombe sembrano molto potenti. Dovrebbero danneggiare la struttura circostante.', 0),
(13390, 'itIT', 'L''ho visto che se ne sbarazzava: l''ha tirato quaggiù.$B$BHa detto che non gli serviva più, che lo indeboliva.', 0),
(13391, 'itIT', 'Che stai aspettando? Devo strofinartelo addosso!$B$BPresto, o ti vedrà!', 0),
(13392, 'itIT', '$N! Pensavamo che fossi morto!$B$BL''esplosione ha causato parecchi danni al Flagello. Il Capitano Kendall ha quasi perso le sopracciglia...', 0),
(13394, 'itIT', 'Visto? Ne hai uccisi molti ma, per ognuno che eliminavi, un altro sorgeva dal terreno per prendere il suo posto.$B$B$N, non sai contro chi combatti. Permettimi di mostrartelo.', 0),
(13395, 'itIT', 'Il vero potere del Principe non è l''abilità di creare degli eserciti di cadaveri... quello è facile.$B$BMa uccidere i suoi uomini, con i quali ha condiviso tante battaglie... Il vero potere del Principe è la sua abilità di fare ciò che deve essere fatto.', 0),
(13396, 'itIT', 'Bel colpo, $N. Il Flagello non aveva alcuna possibilità.$B$BTi senti bene? Sembri uno che ha appena visto un fantasma. Pensandoci bene, da queste parti non sarebbe una cosa così insolita.', 0),
(13397, 'itIT', 'Ottimo lavoro, $N. In confronto a te, siamo tutti degli incapaci!', 0),
(13398, 'itIT', 'Persino i possenti dragoni devono rispondere al suo richiamo. Come può resistere un misero mortale come te?', 0),
(13399, 'itIT', 'Eccoti. Iniziavo a chiedermi quando ti saresti fatto vivo.', 0),
(13400, 'itIT', 'Dopo quel combattimento, il Principe ha capito che ciò che lo tratteneva era la sua umanità: poteva ancora provare dolore... e sanguinare. Aveva ancora un cuore.$B$BLa prima cosa che ha fatto dopo essere diventato Re è stata sbarazzarsene, gettandolo nella fossa dove ci siamo incontrati la prima volta. E tu, $N, sei stata la prima persona a toccarlo da allora.', 0),
(13401, 'itIT', 'Rallenta, $N. Perché non ricominci... dall''inizio?', 0),
(13408, 'itIT', 'Ben fatto, $N. Le tue gesta sul campo di battaglia sono fondamentali per la nostra conquista della Penisola del Fuoco Infernale.', 0),
(13412, 'itIT', 'È molto presuntuoso da parte tua pensare di poter interferire negli affari personali di un drago, non credi, $r?$B$BDetto questo, sbaglierei a non far sapere a mio fratello che sto bene. Puoi dire alla tua amica impicciona che terrò mio fratello informato.', 0),
(13413, 'itIT', 'Il mio draco dice che, con il dovuto allenamento, potresti diventare un combattente capace.$B$BMolto bene, allora. Nell''interesse della nostra guerra contro Malygos, ti concederò di allenarti con i miei piccoli a tuo piacimento.$B$BPreparati, $r, perché Malygos è un avversario feroce e spietato.', 0),
(13419, 'itIT', 'Benvenuto al Martello di Orgrim.$B$BDa qui possiamo schierare le forze di terra per attaccare Arthas. Ci sono molti preparativi da sbrigare ma, prima di entrare nel vivo, voglio assicurarmi che la Crociata d''Argento sia adeguatamente rinforzata: più avanti, avremo bisogno del suo aiuto.$B$BSe ancora non l''hai fatto, parla con Fratello Keltan sul ponte di coperta.', 0),
(13424, 'itIT', 'Continui a dimostrare la tua abilità. Il rispetto delle sorelle nei tuoi confronti continua a crescere.', 0),
(13479, 'itIT', 'Eccellente, eccellente! Grazie. Potrebbero servirmi altri campioni per ottenere risultati certi, ma hai agito bene.', 0),
(13480, 'itIT', 'Eccellente, eccellente! Grazie. Potrebbero servirmi altri campioni per ottenere risultati certi, ma hai agito bene.', 0),
(13482, 'itIT', 'Sia ringraziata la Luce! Temevo che Padre Kamaros fosse morto... o peggio. Grazie al tuo coraggio e alla tua misericordia, abbiamo recuperato un potente alleato della Crociata d''Argento. Hai la mia gratitudine, unita a quella di tutta la Crociata.', 0),
(13483, 'itIT', 'Sì! Sì, credo di avere l''incarico che fa per te...', 0),
(13484, 'itIT', 'Sì! Sì, credo di avere l''incarico che fa per te...', 0),
(13502, 'itIT', 'Ben fatto! Prego, tieni pure il cestino!$B$BRicorda, puoi sempre tornare a scambiare i Cioccolatini di Nobiluova con altri oggetti.', 0),
(13503, 'itIT', 'Ben fatto! Prego, tieni pure il cestino!$B$BRicorda, puoi raccogliere altri Cioccolatini di Nobiluova per scambiarli poi con altri oggetti.', 0),
(13556, 'itIT', 'Una, due, tre... eheh, me ne hai portate assai, cumpà! Basteranno per nu sacco di tempo!', 0),
(13559, 'itIT', 'I Figli di Hodir accettano il tuo tributo, piccolo. Continui a dimostrare in molti modi di essere un valido alleato.', 0),
(13592, 'itIT', 'Bentornato dall''addestramento, $N. Anche mentre facciamo pratica per la competizione, è bene ricordarci che il Flagello è ancora là fuori.', 0),
(13622, 'itIT', 'Analisi dei frammenti... Attendere.', 0),
(13625, 'itIT', 'Ben fatto, $N. Spesso il combattimento su una cavalcatura è difficile da affrontare per chi è abituato a quello a piedi. Non ho dubbi che continuerai a migliorare con la pratica, cosa che devo dire non vale per tutti i guerrieri.', 0),
(13629, 'itIT', 'Confermata l''integrità dell''oggetto. Si prega di attendere mentre vengono rimossi i residui solidi.', 0),
(13631, 'itIT', 'Eccoti. Per il bene di tutti, speriamo che funzioni.', 0),
(13633, 'itIT', 'Stai dicendo, dunque, che la storia di questo Cavaliere è fasulla? Ciò è sospetto. Quantomeno disonorevole e, nell''ipotesi peggiore, delittuoso. Ma non possiamo ancora affrontarlo, finché non avremo la certezza del suo coinvolgimento in questi omicidi.$B$BNon destare sospetti, $N. La discrezione sarà nostra alleata, mentre proseguiamo le indagini.', 0),
(13634, 'itIT', 'Stai dicendo, dunque, che la storia di questo Cavaliere è fasulla? Ciò è sospetto. Quantomeno disonorevole e, nell''ipotesi peggiore, delittuoso. Ma non possiamo ancora affrontarlo, finché non avremo la certezza del suo coinvolgimento in questi omicidi.$B$BNon destare sospetti, $N. La discrezione sarà nostra alleata, mentre proseguiamo le indagini.', 0),
(13641, 'itIT', 'Questo andrà bene. Bisogna solo infondergli il potere della Luce per dargli la capacità di discernere il vero dal falso.', 0),
(13643, 'itIT', 'Dunque Lorien Soleardente è stato avvelenato e Ser Wendell bruciato vivo? Che morti orribili. Solo Conall è stato ucciso dal freddo acciaio e, stando alla tua descrizione, è caduto per un attacco proditorio e non in un duello onorevole.$B$BTutti e tre si sono allenati con il Cavaliere Nero e dovevano affrontarlo nel torneo. Non può essere una coincidenza. Ora dobbiamo trovare il modo di provare che è stata opera sua.', 0),
(13664, 'itIT', 'Con la morte del Cavaliere Nero, il torneo può proseguire così come è stato concepito. I Campioni dell''Orda e dell''Alleanza potranno dimostrare le loro capacità militari e allenarsi fino al giorno in cui Arthas e i suoi servitori non saranno più una minaccia.$B$BHai la gratitudine della Crociata d''Argento, $N, e di tutti coloro che hanno risposto alla nostra chiamata.', 0),
(13665, 'itIT', 'Ben fatto. Allenarsi con gli altri Valorosi è uno dei modi migliori per prepararsi ad affrontare il torneo. So che renderai onore a Roccavento, $N.', 0),
(13666, 'itIT', 'Dunque quelle vecchie storie hanno un fondo di verità? A quanto pare non mentivano sulla qualità della lama. Ben fatto, $N. Il Campione che la brandirà avrà senza dubbio la fortuna dalla sua parte.', 0),
(13667, 'itIT', 'Ho inserito il tuo nome tra i partecipanti, $N. Come Aspirante ti addestrerai con gli altri che desiderano competere nel torneo e affinerai le tue capacità nel combattimento su una cavalcatura. Una volta dimostrato il tuo valore, potrai partecipare al livello più basso della competizione in nome della tua capitale.', 0),
(13668, 'itIT', 'Ho inserito il tuo nome tra i partecipanti, $N. Come Aspirante ti addestrerai con gli altri che desiderano competere nel torneo e affinerai le tue capacità nel combattimento su una cavalcatura. Una volta dimostrato il tuo valore, potrai partecipare al livello più basso della competizione in nome della tua capitale.', 0),
(13670, 'itIT', 'La lama è pregiata come l''ha descritta lo scudiero, ma lui come faceva a saperlo? Non importa, ora ha un nuovo padrone. Forse è giusto che sia il Gran Campione di Forgiardente a brandirla.', 0),
(13671, 'itIT', 'Hai dimostrato il tuo valore in combattimento, $N, e sarai un esempio per il resto degli Aspiranti che desiderano competere per l''Alleanza.', 0),
(13672, 'itIT', 'Molto bene. Mi occuperò dei preparativi.', 0),
(13673, 'itIT', 'Dunque quelle vecchie storie hanno un fondo di verità? A quanto pare non mentivano sulla qualità della lama. Ben fatto, $N. Il Campione che la brandirà avrà senza dubbio la fortuna dalla sua parte.', 0),
(13675, 'itIT', 'La lama è pregiata come l''ha descritta il Valoroso, ma lui come faceva a saperlo? Non importa, ora ha un nuovo padrone. Forse è giusto che sia il Gran Campione di Orgrimmar a brandirla.', 0),
(13676, 'itIT', 'Hai dimostrato il tuo valore in combattimento, $N, e sarai un esempio per il resto degli Aspiranti che desiderano competere per l''Orda.', 0),
(13677, 'itIT', 'Ben fatto, $N. Spesso il combattimento su una cavalcatura è difficile da affrontare per chi è abituato a quello a piedi. Non ho dubbi che continuerai a migliorare con la pratica, cosa che devo dire non vale per tutti i guerrieri.', 0),
(13679, 'itIT', 'Le congratulazioni sono d''obbligo, $N. Hai sconfitto il tuo avversario e guadagnato il diritto di avanzare al grado di Valoroso.', 0),
(13682, 'itIT', '$N, tu e i tuoi alleati avete salvato il torneo da un terribile attacco. Anche se le nostre truppe Artiglio dei Cieli sono valorose, sono impegnate a mantenere la pace sui campi del torneo e avrebbero avuto difficoltà a difendere i cieli dall''attacco del Culto. La Crociata d''Argento e tutti quelli che sono venuti qui a gareggiare ti ringraziano.', 0),
(13689, 'itIT', 'Ti do il benvenuto nella delegazione del torneo di Darnassus, $N. Sarà un piacere addestrarmi e gareggiare al tuo fianco.', 0),
(13696, 'itIT', 'Dunque desideri gareggiare per Lunargenta? Molto bene. Ti inserirò tra i partecipanti e potrai iniziare subito ad allenarti con gli altri Valorosi.', 0),
(13697, 'itIT', 'Notevole, Valoroso. Mi occuperò immediatamente dei preparativi per la tua prova.', 0),
(13705, 'itIT', 'È bello averti con noi, $N. L''addestramento con te sarà di aiuto a tutti.', 0),
(13708, 'itIT', 'Sono felice assai che hai deciso di stare con noi. Nun vedo l''ora di vederti in azione.', 0),
(13710, 'itIT', 'Hai scelto bene, $N. Questo accordo sarà vantaggioso per entrambi.', 0),
(13711, 'itIT', 'Sarà un onore allenarsi e gareggiare con te, $N.', 0),
(13713, 'itIT', 'Hai dimostrato di meritare il titolo di Campione, $N. Prenderai parte in nome di Forgiardente al livello più alto del torneo, combattendo nella Gran Mischia con l''arma in resta e il tuo imponente vessillo sulla schiena.', 0),
(13714, 'itIT', 'Notevole, Valoroso. Mi occuperò immediatamente dei preparativi per la tua prova.', 0),
(13715, 'itIT', 'Notevole, Valoroso. Mi occuperò immediatamente dei preparativi per la tua prova.', 0),
(13717, 'itIT', 'Notevole, Valoroso. Mi occuperò immediatamente dei preparativi per la tua prova.', 0),
(13719, 'itIT', 'Notevole, Valoroso. Mi occuperò subito dei preparativi per la prova tua.', 0),
(13720, 'itIT', 'Notevole, Valoroso. Mi occuperò subito dei preparativi per la tua prova.', 0),
(13721, 'itIT', 'Notevole, Valoroso. Mi occuperò subito dei preparativi per la tua prova.', 0),
(13722, 'itIT', 'Notevole, Valoroso. Mi occuperò subito dei preparativi per la tua prova.', 0),
(13723, 'itIT', 'Hai dimostrato di meritare il titolo di Campione, $N. Prenderai parte in nome di Gnomeregan al livello più alto del torneo, combattendo nella Gran Mischia con l''arma in resta e il tuo imponente vessillo sulla schiena.', 0),
(13725, 'itIT', 'Hai dimostrato di meritare il titolo di Campione, $N. Prenderai parte in nome di Darnassus al livello più alto del torneo, combattendo nella Gran Mischia con l''arma in resta e il tuo imponente vessillo sulla schiena.', 0),
(13726, 'itIT', 'Hai dimostrato di meritare il titolo di Campione, $N. Prenderai parte al livello più alto del torneo, combattendo nella Gran Mischia e schiacciando i tuoi nemici sotto lo stendardo di Orgrimmar.', 0),
(13727, 'itIT', 'Hai dimostrato di meritare il titolo di Campione, $N. Prenderai parte al livello più alto del torneo, combattendo nella Gran Mischia e schiacciando i nemici tuoi sotto lo stendardo dei Lanciascura.', 0),
(13728, 'itIT', 'Hai dimostrato di meritare il titolo di Campione, $N. Prenderai parte al livello più alto del torneo, combattendo nella Gran Mischia e schiacciando i tuoi nemici sotto lo stendardo di Picco del Tuono.', 0),
(13729, 'itIT', 'Hai dimostrato di meritare il titolo di Campione, $N. Prenderai parte al livello più alto del torneo, combattendo nella Gran Mischia e schiacciando i tuoi nemici sotto lo stendardo di Sepulcra.', 0),
(13731, 'itIT', 'Hai dimostrato di meritare il titolo di Campione, $N. Prenderai parte al livello più alto del torneo, combattendo nella Gran Mischia e schiacciando i tuoi nemici sotto lo stendardo di Lunargenta.', 0),
(13735, 'itIT', 'Ti do il benvenuto come Campione del torneo, $N. In quanto tale, potrai competere per la conquista del titolo di Gran Campione del torneo. Puoi anche scegliere di diventare un Valoroso con una delegazione di un''altra città dell''Alleanza e, col tempo, Campione anche di quella città.$B$BTutti i Campioni devono avere uno scudiero, $N, e tu non fai eccezione. Permettimi di assegnartene uno dei nostri affinché ti accompagni in battaglia. Porterà con orgoglio lo stendardo di qualunque città ti nomini Campione.', 0),
(13738, 'itIT', 'Ti do il benvenuto come Campione del torneo, $N. In quanto tale, potrai competere per la conquista del titolo di Gran Campione del torneo. Puoi anche scegliere di diventare un Valoroso con una delegazione di un''altra città dell''Orda e, col tempo, Campione anche di quella città.$B$BTutti i Campioni devono avere uno scudiero, $N, e tu non fai eccezione. Permettimi di assegnartene uno dei nostri affinché ti accompagni in battaglia. Porterà con orgoglio lo stendardo di qualunque città ti nomini Campione.', 0),
(13741, 'itIT', 'Dunque le storie erano vere? Questa è un''ottima lama e non ho dubbi che farà il suo dovere al torneo. Ti ringrazio, $N.', 0),
(13743, 'itIT', 'La lama è splendida come raccontano le storie che ne parlano. A quanto pare, non serve completare le riparazioni della mia spada precedente. Lamagelo è molto meglio e continuerò a usarla. Ti ringrazio, $N.', 0),
(13744, 'itIT', 'Bentornato dall''addestramento, $N. Anche mentre facciamo pratica per la competizione, è bene ricordarci che il Flagello è ancora là fuori.', 0),
(13745, 'itIT', 'Ben fatto. Allenarsi con gli altri Valorosi è uno dei modi migliori per prepararsi ad affrontare il torneo. So che renderai onore a Forgiardente, $N.', 0),
(13746, 'itIT', 'Dunque le storie erano vere? Questa è un''ottima lama e non ho dubbi che farà il suo dovere al torneo. Ti ringrazio, $N.', 0),
(13748, 'itIT', 'La lama è splendida come raccontano le storie che ne parlano. A quanto pare, non serve completare le riparazioni della mia spada precedente. Lamagelo è molto meglio e continuerò a usarla. Ti ringrazio, $N.', 0),
(13749, 'itIT', 'Bentornato dall''allenamento, $N. Non ho dubbi che ci renderai fieri di te quando comincerà la competizione.', 0),
(13750, 'itIT', 'Ben fatto. Allenarsi con gli altri Valorosi è uno dei modi migliori per prepararsi ad affrontare il torneo. So che ci renderai orgogliosi, $N.', 0),
(13752, 'itIT', 'Dunque le storie erano vere? Questa è un''ottima lama e non ho dubbi che farà il suo dovere al torneo. Ti ringrazio, $N.', 0),
(13754, 'itIT', 'La lama è splendida come raccontano le storie che ne parlano. A quanto pare, non serve completare le riparazioni della mia spada precedente. Lamagelo è molto meglio e continuerò a usarla. Ti ringrazio, $N.', 0),
